INSERT INTO public.exercise_gif_catalog (exercise_id, name_pt, name_original, slug, gif_url_source, storage_path, thumbnail_url, body_parts, equipments, target_muscles, secondary_muscles, instructions, created_at, updated_at) VALUES ('01qpYSe', 'Extensão lombar', 'upward facing dog', 'cachorro-olhando-para-cima', 'https://static.exercisedb.dev/media/01qpYSe.gif', 'catalogo/cachorro-olhando-para-cima--01qpYSe.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cachorro-olhando-para-cima--01qpYSe.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['deltoides','peitorais'], '["Step:1 Position yourself face down on the floor with your legs extended behind you.","Step:2 Set your hands on the floor next to your lower ribs, fingers pointing forward.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:05.463061+00', '2026-10-31 19:42:04.671+00'), ('03lzqwk', 'Elevação de joelhos na barra fixa assistida', 'assisted hanging knee raise', 'elevacao-de-joelhos-na-barra-fixa-assistida', 'https://static.exercisedb.dev/media/03lzqwk.gif', 'catalogo/elevacao-de-joelhos-na-barra-fixa-assistida--03lzqwk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-joelhos-na-barra-fixa-assistida--03lzqwk.gif', ARRAY['abdômen'], ARRAY['assistido'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk muscles and lift your knees toward your chest, bending at the hips and knees.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:42:05.464935+00', '2026-10-31 19:42:04.993+00'), ('05Cf2v8', 'Mergulho impossível', 'impossible dips', 'mergulho-impossivel', 'https://static.exercisedb.dev/media/05Cf2v8.gif', 'catalogo/mergulho-impossivel--05Cf2v8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-impossivel--05Cf2v8.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set yourself between two parallel bars with your arms straight and your body suspended in the air.","Step:2 Before moving, bend your knees and cross your ankles.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:42:07.975364+00', '2026-10-31 19:42:07.567+00'), ('0br45wL', 'Flexão de braço com chute lateral interno da perna', 'push-up inside leg kick', 'flexao-de-braco-com-chute-lateral-interno-da-perna', 'https://static.exercisedb.dev/media/0br45wL.gif', 'catalogo/flexao-de-braco-com-chute-lateral-interno-da-perna--0br45wL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-chute-lateral-interno-da-perna--0br45wL.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.","Step:2 Lower your body toward the ground by bending your elbows, with your spine steady and your core engaged.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:05.478377+00', '2026-10-31 19:42:05.007+00'), ('0CXGHya', 'Crucifixo no cabo (crossover)', 'Cable Crossover', 'crucifixo-no-cabo-crossover', 'https://static.exercisedb.dev/media/0CXGHya.gif', 'catalogo/crucifixo-no-cabo-crossover--0CXGHya.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-no-cabo-crossover--0CXGHya.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the cable pulleys to chest height.","Step:2 Take your place in the center of the cable machine with one foot in front of the other.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:42:05.462791+00', '2026-10-31 19:42:04.666+00'), ('0dCyly0', 'Desenvolvimento Bradford Rocky sentado com barra', 'barbell seated bradford rocky press', 'desenvolvimento-bradford-rocky-sentado-com-barra', 'https://static.exercisedb.dev/media/0dCyly0.gif', 'catalogo/desenvolvimento-bradford-rocky-sentado-com-barra--0dCyly0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-bradford-rocky-sentado-com-barra--0dCyly0.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take hold of the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:06.709417+00', '2026-10-31 19:42:06.342+00'), ('0IgNjSM', 'Rosca inversa em pé com halteres', 'dumbbell standing reverse curl', 'rosca-inversa-em-pe-com-halteres', 'https://static.exercisedb.dev/media/0IgNjSM.gif', 'catalogo/rosca-inversa-em-pe-com-halteres--0IgNjSM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-em-pe-com-halteres--0IgNjSM.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:06.206105+00', '2026-10-31 19:42:06.044+00'), ('0jp9Rlz', 'Elevação de panturrilha unilateral no chão', 'Single-Leg Floor Calf Raise', 'elevacao-de-panturrilha-unilateral-no-chao', 'https://static.exercisedb.dev/media/0jp9Rlz.gif', 'catalogo/elevacao-de-panturrilha-unilateral-no-chao--0jp9Rlz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-unilateral-no-chao--0jp9Rlz.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Stand and set your feet about hip width and place your hands on a wall or sturdy object for balance.","Step:2 Before moving, lift one foot off the ground and balance on the other foot.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:42:06.205927+00', '2026-10-31 19:42:06.049+00'), ('0JtKWum', 'Burpee com halteres', 'dumbbell burpee', 'burpee-com-halteres', 'https://static.exercisedb.dev/media/0JtKWum.gif', 'catalogo/burpee-com-halteres--0JtKWum.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/burpee-com-halteres--0JtKWum.gif', ARRAY['cardio'], ARRAY['halteres'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','deltoides','tríceps','core'], '["Step:1 Begin in a standing position with your feet about shoulder width and a dumbbell in each hand.","Step:2 Before moving, lower your body into a squat position, placing the dumbbells on the ground in front of you.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:42:06.911321+00', '2026-10-31 19:42:06.774+00'), ('0L2KwtI', 'Alongamento de quadril e dorsal com rolo', 'roller hip lat stretch', 'alongamento-de-quadril-e-dorsal-com-rolo', 'https://static.exercisedb.dev/media/0L2KwtI.gif', 'catalogo/alongamento-de-quadril-e-dorsal-com-rolo--0L2KwtI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-quadril-e-dorsal-com-rolo--0L2KwtI.gif', ARRAY['coxas'], ARRAY['rolo'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Begin by kneeling on the ground with the roller positioned under your hips.","Step:2 Set your hands on the roller for support.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:07.032947+00', '2026-10-31 19:42:06.633+00'), ('0lQnxMZ', 'Agachamento sissy com peso', 'weighted sissy squat', 'agachamento-sissy-com-peso', 'https://static.exercisedb.dev/media/0lQnxMZ.gif', 'catalogo/agachamento-sissy-com-peso--0lQnxMZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-sissy-com-peso--0lQnxMZ.gif', ARRAY['coxas'], ARRAY['com peso'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and your toes pointing slightly outward.","Step:2 Take a weight ahead of your chest with both hands, or place a barbell across your upper back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:06.990058+00', '2026-10-31 19:42:06.609+00'), ('0mB6wHO', 'Alongamento do corredor', 'runners stretch', 'alongamento-do-corredor', 'https://static.exercisedb.dev/media/0mB6wHO.gif', 'catalogo/alongamento-do-corredor--0mB6wHO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-do-corredor--0mB6wHO.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['panturrilhas','quadríceps'], '["Step:1 Stand and set your feet about hip width.","Step:2 Step forward with your right foot, keeping your left foot planted.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:07.301897+00', '2026-10-31 19:42:07.12+00'), ('0rHfvy9', 'Flexão de pernas invertida (no cabo da barra fixa)', 'inverse leg curl (on pull-up cable machine)', 'flexao-de-pernas-invertida-no-cabo-da-barra-fixa', 'https://static.exercisedb.dev/media/0rHfvy9.gif', 'catalogo/flexao-de-pernas-invertida-no-cabo-da-barra-fixa--0rHfvy9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-pernas-invertida-no-cabo-da-barra-fixa--0rHfvy9.gif', ARRAY['coxas'], ARRAY['peso corporal','cabo'], ARRAY['posteriores de coxa'], ARRAY['glúteos','panturrilhas'], '["Step:1 Set the cable machine so that the ankle straps are at the lowest setting.","Step:2 Position yourself face down on the bench with your legs extended and the ankle straps attached to your feet.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:42:07.620321+00', '2026-10-31 19:42:07.477+00'), ('0S75mYG', 'Panturrilha sentado unilateral no Smith', 'Smith Seated Single-Leg Calf Raise', 'panturrilha-sentado-unilateral-no-smith', 'https://static.exercisedb.dev/media/0S75mYG.gif', 'catalogo/panturrilha-sentado-unilateral-no-smith--0S75mYG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-unilateral-no-smith--0S75mYG.gif', ARRAY['panturrilhas'], ARRAY['Smith'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Take a seat on the machine with your back against the pad and your feet on the footrest.","Step:2 Set one leg on the footrest and keep the other leg off the footrest.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:42:07.94332+00', '2026-10-31 19:42:07.802+00'), ('0V2YQjW', 'Barra fixa com pegada neutra', 'Pull-Up (Neutral Grip)', 'barra-fixa-com-pegada-neutra', 'https://static.exercisedb.dev/media/0V2YQjW.gif', 'catalogo/barra-fixa-com-pegada-neutra--0V2YQjW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-pegada-neutra--0V2YQjW.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Suspend yourself from a pull-up bar with a neutral grip (palms facing each other) and your arms straight.","Step:2 Brace your trunk and draw your shoulder blades toward each other.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:42:07.952631+00', '2026-10-31 19:42:07.813+00'), ('0xDpB4L', 'Abdução de quadril sentado com elástico', 'Band Seated Hip Abduction', 'abducao-de-quadril-sentado-com-elastico', 'https://static.exercisedb.dev/media/0xDpB4L.gif', 'catalogo/abducao-de-quadril-sentado-com-elastico--0xDpB4L.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abducao-de-quadril-sentado-com-elastico--0xDpB4L.gif', ARRAY['coxas'], ARRAY['elástico de resistência'], ARRAY['abdutores'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Take a seat on a chair or bench with your back straight and feet planted.","Step:2 Loop the resistance band around your thighs, just above your knees.","Step:3 Square the pelvis before moving the working leg.","Step:4 Open the knees or legs against resistance without shifting your torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:42:08.225078+00', '2026-10-31 19:42:08.087+00'), ('0Yz8WdV', 'Caminhada do urso', 'bear crawl', 'caminhada-do-urso', 'https://static.exercisedb.dev/media/0Yz8WdV.gif', 'catalogo/caminhada-do-urso--0Yz8WdV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-do-urso--0Yz8WdV.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['core','deltoides','tríceps'], '["Step:1 Get onto hands and knees with your hands directly under your shoulders and your knees directly under your hips.","Step:2 Before moving, lift your knees slightly off the ground, keeping your back flat and your core engaged.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:42:08.352367+00', '2026-10-31 19:42:08.211+00'), ('10Z2DXU', 'Leg press 45°', 'sled 45° leg press', 'leg-press-45', 'https://static.exercisedb.dev/media/10Z2DXU.gif', 'catalogo/leg-press-45--10Z2DXU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-45--10Z2DXU.gif', ARRAY['coxas'], ARRAY['máquina de leg press'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat and footplate of the sled machine to a comfortable position.","Step:2 Take a seat on the sled machine with your back against the backrest and your feet about shoulder width on the footplate.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Stop the descent before the hips lift from the seat.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:42:08.747051+00', '2026-10-31 19:42:08.385+00'), ('11wrviz', 'Limpador de para-brisa isométrico', 'isometric wipers', 'limpador-de-para-brisa-isometrico', 'https://static.exercisedb.dev/media/11wrviz.gif', 'catalogo/limpador-de-para-brisa-isometrico--11wrviz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/limpador-de-para-brisa-isometrico--11wrviz.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['deltoides','tríceps','core'], '["Step:1 Begin by lying flat on your back on a mat or bench.","Step:2 Reach your arms straight out to the sides, perpendicular to your body.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Keep the trunk braced as the legs move together from side to side.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:08.525709+00', '2026-10-31 19:42:08.395+00'), ('13TpY4H', 'Flexão de braço unilateral com elevação', 'raise single arm push-up', 'flexao-de-braco-unilateral-com-elevacao', 'https://static.exercisedb.dev/media/13TpY4H.gif', 'catalogo/flexao-de-braco-unilateral-com-elevacao--13TpY4H.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-unilateral-com-elevacao--13TpY4H.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.","Step:2 Reach one arm straight out to the side, parallel to the ground.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:08.604891+00', '2026-10-31 19:42:08.472+00'), ('13VW2VO', 'Avanço com alongamento e peso', 'weighted stretch lunge', 'avanco-com-alongamento-e-peso', 'https://static.exercisedb.dev/media/13VW2VO.gif', 'catalogo/avanco-com-alongamento-e-peso--13VW2VO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-alongamento-e-peso--13VW2VO.gif', ARRAY['coxas'], ARRAY['com peso'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Step forward with your right foot, with your spine steady.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:08.787829+00', '2026-10-31 19:42:08.659+00'), ('17bqEXD', 'Alongamento de panturrilha sentado', 'Seated Calf Stretch', 'alongamento-de-panturrilha-sentado', 'https://static.exercisedb.dev/media/17bqEXD.gif', 'catalogo/alongamento-de-panturrilha-sentado--17bqEXD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-panturrilha-sentado--17bqEXD.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Take a seat on the edge of a chair or bench with your feet planted.","Step:2 Reach one leg straight out in front of you, keeping your heel on the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:09.27284+00', '2026-10-31 19:42:08.866+00'), ('17lJ1kr', 'Mesa flexora', 'Machine Lying Leg Curl', 'mesa-flexora', 'https://static.exercisedb.dev/media/17lJ1kr.gif', 'catalogo/mesa-flexora--17lJ1kr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mesa-flexora--17lJ1kr.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['posteriores de coxa'], ARRAY['panturrilhas'], '["Step:1 Set the machine to fit your body and select the desired weight.","Step:2 Position yourself face down on the machine with your legs straight and your heels against the padded lever.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:42:09.151034+00', '2026-10-31 19:42:09.011+00'), ('196HJGw', 'Elevação de quadril (joelhos flexionados)', 'hip raise (bent knee)', 'elevacao-de-quadril-joelhos-flexionados', 'https://static.exercisedb.dev/media/196HJGw.gif', 'catalogo/elevacao-de-quadril-joelhos-flexionados--196HJGw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-joelhos-flexionados--196HJGw.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Glúteos','Posteriores de coxa'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands by your sides, palms facing down.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:42:09.398081+00', '2026-10-31 19:42:09.034+00'), ('1bQkKZK', 'Good morning no Smith com joelhos flexionados', 'smith bent knee good morning', 'good-morning-no-smith-com-joelhos-flexionados', 'https://static.exercisedb.dev/media/1bQkKZK.gif', 'catalogo/good-morning-no-smith-com-joelhos-flexionados--1bQkKZK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/good-morning-no-smith-com-joelhos-flexionados--1bQkKZK.gif', ARRAY['Coxas'], ARRAY['Smith'], ARRAY['Glúteos'], ARRAY['Posteriores de coxa','Eretores da espinha'], '["Step:1 Begin by standing with your feet about shoulder width, toes pointing forward.","Step:2 Set the barbell across your upper back, resting it on your traps.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:42:09.540873+00', '2026-10-31 19:42:09.401+00'), ('1cTf2Ux', 'Tríceps francês em pé com barra W', 'EZ-Bar Standing French Press', 'triceps-frances-em-pe-com-barra-w', 'https://static.exercisedb.dev/media/1cTf2Ux.gif', 'catalogo/triceps-frances-em-pe-com-barra-w--1cTf2Ux.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-em-pe-com-barra-w--1cTf2Ux.gif', ARRAY['Braços'], ARRAY['Barra W'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold the ez barbell with palms facing down.","Step:2 Raise the barbell above your head, straighten your arms.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Straighten the elbows to bring the bar overhead, then begin the next controlled rep."]', '2026-10-31 19:42:09.738704+00', '2026-10-31 19:42:09.612+00'), ('1DN3iz4', 'Remada alta no Smith', 'smith upright row', 'remada-alta-no-smith', 'https://static.exercisedb.dev/media/1DN3iz4.gif', 'catalogo/remada-alta-no-smith--1DN3iz4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-no-smith--1DN3iz4.gif', ARRAY['Ombros'], ARRAY['Smith'], ARRAY['Deltoides'], ARRAY['Trapézio','Bíceps'], '["Step:1 Stand and set your feet about shoulder width, facing the smith machine.","Step:2 Hold the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:09.97059+00', '2026-10-31 19:42:09.839+00'), ('1g5bPpA', 'Polichinelo', 'Jack Jump', 'polichinelo', 'https://static.exercisedb.dev/media/1g5bPpA.gif', 'catalogo/polichinelo--1g5bPpA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/polichinelo--1g5bPpA.gif', ARRAY['Cardio'], ARRAY['Peso corporal'], ARRAY['Sistema cardiovascular'], ARRAY['Quadríceps','Panturrilhas'], '["Step:1 Stand and set your feet together and your arms by your sides.","Step:2 Before moving, jump up, spreading your feet apart and raising your arms above your head.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:42:10.128945+00', '2026-10-31 19:42:09.733+00'), ('1gFNTZV', 'Agachamento com salto com barra', 'barbell jump squat', 'agachamento-com-salto-com-barra', 'https://static.exercisedb.dev/media/1gFNTZV.gif', 'catalogo/agachamento-com-salto-com-barra--1gFNTZV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-salto-com-barra--1gFNTZV.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de coxa','Panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width, holding a barbell across your upper back.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:09.986016+00', '2026-10-31 19:42:09.848+00'), ('1GPHRyK', 'Abdominal Janda', 'janda sit-up', 'abdominal-janda', 'https://static.exercisedb.dev/media/1GPHRyK.gif', 'catalogo/abdominal-janda--1GPHRyK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-janda--1GPHRyK.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril','Eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:10.117369+00', '2026-10-31 19:42:09.984+00'), ('1IG6gVF', 'Rotação de tronco em prono na bola suíça', 'prone twist on stability ball', 'rotacao-de-tronco-em-prono-na-bola-suica', 'https://static.exercisedb.dev/media/1IG6gVF.gif', 'catalogo/rotacao-de-tronco-em-prono-na-bola-suica--1IG6gVF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-em-prono-na-bola-suica--1IG6gVF.gif', ARRAY['Abdômen'], ARRAY['Bola suíça'], ARRAY['Abdominais'], ARRAY['Oblíquos','Eretores da espinha'], '["Step:1 Begin by lying face down on a stability ball with your feet about shoulder width and your toes touching the ground.","Step:2 Set your hands behind your head or cross them over your chest.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:10.515689+00', '2026-10-31 19:42:10.369+00'), ('1jXLYEw', 'Alongamento lateral em pé', 'standing lateral stretch', 'alongamento-lateral-em-pe', 'https://static.exercisedb.dev/media/1jXLYEw.gif', 'catalogo/alongamento-lateral-em-pe--1jXLYEw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lateral-em-pe--1jXLYEw.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Latíssimo do dorso'], ARRAY['Deltoides','Oblíquos'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Reach your arms straight out to the sides, parallel to the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:10.54187+00', '2026-10-31 19:42:10.403+00'), ('1kB3Wmk', 'Elevação de panturrilha unilateral com halter', 'dumbbell single leg calf raise', 'elevacao-de-panturrilha-unilateral-com-halter', 'https://static.exercisedb.dev/media/1kB3Wmk.gif', 'catalogo/elevacao-de-panturrilha-unilateral-com-halter--1kB3Wmk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-unilateral-com-halter--1kB3Wmk.gif', ARRAY['Panturrilhas'], ARRAY['Halter'], ARRAY['Panturrilhas'], ARRAY['Tornozelos'], '["Step:1 Step onto the edge of a step or platform with your heels hanging off and your toes on the step.","Step:2 Take a dumbbell in one hand and place your other hand on a wall or railing for support.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:10.938619+00', '2026-10-31 19:42:10.807+00'), ('1LVFcEn', 'Alongamento de panturrilha com corda', 'calf stretch with rope', 'alongamento-de-panturrilha-com-corda', 'https://static.exercisedb.dev/media/1LVFcEn.gif', 'catalogo/alongamento-de-panturrilha-com-corda--1LVFcEn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-panturrilha-com-corda--1LVFcEn.gif', ARRAY['Panturrilhas'], ARRAY['Corda'], ARRAY['Panturrilhas'], ARRAY['Posteriores de coxa'], '["Step:1 Face a wall or sturdy object with your feet about hip width.","Step:2 Take hold of the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:10.998367+00', '2026-10-31 19:42:10.858+00'), ('1PK5Uo3', 'Pushdown inclinado no cabo', 'cable incline pushdown', 'pushdown-inclinado-no-cabo', 'https://static.exercisedb.dev/media/1PK5Uo3.gif', 'catalogo/pushdown-inclinado-no-cabo--1PK5Uo3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pushdown-inclinado-no-cabo--1PK5Uo3.gif', ARRAY['Costas'], ARRAY['Cabo'], ARRAY['Latíssimo do dorso'], ARRAY['Tríceps','Deltoides'], '["Step:1 Connect a straight bar to a high pulley cable machine.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the elbows close to the body instead of letting the shoulders swing.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:42:11.336791+00', '2026-10-31 19:42:11.19+00'), ('1PLE8e9', 'Crucifixo inclinado com rotação com halteres', 'dumbbell incline twisted flyes', 'crucifixo-inclinado-com-rotacao-com-halteres', 'https://static.exercisedb.dev/media/1PLE8e9.gif', 'catalogo/crucifixo-inclinado-com-rotacao-com-halteres--1PLE8e9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-com-rotacao-com-halteres--1PLE8e9.gif', ARRAY['Peito'], ARRAY['Halter'], ARRAY['Peitorais'], ARRAY['Deltoides','Tríceps'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Step:2 Recline on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:42:11.111444+00', '2026-10-31 19:42:10.979+00'), ('1qrWgZ2', 'Supino declinado martelo com halteres', 'dumbbell decline hammer press', 'supino-declinado-martelo-com-halteres', 'https://static.exercisedb.dev/media/1qrWgZ2.gif', 'catalogo/supino-declinado-martelo-com-halteres--1qrWgZ2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-martelo-com-halteres--1qrWgZ2.gif', ARRAY['Peito'], ARRAY['Halter'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides'], '["Step:1 Secure the feet on a decline bench, keeping the head below the hips.","Step:2 Take a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:11.180353+00', '2026-10-31 19:42:11.043+00'), ('1TkiAFK', 'Desenvolvimento unilateral com halter', 'Dumbbell Single-Arm Shoulder Press', 'desenvolvimento-unilateral-com-halter', 'https://static.exercisedb.dev/media/1TkiAFK.gif', 'catalogo/desenvolvimento-unilateral-com-halter--1TkiAFK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-unilateral-com-halter--1TkiAFK.gif', ARRAY['Ombros'], ARRAY['Halter'], ARRAY['Deltoides'], ARRAY['Tríceps','Parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand at shoulder level, palm facing forward.","Step:2 Brace your trunk and press the dumbbell straight up overhead, fully extending your arm.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:11.776246+00', '2026-10-31 19:42:11.407+00'), ('1V1gj1u', 'Rosca concentrada sentada com barra e pegada fechada', 'barbell seated close-grip concentration curl', 'rosca-concentrada-sentada-com-barra-e-pegada-fechada', 'https://static.exercisedb.dev/media/1V1gj1u.gif', 'catalogo/rosca-concentrada-sentada-com-barra-e-pegada-fechada--1V1gj1u.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-sentada-com-barra-e-pegada-fechada--1V1gj1u.gif', ARRAY['Braços'], ARRAY['Barra'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Plant both feet while seated on a bench; hold a barbell with palms facing up, hands about shoulder width.","Step:2 Set your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:11.806754+00', '2026-10-31 19:42:11.673+00'), ('1VpF8db', 'Avanço com rosca bíceps e movimento de boliche com halteres', 'Dumbbell Biceps Curl Lunge With Bowling Motion', 'avanco-com-rosca-biceps-e-movimento-de-boliche-com-halteres', 'https://static.exercisedb.dev/media/1VpF8db.gif', 'catalogo/avanco-com-rosca-biceps-e-movimento-de-boliche-com-halteres--1VpF8db.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-rosca-biceps-e-movimento-de-boliche-com-halteres--1VpF8db.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Bíceps'], ARRAY['Antebraços','Deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing forward.","Step:2 Step forward with your right foot, bending your right knee and lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:42:11.935416+00', '2026-10-31 19:42:11.807+00'), ('1xHyxys', 'Tríceps francês na polia alta', 'Cable High Pulley Overhead Triceps Extension', 'triceps-frances-na-polia-alta', 'https://static.exercisedb.dev/media/1xHyxys.gif', 'catalogo/triceps-frances-na-polia-alta--1xHyxys.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-na-polia-alta--1xHyxys.gif', ARRAY['Braços'], ARRAY['Cabo'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Connect a rope to a high pulley and stand turned away from the machine.","Step:2 Hold the rope with both hands and extend your arms overhead.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:12.393571+00', '2026-10-31 19:42:12.258+00'), ('1YB40kg', 'Flexão inclinada com pegada fechada', 'incline close-grip push-up', 'flexao-inclinada-com-pegada-fechada', 'https://static.exercisedb.dev/media/1YB40kg.gif', 'catalogo/flexao-inclinada-com-pegada-fechada--1YB40kg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-inclinada-com-pegada-fechada--1YB40kg.gif', ARRAY['Braços'], ARRAY['Peso corporal'], ARRAY['Tríceps'], ARRAY['Peitorais','Deltoides'], '["Step:1 Set your hands close together on a stable raised surface, then walk the feet back into a plank.","Step:2 Reach your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:12.460846+00', '2026-10-31 19:42:12.329+00'), ('1ZFqTDN', 'Abdominal Bicicleta', 'Bicycle Crunch', 'abdominal-bicicleta', 'https://static.exercisedb.dev/media/1ZFqTDN.gif', 'catalogo/abdominal-bicicleta--1ZFqTDN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-bicicleta--1ZFqTDN.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your hands placed behind your head.","Step:2 Before moving, lift your legs off the ground and bend your knees at a 90-degree angle.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Bring one elbow toward the opposite knee as the other leg extends; switch sides in a steady rhythm.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:12.546811+00', '2026-10-31 19:42:12.419+00'), ('225x2Vd', 'Abdominal Ajoelhado com Rotação na Faixa Elástica', 'band kneeling twisting crunch', 'abdominal-ajoelhado-com-rotacao-na-faixa-elastica', 'https://static.exercisedb.dev/media/225x2Vd.gif', 'catalogo/abdominal-ajoelhado-com-rotacao-na-faixa-elastica--225x2Vd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-ajoelhado-com-rotacao-na-faixa-elastica--225x2Vd.gif', ARRAY['abdômen'], ARRAY['faixa elástica'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Connect the band to a sturdy anchor point at waist height.","Step:2 Kneel turned away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:12.510266+00', '2026-10-31 19:42:12.382+00'), ('25GPyDY', 'Rosca Direta com Barra', 'barbell curl', 'rosca-direta-com-barra', 'https://static.exercisedb.dev/media/25GPyDY.gif', 'catalogo/rosca-direta-com-barra--25GPyDY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra--25GPyDY.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing up, palms facing forward.","Step:2 Hold your elbows near your torso and Breathe out and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:12.931303+00', '2026-10-31 19:42:12.795+00'), ('27NNGFr', 'Crucifixo Inclinado no Cabo na Bola Suíça', 'cable incline fly (on stability ball)', 'crucifixo-inclinado-no-cabo-na-bola-suica', 'https://static.exercisedb.dev/media/27NNGFr.gif', 'catalogo/crucifixo-inclinado-no-cabo-na-bola-suica--27NNGFr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-no-cabo-na-bola-suica--27NNGFr.gif', ARRAY['peito'], ARRAY['cabo','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Prepare a stability ball at an incline angle.","Step:2 Connect the cable handles to the high pulleys of a cable machine.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:42:13.23281+00', '2026-10-31 19:42:12.825+00'), ('2dImyQ8', 'Rosca de Punho Sentado com Halteres (Palmas para Cima)', 'dumbbell seated palms up wrist curl', 'rosca-de-punho-sentado-com-halteres-palmas-para-cima', 'https://static.exercisedb.dev/media/2dImyQ8.gif', 'catalogo/rosca-de-punho-sentado-com-halteres-palmas-para-cima--2dImyQ8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-sentado-com-halteres-palmas-para-cima--2dImyQ8.gif', ARRAY['antebraços'], ARRAY['halteres'], ARRAY['antebraços'], ARRAY['bíceps','deltoides'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.","Step:2 Set your forearms on your thighs, letting your wrists hang off the edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:13.049673+00', '2026-10-31 19:42:12.907+00'), ('2Dk4xQV', 'Alongamento do Sapo com Balanço', 'rocking frog stretch', 'alongamento-do-sapo-com-balanco', 'https://static.exercisedb.dev/media/2Dk4xQV.gif', 'catalogo/alongamento-do-sapo-com-balanco--2Dk4xQV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-do-sapo-com-balanco--2Dk4xQV.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Begin by kneeling on the ground with your knees about hip width.","Step:2 Set your hands on the ground in front of you for support.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:13.145355+00', '2026-10-31 19:42:13+00'), ('2DxtqHL', 'Levantamento Terra Lateral Unilateral com Barra', 'Barbell Single-Arm Side Deadlift', 'levantamento-terra-lateral-unilateral-com-barra', 'https://static.exercisedb.dev/media/2DxtqHL.gif', 'catalogo/levantamento-terra-lateral-unilateral-com-barra--2DxtqHL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-lateral-unilateral-com-barra--2DxtqHL.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width, holding a barbell in one hand with palms facing down.","Step:2 Keep your spine in a comfortable neutral position and your core engaged.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Drive the hips forward to stand tall without leaning back at the top; switch sides when the set calls for it."]', '2026-10-31 19:42:13.43655+00', '2026-10-31 19:42:13.304+00'), ('2gPfomN', 'Abdominal 3/4', '3/4 sit-up', 'abdominal-3-4', 'https://static.exercisedb.dev/media/2gPfomN.gif', 'catalogo/abdominal-3-4--2gPfomN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-3-4--2gPfomN.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:13.855008+00', '2026-10-31 19:42:13.717+00'), ('2IHEa2T', 'Elevação de Panturrilha no Chão com Barra', 'barbell floor calf raise', 'elevacao-de-panturrilha-no-chao-com-barra', 'https://static.exercisedb.dev/media/2IHEa2T.gif', 'catalogo/elevacao-de-panturrilha-no-chao-com-barra--2IHEa2T.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-no-chao-com-barra--2IHEa2T.gif', ARRAY['panturrilhas'], ARRAY['barra'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Set a barbell on the floor in front of you.","Step:2 Stand and set the balls of your feet on the edge of the barbell, with your heels hanging off.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:13.6611+00', '2026-10-31 19:42:13.527+00'), ('2IxROQ1', 'Tríceps Corda Acima da Cabeça no Cabo', 'cable overhead triceps extension (rope attachment)', 'triceps-corda-acima-da-cabeca-no-cabo', 'https://static.exercisedb.dev/media/2IxROQ1.gif', 'catalogo/triceps-corda-acima-da-cabeca-no-cabo--2IxROQ1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-corda-acima-da-cabeca-no-cabo--2IxROQ1.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Connect a rope to a cable machine at a high position.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:13.596934+00', '2026-10-31 19:42:13.462+00'), ('2JCuFTU', 'Rosca Direta com Halteres Ajoelhado na Bola Suíça', 'Dumbbell Kneeling Biceps Curl Exercise Ball', 'rosca-direta-com-halteres-ajoelhado-na-bola-suica', 'https://static.exercisedb.dev/media/2JCuFTU.gif', 'catalogo/rosca-direta-com-halteres-ajoelhado-na-bola-suica--2JCuFTU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-ajoelhado-na-bola-suica--2JCuFTU.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Get down on the floor with an exercise ball in front of you.","Step:2 Set your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:14.6341+00', '2026-10-31 19:42:14.147+00'), ('2jl9K55', 'Rotação de Coluna', 'spine twist', 'rotacao-de-coluna', 'https://static.exercisedb.dev/media/2jl9K55.gif', 'catalogo/rotacao-de-coluna--2jl9K55.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-coluna--2jl9K55.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Bend your knees and place your feet planted, about hip width.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:14.076239+00', '2026-10-31 19:42:13.942+00'), ('2kattbR', 'Rosca Aranha com Barra W', 'EZ-Bar Spider Curl', 'rosca-aranha-com-barra-w', 'https://static.exercisedb.dev/media/2kattbR.gif', 'catalogo/rosca-aranha-com-barra-w--2kattbR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-aranha-com-barra-w--2kattbR.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold the ez barbell with palms facing up.","Step:2 Set your upper arms on a preacher bench or stability ball, letting your elbows to hang down.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:14.636248+00', '2026-10-31 19:42:14.028+00'), ('2KGnL6M', 'Desenvolvimento Unilateral na Máquina', 'Machine Single-Arm Shoulder Press', 'desenvolvimento-unilateral-na-maquina', 'https://static.exercisedb.dev/media/2KGnL6M.gif', 'catalogo/desenvolvimento-unilateral-na-maquina--2KGnL6M.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-unilateral-na-maquina--2KGnL6M.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the lever handle with one hand and position your elbow at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:14.600885+00', '2026-10-31 19:42:14.084+00'), ('2kr2lWy', 'Flexão de Braço no Bosu', 'push-up (bosu ball)', 'flexao-de-braco-no-bosu', 'https://static.exercisedb.dev/media/2kr2lWy.gif', 'catalogo/flexao-de-braco-no-bosu--2kr2lWy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-no-bosu--2kr2lWy.gif', ARRAY['peito'], ARRAY['bosu'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Set the bosu ball on the ground with the flat side facing up.","Step:2 Set yourself in a push-up position with your hands on the outer edges of the bosu ball.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:14.635324+00', '2026-10-31 19:42:14.291+00'), ('2LQkNPW', 'Alongamento de Flexores do Quadril na Bola Suíça', 'exercise ball hip flexor stretch', 'alongamento-de-flexores-do-quadril-na-bola-suica', 'https://static.exercisedb.dev/media/2LQkNPW.gif', 'catalogo/alongamento-de-flexores-do-quadril-na-bola-suica--2LQkNPW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-flexores-do-quadril-na-bola-suica--2LQkNPW.gif', ARRAY['coxas'], ARRAY['bola suíça'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa'], '["Step:1 Set the stability ball on the ground and kneel in front of it.","Step:2 Set your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:15.18855+00', '2026-10-31 19:42:15.061+00'), ('2NImIAG', 'Rosca Direta com Halteres na Bola Suíça com Perna Elevada', 'Dumbbell Biceps Curl On Exercise Ball With Leg Raised', 'rosca-direta-com-halteres-na-bola-suica-com-perna-elevada', 'https://static.exercisedb.dev/media/2NImIAG.gif', 'catalogo/rosca-direta-com-halteres-na-bola-suica-com-perna-elevada--2NImIAG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-na-bola-suica-com-perna-elevada--2NImIAG.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing forward and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:15.290331+00', '2026-10-31 19:42:15.142+00'), ('2NpxjC1', 'Rosca Martelo com Halteres', 'dumbbell hammer curl', 'rosca-martelo-com-halteres', 'https://static.exercisedb.dev/media/2NpxjC1.gif', 'catalogo/rosca-martelo-com-halteres--2NpxjC1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-com-halteres--2NpxjC1.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.","Step:2 Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:15.519713+00', '2026-10-31 19:42:15.383+00'), ('2ORFMoR', 'Panturrilha no Hack', 'hack calf raise', 'panturrilha-no-hack', 'https://static.exercisedb.dev/media/2ORFMoR.gif', 'catalogo/panturrilha-no-hack--2ORFMoR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-no-hack--2ORFMoR.gif', ARRAY['panturrilhas'], ARRAY['máquina hack'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set the sled machine to a comfortable weight.","Step:2 Step onto the sled machine with your toes on the platform and your heels hanging off.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:15.438608+00', '2026-10-31 19:42:15.303+00'), ('2Pya1cP', 'Supino Declinado no Cabo', 'cable decline press', 'supino-declinado-no-cabo', 'https://static.exercisedb.dev/media/2Pya1cP.gif', 'catalogo/supino-declinado-no-cabo--2Pya1cP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-no-cabo--2Pya1cP.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the cable machine to a decline position.","Step:2 Take a seat on the decline bench facing the cable machine.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:15.535899+00', '2026-10-31 19:42:15.159+00'), ('2Qh2J1e', 'Leg Press 45°', 'Sled 45° Leg Press', 'leg-press-45', 'https://static.exercisedb.dev/media/2Qh2J1e.gif', 'catalogo/leg-press-45--2Qh2J1e.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-45--2Qh2J1e.gif', ARRAY['coxas'], ARRAY['máquina de leg press'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Step:2 Take a seat on the sled machine with your back flat against the backrest and your feet about shoulder width on the footplate.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Stop the descent before the hips lift from the seat.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:42:15.741872+00', '2026-10-31 19:42:15.61+00'), ('2qTvJAZ', 'Rosca de Punho Invertida por Trás das Costas em Pé com Barra', 'barbell standing back wrist curl', 'rosca-de-punho-invertida-por-tras-das-costas-em-pe-com-barra', 'https://static.exercisedb.dev/media/2qTvJAZ.gif', 'catalogo/rosca-de-punho-invertida-por-tras-das-costas-em-pe-com-barra--2qTvJAZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-invertida-por-tras-das-costas-em-pe-com-barra--2qTvJAZ.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['bíceps','deltoides'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing down.","Step:2 Rest the barbell on the back of your hands with your palms facing down and your fingers pointing toward your body.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:16.055953+00', '2026-10-31 19:42:15.924+00'), ('2Ryn564', 'Alongamento Assistido de Reto Femoral em Decúbito Ventral', 'assisted prone rectus femoris stretch', 'alongamento-assistido-de-reto-femoral-em-decubito-ventral', 'https://static.exercisedb.dev/media/2Ryn564.gif', 'catalogo/alongamento-assistido-de-reto-femoral-em-decubito-ventral--2Ryn564.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-assistido-de-reto-femoral-em-decubito-ventral--2Ryn564.gif', ARRAY['abdômen'], ARRAY['assistido'], ARRAY['abdominais'], ARRAY['quadríceps'], '["Step:1 Position yourself face down on the ground with your legs straight.","Step:2 Before moving, bend your right knee and reach back with your right hand to grab your right foot or ankle.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:16.02431+00', '2026-10-31 19:42:15.891+00'), ('2sQGZ5b', 'Rosca Martelo Unilateral em Pé com Halter', 'Dumbbell Single-Arm Standing Hammer Curl', 'rosca-martelo-unilateral-em-pe-com-halter', 'https://static.exercisedb.dev/media/2sQGZ5b.gif', 'catalogo/rosca-martelo-unilateral-em-pe-com-halter--2sQGZ5b.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-unilateral-em-pe-com-halter--2sQGZ5b.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.","Step:2 Hold your elbows near your torso and your upper arms stationary.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:16.332358+00', '2026-10-31 19:42:15.942+00'), ('2zNKRUB', 'Círculos de punho', 'wrist circles', 'circulos-de-punho', 'https://static.exercisedb.dev/media/2zNKRUB.gif', 'catalogo/circulos-de-punho--2zNKRUB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/circulos-de-punho--2zNKRUB.gif', ARRAY['antebraços'], ARRAY['peso corporal'], ARRAY['antebraços'], ARRAY['mãos','punhos'], '["Step:1 Reach your arms straight out in front of you.","Step:2 Close both hands into fists.","Step:3 Relax the limb above the joint you are circling.","Step:4 Circle the joint slowly in one direction, then reverse the circle without forcing the range.","Step:5 Keep the rest of the limb still while the joint traces each circle.","Step:6 Switch to the other side after completing both directions."]', '2026-10-31 19:42:16.316181+00', '2026-10-31 19:42:16.171+00'), ('33AzZeV', 'Elevação frontal com barra e pullover', 'barbell front raise and pullover', 'elevacao-frontal-com-barra-e-pullover', 'https://static.exercisedb.dev/media/33AzZeV.gif', 'catalogo/elevacao-frontal-com-barra-e-pullover--33AzZeV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-barra-e-pullover--33AzZeV.gif', ARRAY['peitoral'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down.","Step:2 Maintain straight arms and raise the barbell in front of you until it reaches shoulder height.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:42:16.38788+00', '2026-10-31 19:42:16.252+00'), ('3d7wHyd', 'Desenvolvimento sentado no banco com halteres', 'dumbbell bench seated press', 'desenvolvimento-sentado-no-banco-com-halteres', 'https://static.exercisedb.dev/media/3d7wHyd.gif', 'catalogo/desenvolvimento-sentado-no-banco-com-halteres--3d7wHyd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-no-banco-com-halteres--3d7wHyd.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, resting on your thighs.","Step:2 Recline and position the dumbbells to the sides of your chest, palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:16.832756+00', '2026-10-31 19:42:16.706+00'), ('3eGE2JC', 'Elevação frontal com halteres', 'dumbbell front raise', 'elevacao-frontal-com-halteres', 'https://static.exercisedb.dev/media/3eGE2JC.gif', 'catalogo/elevacao-frontal-com-halteres--3eGE2JC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-halteres--3eGE2JC.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['bíceps','trapézio'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.","Step:2 With your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:16.59207+00', '2026-10-31 19:42:16.46+00'), ('3omWx6P', 'Rosca alternada com faixa elástica', 'band alternating biceps curl', 'rosca-alternada-com-faixa-elastica', 'https://static.exercisedb.dev/media/3omWx6P.gif', 'catalogo/rosca-alternada-com-faixa-elastica--3omWx6P.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-alternada-com-faixa-elastica--3omWx6P.gif', ARRAY['braços'], ARRAY['faixa elástica'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold the band with palms facing up.","Step:2 Hold your elbows near your sides and With control curl one arm up toward your shoulder, squeezing your biceps at the top.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:16.885977+00', '2026-10-31 19:42:16.76+00'), ('3s4NnTh', 'Rosca direta em pé com halteres', 'dumbbell standing biceps curl', 'rosca-direta-em-pe-com-halteres', 'https://static.exercisedb.dev/media/3s4NnTh.gif', 'catalogo/rosca-direta-em-pe-com-halteres--3s4NnTh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-em-pe-com-halteres--3s4NnTh.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:17.458399+00', '2026-10-31 19:42:17.325+00'), ('3T12T87', 'Tríceps coice com dois halteres em pé inclinado', 'Dumbbell Standing Bent Over Two-Arm Triceps Extension', 'triceps-coice-com-dois-halteres-em-pe-inclinado', 'https://static.exercisedb.dev/media/3T12T87.gif', 'catalogo/triceps-coice-com-dois-halteres-em-pe-inclinado--3T12T87.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-com-dois-halteres-em-pe-inclinado--3T12T87.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides','costas'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend forward at the waist, with your spine steady and your knees soft.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:17.526199+00', '2026-10-31 19:42:17.388+00'), ('3tAXPQ6', 'Rosca de punho inversa com halteres sobre o banco', 'dumbbell over bench reverse wrist curl', 'rosca-de-punho-inversa-com-halteres-sobre-o-banco', 'https://static.exercisedb.dev/media/3tAXPQ6.gif', 'catalogo/rosca-de-punho-inversa-com-halteres-sobre-o-banco--3tAXPQ6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-com-halteres-sobre-o-banco--3tAXPQ6.gif', ARRAY['antebraços'], ARRAY['halteres'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing down.","Step:2 Support the forearms on the bench while leaving the wrists free beyond its edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:17.361529+00', '2026-10-31 19:42:17.231+00'), ('3TZduzM', 'Supino inclinado com barra', 'barbell incline bench press', 'supino-inclinado-com-barra', 'https://static.exercisedb.dev/media/3TZduzM.gif', 'catalogo/supino-inclinado-com-barra--3TZduzM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-barra--3TZduzM.gif', ARRAY['peitoral'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Get onto the bench with your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:17.462768+00', '2026-10-31 19:42:17.314+00'), ('3uj0Ozg', 'Alongamento dinâmico de peitoral', 'Dynamic Chest Stretch', 'alongamento-dinamico-de-peitoral', 'https://static.exercisedb.dev/media/3uj0Ozg.gif', 'catalogo/alongamento-dinamico-de-peitoral--3uj0Ozg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-dinamico-de-peitoral--3uj0Ozg.gif', ARRAY['peitoral'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Stand tall and set your feet about shoulder width.","Step:2 Reach your arms straight out to the sides, parallel to the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:17.734324+00', '2026-10-31 19:42:17.604+00'), ('3XFdb1Z', 'Rosca agachada no cabo', 'cable squatting curl', 'rosca-agachada-no-cabo', 'https://static.exercisedb.dev/media/3XFdb1Z.gif', 'catalogo/rosca-agachada-no-cabo--3XFdb1Z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-agachada-no-cabo--3XFdb1Z.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Connect a cable handle to the lowest setting on a cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:17.932512+00', '2026-10-31 19:42:17.801+00'), ('3xK09Sk', 'Remada agachada com peso corporal', 'bodyweight squatting row', 'remada-agachada-com-peso-corporal', 'https://static.exercisedb.dev/media/3xK09Sk.gif', 'catalogo/remada-agachada-com-peso-corporal--3xK09Sk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-agachada-com-peso-corporal--3xK09Sk.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding onto a sturdy object or suspension trainer with your arms extended.","Step:2 Lower your body into a squat position, with your spine steady and your knees behind your toes.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:18.019519+00', '2026-10-31 19:42:17.892+00'), ('3ZflifB', 'Tríceps pulley', 'cable pushdown', 'triceps-pulley', 'https://static.exercisedb.dev/media/3ZflifB.gif', 'catalogo/triceps-pulley--3ZflifB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-pulley--3ZflifB.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Connect a straight bar to a high pulley cable machine.","Step:2 Face the machine with your feet about shoulder width and a slight bend in your knees.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the elbows close to the body instead of letting the shoulders swing.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:42:18.820873+00', '2026-10-31 19:42:18.42+00'), ('4c9BhzB', 'Puxada frontal com triângulo', 'cable lateral pulldown with v-bar', 'puxada-frontal-com-triangulo', 'https://static.exercisedb.dev/media/4c9BhzB.gif', 'catalogo/puxada-frontal-com-triangulo--4c9BhzB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-frontal-com-triangulo--4c9BhzB.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['grande dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Sit down on the cable pulldown machine and grab the v-bar attachment with palms facing down.","Step:2 Set the knee pad so that your thighs are secured under it.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:42:18.073177+00', '2026-10-31 19:42:17.941+00'), ('4CBIBOM', 'Tríceps testa atrás da nuca sentado com barra pegada fechada', 'Barbell Seated Close-Grip Behind Neck Triceps Extension', 'triceps-testa-atras-da-nuca-sentado-com-barra-pegada-fechada', 'https://static.exercisedb.dev/media/4CBIBOM.gif', 'catalogo/triceps-testa-atras-da-nuca-sentado-com-barra-pegada-fechada--4CBIBOM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-atras-da-nuca-sentado-com-barra-pegada-fechada--4CBIBOM.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take hold of the barbell with a close grip behind your neck, palms facing forward.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:18.310236+00', '2026-10-31 19:42:18.182+00'), ('4cWjYEN', 'Flexão fechada na bola de estabilidade', 'narrow push-up on exercise ball', 'flexao-fechada-na-bola-de-estabilidade', 'https://static.exercisedb.dev/media/4cWjYEN.gif', 'catalogo/flexao-fechada-na-bola-de-estabilidade--4cWjYEN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-fechada-na-bola-de-estabilidade--4cWjYEN.gif', ARRAY['braços'], ARRAY['bola de estabilidade'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than about shoulder width.","Step:2 Brace your trunk and keep your body in a straight line from head to toe.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:18.598021+00', '2026-10-31 19:42:18.468+00'), ('4dF3maG', 'Rosca martelo unilateral no banco Scott com halter', 'Dumbbell Single-Arm Hammer Preacher Curl', 'rosca-martelo-unilateral-no-banco-scott-com-halter', 'https://static.exercisedb.dev/media/4dF3maG.gif', 'catalogo/rosca-martelo-unilateral-no-banco-scott-com-halter--4dF3maG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-unilateral-no-banco-scott-com-halter--4dF3maG.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Step:2 Take hold of the dumbbell with a neutral grip (palms facing your body).","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:18.62303+00', '2026-10-31 19:42:18.495+00'), ('4dUn2iv', 'Rosca direta em pé com barra pegada fechada', 'Barbell Standing Close-Grip Curl', 'rosca-direta-em-pe-com-barra-pegada-fechada', 'https://static.exercisedb.dev/media/4dUn2iv.gif', 'catalogo/rosca-direta-em-pe-com-barra-pegada-fechada--4dUn2iv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-em-pe-com-barra-pegada-fechada--4dUn2iv.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing up, hands close together.","Step:2 Hold your elbows near your torso and your upper arms stationary throughout the movement.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:19.013929+00', '2026-10-31 19:42:18.883+00'), ('4f8RXP8', 'Remada em pé no cabo com triângulo', 'cable standing row (v-bar)', 'remada-em-pe-no-cabo-com-triangulo', 'https://static.exercisedb.dev/media/4f8RXP8.gif', 'catalogo/remada-em-pe-no-cabo-com-triangulo--4f8RXP8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-no-cabo-com-triangulo--4f8RXP8.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the v-bar attachment with palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:18.767239+00', '2026-10-31 19:42:18.637+00'), ('4GqRrAk', 'Flexão superman', 'superman push-up', 'flexao-superman', 'https://static.exercisedb.dev/media/4GqRrAk.gif', 'catalogo/flexao-superman--4GqRrAk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-superman--4GqRrAk.gif', ARRAY['peitoral'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['core','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your feet together.","Step:2 Brace your trunk and lower your body toward the ground, keeping your elbows close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:19.02744+00', '2026-10-31 19:42:18.898+00'), ('4hATdoB', 'Rosca Scott unilateral na corda no cabo', 'Single-Arm Cable Rope Preacher Curl', 'rosca-scott-unilateral-na-corda-no-cabo', 'https://static.exercisedb.dev/media/4hATdoB.gif', 'catalogo/rosca-scott-unilateral-na-corda-no-cabo--4hATdoB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-unilateral-na-corda-no-cabo--4hATdoB.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Connect a rope handle to a low pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:19.352151+00', '2026-10-31 19:42:19.218+00'), ('4ievMJ9', 'Tríceps Curvado Sentado com Halteres', 'dumbbell seated bent over triceps extension', 'triceps-curvado-sentado-com-halteres', 'https://static.exercisedb.dev/media/4ievMJ9.gif', 'catalogo/triceps-curvado-sentado-com-halteres--4ievMJ9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-curvado-sentado-com-halteres--4ievMJ9.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides','costas'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand.","Step:2 Bend forward at the waist, with your spine steady and your head up.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:19.651054+00', '2026-10-31 19:42:19.508+00'), ('4IKbhHV', 'Puxada Alternada na Polia', 'alternate lateral pulldown', 'puxada-alternada-na-polia', 'https://static.exercisedb.dev/media/4IKbhHV.gif', 'catalogo/puxada-alternada-na-polia--4IKbhHV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-alternada-na-polia--4IKbhHV.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides'], '["Step:1 Take a seat on the cable machine with your back straight and feet planted.","Step:2 Hold the handles with palms facing down, just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it."]', '2026-10-31 19:42:19.669475+00', '2026-10-31 19:42:19.302+00'), ('4Jc36XM', 'Rosca de Punho Inversa Unilateral com Halter no Banco', 'Dumbbell Over Bench Single-Arm Reverse Wrist Curl', 'rosca-de-punho-inversa-unilateral-com-halter-no-banco', 'https://static.exercisedb.dev/media/4Jc36XM.gif', 'catalogo/rosca-de-punho-inversa-unilateral-com-halter-no-banco--4Jc36XM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-unilateral-com-halter-no-banco--4Jc36XM.gif', ARRAY['antebraços'], ARRAY['halteres'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing down.","Step:2 Set your forearm on the bench with your wrist hanging off the edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:42:19.754977+00', '2026-10-31 19:42:19.628+00'), ('4Jt8QsQ', 'Flexão de Braço com Apoio nos Antebraços', 'push-up on lower arms', 'flexao-de-braco-com-apoio-nos-antebracos', 'https://static.exercisedb.dev/media/4Jt8QsQ.gif', 'catalogo/flexao-de-braco-com-apoio-nos-antebracos--4Jt8QsQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-apoio-nos-antebracos--4Jt8QsQ.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Begin in a plank position with your forearms on the ground and elbows directly below your shoulders.","Step:2 Brace your trunk and keep your body in a straight line from head to toe.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:19.590865+00', '2026-10-31 19:42:19.461+00'), ('4KJEpzb', 'Clean com Kettlebell Invertido a Partir da Posição Suspensa', 'kettlebell bottoms up clean from the hang position', 'clean-com-kettlebell-invertido-a-partir-da-posicao-suspensa', 'https://static.exercisedb.dev/media/4KJEpzb.gif', 'catalogo/clean-com-kettlebell-invertido-a-partir-da-posicao-suspensa--4KJEpzb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/clean-com-kettlebell-invertido-a-partir-da-posicao-suspensa--4KJEpzb.gif', ARRAY['braços'], ARRAY['kettlebell'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:42:19.915013+00', '2026-10-31 19:42:19.786+00'), ('4Leypho', 'Skier com Barra', 'barbell skier', 'skier-com-barra', 'https://static.exercisedb.dev/media/4Leypho.gif', 'catalogo/skier-com-barra--4Leypho.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/skier-com-barra--4Leypho.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell ahead of your thighs with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:42:20.152243+00', '2026-10-31 19:42:20.023+00'), ('4LIG9xr', 'Rosca Scott Inversa com Barra', 'barbell reverse preacher curl', 'rosca-scott-inversa-com-barra', 'https://static.exercisedb.dev/media/4LIG9xr.gif', 'catalogo/rosca-scott-inversa-com-barra--4LIG9xr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-inversa-com-barra--4LIG9xr.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with palms facing down.","Step:2 With your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:20.507145+00', '2026-10-31 19:42:20.368+00'), ('4LoWllp', 'Puxada com Pegada Fechada com Elástico Fixado Atrás', 'Band Fixed Back Close-Grip Pulldown', 'puxada-com-pegada-fechada-com-elastico-fixado-atras', 'https://static.exercisedb.dev/media/4LoWllp.gif', 'catalogo/puxada-com-pegada-fechada-com-elastico-fixado-atras--4LoWllp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-com-pegada-fechada-com-elastico-fixado-atras--4LoWllp.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Connect the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Step:2 Sit down on a bench or chair facing the band, with your feet planted and your knees bent.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:42:20.148681+00', '2026-10-31 19:42:20.019+00'), ('4Ml7QFO', 'Elevação de Pernas Estendidas na Barra Fixa', 'Hanging Straight-Leg Raise', 'elevacao-de-pernas-estendidas-na-barra-fixa', 'https://static.exercisedb.dev/media/4Ml7QFO.gif', 'catalogo/elevacao-de-pernas-estendidas-na-barra-fixa--4Ml7QFO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-estendidas-na-barra-fixa--4Ml7QFO.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your legs up in front of you, keeping them straight.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:42:20.480705+00', '2026-10-31 19:42:20.111+00'), ('4OaumBr', 'Remada Suspensa', 'suspended row', 'remada-suspensa', 'https://static.exercisedb.dev/media/4OaumBr.gif', 'catalogo/remada-suspensa--4OaumBr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-suspensa--4OaumBr.gif', ARRAY['costas'], ARRAY['peso corporal','TRX'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Prepare a suspension trainer at an appropriate height.","Step:2 Face the anchor point from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:20.449125+00', '2026-10-31 19:42:20.321+00'), ('4U7iLb5', 'Pullover na Máquina', 'Machine Pullover', 'pullover-na-maquina', 'https://static.exercisedb.dev/media/4U7iLb5.gif', 'catalogo/pullover-na-maquina--4U7iLb5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-na-maquina--4U7iLb5.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['tríceps','deltoides'], '["Step:1 Set the seat and handles of the leverage machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the pad and Hold the handles with palms facing down.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:42:21.382987+00', '2026-10-31 19:42:20.99+00'), ('4x5Okof', 'Supino Sentado com Elástico', 'Band Seated Chest Press', 'supino-sentado-com-elastico', 'https://static.exercisedb.dev/media/4x5Okof.gif', 'catalogo/supino-sentado-com-elastico--4x5Okof.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-sentado-com-elastico--4x5Okof.gif', ARRAY['peito'], ARRAY['elástico'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on a chair or bench with your back straight and feet planted.","Step:2 Take hold of the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:20.984501+00', '2026-10-31 19:42:20.845+00'), ('50BETrz', 'Barra Fixa com Pegada Fechada para Bíceps', 'biceps narrow pull-ups', 'barra-fixa-com-pegada-fechada-para-biceps', 'https://static.exercisedb.dev/media/50BETrz.gif', 'catalogo/barra-fixa-com-pegada-fechada-para-biceps--50BETrz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-pegada-fechada-para-biceps--50BETrz.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.","Step:2 Brace your trunk and pull yourself up toward the bar, focusing on using your biceps to lift your body.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:42:21.241409+00', '2026-10-31 19:42:21.112+00'), ('53Ttlck', 'Crucifixo Inverso Deitado com Halteres', 'dumbbell lying rear lateral raise', 'crucifixo-inverso-deitado-com-halteres', 'https://static.exercisedb.dev/media/53Ttlck.gif', 'catalogo/crucifixo-inverso-deitado-com-halteres--53Ttlck.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-deitado-com-halteres--53Ttlck.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Position yourself face down on a flat bench with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight down toward the floor, keeping a slight bend in your elbows.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:21.039207+00', '2026-10-31 19:42:20.91+00'), ('5bpPTHv', 'Agachamento Pistol com Kettlebell', 'kettlebell pistol squat', 'agachamento-pistol-com-kettlebell', 'https://static.exercisedb.dev/media/5bpPTHv.gif', 'catalogo/agachamento-pistol-com-kettlebell--5bpPTHv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-pistol-com-kettlebell--5bpPTHv.gif', ARRAY['coxas'], ARRAY['kettlebell'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell ahead of your chest with both hands.","Step:2 Before moving, lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Extend the free leg ahead of you as you squat on the standing leg, keeping its heel grounded.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:21.708761+00', '2026-10-31 19:42:21.578+00'), ('5BZHW9s', 'Agachamento com Alcance Acima da Cabeça e Rotação', 'squat to overhead reach with twist', 'agachamento-com-alcance-acima-da-cabeca-e-rotacao', 'https://static.exercisedb.dev/media/5BZHW9s.gif', 'catalogo/agachamento-com-alcance-acima-da-cabeca-e-rotacao--5BZHW9s.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-alcance-acima-da-cabeca-e-rotacao--5BZHW9s.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','core'], '["Step:1 Stand and set your feet about shoulder width and toes slightly turned out.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:21.446095+00', '2026-10-31 19:42:21.315+00'), ('5eLRITT', 'Stiff com Halteres', 'dumbbell stiff leg deadlift', 'stiff-com-halteres', 'https://static.exercisedb.dev/media/5eLRITT.gif', 'catalogo/stiff-com-halteres--5eLRITT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stiff-com-halteres--5eLRITT.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 With your back straight and your core engaged, hinge at the hips and lower the dumbbells toward the ground, letting a slight bend in your knees.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:42:21.635404+00', '2026-10-31 19:42:21.487+00'), ('5fKX7wi', 'Tríceps Testa Unilateral Sentado com Pegada Invertida e Halter', 'Dumbbell Seated Reverse-Grip Single-Arm Overhead Triceps Extension', 'triceps-testa-unilateral-sentado-com-pegada-invertida-e-halter', 'https://static.exercisedb.dev/media/5fKX7wi.gif', 'catalogo/triceps-testa-unilateral-sentado-com-pegada-invertida-e-halter--5fKX7wi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-unilateral-sentado-com-pegada-invertida-e-halter--5fKX7wi.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell with palms facing up and extend your arm straight up overhead.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:42:22.255004+00', '2026-10-31 19:42:22.127+00'), ('5KLbZWx', 'Desenvolvimento Alternado com Kettlebell', 'kettlebell alternating press', 'desenvolvimento-alternado-com-kettlebell', 'https://static.exercisedb.dev/media/5KLbZWx.gif', 'catalogo/desenvolvimento-alternado-com-kettlebell--5KLbZWx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-alternado-com-kettlebell--5KLbZWx.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.","Step:2 Before moving, press one kettlebell overhead, fully extending your arm.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:22.268189+00', '2026-10-31 19:42:22.13+00'), ('5MRH8H2', 'Ski Step', 'ski step', 'ski-step', 'https://static.exercisedb.dev/media/5MRH8H2.gif', 'catalogo/ski-step--5MRH8H2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/ski-step--5MRH8H2.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Bend your knees slightly and Keep your spine in a comfortable neutral position.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Bound from side to side, landing on one foot as the other leg sweeps behind it.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:42:22.308271+00', '2026-10-31 19:42:22.181+00'), ('5uFK1xr', 'Tríceps Francês Sentado com Barra', 'barbell seated overhead triceps extension', 'triceps-frances-sentado-com-barra', 'https://static.exercisedb.dev/media/5uFK1xr.gif', 'catalogo/triceps-frances-sentado-com-barra--5uFK1xr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-sentado-com-barra--5uFK1xr.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a barbell with palms facing down, hands about shoulder width, and raise it overhead.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:22.472726+00', '2026-10-31 19:42:22.343+00'), ('5v7KYld', 'Supino inclinado no Smith', 'smith incline bench press', 'supino-inclinado-no-smith', 'https://static.exercisedb.dev/media/5v7KYld.gif', 'catalogo/supino-inclinado-no-smith--5v7KYld.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-no-smith--5v7KYld.gif', ARRAY['peito'], ARRAY['Smith'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the bench to a 30-45 degree incline.","Step:2 Take a seat on the bench with your back flat against the pad and feet firmly on the ground.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:22.532018+00', '2026-10-31 19:42:22.403+00'), ('5VCj6iH', 'Agachamento hack com barra', 'barbell hack squat', 'agachamento-hack-com-barra', 'https://static.exercisedb.dev/media/5VCj6iH.gif', 'catalogo/agachamento-hack-com-barra--5VCj6iH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-hack-com-barra--5VCj6iH.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width and your toes slightly turned out.","Step:2 Take hold of the barbell behind your legs, resting it on your upper thighs.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:22.832889+00', '2026-10-31 19:42:22.69+00'), ('5vfAI0I', 'Desenvolvimento Scott com halteres', 'dumbbell scott press', 'desenvolvimento-scott-com-halteres', 'https://static.exercisedb.dev/media/5vfAI0I.gif', 'catalogo/desenvolvimento-scott-com-halteres--5vfAI0I.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-scott-com-halteres--5vfAI0I.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing forward.","Step:2 Before moving, raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:22.710243+00', '2026-10-31 19:42:22.573+00'), ('5VXmnV5', 'Prancha lateral inclinada com peso corporal', 'bodyweight incline side plank', 'prancha-lateral-inclinada-com-peso-corporal', 'https://static.exercisedb.dev/media/5VXmnV5.gif', 'catalogo/prancha-lateral-inclinada-com-peso-corporal--5VXmnV5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-lateral-inclinada-com-peso-corporal--5VXmnV5.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','deltoides'], '["Step:1 Begin by lying on your side with your legs extended and stacked on top of each other.","Step:2 Set your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:42:23.238306+00', '2026-10-31 19:42:23.1+00'), ('5WiFcYk', 'Avanço com peso e balanço', 'weighted lunge with swing', 'avanco-com-peso-e-balanco', 'https://static.exercisedb.dev/media/5WiFcYk.gif', 'catalogo/avanco-com-peso-e-balanco--5WiFcYk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-peso-e-balanco--5WiFcYk.gif', ARRAY['coxas'], ARRAY['peso adicional'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a weight in each hand.","Step:2 Step forward with your right foot, lowering your body into a lunge position.","Step:3 Set the shoulders and let the weight move back between the legs as the hips hinge.","Step:4 Hinge back, then drive the hips forward to send the weight up; let the arms guide it.","Step:5 Let the hips, not the shoulders, provide the power.","Step:6 Let the weight fall naturally and hinge again for the next swing."]', '2026-10-31 19:42:23.151079+00', '2026-10-31 19:42:23.021+00'), ('61GrD55', 'Rosca deitado na polia com pegada fechada', 'cable lying close-grip curl', 'rosca-deitado-na-polia-com-pegada-fechada', 'https://static.exercisedb.dev/media/61GrD55.gif', 'catalogo/rosca-deitado-na-polia-com-pegada-fechada--61GrD55.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-deitado-na-polia-com-pegada-fechada--61GrD55.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Connect a straight bar to a low pulley cable machine.","Step:2 Lie face up on a flat bench with your feet planted.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:23.389479+00', '2026-10-31 19:42:23.257+00'), ('62Nw60O', 'Avanço para trás com barra', 'barbell rear lunge', 'avanco-para-tras-com-barra', 'https://static.exercisedb.dev/media/62Nw60O.gif', 'catalogo/avanco-para-tras-com-barra--62Nw60O.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-para-tras-com-barra--62Nw60O.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell across your upper back.","Step:2 Step backward with your right foot, landing on the ball of your foot.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:42:23.293284+00', '2026-10-31 19:42:23.164+00'), ('641mIfk', 'Supino inclinado com barra e pegada invertida', 'barbell incline reverse-grip press', 'supino-inclinado-com-barra-e-pegada-invertida', 'https://static.exercisedb.dev/media/641mIfk.gif', 'catalogo/supino-inclinado-com-barra-e-pegada-invertida--641mIfk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-barra-e-pegada-invertida--641mIfk.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Recline on the bench and Hold the barbell with a reverse grip, hands just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:23.71405+00', '2026-10-31 19:42:23.579+00'), ('67n3r98', 'Desenvolvimento de ombros na máquina', 'Machine Shoulder Press', 'desenvolvimento-de-ombros-na-maquina', 'https://static.exercisedb.dev/media/67n3r98.gif', 'catalogo/desenvolvimento-de-ombros-na-maquina--67n3r98.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-de-ombros-na-maquina--67n3r98.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and position your hands at shoulder level.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:23.710913+00', '2026-10-31 19:42:23.585+00'), ('6bOA1Oi', 'Flexão lateral de tronco com peso na bola suíça', 'weighted side bend (on stability ball)', 'flexao-lateral-de-tronco-com-peso-na-bola-suica', 'https://static.exercisedb.dev/media/6bOA1Oi.gif', 'catalogo/flexao-lateral-de-tronco-com-peso-na-bola-suica--6bOA1Oi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-lateral-de-tronco-com-peso-na-bola-suica--6bOA1Oi.gif', ARRAY['abdômen'], ARRAY['peso adicional','bola suíça'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on a stability ball with your feet about shoulder width and flat on the ground.","Step:2 Take a weight in one hand and place your other hand on your hip.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:42:23.818625+00', '2026-10-31 19:42:23.69+00'), ('6cKQC5E', 'Remada alta unilateral com halter', 'Dumbbell Single-Arm Upright Row', 'remada-alta-unilateral-com-halter', 'https://static.exercisedb.dev/media/6cKQC5E.gif', 'catalogo/remada-alta-unilateral-com-halter--6cKQC5E.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-unilateral-com-halter--6cKQC5E.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand with palms facing down.","Step:2 Let the dumbbell hang at arm''s length ahead of your thighs, with your palm facing your body.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:42:23.848883+00', '2026-10-31 19:42:23.714+00'), ('6CKUx7o', 'Tríceps testa com barra W e pegada fechada atrás da cabeça', 'EZ-Bar Lying Close-Grip Triceps Extension Behind Head', 'triceps-testa-com-barra-w-e-pegada-fechada-atras-da-cabeca', 'https://static.exercisedb.dev/media/6CKUx7o.gif', 'catalogo/triceps-testa-com-barra-w-e-pegada-fechada-atras-da-cabeca--6CKUx7o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra-w-e-pegada-fechada-atras-da-cabeca--6CKUx7o.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take hold of the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:24.324876+00', '2026-10-31 19:42:24.193+00'), ('6e2DcYX', 'Elevação de ombro inclinada com halteres', 'dumbbell incline shoulder raise', 'elevacao-de-ombro-inclinada-com-halteres', 'https://static.exercisedb.dev/media/6e2DcYX.gif', 'catalogo/elevacao-de-ombro-inclinada-com-halteres--6e2DcYX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-ombro-inclinada-com-halteres--6e2DcYX.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['serrátil anterior'], ARRAY['deltoides','trapézio'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Step:2 Set the dumbbells on your thighs and lean back onto the bench.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:24.3135+00', '2026-10-31 19:42:24.183+00'), ('6em2Dxj', 'Rosca martelo alternada sentado com halteres', 'dumbbell alternate seated hammer curl', 'rosca-martelo-alternada-sentado-com-halteres', 'https://static.exercisedb.dev/media/6em2Dxj.gif', 'catalogo/rosca-martelo-alternada-sentado-com-halteres--6em2Dxj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-alternada-sentado-com-halteres--6em2Dxj.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Step:2 Keep your spine in a comfortable neutral position and your elbows close to your torso.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:24.318739+00', '2026-10-31 19:42:24.184+00'), ('6FMU51h', 'Salto de semiagachamento', 'Semi Squat Jump', 'salto-de-semiagachamento', 'https://static.exercisedb.dev/media/6FMU51h.gif', 'catalogo/salto-de-semiagachamento--6FMU51h.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/salto-de-semiagachamento--6FMU51h.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, bend your knees and lower your body into a squat position.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:24.305883+00', '2026-10-31 19:42:24.174+00'), ('6HiHHe0', 'Panturrilha em pé com barra e balanço', 'barbell standing rocking leg calf raise', 'panturrilha-em-pe-com-barra-e-balanco', 'https://static.exercisedb.dev/media/6HiHHe0.gif', 'catalogo/panturrilha-em-pe-com-barra-e-balanco--6HiHHe0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-com-barra-e-balanco--6HiHHe0.gif', ARRAY['panturrilhas'], ARRAY['barra'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell across your upper back.","Step:2 Before moving, raise your heels off the ground as high as possible, balancing on the balls of your feet.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:24.456796+00', '2026-10-31 19:42:24.329+00'), ('6HmFgmx', 'Panturrilha em pé na escada', 'standing calf raise (on a staircase)', 'panturrilha-em-pe-na-escada', 'https://static.exercisedb.dev/media/6HmFgmx.gif', 'catalogo/panturrilha-em-pe-na-escada--6HmFgmx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-na-escada--6HmFgmx.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Step onto the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Step:2 Use a railing or wall for balance if needed.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:24.886169+00', '2026-10-31 19:42:24.759+00'), ('6kSxYnw', 'Rosca de punho com barra', 'barbell wrist curl', 'rosca-de-punho-com-barra', 'https://static.exercisedb.dev/media/6kSxYnw.gif', 'catalogo/rosca-de-punho-com-barra--6kSxYnw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-com-barra--6kSxYnw.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; your knees bent.","Step:2 Take a barbell with palms facing up, and your hands about shoulder width.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:25.172478+00', '2026-10-31 19:42:25.042+00'), ('6MaEjVA', 'Panturrilha em pé no Smith', 'smith standing leg calf raise', 'panturrilha-em-pe-no-smith', 'https://static.exercisedb.dev/media/6MaEjVA.gif', 'catalogo/panturrilha-em-pe-no-smith--6MaEjVA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-no-smith--6MaEjVA.gif', ARRAY['panturrilhas'], ARRAY['Smith'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set the smith machine bar to a height that allows you to stand with your feet planted and your shoulders under the bar.","Step:2 Set yourself under the bar with your feet about shoulder width and your toes pointing forward.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:25.27845+00', '2026-10-31 19:42:25.145+00'), ('6MfS53i', 'Extensão de tríceps unilateral deitado com halter', 'dumbbell lying single extension', 'extensao-de-triceps-unilateral-deitado-com-halter', 'https://static.exercisedb.dev/media/6MfS53i.gif', 'catalogo/extensao-de-triceps-unilateral-deitado-com-halter--6MfS53i.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-unilateral-deitado-com-halter--6MfS53i.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with a dumbbell in one hand and your arm straight above your chest.","Step:2 Lower the dumbbell in a controlled manner toward your forehead, keeping your upper arm stationary.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:25.016105+00', '2026-10-31 19:42:24.886+00'), ('6pTkI99', 'Arranco unilateral com halter', 'Dumbbell Single-Arm Snatch', 'arranco-unilateral-com-halter', 'https://static.exercisedb.dev/media/6pTkI99.gif', 'catalogo/arranco-unilateral-com-halter--6pTkI99.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arranco-unilateral-com-halter--6pTkI99.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:42:25.032246+00', '2026-10-31 19:42:24.905+00'), ('6sMAmNv', 'Rosca aranha inversa com halteres', 'dumbbell reverse spider curl', 'rosca-aranha-inversa-com-halteres', 'https://static.exercisedb.dev/media/6sMAmNv.gif', 'catalogo/rosca-aranha-inversa-com-halteres--6sMAmNv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-aranha-inversa-com-halteres--6sMAmNv.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your body and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:25.501095+00', '2026-10-31 19:42:25.374+00'), ('6sYyrRX', 'Rotação de quadril deitado com joelhos flexionados', 'Bent Knee Lying Twist', 'rotacao-de-quadril-deitado-com-joelhos-flexionados', 'https://static.exercisedb.dev/media/6sYyrRX.gif', 'catalogo/rotacao-de-quadril-deitado-com-joelhos-flexionados--6sYyrRX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-quadril-deitado-com-joelhos-flexionados--6sYyrRX.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Reach your arms out to the sides, perpendicular to your body.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:25.931482+00', '2026-10-31 19:42:25.795+00'), ('6t00BsF', 'Supino inclinado unilateral na polia com bola suíça', 'Cable Single-Arm Incline Press On Exercise Ball', 'supino-inclinado-unilateral-na-polia-com-bola-suica', 'https://static.exercisedb.dev/media/6t00BsF.gif', 'catalogo/supino-inclinado-unilateral-na-polia-com-bola-suica--6t00BsF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-unilateral-na-polia-com-bola-suica--6t00BsF.gif', ARRAY['peito'], ARRAY['polia','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back resting against an incline bench.","Step:2 Take a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:25.629174+00', '2026-10-31 19:42:25.498+00'), ('6TG6x2w', 'Rosca direta com barra W', 'EZ-Bar Curl', 'rosca-direta-com-barra-w', 'https://static.exercisedb.dev/media/6TG6x2w.gif', 'catalogo/rosca-direta-com-barra-w--6TG6x2w.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra-w--6TG6x2w.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up.","Step:2 Hold your elbows near your torso and your upper arms stationary throughout the movement.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:25.744047+00', '2026-10-31 19:42:25.614+00'), ('6YUfHPL', 'Agachamento livre com peso corporal', 'quads (bodyweight squat)', 'agachamento-livre-com-peso-corporal', 'https://static.exercisedb.dev/media/6YUfHPL.gif', 'catalogo/agachamento-livre-com-peso-corporal--6YUfHPL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-livre-com-peso-corporal--6YUfHPL.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['posteriores da coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:26.092072+00', '2026-10-31 19:42:25.965+00'), ('6ZCiYWQ', 'Abdominal com braços no peito', 'sit-up with arms on chest', 'abdominal-com-bracos-no-peito', 'https://static.exercisedb.dev/media/6ZCiYWQ.gif', 'catalogo/abdominal-com-bracos-no-peito--6ZCiYWQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-bracos-no-peito--6ZCiYWQ.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Fold your arms over your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:26.210774+00', '2026-10-31 19:42:26.076+00'), ('72BC5Za', 'Barra fixa arqueiro', 'Archer Pull-Up', 'barra-fixa-arqueiro', 'https://static.exercisedb.dev/media/72BC5Za.gif', 'catalogo/barra-fixa-arqueiro--72BC5Za.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-arqueiro--72BC5Za.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Begin by hanging from a pull-up bar with palms facing down, just beyond shoulder width.","Step:2 Brace your trunk and pull your shoulder blades down and back.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:42:26.407421+00', '2026-10-31 19:42:26.039+00'), ('75Bgtjy', 'Agachamento potty', 'potty squat', 'agachamento-potty', 'https://static.exercisedb.dev/media/75Bgtjy.gif', 'catalogo/agachamento-potty--75Bgtjy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-potty--75Bgtjy.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['quadríceps','glúteos'], '["Step:1 Stand and set your feet about shoulder width, toes pointing slightly outward.","Step:2 Before moving, lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:26.329807+00', '2026-10-31 19:42:26.199+00'), ('76vfTdU', 'Step-up unilateral com equilíbrio e rosca direta com halteres', 'Dumbbell Step Up Single Leg Balance With Biceps Curl', 'step-up-unilateral-com-equilibrio-e-rosca-direta-com-halteres', 'https://static.exercisedb.dev/media/76vfTdU.gif', 'catalogo/step-up-unilateral-com-equilibrio-e-rosca-direta-com-halteres--76vfTdU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/step-up-unilateral-com-equilibrio-e-rosca-direta-com-halteres--76vfTdU.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['quadríceps','glúteos','posteriores da coxa'], '["Step:1 Take your place in front of a step or platform with a dumbbell in each hand, palms facing your body.","Step:2 Set your right foot on the step, ensuring your entire foot is in contact with the surface.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:26.498809+00', '2026-10-31 19:42:26.362+00'), ('78VqWQK', 'Supino inclinado com pegada supinada no Smith', 'smith incline reverse-grip press', 'supino-inclinado-com-pegada-supinada-no-smith', 'https://static.exercisedb.dev/media/78VqWQK.gif', 'catalogo/supino-inclinado-com-pegada-supinada-no-smith--78VqWQK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-pegada-supinada-no-smith--78VqWQK.gif', ARRAY['peito'], ARRAY['Smith'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the seat of the smith machine to a comfortable incline angle.","Step:2 Take a seat on the machine with your back against the pad and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:27.046061+00', '2026-10-31 19:42:26.915+00'), ('7aolH9D', 'Arremesso de medicine ball no peito em repetições contínuas', 'medicine ball chest push multiple response', 'arremesso-de-medicine-ball-no-peito-em-repeticoes-continuas', 'https://static.exercisedb.dev/media/7aolH9D.gif', 'catalogo/arremesso-de-medicine-ball-no-peito-em-repeticoes-continuas--7aolH9D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-de-medicine-ball-no-peito-em-repeticoes-continuas--7aolH9D.gif', ARRAY['peito'], ARRAY['medicine ball'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a medicine ball at chest level.","Step:2 Reach your arms forward, pushing the medicine ball away from your chest.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Follow through with the whole body while keeping control of the landing or catch.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:42:26.99879+00', '2026-10-31 19:42:26.872+00'), ('7aVz15j', 'Mergulho de tríceps no chão', 'triceps dips floor', 'mergulho-de-triceps-no-chao', 'https://static.exercisedb.dev/media/7aVz15j.gif', 'catalogo/mergulho-de-triceps-no-chao--7aVz15j.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-de-triceps-no-chao--7aVz15j.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Step:2 Move your butt off the front of the chair with your legs extended in front of you.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:42:27.102724+00', '2026-10-31 19:42:26.972+00'), ('7B4F5nZ', 'Panturrilha na máquina', 'Machine Calf Press', 'panturrilha-na-maquina', 'https://static.exercisedb.dev/media/7B4F5nZ.gif', 'catalogo/panturrilha-na-maquina--7B4F5nZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-na-maquina--7B4F5nZ.gif', ARRAY['panturrilhas'], ARRAY['máquina articulada'], ARRAY['panturrilhas'], ARRAY['posteriores da coxa'], '["Step:1 Set the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Step:2 Set your toes on the lever pad, with your heels hanging off the edge.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:27.215251+00', '2026-10-31 19:42:27.083+00'), ('7Ba7bQ2', 'Clean com kettlebell com as duas mãos', 'Kettlebell Two-Arm Clean', 'clean-com-kettlebell-com-as-duas-maos', 'https://static.exercisedb.dev/media/7Ba7bQ2.gif', 'catalogo/clean-com-kettlebell-com-as-duas-maos--7Ba7bQ2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/clean-com-kettlebell-com-as-duas-maos--7Ba7bQ2.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['trapézio','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell ahead of your thighs with both hands, palms facing toward you.","Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell toward the ground.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:42:27.191622+00', '2026-10-31 19:42:27.064+00'), ('7D5bgLT', 'Rosca Scott sentado com halter', 'dumbbell seated preacher curl', 'rosca-scott-sentado-com-halter', 'https://static.exercisedb.dev/media/7D5bgLT.gif', 'catalogo/rosca-scott-sentado-com-halter--7D5bgLT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-sentado-com-halter--7D5bgLT.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher curl bench with your feet planted.","Step:2 Take a dumbbell in one hand with palms facing up, resting your upper arm against the preacher pad.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:27.575256+00', '2026-10-31 19:42:27.436+00'), ('7E06s6d', 'Flexão com toque no peito', 'Chest Tap Push-Up', 'flexao-com-toque-no-peito', 'https://static.exercisedb.dev/media/7E06s6d.gif', 'catalogo/flexao-com-toque-no-peito--7E06s6d.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-com-toque-no-peito--7E06s6d.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your body in a straight line.","Step:2 Lower your body toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:27.890252+00', '2026-10-31 19:42:27.496+00'), ('7ePTw4B', 'Alongamento de tríceps sentado na bola suíça', 'exercise ball seated triceps stretch', 'alongamento-de-triceps-sentado-na-bola-suica', 'https://static.exercisedb.dev/media/7ePTw4B.gif', 'catalogo/alongamento-de-triceps-sentado-na-bola-suica--7ePTw4B.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-triceps-sentado-na-bola-suica--7ePTw4B.gif', ARRAY['braços'], ARRAY['bola suíça'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a stability ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand and extend your arm straight up above your head.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:27.738907+00', '2026-10-31 19:42:27.612+00'), ('7F1DVzn', 'Puxada frontal na máquina', 'Machine Front Pulldown', 'puxada-frontal-na-maquina', 'https://static.exercisedb.dev/media/7F1DVzn.gif', 'catalogo/puxada-frontal-na-maquina--7F1DVzn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-frontal-na-maquina--7F1DVzn.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down, just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:42:27.819039+00', '2026-10-31 19:42:27.689+00'), ('7f2jsqP', 'Rotação de antebraço unilateral sentado com halter', 'Dumbbell Seated Single-Arm Rotate', 'rotacao-de-antebraco-unilateral-sentado-com-halter', 'https://static.exercisedb.dev/media/7f2jsqP.gif', 'catalogo/rotacao-de-antebraco-unilateral-sentado-com-halter--7f2jsqP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-antebraco-unilateral-sentado-com-halter--7f2jsqP.gif', ARRAY['antebraços'], ARRAY['halteres'], ARRAY['antebraços'], ARRAY['deltoides','bíceps'], '["Step:1 Take a seat on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Step:2 Before moving, raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:42:28.168548+00', '2026-10-31 19:42:28.032+00'), ('7gdLIXa', 'Supino martelo deitado com halteres', 'dumbbell lying hammer press', 'supino-martelo-deitado-com-halteres', 'https://static.exercisedb.dev/media/7gdLIXa.gif', 'catalogo/supino-martelo-deitado-com-halteres--7gdLIXa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-martelo-deitado-com-halteres--7gdLIXa.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Step:2 Before moving, lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:28.581188+00', '2026-10-31 19:42:28.44+00'), ('7HcfMBP', 'Extensão de tríceps em pé com toalha (assistida)', 'assisted standing triceps extension (with towel)', 'extensao-de-triceps-em-pe-com-toalha-assistida', 'https://static.exercisedb.dev/media/7HcfMBP.gif', 'catalogo/extensao-de-triceps-em-pe-com-toalha-assistida--7HcfMBP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-em-pe-com-toalha-assistida--7HcfMBP.gif', ARRAY['braços'], ARRAY['assistido','toalha'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a towel with both hands behind your head.","Step:2 Hold your elbows near your ears and your upper arms stationary.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:28.345798+00', '2026-10-31 19:42:28.216+00'), ('7Hg55JG', 'Clean com halteres', 'dumbbell clean', 'clean-com-halteres', 'https://static.exercisedb.dev/media/7Hg55JG.gif', 'catalogo/clean-com-halteres--7Hg55JG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/clean-com-halteres--7Hg55JG.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['posteriores da coxa','quadríceps','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 Bend your knees and lower your hips into a squat position, with your spine steady and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:42:28.84969+00', '2026-10-31 19:42:28.72+00'), ('7I6LNUG', 'Remada sentada na máquina', 'Machine Seated Row', 'remada-sentada-na-maquina', 'https://static.exercisedb.dev/media/7I6LNUG.gif', 'catalogo/remada-sentada-na-maquina--7I6LNUG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-na-maquina--7I6LNUG.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Set the seat height and footrests to a comfortable position.","Step:2 Take a seat on the machine with your chest against the pad and your feet on the footrests.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:29.010558+00', '2026-10-31 19:42:28.877+00'), ('7inpWch', 'Rosca concentrada em pé com halter', 'dumbbell standing concentration curl', 'rosca-concentrada-em-pe-com-halter', 'https://static.exercisedb.dev/media/7inpWch.gif', 'catalogo/rosca-concentrada-em-pe-com-halter--7inpWch.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-em-pe-com-halter--7inpWch.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand, with your arm straight and palm facing inwards.","Step:2 Set your opposite hand on your thigh for support.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:29.052116+00', '2026-10-31 19:42:28.916+00'), ('7jGOBF3', 'Supino pegada fechada com halteres', 'Dumbbell Close-Grip Press', 'supino-pegada-fechada-com-halteres', 'https://static.exercisedb.dev/media/7jGOBF3.gif', 'catalogo/supino-pegada-fechada-com-halteres--7jGOBF3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-pegada-fechada-com-halteres--7jGOBF3.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on a flat bench with a dumbbell in each hand, resting on your thighs.","Step:2 Use your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:29.209437+00', '2026-10-31 19:42:29.081+00'), ('7M66AVi', 'Rollout com barra', 'Barbell Rollout', 'rollout-com-barra', 'https://static.exercisedb.dev/media/7M66AVi.gif', 'catalogo/rollout-com-barra--7M66AVi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rollout-com-barra--7M66AVi.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['eretores da espinha'], '["Step:1 Get down on the floor and hold a barbell with both hands, about shoulder width.","Step:2 Guide the barbell forward, extending your arms and keeping your core engaged.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:42:29.176566+00', '2026-10-31 19:42:29.048+00'), ('7OeHptV', 'Barra fixa supinada assistida em pé', 'assisted standing chin-up', 'barra-fixa-supinada-assistida-em-pe', 'https://static.exercisedb.dev/media/7OeHptV.gif', 'catalogo/barra-fixa-supinada-assistida-em-pe--7OeHptV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-assistida-em-pe--7OeHptV.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Set the machine to your desired assistance level.","Step:2 Step onto the foot platform and grip the handles with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:42:29.526724+00', '2026-10-31 19:42:29.378+00'), ('7RWNjiB', 'Pronação com halter deitado no chão', 'dumbbell lying pronation on floor', 'pronacao-com-halter-deitado-no-chao', 'https://static.exercisedb.dev/media/7RWNjiB.gif', 'catalogo/pronacao-com-halter-deitado-no-chao--7RWNjiB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pronacao-com-halter-deitado-no-chao--7RWNjiB.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['bíceps','tríceps'], '["Step:1 Settle onto the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Step:2 Rotate your palms so they are facing down toward the floor.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:29.633533+00', '2026-10-31 19:42:29.5+00'), ('7saC5zz', 'Crucifixo declinado no cabo', 'cable decline fly', 'crucifixo-declinado-no-cabo', 'https://static.exercisedb.dev/media/7saC5zz.gif', 'catalogo/crucifixo-declinado-no-cabo--7saC5zz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-declinado-no-cabo--7saC5zz.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the cable machine to a decline position.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:42:29.750889+00', '2026-10-31 19:42:29.622+00'), ('7uFJuXp', 'Avanço ajoelhado com balanço e peso', 'weighted kneeling step with swing', 'avanco-ajoelhado-com-balanco-e-peso', 'https://static.exercisedb.dev/media/7uFJuXp.gif', 'catalogo/avanco-ajoelhado-com-balanco-e-peso--7uFJuXp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-ajoelhado-com-balanco-e-peso--7uFJuXp.gif', ARRAY['ombros'], ARRAY['peso adicional'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Begin in a kneeling position with your knees about hip width and your back straight.","Step:2 Take a weight in each hand, with your arms extended straight down in front of you.","Step:3 Set the shoulders and let the weight move back between the legs as the hips hinge.","Step:4 Hinge back, then drive the hips forward to send the weight up; let the arms guide it.","Step:5 Let the hips, not the shoulders, provide the power.","Step:6 Let the weight fall naturally and hinge again for the next swing."]', '2026-10-31 19:42:29.85141+00', '2026-10-31 19:42:29.723+00'), ('7vG5o25', 'Remada inclinada com halteres', 'dumbbell incline row', 'remada-inclinada-com-halteres', 'https://static.exercisedb.dev/media/7vG5o25.gif', 'catalogo/remada-inclinada-com-halteres--7vG5o25.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-inclinada-com-halteres--7vG5o25.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take hold of a dumbbell in each hand and Take a seat on the bench with your chest against the incline.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:29.82033+00', '2026-10-31 19:42:29.687+00'), ('7w6i0vE', 'Supino alternado com kettlebell no chão', 'kettlebell alternating press on floor', 'supino-alternado-com-kettlebell-no-chao', 'https://static.exercisedb.dev/media/7w6i0vE.gif', 'catalogo/supino-alternado-com-kettlebell-no-chao--7w6i0vE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-alternado-com-kettlebell-no-chao--7w6i0vE.gif', ARRAY['peito'], ARRAY['kettlebell'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Begin by lying on your back on the floor with your knees bent and feet planted.","Step:2 Take a kettlebell in each hand, with your palms facing toward your feet and your arms extended straight up toward the ceiling.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:30.349683+00', '2026-10-31 19:42:30.22+00'), ('7WaDzyL', 'Abdução de quadril lateral', 'side hip abduction', 'abducao-de-quadril-lateral', 'https://static.exercisedb.dev/media/7WaDzyL.gif', 'catalogo/abducao-de-quadril-lateral--7WaDzyL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abducao-de-quadril-lateral--7WaDzyL.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['abdutores'], ARRAY['glúteos','quadríceps'], '["Step:1 Stand and set your feet about shoulder width and your hands on your hips.","Step:2 Transfer your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Open the knees or legs against resistance without shifting your torso.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:42:30.283728+00', '2026-10-31 19:42:30.148+00'), ('7xeukSt', 'Paralelas escapulares', 'scapula dips', 'paralelas-escapulares', 'https://static.exercisedb.dev/media/7xeukSt.gif', 'catalogo/paralelas-escapulares--7xeukSt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralelas-escapulares--7xeukSt.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['trapézio'], ARRAY['romboides','deltoides'], '["Step:1 Begin by standing with your feet about shoulder width and your arms extended in front of you.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:42:30.391418+00', '2026-10-31 19:42:30.248+00'), ('7xI5MXA', 'Supino no banco com cabos', 'cable bench press', 'supino-no-banco-com-cabos', 'https://static.exercisedb.dev/media/7xI5MXA.gif', 'catalogo/supino-no-banco-com-cabos--7xI5MXA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-no-banco-com-cabos--7xI5MXA.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the cable machine to chest height and attach the handles.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:30.435427+00', '2026-10-31 19:42:30.307+00'), ('7zdxRTl', 'Leg press no Smith', 'smith leg press', 'leg-press-no-smith', 'https://static.exercisedb.dev/media/7zdxRTl.gif', 'catalogo/leg-press-no-smith--7zdxRTl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-no-smith--7zdxRTl.gif', ARRAY['coxas'], ARRAY['Smith'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat and footplate of the smith machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the backrest and your feet about shoulder width on the footplate.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Stop the descent before the hips lift from the seat.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:42:31.025087+00', '2026-10-31 19:42:30.893+00'), ('82LxxkW', 'Rosca de punho com barra', 'barbell wrist curl', 'rosca-de-punho-com-barra', 'https://static.exercisedb.dev/media/82LxxkW.gif', 'catalogo/rosca-de-punho-com-barra--82LxxkW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-com-barra--82LxxkW.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; your forearms resting on your thighs, holding a barbell with palms facing up.","Step:2 Let the barbell to roll down to your fingertips, keeping your wrists straight.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:31.087917+00', '2026-10-31 19:42:30.955+00'), ('83HoW9X', 'Remada alta com barra', 'barbell upright row', 'remada-alta-com-barra', 'https://static.exercisedb.dev/media/83HoW9X.gif', 'catalogo/remada-alta-com-barra--83HoW9X.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-com-barra--83HoW9X.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down, hands just beyond shoulder width.","Step:2 Keep the barbell hanging ahead of your thighs, arms straight.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:30.949859+00', '2026-10-31 19:42:30.818+00'), ('84RyJf8', 'Desenvolvimento unilateral com halter', 'Dumbbell Single-Arm Shoulder Press', 'desenvolvimento-unilateral-com-halter', 'https://static.exercisedb.dev/media/84RyJf8.gif', 'catalogo/desenvolvimento-unilateral-com-halter--84RyJf8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-unilateral-com-halter--84RyJf8.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand at shoulder level, palm facing forward.","Step:2 Press the dumbbell upward until your arm is straight overhead.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:30.833825+00', '2026-10-31 19:42:30.704+00'), ('84sESNy', 'Rosca direta unilateral sentado na bola suíça com perna elevada', 'Dumbbell Seated Single-Arm Biceps Curl On Exercise Ball With Leg Raised', 'rosca-direta-unilateral-sentado-na-bola-suica-com-perna-elevada', 'https://static.exercisedb.dev/media/84sESNy.gif', 'catalogo/rosca-direta-unilateral-sentado-na-bola-suica-com-perna-elevada--84sESNy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-unilateral-sentado-na-bola-suica-com-perna-elevada--84sESNy.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand with your palm facing up and your arm straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:31.057856+00', '2026-10-31 19:42:30.916+00'), ('8ARQ9Hw', 'Remada alta sumô com kettlebell', 'kettlebell sumo high pull', 'remada-alta-sumo-com-kettlebell', 'https://static.exercisedb.dev/media/8ARQ9Hw.gif', 'catalogo/remada-alta-sumo-com-kettlebell--8ARQ9Hw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-sumo-com-kettlebell--8ARQ9Hw.gif', ARRAY['costas'], ARRAY['kettlebell'], ARRAY['trapézio'], ARRAY['deltoides','glúteos','posteriores de coxa'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointing outwards.","Step:2 Take a kettlebell with both hands ahead of your body, arms extended downwards.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive up from the wide stance and pull the kettlebell toward the upper chest, leading with the elbows.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:42:31.936109+00', '2026-10-31 19:42:31.803+00'), ('8coXSYU', 'Flexão e retração de ombros sentado com rolo', 'Seated Roller Shoulder Flexion And Retraction', 'flexao-e-retracao-de-ombros-sentado-com-rolo', 'https://static.exercisedb.dev/media/8coXSYU.gif', 'catalogo/flexao-e-retracao-de-ombros-sentado-com-rolo--8coXSYU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-e-retracao-de-ombros-sentado-com-rolo--8coXSYU.gif', ARRAY['peito'], ARRAY['rolo'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on a flat surface with your legs extended in front of you.","Step:2 Take hold of the roller with both hands, palms facing down, and place it on your thighs.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Roll the roller away along your legs as the arms reach forward, then draw it back toward your thighs.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:42:31.518237+00', '2026-10-31 19:42:31.386+00'), ('8d8qJQI', 'Remada no banco inclinado com barra pegada invertida', 'Barbell Reverse-Grip Incline Bench Row', 'remada-no-banco-inclinado-com-barra-pegada-invertida', 'https://static.exercisedb.dev/media/8d8qJQI.gif', 'catalogo/remada-no-banco-inclinado-com-barra-pegada-invertida--8d8qJQI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-no-banco-inclinado-com-barra-pegada-invertida--8d8qJQI.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench facing the backrest with your chest against it.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:31.738872+00', '2026-10-31 19:42:31.605+00'), ('8DiFDVA', 'Crucifixo inverso com halteres', 'dumbbell rear fly', 'crucifixo-inverso-com-halteres', 'https://static.exercisedb.dev/media/8DiFDVA.gif', 'catalogo/crucifixo-inverso-com-halteres--8DiFDVA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres--8DiFDVA.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:42:31.658317+00', '2026-10-31 19:42:31.527+00'), ('8eqjhOl', 'Supino inclinado com halteres e pegada neutra', 'dumbbell palms in incline bench press', 'supino-inclinado-com-halteres-e-pegada-neutra', 'https://static.exercisedb.dev/media/8eqjhOl.gif', 'catalogo/supino-inclinado-com-halteres-e-pegada-neutra--8eqjhOl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-halteres-e-pegada-neutra--8eqjhOl.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your back against the backrest and feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:31.674665+00', '2026-10-31 19:42:31.547+00'), ('8fgqP5a', 'Rosca concentrada unilateral em pé com halter', 'Dumbbell Standing Single-Arm Concentration Curl', 'rosca-concentrada-unilateral-em-pe-com-halter', 'https://static.exercisedb.dev/media/8fgqP5a.gif', 'catalogo/rosca-concentrada-unilateral-em-pe-com-halter--8fgqP5a.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-unilateral-em-pe-com-halter--8fgqP5a.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a dumbbell in one hand, palm facing up.","Step:2 Set your free hand on your thigh for support.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:32.50042+00', '2026-10-31 19:42:32.37+00'), ('8K0w2yA', 'Elevação de joelhos suspenso assistida com arremesso para baixo', 'assisted hanging knee raise with throw down', 'elevacao-de-joelhos-suspenso-assistida-com-arremesso-para-baixo', 'https://static.exercisedb.dev/media/8K0w2yA.gif', 'catalogo/elevacao-de-joelhos-suspenso-assistida-com-arremesso-para-baixo--8K0w2yA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-joelhos-suspenso-assistida-com-arremesso-para-baixo--8K0w2yA.gif', ARRAY['abdômen'], ARRAY['assistido'], ARRAY['abdômen'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your knees toward your chest, keeping your legs together.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:42:32.323668+00', '2026-10-31 19:42:32.196+00'), ('8K7m2SS', 'Flexão de braço fechada na medicine ball', 'Medicine Ball Close-Grip Push Up', 'flexao-de-braco-fechada-na-medicine-ball', 'https://static.exercisedb.dev/media/8K7m2SS.gif', 'catalogo/flexao-de-braco-fechada-na-medicine-ball--8K7m2SS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-fechada-na-medicine-ball--8K7m2SS.gif', ARRAY['braços'], ARRAY['medicine ball'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Begin in a high plank position with your hands on the medicine ball, about shoulder width.","Step:2 Lower your body toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:32.709024+00', '2026-10-31 19:42:32.336+00'), ('8oYqOt9', 'Rosca sentada na polia', 'cable seated curl', 'rosca-sentada-na-polia', 'https://static.exercisedb.dev/media/8oYqOt9.gif', 'catalogo/rosca-sentada-na-polia--8oYqOt9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-sentada-na-polia--8oYqOt9.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a cable machine with your feet planted and your back straight.","Step:2 Hold the cable attachment with palms facing up, and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:32.495616+00', '2026-10-31 19:42:32.369+00'), ('8ozhUIZ', 'Panturrilha em pé com barra', 'barbell standing calf raise', 'panturrilha-em-pe-com-barra', 'https://static.exercisedb.dev/media/8ozhUIZ.gif', 'catalogo/panturrilha-em-pe-com-barra--8ozhUIZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-com-barra--8ozhUIZ.gif', ARRAY['panturrilhas'], ARRAY['barra'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width and place a barbell across your upper back.","Step:2 Before moving, raise your heels off the ground as high as possible, using only your toes.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:32.768463+00', '2026-10-31 19:42:32.403+00'), ('8urJS9b', 'Hiperextensão com peso na bola suíça', 'weighted hyperextension (on stability ball)', 'hiperextensao-com-peso-na-bola-suica', 'https://static.exercisedb.dev/media/8urJS9b.gif', 'catalogo/hiperextensao-com-peso-na-bola-suica--8urJS9b.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/hiperextensao-com-peso-na-bola-suica--8urJS9b.gif', ARRAY['costas'], ARRAY['peso adicional','bola suíça'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Step:2 Set your hands behind your head or cross them over your chest.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:42:32.948953+00', '2026-10-31 19:42:32.821+00'), ('8xUv4J7', 'Abdominal sentado na polia', 'cable seated crunch', 'abdominal-sentado-na-polia', 'https://static.exercisedb.dev/media/8xUv4J7.gif', 'catalogo/abdominal-sentado-na-polia--8xUv4J7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-sentado-na-polia--8xUv4J7.gif', ARRAY['abdômen'], ARRAY['polia'], ARRAY['abdômen'], ARRAY['oblíquos'], '["Step:1 Take a seat on a cable machine with your feet planted and your knees bent.","Step:2 Take hold of the cable handle with both hands and position it behind your head.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:33.089739+00', '2026-10-31 19:42:32.959+00'), ('903mzG8', 'Desenvolvimento de ombros no Smith', 'smith shoulder press', 'desenvolvimento-de-ombros-no-smith', 'https://static.exercisedb.dev/media/903mzG8.gif', 'catalogo/desenvolvimento-de-ombros-no-smith--903mzG8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-de-ombros-no-smith--903mzG8.gif', ARRAY['ombros'], ARRAY['Smith'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the bar with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:33.305011+00', '2026-10-31 19:42:33.177+00'), ('945zpRg', 'Supino com barra pegada aberta invertida', 'Barbell Wide Reverse-Grip Bench Press', 'supino-com-barra-pegada-aberta-invertida', 'https://static.exercisedb.dev/media/945zpRg.gif', 'catalogo/supino-com-barra-pegada-aberta-invertida--945zpRg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-com-barra-pegada-aberta-invertida--945zpRg.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitoral'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with a wide reverse grip, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:33.627823+00', '2026-10-31 19:42:33.498+00'), ('99rWm7w', 'Alongamento de posterior de coxa', 'hamstring stretch', 'alongamento-de-posterior-de-coxa', 'https://static.exercisedb.dev/media/99rWm7w.gif', 'catalogo/alongamento-de-posterior-de-coxa--99rWm7w.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-posterior-de-coxa--99rWm7w.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Move forward with your right foot and shift your weight onto your right leg.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:33.753412+00', '2026-10-31 19:42:33.625+00'), ('9Ap7miY', 'Abdominal declinado', 'decline crunch', 'abdominal-declinado', 'https://static.exercisedb.dev/media/9Ap7miY.gif', 'catalogo/abdominal-declinado--9Ap7miY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-declinado--9Ap7miY.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdômen'], ARRAY['flexores do quadril'], '["Step:1 Settle onto a decline bench with your feet secured and your knees bent at a 90-degree angle.","Step:2 Set your hands behind your head or across your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:33.965602+00', '2026-10-31 19:42:33.831+00'), ('9c6T1YX', 'Prancha com mountain climber cruzado', 'bridge - mountain climber (cross body)', 'prancha-com-mountain-climber-cruzado', 'https://static.exercisedb.dev/media/9c6T1YX.gif', 'catalogo/prancha-com-mountain-climber-cruzado--9c6T1YX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-com-mountain-climber-cruzado--9c6T1YX.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdômen'], ARRAY['glúteos','quadríceps','posteriores de coxa','deltoides','tríceps'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Brace your trunk and lift your right foot off the ground, bringing your right knee toward your left elbow.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:42:34.416882+00', '2026-10-31 19:42:34.289+00'), ('9E25EOx', 'Agachamento split', 'split squats', 'agachamento-split', 'https://static.exercisedb.dev/media/9E25EOx.gif', 'catalogo/agachamento-split--9E25EOx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-split--9E25EOx.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Step forward with one foot and place it about two feet in front of the other foot.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:33.858443+00', '2026-10-31 19:42:33.731+00'), ('9gbyYKk', 'Rotação interna do quadril sentado com elástico', 'band seated hip internal rotation', 'rotacao-interna-do-quadril-sentado-com-elastico', 'https://static.exercisedb.dev/media/9gbyYKk.gif', 'catalogo/rotacao-interna-do-quadril-sentado-com-elastico--9gbyYKk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-interna-do-quadril-sentado-com-elastico--9gbyYKk.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Take a seat on a chair or bench with your back straight and feet planted.","Step:2 Set a resistance band around your thighs, just above your knees.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:34.615113+00', '2026-10-31 19:42:34.475+00'), ('9GXrTE6', 'Panturrilha unilateral no chão no Smith', 'Smith Single-Leg Floor Calf Raise', 'panturrilha-unilateral-no-chao-no-smith', 'https://static.exercisedb.dev/media/9GXrTE6.gif', 'catalogo/panturrilha-unilateral-no-chao-no-smith--9GXrTE6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-unilateral-no-chao-no-smith--9GXrTE6.gif', ARRAY['panturrilhas'], ARRAY['Smith'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set yourself on the floor under the smith machine bar, turned away from the machine.","Step:2 Set the balls of your feet on a raised surface, such as a weight plate or block.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:42:34.764909+00', '2026-10-31 19:42:34.399+00'), ('9IxJdtC', 'Elevação de pernas e quadril deitado', 'lying leg-hip raise', 'elevacao-de-pernas-e-quadril-deitado', 'https://static.exercisedb.dev/media/9IxJdtC.gif', 'catalogo/elevacao-de-pernas-e-quadril-deitado--9IxJdtC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-e-quadril-deitado--9IxJdtC.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdômen'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Set your hands under your glutes for support.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:42:34.741054+00', '2026-10-31 19:42:34.606+00'), ('9JprnPh', 'Panturrilha unilateral com elástico', 'band single leg calf raise', 'panturrilha-unilateral-com-elastico', 'https://static.exercisedb.dev/media/9JprnPh.gif', 'catalogo/panturrilha-unilateral-com-elastico--9JprnPh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-unilateral-com-elastico--9JprnPh.gif', ARRAY['panturrilhas'], ARRAY['elástico'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Stand and set your feet about hip width and place the band around the ball of your left foot.","Step:2 Use a stable object for balance if needed.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:34.561638+00', '2026-10-31 19:42:34.424+00'), ('9KU9TYF', 'Leg press horizontal unilateral na máquina', 'Machine Horizontal Single-Leg Press', 'leg-press-horizontal-unilateral-na-maquina', 'https://static.exercisedb.dev/media/9KU9TYF.gif', 'catalogo/leg-press-horizontal-unilateral-na-maquina--9KU9TYF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-horizontal-unilateral-na-maquina--9KU9TYF.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Step:2 Take a seat on the machine with your back against the backrest and your feet about shoulder width on the footplate.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Return along the same path at a controlled pace; switch sides when the set calls for it."]', '2026-10-31 19:42:35.360627+00', '2026-10-31 19:42:35.226+00'), ('9n2149Z', 'Agachamento deitado no sled', 'sled lying squat', 'agachamento-deitado-no-sled', 'https://static.exercisedb.dev/media/9n2149Z.gif', 'catalogo/agachamento-deitado-no-sled--9n2149Z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-deitado-no-sled--9n2149Z.gif', ARRAY['coxas'], ARRAY['máquina sled'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the sled machine to a comfortable weight.","Step:2 Settle onto your back on the sled machine with your feet on the footplate.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:35.461485+00', '2026-10-31 19:42:35.333+00'), ('9pa4H5m', 'Pallof press horizontal com elástico', 'band horizontal pallof press', 'pallof-press-horizontal-com-elastico', 'https://static.exercisedb.dev/media/9pa4H5m.gif', 'catalogo/pallof-press-horizontal-com-elastico--9pa4H5m.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pallof-press-horizontal-com-elastico--9pa4H5m.gif', ARRAY['abdômen'], ARRAY['elástico'], ARRAY['abdômen'], ARRAY['oblíquos','glúteos'], '["Step:1 Connect the band to a sturdy anchor point at waist height.","Step:2 Stand perpendicular to the anchor point with your feet about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:35.195449+00', '2026-10-31 19:42:35.049+00'), ('9pQSkH8', 'Remada com Halteres no Banco Inclinado com Pegada Supinada', 'Dumbbell Reverse-Grip Incline Bench Two-Arm Row', 'remada-com-halteres-no-banco-inclinado-com-pegada-supinada', 'https://static.exercisedb.dev/media/9pQSkH8.gif', 'catalogo/remada-com-halteres-no-banco-inclinado-com-pegada-supinada--9pQSkH8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-com-halteres-no-banco-inclinado-com-pegada-supinada--9pQSkH8.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your chest against the backrest and your feet planted.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:35.34149+00', '2026-10-31 19:42:35.212+00'), ('9RT8oQW', 'Mergulho no Banco com Pés no Chão', 'bench dip on floor', 'mergulho-no-banco-com-pes-no-chao', 'https://static.exercisedb.dev/media/9RT8oQW.gif', 'catalogo/mergulho-no-banco-com-pes-no-chao--9RT8oQW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-no-banco-com-pes-no-chao--9RT8oQW.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Step:2 Move your butt off the bench, supporting your weight with your hands.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:42:35.57128+00', '2026-10-31 19:42:35.437+00'), ('9sgNE2O', 'Pullover com Barra no Banco Declinado', 'barbell decline pullover', 'pullover-com-barra-no-banco-declinado', 'https://static.exercisedb.dev/media/9sgNE2O.gif', 'catalogo/pullover-com-barra-no-banco-declinado--9sgNE2O.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-barra-no-banco-declinado--9sgNE2O.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Get onto a decline bench with your head lower than your hips and your feet secured.","Step:2 Take hold of the barbell with a pronated grip (palms turned away from you) and your hands just beyond shoulder width.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:42:36.006512+00', '2026-10-31 19:42:35.878+00'), ('9Tkqa9O', 'Moinho de Vento com Kettlebell', 'kettlebell windmill', 'moinho-de-vento-com-kettlebell', 'https://static.exercisedb.dev/media/9Tkqa9O.gif', 'catalogo/moinho-de-vento-com-kettlebell--9Tkqa9O.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/moinho-de-vento-com-kettlebell--9Tkqa9O.gif', ARRAY['abdômen'], ARRAY['kettlebell'], ARRAY['abdominais'], ARRAY['oblíquos','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in your right hand overhead.","Step:2 Before moving, rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:46.603006+00', '2026-10-31 19:42:35.787+00'), ('9WTm7dq', 'Paralelas para Peito', 'chest dip', 'paralelas-para-peito', 'https://static.exercisedb.dev/media/9WTm7dq.gif', 'catalogo/paralelas-para-peito--9WTm7dq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralelas-para-peito--9WTm7dq.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set yourself on parallel bars with your arms straight and your body straight.","Step:2 Before moving, lower your body by bending your elbows until your shoulders are below your elbows.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:42:47.163439+00', '2026-10-31 19:42:47.025+00'), ('9XjtHvS', 'Pullover com Halter', 'dumbbell pullover', 'pullover-com-halter', 'https://static.exercisedb.dev/media/9XjtHvS.gif', 'catalogo/pullover-com-halter--9XjtHvS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-halter--9XjtHvS.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['latíssimo do dorso','tríceps'], '["Step:1 Settle onto a bench with your head at one end and your feet on the floor.","Step:2 Take a dumbbell with both hands and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:42:36.245324+00', '2026-10-31 19:42:36.108+00'), ('9ZGZuOD', 'Abdominal com Rotação no Banco Inclinado', 'incline twisting sit-up', 'abdominal-com-rotacao-no-banco-inclinado', 'https://static.exercisedb.dev/media/9ZGZuOD.gif', 'catalogo/abdominal-com-rotacao-no-banco-inclinado--9ZGZuOD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-rotacao-no-banco-inclinado--9ZGZuOD.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Get onto the bench with your feet secured under the foot pads.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:49.395271+00', '2026-10-31 19:42:49.264+00'), ('A2upspL', 'Panturrilha Burro Unilateral', 'Single-Leg Donkey Calf Raise', 'panturrilha-burro-unilateral', 'https://static.exercisedb.dev/media/A2upspL.gif', 'catalogo/panturrilha-burro-unilateral--A2upspL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-burro-unilateral--A2upspL.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width, toes pointing forward.","Step:2 Set your hands on a stable surface for support, such as a wall or a bar.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:42:48.380462+00', '2026-10-31 19:42:48.239+00'), ('a4F9Oyc', 'Clean Suspenso Alternado com Dois Kettlebells', 'kettlebell double alternating hang clean', 'clean-suspenso-alternado-com-dois-kettlebells', 'https://static.exercisedb.dev/media/a4F9Oyc.gif', 'catalogo/clean-suspenso-alternado-com-dois-kettlebells--a4F9Oyc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/clean-suspenso-alternado-com-dois-kettlebells--a4F9Oyc.gif', ARRAY['braços'], ARRAY['kettlebell'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:42:48.240237+00', '2026-10-31 19:42:36.868+00'), ('A6wtbuL', 'Desenvolvimento em Pé com Halteres', 'dumbbell standing overhead press', 'desenvolvimento-em-pe-com-halteres', 'https://static.exercisedb.dev/media/A6wtbuL.gif', 'catalogo/desenvolvimento-em-pe-com-halteres--A6wtbuL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-em-pe-com-halteres--A6wtbuL.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Step:2 Press the dumbbells upward until your arms are straight overhead.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:47.447576+00', '2026-10-31 19:42:47.318+00'), ('a8VDgLw', 'Caminhada na Bicicleta Ergométrica', 'stationary bike walk', 'caminhada-na-bicicleta-ergometrica', 'https://static.exercisedb.dev/media/a8VDgLw.gif', 'catalogo/caminhada-na-bicicleta-ergometrica--a8VDgLw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-na-bicicleta-ergometrica--a8VDgLw.gif', ARRAY['cardio'], ARRAY['máquina de alavanca'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat height and position on the stationary bike to ensure proper alignment.","Step:2 Set your feet on the pedals and secure them with the straps if available.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:42:47.748949+00', '2026-10-31 19:42:47.61+00'), ('A9qxk2F', 'Flexão Arqueiro', 'archer push up', 'flexao-arqueiro', 'https://static.exercisedb.dev/media/A9qxk2F.gif', 'catalogo/flexao-arqueiro--A9qxk2F.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-arqueiro--A9qxk2F.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width.","Step:2 Reach one arm straight out to the side, parallel to the ground.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Shift toward one hand and bend that elbow while the other arm straightens to the side.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:48.396995+00', '2026-10-31 19:42:48.269+00'), ('aaxA3cm', 'Remada Curvada no Smith com Pegada Supinada', 'Smith Reverse-Grip Bent Over Row', 'remada-curvada-no-smith-com-pegada-supinada', 'https://static.exercisedb.dev/media/aaxA3cm.gif', 'catalogo/remada-curvada-no-smith-com-pegada-supinada--aaxA3cm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-no-smith-com-pegada-supinada--aaxA3cm.gif', ARRAY['costas'], ARRAY['Smith'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Prepare the smith machine with the bar at hip height.","Step:2 Face the bar from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:48.315522+00', '2026-10-31 19:42:48.185+00'), ('aaXr7ld', 'Remada Cavalinho na Máquina', 'Machine T Bar Row', 'remada-cavalinho-na-maquina', 'https://static.exercisedb.dev/media/aaXr7ld.gif', 'catalogo/remada-cavalinho-na-maquina--aaXr7ld.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-cavalinho-na-maquina--aaXr7ld.gif', ARRAY['costas'], ARRAY['máquina de alavanca'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Set the seat height and footplate position to ensure proper alignment.","Step:2 Take a seat on the machine with your chest against the pad and your feet flat on the footplate.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:49.378925+00', '2026-10-31 19:42:49.234+00'), ('aDoFKrE', 'Arremesso de Medicine Ball no Peito', 'medicine ball chest pass', 'arremesso-de-medicine-ball-no-peito', 'https://static.exercisedb.dev/media/aDoFKrE.gif', 'catalogo/arremesso-de-medicine-ball-no-peito--aDoFKrE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-de-medicine-ball-no-peito--aDoFKrE.gif', ARRAY['peito'], ARRAY['medicine ball'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Stand and set your feet about shoulder width, holding the medicine ball at chest level.","Step:2 Reach your arms forward, pushing the medicine ball away from your chest with force.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Follow through with the whole body while keeping control of the landing or catch.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:42:48.910681+00', '2026-10-31 19:42:48.781+00'), ('ae9UoXQ', 'Rosca Inclinada com Halteres', 'dumbbell incline curl', 'rosca-inclinada-com-halteres', 'https://static.exercisedb.dev/media/ae9UoXQ.gif', 'catalogo/rosca-inclinada-com-halteres--ae9UoXQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inclinada-com-halteres--ae9UoXQ.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Step:2 Set your upper arms on the incline bench and let your elbows hang down, straighten your arms.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:49.089989+00', '2026-10-31 19:42:48.943+00'), ('aee2Fcj', 'Rosca Direta com Barra e Arm Blaster', 'barbell biceps curl (with arm blaster)', 'rosca-direta-com-barra-e-arm-blaster', 'https://static.exercisedb.dev/media/aee2Fcj.gif', 'catalogo/rosca-direta-com-barra-e-arm-blaster--aee2Fcj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra-e-arm-blaster--aee2Fcj.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing up.","Step:2 Set your upper arms against the arm blaster, keeping your elbows close to your torso.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:49.567203+00', '2026-10-31 19:42:49.438+00'), ('Af0EW2I', 'Muscle-up na Barra Vertical', 'muscle-up (on vertical bar)', 'muscle-up-na-barra-vertical', 'https://static.exercisedb.dev/media/Af0EW2I.gif', 'catalogo/muscle-up-na-barra-vertical--Af0EW2I.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/muscle-up-na-barra-vertical--Af0EW2I.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','tríceps','antebraços'], '["Step:1 Begin by hanging from a vertical bar with your palms turned away from you and your arms straight.","Step:2 Brace your trunk and pull your body up toward the bar, leading with your chest.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:42:49.419972+00', '2026-10-31 19:42:49.288+00'), ('aHDy5O5', 'Elevação em Y com elástico', 'band y-raise', 'elevacao-em-y-com-elastico', 'https://static.exercisedb.dev/media/aHDy5O5.gif', 'catalogo/elevacao-em-y-com-elastico--aHDy5O5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-em-y-com-elastico--aHDy5O5.gif', ARRAY['ombros'], ARRAY['elástico'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold the band ahead of your thighs with your palms facing inwards.","Step:2 Maintain straight arms and lift them up and out to the sides, forming a ''Y'' shape with your body.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms diagonally into a Y shape while keeping the shoulders away from your ears.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:49.925258+00', '2026-10-31 19:42:49.795+00'), ('ainizkb', 'Remada alta com halteres', 'dumbbell upright row', 'remada-alta-com-halteres', 'https://static.exercisedb.dev/media/ainizkb.gif', 'catalogo/remada-alta-com-halteres--ainizkb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-com-halteres--ainizkb.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 Let the dumbbells hang ahead of your thighs, with your arms straight.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:50.160855+00', '2026-10-31 19:42:50.027+00'), ('Al3tP0D', 'Arremesso de medicine ball deitado', 'medicine ball supine chest throw', 'arremesso-de-medicine-ball-deitado', 'https://static.exercisedb.dev/media/Al3tP0D.gif', 'catalogo/arremesso-de-medicine-ball-deitado--Al3tP0D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-de-medicine-ball-deitado--Al3tP0D.gif', ARRAY['braços'], ARRAY['medicine ball'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto your back on a bench with your knees bent and feet planted.","Step:2 Take hold of the medicine ball with both hands, extending your arms straight up above your chest.","Step:3 Brace and settle into a stable starting position.","Step:4 Move through the intended path under control, keeping the joints aligned with the resistance.","Step:5 Keep the movement controlled throughout the range.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:42:50.330665+00', '2026-10-31 19:42:50.201+00'), ('Am02iPd', 'Crucifixo unilateral com halter na bola suíça', 'Dumbbell Single-Arm Fly On Exercise Ball', 'crucifixo-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/Am02iPd.gif', 'catalogo/crucifixo-unilateral-com-halter-na-bola-suica--Am02iPd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-unilateral-com-halter-na-bola-suica--Am02iPd.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with a dumbbell in one hand and your feet planted.","Step:2 Step your feet forward and roll your body down until your upper back is resting on the exercise ball.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:42:50.220993+00', '2026-10-31 19:42:50.092+00'), ('ANbbry2', 'Curl lombar', 'lower back curl', 'curl-lombar', 'https://static.exercisedb.dev/media/ANbbry2.gif', 'catalogo/curl-lombar--ANbbry2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/curl-lombar--ANbbry2.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores da coxa'], '["Step:1 Settle onto your stomach with your legs extended and your arms by your sides.","Step:2 Engage your glutes and hamstrings, and With control lift your upper body off the ground, curling your back upwards.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:50.144451+00', '2026-10-31 19:42:50.014+00'), ('AQ0mC4Y', 'Elevação lateral com halteres pegada "full can" (polegares para cima)', 'dumbbell full can lateral raise', 'elevacao-lateral-com-halteres-pegada-full-can-polegares-para-cima', 'https://static.exercisedb.dev/media/AQ0mC4Y.gif', 'catalogo/elevacao-lateral-com-halteres-pegada-full-can-polegares-para-cima--AQ0mC4Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-com-halteres-pegada-full-can-polegares-para-cima--AQ0mC4Y.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','manguito rotador'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your body.","Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:50.505208+00', '2026-10-31 19:42:50.372+00'), ('AQIhRjM', 'Abdominal deitado cotovelo ao joelho', 'lying elbow to knee', 'abdominal-deitado-cotovelo-ao-joelho', 'https://static.exercisedb.dev/media/AQIhRjM.gif', 'catalogo/abdominal-deitado-cotovelo-ao-joelho--AQIhRjM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-deitado-cotovelo-ao-joelho--AQIhRjM.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:50.704927+00', '2026-10-31 19:42:50.568+00'), ('aqvSOQE', 'Crucifixo inverso no crossover com cabos', 'Cable Crossover Reverse Fly', 'crucifixo-inverso-no-crossover-com-cabos', 'https://static.exercisedb.dev/media/aqvSOQE.gif', 'catalogo/crucifixo-inverso-no-crossover-com-cabos--aqvSOQE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-no-crossover-com-cabos--aqvSOQE.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['romboides','trapézio'], '["Step:1 Connect a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Step:2 Hold the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet about shoulder width.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:42:50.723057+00', '2026-10-31 19:42:50.591+00'), ('AR0ig3o', 'Abdominal com flexão de pernas (joelhos flexionados)', 'flexion leg sit up (bent knee)', 'abdominal-com-flexao-de-pernas-joelhos-flexionados', 'https://static.exercisedb.dev/media/AR0ig3o.gif', 'catalogo/abdominal-com-flexao-de-pernas-joelhos-flexionados--AR0ig3o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-flexao-de-pernas-joelhos-flexionados--AR0ig3o.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:51.745755+00', '2026-10-31 19:42:51.363+00'), ('arsYEd3', 'Agachamento split unilateral com elástico (um braço e uma perna)', 'Band Single-Arm Single Leg Split Squat', 'agachamento-split-unilateral-com-elastico-um-braco-e-uma-perna', 'https://static.exercisedb.dev/media/arsYEd3.gif', 'catalogo/agachamento-split-unilateral-com-elastico-um-braco-e-uma-perna--arsYEd3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-split-unilateral-com-elastico-um-braco-e-uma-perna--arsYEd3.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores da coxa'], '["Step:1 Stand and set your feet about hip width and place a resistance band around your ankles.","Step:2 Reach one leg forward and rest the top of your foot on a bench or step behind you.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent; switch sides when the set calls for it."]', '2026-10-31 19:42:51.035233+00', '2026-10-31 19:42:50.797+00'), ('arvaszz', 'Flexão de braço modificada para antebraços', 'modified push up to lower arms', 'flexao-de-braco-modificada-para-antebracos', 'https://static.exercisedb.dev/media/arvaszz.gif', 'catalogo/flexao-de-braco-modificada-para-antebracos--arvaszz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-modificada-para-antebracos--arvaszz.gif', ARRAY['antebraços'], ARRAY['peso corporal'], ARRAY['antebraços'], ARRAY['tríceps','peitorais','deltoides'], '["Step:1 Begin in a push-up position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your body down toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:50.954889+00', '2026-10-31 19:42:50.819+00'), ('aTNKZiC', 'Elevação lateral unilateral com halter no banco inclinado', 'Dumbbell Incline Single-Arm Lateral Raise', 'elevacao-lateral-unilateral-com-halter-no-banco-inclinado', 'https://static.exercisedb.dev/media/aTNKZiC.gif', 'catalogo/elevacao-lateral-unilateral-com-halter-no-banco-inclinado--aTNKZiC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-unilateral-com-halter-no-banco-inclinado--aTNKZiC.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Take a seat on an incline bench with a dumbbell in one hand, resting it on your thigh.","Step:2 Tip forward and position your upper arm against the inside of your thigh.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:42:51.275806+00', '2026-10-31 19:42:51.142+00'), ('aumB2IV', 'Abdominal assistido', 'assisted sit-up', 'abdominal-assistido', 'https://static.exercisedb.dev/media/aumB2IV.gif', 'catalogo/abdominal-assistido--aumB2IV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-assistido--aumB2IV.gif', ARRAY['abdômen'], ARRAY['assistido'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Sit at the bench edge, or ask a partner to secure your feet.","Step:2 Settle onto your back with your knees bent and feet planted.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:51.573186+00', '2026-10-31 19:42:51.189+00'), ('aVs3BR3', 'Rotação de tronco no cabo', 'cable twist', 'rotacao-de-tronco-no-cabo', 'https://static.exercisedb.dev/media/aVs3BR3.gif', 'catalogo/rotacao-de-tronco-no-cabo--aVs3BR3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-no-cabo--aVs3BR3.gif', ARRAY['abdômen'], ARRAY['cabo'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Stand and set your feet about shoulder width, facing the cable machine.","Step:2 Take hold of the cable handle with both hands ahead of your chest, keeping your arms soft.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:51.782712+00', '2026-10-31 19:42:51.654+00'), ('aWedzZX', 'Ponte de glúteos com duas pernas no banco', 'Glute Bridge Two-Leg On Bench', 'ponte-de-gluteos-com-duas-pernas-no-banco', 'https://static.exercisedb.dev/media/aWedzZX.gif', 'catalogo/ponte-de-gluteos-com-duas-pernas-no-banco--aWedzZX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/ponte-de-gluteos-com-duas-pernas-no-banco--aWedzZX.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores da coxa','core'], '["Step:1 Take a seat on the edge of a bench with your back against it and your feet planted.","Step:2 Set your hands on the bench beside your hips for support.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:42:51.837016+00', '2026-10-31 19:42:51.71+00'), ('awG04cF', 'Rosca de dedos com barra', 'finger curls', 'rosca-de-dedos-com-barra', 'https://static.exercisedb.dev/media/awG04cF.gif', 'catalogo/rosca-de-dedos-com-barra--awG04cF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-dedos-com-barra--awG04cF.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['flexores do punho','músculos da pegada'], '["Step:1 Plant both feet while seated on a bench; hold a barbell with palms facing up.","Step:2 Set your forearms on your thighs, letting your wrists hang off the edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Let the bar roll toward your fingertips, then close your fingers firmly around it.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:52.300105+00', '2026-10-31 19:42:52.173+00'), ('AX1kB0o', 'Elevação de quadril com rotação', 'twist hip lift', 'elevacao-de-quadril-com-rotacao', 'https://static.exercisedb.dev/media/AX1kB0o.gif', 'catalogo/elevacao-de-quadril-com-rotacao--AX1kB0o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-com-rotacao--AX1kB0o.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['oblíquos','posteriores da coxa'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands by your sides for support.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:42:52.136889+00', '2026-10-31 19:42:51.999+00'), ('aXcUyKb', 'Snatch unilateral com kettlebell', 'Kettlebell Single-Arm Snatch', 'snatch-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/aXcUyKb.gif', 'catalogo/snatch-unilateral-com-kettlebell--aXcUyKb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/snatch-unilateral-com-kettlebell--aXcUyKb.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['trapézio','antebraços','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand between your legs.","Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell toward the ground.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:42:52.591741+00', '2026-10-31 19:42:52.461+00'), ('AxFoqAD', 'Panturrilha unilateral no hack', 'Hack Single-Leg Calf Raise', 'panturrilha-unilateral-no-hack', 'https://static.exercisedb.dev/media/AxFoqAD.gif', 'catalogo/panturrilha-unilateral-no-hack--AxFoqAD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-unilateral-no-hack--AxFoqAD.gif', ARRAY['panturrilhas'], ARRAY['máquina hack'], ARRAY['panturrilhas'], ARRAY['posteriores da coxa','glúteos'], '["Step:1 Set the sled machine to an appropriate weight.","Step:2 Step onto the sled machine with one foot, keeping the other foot off the ground.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:42:52.637578+00', '2026-10-31 19:42:52.509+00'), ('aXtJhlg', 'Step-up com halteres', 'dumbbell step-up', 'step-up-com-halteres', 'https://static.exercisedb.dev/media/aXtJhlg.gif', 'catalogo/step-up-com-halteres--aXtJhlg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/step-up-com-halteres--aXtJhlg.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores da coxa','panturrilhas'], '["Step:1 Take your place in front of a bench or step with a dumbbell in each hand, palms facing your body.","Step:2 Set your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step:3 Put the lead foot fully on the platform before shifting your weight onto it.","Step:4 Step onto the platform and drive through the lead foot to stand tall on it.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:42:52.296245+00', '2026-10-31 19:42:52.167+00'), ('ayAHcEm', 'Elevação de ombros inclinada no Smith', 'smith incline shoulder raises', 'elevacao-de-ombros-inclinada-no-smith', 'https://static.exercisedb.dev/media/ayAHcEm.gif', 'catalogo/elevacao-de-ombros-inclinada-no-smith--ayAHcEm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-ombros-inclinada-no-smith--ayAHcEm.gif', ARRAY['peito'], ARRAY['Smith'], ARRAY['serrátil anterior'], ARRAY['deltoides','trapézio'], '["Step:1 Set the smith machine to an incline position.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:52.803664+00', '2026-10-31 19:42:52.67+00'), ('B1EVP9F', 'Flexão de braço inclinada', 'incline push-up', 'flexao-de-braco-inclinada', 'https://static.exercisedb.dev/media/B1EVP9F.gif', 'catalogo/flexao-de-braco-inclinada--B1EVP9F.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-inclinada--B1EVP9F.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set your hands on an elevated surface, such as a bench or step, just beyond shoulder width.","Step:2 Reach your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:42:52.93303+00', '2026-10-31 19:42:52.806+00'), ('b2Uoz54', 'Elevação frontal com barra', 'barbell front raise', 'elevacao-frontal-com-barra', 'https://static.exercisedb.dev/media/b2Uoz54.gif', 'catalogo/elevacao-frontal-com-barra--b2Uoz54.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-barra--b2Uoz54.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['bíceps','tríceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell ahead of your thighs with palms facing down.","Step:2 Maintain straight arms and lift the barbell forward and upward until it reaches shoulder level.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:42:52.908691+00', '2026-10-31 19:42:52.769+00'), ('B3Rxp6L', 'Supino Inclinado com Halteres', 'Dumbbell Incline Bench Press', 'supino-inclinado-com-halteres', 'https://static.exercisedb.dev/media/B3Rxp6L.gif', 'catalogo/supino-inclinado-com-halteres--B3Rxp6L.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-halteres--B3Rxp6L.gif', ARRAY['Peitoral'], ARRAY['Halteres'], ARRAY['Peitoral'], ARRAY['Deltoides','Tríceps'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your back against the pad and feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:53.155885+00', '2026-10-31 19:42:53.025+00'), ('b4b6afT', 'Rosca Direta Sentada com Peso na Bola Suíça', 'Weighted Seated Biceps Curl (On Stability Ball)', 'rosca-direta-sentada-com-peso-na-bola-suica', 'https://static.exercisedb.dev/media/b4b6afT.gif', 'catalogo/rosca-direta-sentada-com-peso-na-bola-suica--b4b6afT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-sentada-com-peso-na-bola-suica--b4b6afT.gif', ARRAY['Braços'], ARRAY['Medicine Ball','Bola Suíça'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Take a seat on a stability ball with your feet planted and your back straight.","Step:2 Take a medicine ball with palms facing up, and let your arms hang down by your sides.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:53.242123+00', '2026-10-31 19:42:53.112+00'), ('B5xca8s', 'Toque nos Pés Circular com Mãos Entrelaçadas', 'Hands Clasped Circular Toe Touch', 'toque-nos-pes-circular-com-maos-entrelacadas', 'https://static.exercisedb.dev/media/B5xca8s.gif', 'catalogo/toque-nos-pes-circular-com-maos-entrelacadas--B5xca8s.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/toque-nos-pes-circular-com-maos-entrelacadas--B5xca8s.gif', ARRAY['Coxas'], ARRAY['Peso Corporal'], ARRAY['Glúteos'], ARRAY['Posteriores de Coxa','Quadríceps','Panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and your hands clasped together ahead of your chest.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Soften the knees and let the hips start the fold.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Keep the movement controlled throughout the range.","Step:6 Hold briefly at a comfortable depth, then rise by extending the hips."]', '2026-10-31 19:42:53.583781+00', '2026-10-31 19:42:53.449+00'), ('b63ZzGe', 'Agachamento Sumô Profundo com Apoio', 'potty squat with support', 'agachamento-sumo-profundo-com-apoio', 'https://static.exercisedb.dev/media/b63ZzGe.gif', 'catalogo/agachamento-sumo-profundo-com-apoio--b63ZzGe.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-sumo-profundo-com-apoio--b63ZzGe.gif', ARRAY['Coxas'], ARRAY['Peso Corporal'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de Coxa','Panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, toes pointing slightly outward.","Step:2 Use a stable support, such as a chair or wall, for balance.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:53.520881+00', '2026-10-31 19:42:53.38+00'), ('B6dAO1t', 'Rosca de Punho Sentada no Smith', 'smith seated wrist curl', 'rosca-de-punho-sentada-no-smith', 'https://static.exercisedb.dev/media/B6dAO1t.gif', 'catalogo/rosca-de-punho-sentada-no-smith--B6dAO1t.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-sentada-no-smith--B6dAO1t.gif', ARRAY['Antebraços'], ARRAY['Smith Machine'], ARRAY['Antebraços'], ARRAY['Bíceps','Braquial'], '["Step:1 Take a seat on a bench in front of a Smith machine with your feet planted.","Step:2 Hold the barbell with palms facing up, hands about shoulder width.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:53.638916+00', '2026-10-31 19:42:53.511+00'), ('b6hQYMb', 'Rosca Scott na Máquina', 'Machine Preacher Curl', 'rosca-scott-na-maquina', 'https://static.exercisedb.dev/media/b6hQYMb.gif', 'catalogo/rosca-scott-na-maquina--b6hQYMb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-na-maquina--b6hQYMb.gif', ARRAY['Braços'], ARRAY['Máquina'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Set your upper arms on the pad and grip the handles with palms facing up.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:53.747292+00', '2026-10-31 19:42:53.612+00'), ('b9kqlBy', 'Remada Renegado Alternada com Kettlebell', 'kettlebell alternating renegade row', 'remada-renegado-alternada-com-kettlebell', 'https://static.exercisedb.dev/media/b9kqlBy.gif', 'catalogo/remada-renegado-alternada-com-kettlebell--b9kqlBy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-renegado-alternada-com-kettlebell--b9kqlBy.gif', ARRAY['Costas'], ARRAY['Kettlebell'], ARRAY['Parte Superior das Costas'], ARRAY['Core','Deltoides'], '["Step:1 Begin in a high plank position with your hands gripping the kettlebells and your feet about hip width.","Step:2 Brace your trunk and keep your body in a straight line from head to heels.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:42:53.816309+00', '2026-10-31 19:42:53.686+00'), ('BaE7O6U', 'Elevação de Joelhos Oblíqua na Barra Fixa', 'hanging oblique knee raise', 'elevacao-de-joelhos-obliqua-na-barra-fixa', 'https://static.exercisedb.dev/media/BaE7O6U.gif', 'catalogo/elevacao-de-joelhos-obliqua-na-barra-fixa--BaE7O6U.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-joelhos-obliqua-na-barra-fixa--BaE7O6U.gif', ARRAY['Abdômen'], ARRAY['Peso Corporal'], ARRAY['Abdominais'], ARRAY['Oblíquos'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your knees toward your chest, twisting your torso to the side as you do so.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:42:54.151262+00', '2026-10-31 19:42:54.013+00'), ('BbfB8Gb', 'Toque nos Pés em Pé', 'Standing Toe Touch', 'toque-nos-pes-em-pe', 'https://static.exercisedb.dev/media/BbfB8Gb.gif', 'catalogo/toque-nos-pes-em-pe--BbfB8Gb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/toque-nos-pes-em-pe--BbfB8Gb.gif', ARRAY['Coxas'], ARRAY['Peso Corporal'], ARRAY['Glúteos'], ARRAY['Posteriores de Coxa','Panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and your arms by your sides.","Step:2 Bend forward at the waist, with your spine steady and your knees soft.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold briefly at a comfortable depth, then rise by extending the hips."]', '2026-10-31 19:42:54.056183+00', '2026-10-31 19:42:53.926+00'), ('bBi35y3', 'Desenvolvimento Alternado em Pé com Halteres', 'dumbbell standing alternate overhead press', 'desenvolvimento-alternado-em-pe-com-halteres', 'https://static.exercisedb.dev/media/bBi35y3.gif', 'catalogo/desenvolvimento-alternado-em-pe-com-halteres--bBi35y3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-alternado-em-pe-com-halteres--bBi35y3.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Tríceps','Core'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Step:2 Before moving, press one dumbbell overhead, fully extending your arm.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:54.241615+00', '2026-10-31 19:42:54.103+00'), ('bbLR7fB', 'Elevação de Pernas Estendidas Deitado com Elástico', 'Band Lying Straight-Leg Raise', 'elevacao-de-pernas-estendidas-deitado-com-elastico', 'https://static.exercisedb.dev/media/bbLR7fB.gif', 'catalogo/elevacao-de-pernas-estendidas-deitado-com-elastico--bbLR7fB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-estendidas-deitado-com-elastico--bbLR7fB.gif', ARRAY['Abdômen'], ARRAY['Elástico'], ARRAY['Abdominais'], ARRAY['Flexores do Quadril'], '["Step:1 Settle onto your back with your legs straight and your feet together.","Step:2 Set the band around the arches of your feet and hold the ends of the band with your hands.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:42:54.374007+00', '2026-10-31 19:42:54.246+00'), ('BCGQ6J5', 'Rosca Direta Pegada Fechada no Cabo', 'Cable Close-Grip Curl', 'rosca-direta-pegada-fechada-no-cabo', 'https://static.exercisedb.dev/media/BCGQ6J5.gif', 'catalogo/rosca-direta-pegada-fechada-no-cabo--BCGQ6J5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-pegada-fechada-no-cabo--BCGQ6J5.gif', ARRAY['Braços'], ARRAY['Cabo'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Connect a straight bar to a low pulley cable machine.","Step:2 Face the machine with your feet about shoulder width and your knees soft.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:42:54.863171+00', '2026-10-31 19:42:54.735+00'), ('BCs0G2F', 'Elevação Alternada de Pernas Sentado com Barra', 'Barbell Seated Alternate Leg Raise', 'elevacao-alternada-de-pernas-sentado-com-barra', 'https://static.exercisedb.dev/media/BCs0G2F.gif', 'catalogo/elevacao-alternada-de-pernas-sentado-com-barra--BCs0G2F.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-alternada-de-pernas-sentado-com-barra--BCs0G2F.gif', ARRAY['Abdômen'], ARRAY['Barra'], ARRAY['Abdominais'], ARRAY['Flexores do Quadril','Quadríceps'], '["Step:1 Take a seat on a bench with your back straight and hold a barbell across your thighs.","Step:2 Set your hands on the sides of the bench for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the legs slowly without swinging or losing your trunk position; switch sides when the set calls for it."]', '2026-10-31 19:42:54.632682+00', '2026-10-31 19:42:54.496+00'), ('BCUR88E', 'Tríceps Francês Unilateral em Pé com Halter', 'Dumbbell Standing Single-Arm Extension', 'triceps-frances-unilateral-em-pe-com-halter', 'https://static.exercisedb.dev/media/BCUR88E.gif', 'catalogo/triceps-frances-unilateral-em-pe-com-halter--BCUR88E.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-unilateral-em-pe-com-halter--BCUR88E.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand.","Step:2 Before moving, raise the dumbbell overhead, fully extending your arm.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:42:54.622523+00', '2026-10-31 19:42:54.487+00'), ('bd5b860', 'Rolo de Punho', 'wrist rollerer', 'rolo-de-punho', 'https://static.exercisedb.dev/media/bd5b860.gif', 'catalogo/rolo-de-punho--bd5b860.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rolo-de-punho--bd5b860.gif', ARRAY['Antebraços'], ARRAY['Com Peso'], ARRAY['Antebraços'], ARRAY['Bíceps','Tríceps'], '["Step:1 Connect a weight to one end of a rope or bar.","Step:2 Take hold of the other end of the rope or bar with both hands, palms facing down.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:54.802323+00', '2026-10-31 19:42:54.665+00'), ('bdWcbaU', 'Agachamento Frankenstein', 'frankenstein squat', 'agachamento-frankenstein', 'https://static.exercisedb.dev/media/bdWcbaU.gif', 'catalogo/agachamento-frankenstein--bdWcbaU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frankenstein--bdWcbaU.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de Coxa','Panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and hold the barbell ahead of your body with straight arms.","Step:2 With your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:55.087158+00', '2026-10-31 19:42:54.956+00'), ('bfiHMpI', 'Supino Inclinado com Halteres na Bola Suíça', 'dumbbell incline press on exercise ball', 'supino-inclinado-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/bfiHMpI.gif', 'catalogo/supino-inclinado-com-halteres-na-bola-suica--bfiHMpI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-halteres-na-bola-suica--bfiHMpI.gif', ARRAY['Peitoral'], ARRAY['Halteres','Bola Suíça'], ARRAY['Peitoral'], ARRAY['Deltoides','Tríceps'], '["Step:1 Take a seat on an exercise ball with a dumbbell in each hand, palms facing forward.","Step:2 With control walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:55.225503+00', '2026-10-31 19:42:55.096+00'), ('Bg5JKSH', 'Supino Inclinado Unilateral com Halter na Bola Suíça', 'Dumbbell Incline Single-Arm Press On Exercise Ball', 'supino-inclinado-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/Bg5JKSH.gif', 'catalogo/supino-inclinado-unilateral-com-halter-na-bola-suica--Bg5JKSH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-unilateral-com-halter-na-bola-suica--Bg5JKSH.gif', ARRAY['Peitoral'], ARRAY['Halteres','Bola Suíça'], ARRAY['Peitoral'], ARRAY['Deltoides','Tríceps'], '["Step:1 Take a seat on an exercise ball with a dumbbell in one hand, feet planted.","Step:2 With control walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:42:56.008507+00', '2026-10-31 19:42:55.879+00'), ('BgljGjd', 'Remada Cavalinho Invertida na Máquina', 'Machine Reverse T-Bar Row', 'remada-cavalinho-invertida-na-maquina', 'https://static.exercisedb.dev/media/BgljGjd.gif', 'catalogo/remada-cavalinho-invertida-na-maquina--BgljGjd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-cavalinho-invertida-na-maquina--BgljGjd.gif', ARRAY['Costas'], ARRAY['Máquina'], ARRAY['Parte Superior das Costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Set the seat height and footplate position on the leverage machine.","Step:2 Take a seat on the machine with your chest against the pad and your feet flat on the footplate.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:55.490032+00', '2026-10-31 19:42:55.359+00'), ('BIb1tGo', 'Rosca Unilateral em Pé com Halter Apoiado no Banco Inclinado', 'Dumbbell Standing Single-Arm Curl (Over Incline Bench)', 'rosca-unilateral-em-pe-com-halter-apoiado-no-banco-inclinado', 'https://static.exercisedb.dev/media/BIb1tGo.gif', 'catalogo/rosca-unilateral-em-pe-com-halter-apoiado-no-banco-inclinado--BIb1tGo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-unilateral-em-pe-com-halter-apoiado-no-banco-inclinado--BIb1tGo.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand with your palm facing forward.","Step:2 Set your other hand on an incline bench for support.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:55.429527+00', '2026-10-31 19:42:55.301+00'), ('BJ0Hz5L', 'Remada Curvada com Halteres', 'dumbbell bent over row', 'remada-curvada-com-halteres', 'https://static.exercisedb.dev/media/BJ0Hz5L.gif', 'catalogo/remada-curvada-com-halteres--BJ0Hz5L.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-com-halteres--BJ0Hz5L.gif', ARRAY['Costas'], ARRAY['Halteres'], ARRAY['Parte Superior das Costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a dumbbell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:55.715431+00', '2026-10-31 19:42:55.577+00'), ('bjqbauy', 'Aperto de Mão em Pé com Peso', 'weighted standing hand squeeze', 'aperto-de-mao-em-pe-com-peso', 'https://static.exercisedb.dev/media/bjqbauy.gif', 'catalogo/aperto-de-mao-em-pe-com-peso--bjqbauy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/aperto-de-mao-em-pe-com-peso--bjqbauy.gif', ARRAY['Antebraços'], ARRAY['Com Peso'], ARRAY['Antebraços'], ARRAY['Bíceps','Tríceps'], '["Step:1 Stand and set your feet about shoulder width and hold a weight in each hand.","Step:2 Reach your arms straight in front of you, palms facing each other.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:56.065305+00', '2026-10-31 19:42:55.678+00'), ('bJYHBIN', 'Elevação de Panturrilha em Pé com Peso Corporal', 'bodyweight standing calf raise', 'elevacao-de-panturrilha-em-pe-com-peso-corporal', 'https://static.exercisedb.dev/media/bJYHBIN.gif', 'catalogo/elevacao-de-panturrilha-em-pe-com-peso-corporal--bJYHBIN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-em-pe-com-peso-corporal--bJYHBIN.gif', ARRAY['Panturrilhas'], ARRAY['Peso Corporal'], ARRAY['Panturrilhas'], ARRAY['Tornozelos','Pés'], '["Step:1 Stand and set your feet about shoulder width, toes pointing forward.","Step:2 Set your hands on a wall or stable surface for balance.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:55.913101+00', '2026-10-31 19:42:55.782+00'), ('BKa8dmT', 'Rosca punho neutra com halter sobre o banco', 'dumbbell over bench neutral wrist curl', 'rosca-punho-neutra-com-halter-sobre-o-banco', 'https://static.exercisedb.dev/media/BKa8dmT.gif', 'catalogo/rosca-punho-neutra-com-halter-sobre-o-banco--BKa8dmT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-punho-neutra-com-halter-sobre-o-banco--BKa8dmT.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.","Step:2 Support the forearms on the bench while leaving the wrists free beyond its edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:56.415291+00', '2026-10-31 19:42:56.274+00'), ('bKWbrTA', 'Remada unilateral com toalha', 'Single-Arm Towel Row', 'remada-unilateral-com-toalha', 'https://static.exercisedb.dev/media/bKWbrTA.gif', 'catalogo/remada-unilateral-com-toalha--bKWbrTA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-unilateral-com-toalha--bKWbrTA.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a towel with one hand.","Step:2 Bend forward at the waist, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:42:56.297111+00', '2026-10-31 19:42:56.165+00'), ('BkxB8LW', 'Desenvolvimento sentado com kettlebell', 'kettlebell seated press', 'desenvolvimento-sentado-com-kettlebell', 'https://static.exercisedb.dev/media/BkxB8LW.gif', 'catalogo/desenvolvimento-sentado-com-kettlebell--BkxB8LW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-com-kettlebell--BkxB8LW.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a kettlebell in each hand at shoulder height, palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:56.509139+00', '2026-10-31 19:42:56.379+00'), ('BL3GHeY', 'Prancha planche com pernas afastadas', 'straddle planche', 'prancha-planche-com-pernas-afastadas', 'https://static.exercisedb.dev/media/BL3GHeY.gif', 'catalogo/prancha-planche-com-pernas-afastadas--BL3GHeY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-planche-com-pernas-afastadas--BL3GHeY.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','tríceps','peitorais'], '["Step:1 Begin in a push-up position with your hands about shoulder width and your feet spread wide apart.","Step:2 Brace your trunk and With control shift your weight forward, bringing your shoulders over your hands.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:42:56.675048+00', '2026-10-31 19:42:56.546+00'), ('blBXysN', 'Desenvolvimento militar com dois kettlebells', 'Kettlebell Two-Arm Military Press', 'desenvolvimento-militar-com-dois-kettlebells', 'https://static.exercisedb.dev/media/blBXysN.gif', 'catalogo/desenvolvimento-militar-com-dois-kettlebells--blBXysN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-com-dois-kettlebells--blBXysN.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Step:2 Brace your trunk and press the kettlebells overhead, straighten your arms.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:56.703417+00', '2026-10-31 19:42:56.526+00'), ('BLCvwr2', 'Rosca inversa de punho com halter', 'dumbbell reverse wrist curl', 'rosca-inversa-de-punho-com-halter', 'https://static.exercisedb.dev/media/BLCvwr2.gif', 'catalogo/rosca-inversa-de-punho-com-halter--BLCvwr2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-de-punho-com-halter--BLCvwr2.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Take a seat on a bench or chair with your feet planted.","Step:2 Take a dumbbell in each hand with palms facing down.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:42:57.230885+00', '2026-10-31 19:42:57.093+00'), ('bLyQokI', 'London bridge com corda', 'london bridge', 'london-bridge-com-corda', 'https://static.exercisedb.dev/media/bLyQokI.gif', 'catalogo/london-bridge-com-corda--bLyQokI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/london-bridge-com-corda--bLyQokI.gif', ARRAY['costas'], ARRAY['corda'], ARRAY['parte superior das costas'], ARRAY['deltoides','bíceps','antebraços'], '["Step:1 Connect the rope to a high anchor point.","Step:2 Face the away from the anchor point from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:42:56.990174+00', '2026-10-31 19:42:56.861+00'), ('bmBf7LN', 'Rotação externa de ombro deitado com halter', 'dumbbell lying external shoulder rotation', 'rotacao-externa-de-ombro-deitado-com-halter', 'https://static.exercisedb.dev/media/bmBf7LN.gif', 'catalogo/rotacao-externa-de-ombro-deitado-com-halter--bmBf7LN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-externa-de-ombro-deitado-com-halter--bmBf7LN.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['manguito rotador','tríceps'], '["Step:1 Settle onto your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Step:2 Take a dumbbell in your hand with your palm facing down.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:42:57.045949+00', '2026-10-31 19:42:56.917+00'), ('BMMolZ3', 'Abdominal com joelhos flexionados (tuck crunch)', 'tuck crunch', 'abdominal-com-joelhos-flexionados-tuck-crunch', 'https://static.exercisedb.dev/media/BMMolZ3.gif', 'catalogo/abdominal-com-joelhos-flexionados-tuck-crunch--BMMolZ3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-joelhos-flexionados-tuck-crunch--BMMolZ3.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:57.2993+00', '2026-10-31 19:42:57.17+00'), ('BmrwWzo', 'Puxada sumô entre as pernas com halter (pull through)', 'dumbbell sumo pull through', 'puxada-sumo-entre-as-pernas-com-halter-pull-through', 'https://static.exercisedb.dev/media/BmrwWzo.gif', 'catalogo/puxada-sumo-entre-as-pernas-com-halter-pull-through--BmrwWzo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-sumo-entre-as-pernas-com-halter-pull-through--BmrwWzo.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','core'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointed outwards.","Step:2 Take a dumbbell with both hands ahead of your body, arms extended.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:42:57.319298+00', '2026-10-31 19:42:57.192+00'), ('bmwlYvD', 'Gorilla chin', 'gorilla chin', 'gorilla-chin', 'https://static.exercisedb.dev/media/bmwlYvD.gif', 'catalogo/gorilla-chin--bmwlYvD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/gorilla-chin--bmwlYvD.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['antebraços','bíceps'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Hold a pull-up bar with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:42:57.605495+00', '2026-10-31 19:42:57.473+00'), ('Bn6TXyO', 'Abdominal supra', 'sit-up', 'abdominal-supra', 'https://static.exercisedb.dev/media/Bn6TXyO.gif', 'catalogo/abdominal-supra--Bn6TXyO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-supra--Bn6TXyO.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:42:57.609317+00', '2026-10-31 19:42:57.48+00'), ('bndCa3Q', 'Supino com pinos (pin press) com barra', 'barbell pin presses', 'supino-com-pinos-pin-press-com-barra', 'https://static.exercisedb.dev/media/bndCa3Q.gif', 'catalogo/supino-com-pinos-pin-press-com-barra--bndCa3Q.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-com-pinos-pin-press-com-barra--bndCa3Q.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Prepare a barbell on a power rack at chest height.","Step:2 Face the barbell and position yourself underneath it, from a stable stance with feet about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:58.129556+00', '2026-10-31 19:42:57.998+00'), ('bOOdeyc', 'Panturrilha sentado na máquina', 'Machine Seated Calf Raise', 'panturrilha-sentado-na-maquina', 'https://static.exercisedb.dev/media/bOOdeyc.gif', 'catalogo/panturrilha-sentado-na-maquina--bOOdeyc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-na-maquina--bOOdeyc.gif', ARRAY['panturrilhas'], ARRAY['máquina articulada'], ARRAY['panturrilhas'], ARRAY['sóleo','estabilizadores do tornozelo'], '["Step:1 Set the seat height so that your knees are soft and your feet are flat on the footplate.","Step:2 Set your toes on the footplate with your heels hanging off the edge.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:42:58.149871+00', '2026-10-31 19:42:57.766+00'), ('bpJL2Qs', 'Tríceps com halter pegada pronada', 'dumbbell pronate-grip triceps extension', 'triceps-com-halter-pegada-pronada', 'https://static.exercisedb.dev/media/bpJL2Qs.gif', 'catalogo/triceps-com-halter-pegada-pronada--bpJL2Qs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-com-halter-pegada-pronada--bpJL2Qs.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench or chair with your back straight and feet planted.","Step:2 Take a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:42:57.895164+00', '2026-10-31 19:42:57.767+00'), ('Bpkf41o', 'Crucifixo unilateral com halter na bola suíça', 'Dumbbell Single-Arm Chest Fly On Exercise Ball', 'crucifixo-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/Bpkf41o.gif', 'catalogo/crucifixo-unilateral-com-halter-na-bola-suica--Bpkf41o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-unilateral-com-halter-na-bola-suica--Bpkf41o.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with a dumbbell in one hand and your feet planted.","Step:2 Step your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:42:58.437876+00', '2026-10-31 19:42:58.3+00'), ('BqgCRif', 'Cuban press com halter', 'dumbbell cuban press', 'cuban-press-com-halter', 'https://static.exercisedb.dev/media/BqgCRif.gif', 'catalogo/cuban-press-com-halter--BqgCRif.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cuban-press-com-halter--BqgCRif.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder height with your palms facing down.","Step:2 With your core engaged and your back straight, press the dumbbells straight up overhead until your arms are straight.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:42:58.228299+00', '2026-10-31 19:42:58.09+00'), ('bQHPBU3', 'Pullover unilateral com halter na bola suíça', 'Dumbbell Single-Arm Pullover On Exercise Ball', 'pullover-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/bQHPBU3.gif', 'catalogo/pullover-unilateral-com-halter-na-bola-suica--bQHPBU3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-unilateral-com-halter-na-bola-suica--bQHPBU3.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['tríceps','latíssimo do dorso','romboides'], '["Step:1 Take a seat on an exercise ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a dumbbell with one hand and extend your arm straight up above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs; switch sides when the set calls for it."]', '2026-10-31 19:42:58.717448+00', '2026-10-31 19:42:58.585+00'), ('bQy2Eni', 'Tríceps coice unilateral com halter', 'Dumbbell Single-Arm Kickback', 'triceps-coice-unilateral-com-halter', 'https://static.exercisedb.dev/media/bQy2Eni.gif', 'catalogo/triceps-coice-unilateral-com-halter--bQy2Eni.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-unilateral-com-halter--bQy2Eni.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in your right hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:42:58.733345+00', '2026-10-31 19:42:58.598+00'), ('BReCuOn', 'Remada agachada com toalha (peso corporal)', 'bodyweight squatting row (with towel)', 'remada-agachada-com-toalha-peso-corporal', 'https://static.exercisedb.dev/media/BReCuOn.gif', 'catalogo/remada-agachada-com-toalha-peso-corporal--BReCuOn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-agachada-com-toalha-peso-corporal--BReCuOn.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a towel in front of you with your palms facing down.","Step:2 Bend your knees and lower your body into a squat position, with your spine steady and your chest up.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:58.733235+00', '2026-10-31 19:42:58.605+00'), ('BRImeP8', 'Mergulho sentado na máquina', 'Machine Seated Dip', 'mergulho-sentado-na-maquina', 'https://static.exercisedb.dev/media/BRImeP8.gif', 'catalogo/mergulho-sentado-na-maquina--BRImeP8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-sentado-na-maquina--BRImeP8.gif', ARRAY['braços'], ARRAY['máquina articulada'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Step:2 Hold the handles of the leverage machine with your palms facing down and your arms straight.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:42:58.797415+00', '2026-10-31 19:42:58.664+00'), ('bRlbdjK', 'Encolhimento declinado com halter', 'dumbbell decline shrug', 'encolhimento-declinado-com-halter', 'https://static.exercisedb.dev/media/bRlbdjK.gif', 'catalogo/encolhimento-declinado-com-halter--bRlbdjK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-declinado-com-halter--bRlbdjK.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['trapézio'], ARRAY['deltoides','romboides'], '["Step:1 Prepare a decline bench at a 45-degree angle.","Step:2 Position yourself face down on the bench with your chest and stomach resting on it.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:42:59.043688+00', '2026-10-31 19:42:58.911+00'), ('bTpEUcm', 'Agachamento com barra baixa (low bar)', 'barbell low bar squat', 'agachamento-com-barra-baixa-low-bar', 'https://static.exercisedb.dev/media/bTpEUcm.gif', 'catalogo/agachamento-com-barra-baixa-low-bar--bTpEUcm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-barra-baixa-low-bar--bTpEUcm.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and the barbell resting on your upper back.","Step:2 With your chest up and core engaged, With control lower your body by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:42:59.532071+00', '2026-10-31 19:42:59.403+00'), ('BU15nH4', 'Rosca direta alternada com halteres', 'dumbbell alternate biceps curl', 'rosca-direta-alternada-com-halteres', 'https://static.exercisedb.dev/media/BU15nH4.gif', 'catalogo/rosca-direta-alternada-com-halteres--BU15nH4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-alternada-com-halteres--BU15nH4.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:59.333276+00', '2026-10-31 19:42:59.206+00'), ('bWlZvXh', 'Postura da borboleta (ioga)', 'butterfly yoga pose', 'postura-da-borboleta-ioga', 'https://static.exercisedb.dev/media/bWlZvXh.gif', 'catalogo/postura-da-borboleta-ioga--bWlZvXh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/postura-da-borboleta-ioga--bWlZvXh.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['adutores'], ARRAY['posteriores de coxa','adutores'], '["Step:1 Take a seat on the floor with your legs extended in front of you.","Step:2 Bend your knees and bring the soles of your feet together, letting your knees to fall out to the sides.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:59.383506+00', '2026-10-31 19:42:59.254+00'), ('BWnJR72', 'Alongamento de quadríceps deitado de lado', 'lying (side) quads stretch', 'alongamento-de-quadriceps-deitado-de-lado', 'https://static.exercisedb.dev/media/BWnJR72.gif', 'catalogo/alongamento-de-quadriceps-deitado-de-lado--BWnJR72.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-quadriceps-deitado-de-lado--BWnJR72.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['posteriores de coxa'], '["Step:1 Settle onto your side with your legs straight.","Step:2 Before moving, bend your top leg and grab your ankle or foot with your hand.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:42:59.478296+00', '2026-10-31 19:42:59.35+00'), ('BwSNDGt', 'Rosca de punho inversa com halter unilateral', 'Dumbbell Single-Arm Reverse Wrist Curl', 'rosca-de-punho-inversa-com-halter-unilateral', 'https://static.exercisedb.dev/media/BwSNDGt.gif', 'catalogo/rosca-de-punho-inversa-com-halter-unilateral--BwSNDGt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-com-halter-unilateral--BwSNDGt.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['extensores do punho'], '["Step:1 Take a seat on a bench or chair with your feet planted.","Step:2 Take a dumbbell in one hand with palms facing down, palm facing down.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:42:59.97931+00', '2026-10-31 19:42:59.848+00'), ('bWxq4op', 'Rosca Scott inversa com halter unilateral', 'Dumbbell Single-Arm Reverse Preacher Curl', 'rosca-scott-inversa-com-halter-unilateral', 'https://static.exercisedb.dev/media/bWxq4op.gif', 'catalogo/rosca-scott-inversa-com-halter-unilateral--bWxq4op.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-inversa-com-halter-unilateral--bWxq4op.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with palms facing up.","Step:2 Lower the dumbbell With control until your arm is straight.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:42:59.928215+00', '2026-10-31 19:42:59.801+00'), ('ByX0WxV', 'Rosca martelo inclinada com halteres', 'dumbbell incline hammer curl', 'rosca-martelo-inclinada-com-halteres', 'https://static.exercisedb.dev/media/ByX0WxV.gif', 'catalogo/rosca-martelo-inclinada-com-halteres--ByX0WxV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-inclinada-com-halteres--ByX0WxV.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, palms facing your torso and arms straight.","Step:2 Keep your back against the bench and your feet planted.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:00.524362+00', '2026-10-31 19:43:00.396+00'), ('bZGHsAZ', 'Remada invertida', 'inverted row', 'remada-invertida', 'https://static.exercisedb.dev/media/bZGHsAZ.gif', 'catalogo/remada-invertida--bZGHsAZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-invertida--bZGHsAZ.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Prepare a bar at waist height or use a suspension trainer.","Step:2 Face the bar or suspension trainer, from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:00.08888+00', '2026-10-31 19:42:59.96+00'), ('bZq4bwK', 'Mergulho para tríceps com peso', 'Weighted Triceps Dips', 'mergulho-para-triceps-com-peso', 'https://static.exercisedb.dev/media/bZq4bwK.gif', 'catalogo/mergulho-para-triceps-com-peso--bZq4bwK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-para-triceps-com-peso--bZq4bwK.gif', ARRAY['braços'], ARRAY['peso adicional'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge next to your hips.","Step:2 Move your butt off the front of the bench with your legs extended in front of you.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:00.102651+00', '2026-10-31 19:42:59.974+00'), ('C0eCeEt', 'Elevação de pernas com rotação', 'twisted leg raise', 'elevacao-de-pernas-com-rotacao', 'https://static.exercisedb.dev/media/C0eCeEt.gif', 'catalogo/elevacao-de-pernas-com-rotacao--C0eCeEt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-com-rotacao--C0eCeEt.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Set your hands under your glutes for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:43:00.573126+00', '2026-10-31 19:43:00.436+00'), ('C0MA9bC', 'Remada curvada unilateral com halter', 'Dumbbell Single-Arm Bent-Over Row', 'remada-curvada-unilateral-com-halter', 'https://static.exercisedb.dev/media/C0MA9bC.gif', 'catalogo/remada-curvada-unilateral-com-halter--C0MA9bC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-unilateral-com-halter--C0MA9bC.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand with your palm facing your body.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:00.567334+00', '2026-10-31 19:43:00.436+00'), ('c16nYGA', 'Supino unilateral com rotação com elástico', 'Band Single-Arm Twisting Chest Press', 'supino-unilateral-com-rotacao-com-elastico', 'https://static.exercisedb.dev/media/c16nYGA.gif', 'catalogo/supino-unilateral-com-rotacao-com-elastico--c16nYGA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-com-rotacao-com-elastico--c16nYGA.gif', ARRAY['peito'], ARRAY['faixa elástica'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Connect the band to a sturdy anchor point at chest height.","Step:2 Stand and set your side facing the anchor point and grab the band with one hand.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weights up while turning the palms inward; reverse the turn as you lower.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:00.700092+00', '2026-10-31 19:43:00.557+00'), ('C31LMnP', 'Agachamento unilateral', 'Single-Leg Squat', 'agachamento-unilateral', 'https://static.exercisedb.dev/media/C31LMnP.gif', 'catalogo/agachamento-unilateral--C31LMnP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-unilateral--C31LMnP.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Reach one leg forward, keeping it off the ground.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent; switch sides when the set calls for it."]', '2026-10-31 19:43:00.666082+00', '2026-10-31 19:43:00.538+00'), ('c3Pfhti', 'Alongamento lateral de dorsais com rolo', 'roller side lat stretch', 'alongamento-lateral-de-dorsais-com-rolo', 'https://static.exercisedb.dev/media/c3Pfhti.gif', 'catalogo/alongamento-lateral-de-dorsais-com-rolo--c3Pfhti.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lateral-de-dorsais-com-rolo--c3Pfhti.gif', ARRAY['costas'], ARRAY['rolo'], ARRAY['dorsais'], ARRAY['deltoides','tríceps'], '["Step:1 Stand and set your feet about shoulder width and hold the roller with both hands ahead of your body.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:01.354223+00', '2026-10-31 19:43:01.226+00'), ('c3QQLPi', 'Tríceps coice no cabo', 'cable rear drive', 'triceps-coice-no-cabo', 'https://static.exercisedb.dev/media/c3QQLPi.gif', 'catalogo/triceps-coice-no-cabo--c3QQLPi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-no-cabo--c3QQLPi.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['deltoides','costas'], '["Step:1 Connect a handle to a low pulley cable machine and stand turned away from the machine.","Step:2 Hold the handle with palms facing down and extend your arms straight out in front of you.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:01.111519+00', '2026-10-31 19:43:00.98+00'), ('C5jncD2', 'Flexão de perna unilateral em pé', 'standing single leg curl', 'flexao-de-perna-unilateral-em-pe', 'https://static.exercisedb.dev/media/C5jncD2.gif', 'catalogo/flexao-de-perna-unilateral-em-pe--C5jncD2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-perna-unilateral-em-pe--C5jncD2.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos'], '["Step:1 Stand and set your feet about hip width and your hands on your hips.","Step:2 Transfer your weight onto your left leg and lift your right foot off the ground, bending your knee.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:01.026435+00', '2026-10-31 19:43:00.898+00'), ('c8f5cSY', 'Adução de quadril deitado de lado', 'Side-Lying Hip Adduction', 'aducao-de-quadril-deitado-de-lado', 'https://static.exercisedb.dev/media/c8f5cSY.gif', 'catalogo/aducao-de-quadril-deitado-de-lado--c8f5cSY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/aducao-de-quadril-deitado-de-lado--c8f5cSY.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['adutores'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Settle onto your side with your legs straight and stacked on top of each other.","Step:2 Set your bottom arm under your head for support.","Step:3 Square the pelvis before moving the working leg.","Step:4 Draw the working leg inward against resistance without leaning sideways.","Step:5 Move only as far as the pelvis can remain steady.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:01.326591+00', '2026-10-31 19:43:01.172+00'), ('c8oybX6', 'Remada sentada elevada com corda no cabo', 'cable rope elevated seated row', 'remada-sentada-elevada-com-corda-no-cabo', 'https://static.exercisedb.dev/media/c8oybX6.gif', 'catalogo/remada-sentada-elevada-com-corda-no-cabo--c8oybX6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-elevada-com-corda-no-cabo--c8oybX6.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the elevated seat facing the cable machine.","Step:2 Take a rope end in each hand with the palms facing each other.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:01.575282+00', '2026-10-31 19:43:01.436+00'), ('C9LuR4A', 'Panturrilha burro na máquina', 'Machine Donkey Calf Raise', 'panturrilha-burro-na-maquina', 'https://static.exercisedb.dev/media/C9LuR4A.gif', 'catalogo/panturrilha-burro-na-maquina--C9LuR4A.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-burro-na-maquina--C9LuR4A.gif', ARRAY['panturrilhas'], ARRAY['máquina articulada'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set the leverage machine to the appropriate height for your body.","Step:2 Set yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:01.667018+00', '2026-10-31 19:43:01.533+00'), ('c9MnDRp', 'Elevação com halteres', 'dumbbell raise', 'elevacao-com-halteres', 'https://static.exercisedb.dev/media/c9MnDRp.gif', 'catalogo/elevacao-com-halteres--c9MnDRp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-com-halteres--c9MnDRp.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.","Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:01.666954+00', '2026-10-31 19:43:01.536+00'), ('Ca76jUE', 'Remada alternada com kettlebell', 'kettlebell alternating row', 'remada-alternada-com-kettlebell', 'https://static.exercisedb.dev/media/Ca76jUE.gif', 'catalogo/remada-alternada-com-kettlebell--Ca76jUE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alternada-com-kettlebell--Ca76jUE.gif', ARRAY['costas'], ARRAY['kettlebell'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a kettlebell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:01.954432+00', '2026-10-31 19:43:01.821+00'), ('cA9FuWG', 'Pullover com barra e cotovelos flexionados', 'barbell bent arm pullover', 'pullover-com-barra-e-cotovelos-flexionados', 'https://static.exercisedb.dev/media/cA9FuWG.gif', 'catalogo/pullover-com-barra-e-cotovelos-flexionados--cA9FuWG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-barra-e-cotovelos-flexionados--cA9FuWG.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['dorsais'], ARRAY['tríceps','peitorais'], '["Step:1 Settle onto a bench with your head at one end and your feet on the floor.","Step:2 Take a barbell with a shoulder-width grip and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:02.454045+00', '2026-10-31 19:43:02.068+00'), ('cALkHHX', 'Crucifixo cruzado com halteres (cruz de ferro)', 'dumbbell iron cross', 'crucifixo-cruzado-com-halteres-cruz-de-ferro', 'https://static.exercisedb.dev/media/cALkHHX.gif', 'catalogo/crucifixo-cruzado-com-halteres-cruz-de-ferro--cALkHHX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-cruzado-com-halteres-cruz-de-ferro--cALkHHX.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at your sides.","Step:2 Before moving, raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Open the arms out to the sides to form a T, then bring them back under control.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:02.172083+00', '2026-10-31 19:43:02.04+00'), ('cALKspW', 'Remada alta no cabo', 'cable upright row', 'remada-alta-no-cabo', 'https://static.exercisedb.dev/media/cALKspW.gif', 'catalogo/remada-alta-no-cabo--cALKspW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-no-cabo--cALKspW.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold the cable attachment with palms facing down.","Step:2 Keep your spine in a comfortable neutral position and your core engaged throughout the exercise.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:02.232083+00', '2026-10-31 19:43:02.09+00'), ('cAvTaSg', 'Tríceps coice com halteres na bola suíça', 'dumbbell kickbacks on exercise ball', 'triceps-coice-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/cAvTaSg.gif', 'catalogo/triceps-coice-com-halteres-na-bola-suica--cAvTaSg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-com-halteres-na-bola-suica--cAvTaSg.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['tríceps'], ARRAY['deltoides','costas'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:02.251889+00', '2026-10-31 19:43:02.124+00'), ('CB8WET1', 'Flexão inclinada com salto de profundidade', 'incline push up depth jump', 'flexao-inclinada-com-salto-de-profundidade', 'https://static.exercisedb.dev/media/CB8WET1.gif', 'catalogo/flexao-inclinada-com-salto-de-profundidade--CB8WET1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-inclinada-com-salto-de-profundidade--CB8WET1.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Choose an elevated surface, such as a bench or step, and place your hands about shoulder width on the edge.","Step:2 Move your feet back, keeping your body in a straight line from head to heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:02.578583+00', '2026-10-31 19:43:02.429+00'), ('CbFSYC1', 'Barra fixa por trás da nuca', 'rear pull-up', 'barra-fixa-por-tras-da-nuca', 'https://static.exercisedb.dev/media/CbFSYC1.gif', 'catalogo/barra-fixa-por-tras-da-nuca--CbFSYC1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-por-tras-da-nuca--CbFSYC1.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['dorsais'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with palms facing down, just beyond shoulder width.","Step:2 Suspend yourself from the bar with your arms straight and your body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull up with control, keeping the head neutral and the elbows moving down beside the torso.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:03.05273+00', '2026-10-31 19:43:02.925+00'), ('cbuFJrn', 'Encolhimento na máquina sem pegada', 'Machine Gripless Shrug', 'encolhimento-na-maquina-sem-pegada', 'https://static.exercisedb.dev/media/cbuFJrn.gif', 'catalogo/encolhimento-na-maquina-sem-pegada--cbuFJrn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-na-maquina-sem-pegada--cbuFJrn.gif', ARRAY['costas'], ARRAY['máquina'], ARRAY['trapézio'], ARRAY['deltoides','antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles or bars with palms facing down, keeping your arms straight.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:03.22506+00', '2026-10-31 19:43:03.093+00'), ('CcWEoWV', 'Corrida com passadas curtas', 'short stride run', 'corrida-com-passadas-curtas', 'https://static.exercisedb.dev/media/CcWEoWV.gif', 'catalogo/corrida-com-passadas-curtas--CcWEoWV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-com-passadas-curtas--CcWEoWV.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Choose an open space or a treadmill to perform the exercise.","Step:2 Stand tall and set your feet about hip width.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:03.134214+00', '2026-10-31 19:43:02.986+00'), ('CfKsRbG', 'Rosca alternada com halteres (com arm blaster)', 'dumbbell alternate biceps curl (with arm blaster)', 'rosca-alternada-com-halteres-com-arm-blaster', 'https://static.exercisedb.dev/media/CfKsRbG.gif', 'catalogo/rosca-alternada-com-halteres-com-arm-blaster--CfKsRbG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-alternada-com-halteres-com-arm-blaster--CfKsRbG.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.","Step:2 Set the arm blaster on your upper arms, ensuring a secure fit.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:03.015812+00', '2026-10-31 19:43:02.885+00'), ('CFN9P8G', 'Tríceps testa com barra W na bola suíça', 'EZ-Bar French Press On Exercise Ball', 'triceps-testa-com-barra-w-na-bola-suica', 'https://static.exercisedb.dev/media/CFN9P8G.gif', 'catalogo/triceps-testa-com-barra-w-na-bola-suica--CFN9P8G.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra-w-na-bola-suica--CFN9P8G.gif', ARRAY['braços'], ARRAY['barra W','bola suíça'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on an exercise ball and hold an EZ barbell with palms facing down.","Step:2 Reach your arms straight up, keeping your elbows close to your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Straighten the elbows to bring the bar overhead, then begin the next controlled rep."]', '2026-10-31 19:43:03.517716+00', '2026-10-31 19:43:03.389+00'), ('CggQhII', 'Desenvolvimento militar na máquina', 'Machine Military Press', 'desenvolvimento-militar-na-maquina', 'https://static.exercisedb.dev/media/CggQhII.gif', 'catalogo/desenvolvimento-militar-na-maquina--CggQhII.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-na-maquina--CggQhII.gif', ARRAY['ombros'], ARRAY['máquina'], ARRAY['deltoides'], ARRAY['tríceps','peitoral'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and position your hands just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:03.903826+00', '2026-10-31 19:43:03.769+00'), ('chfnQnM', 'Alongamento de peitoral com as mãos atrás', 'back pec stretch', 'alongamento-de-peitoral-com-as-maos-atras', 'https://static.exercisedb.dev/media/chfnQnM.gif', 'catalogo/alongamento-de-peitoral-com-as-maos-atras--chfnQnM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-peitoral-com-as-maos-atras--chfnQnM.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['dorsal'], ARRAY['deltoides','peitoral'], '["Step:1 Stand tall and set your feet about shoulder width.","Step:2 Reach your arms straight out in front of you, parallel to the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:03.513662+00', '2026-10-31 19:43:03.345+00'), ('CHpahtl', 'Cadeira abdutora', 'Machine Seated Hip Abduction', 'cadeira-abdutora', 'https://static.exercisedb.dev/media/CHpahtl.gif', 'catalogo/cadeira-abdutora--CHpahtl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cadeira-abdutora--CHpahtl.gif', ARRAY['coxas'], ARRAY['máquina'], ARRAY['abdutores'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the seat height so that your knees are at a 90-degree angle.","Step:2 Take a seat on the machine with your back against the backrest and your feet on the footrests.","Step:3 Square the pelvis before moving the working leg.","Step:4 Open the knees or legs against resistance without shifting your torso.","Step:5 Move only as far as the pelvis can remain steady.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:03.788824+00', '2026-10-31 19:43:03.654+00'), ('CI6baTY', 'Abdominal bottoms-up', 'bottoms-up', 'abdominal-bottoms-up', 'https://static.exercisedb.dev/media/CI6baTY.gif', 'catalogo/abdominal-bottoms-up--CI6baTY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-bottoms-up--CI6baTY.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and bring them toward your chest, keeping your feet off the ground.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:03.793049+00', '2026-10-31 19:43:03.665+00'), ('CjETvlw', 'Flexão, depressão e retração de ombro sentado no rolo com uma perna', 'Roller Seated Single Leg Shoulder Flexor Depressor Retractor', 'flexao-depressao-e-retracao-de-ombro-sentado-no-rolo-com-uma-perna', 'https://static.exercisedb.dev/media/CjETvlw.gif', 'catalogo/flexao-depressao-e-retracao-de-ombro-sentado-no-rolo-com-uma-perna--CjETvlw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-depressao-e-retracao-de-ombro-sentado-no-rolo-com-uma-perna--CjETvlw.gif', ARRAY['peito'], ARRAY['rolo'], ARRAY['peitoral'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on a flat surface with your legs extended in front of you.","Step:2 Take hold of the roller with both hands, palms facing down, and place it on your thighs.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:04.078668+00', '2026-10-31 19:43:03.951+00'), ('cJgSTmh', 'Abdominal oblíquo', 'oblique crunch', 'abdominal-obliquo', 'https://static.exercisedb.dev/media/cJgSTmh.gif', 'catalogo/abdominal-obliquo--cJgSTmh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-obliquo--cJgSTmh.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head or cross them over your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:04.091798+00', '2026-10-31 19:43:03.949+00'), ('CJwa0vD', 'Extensão de tríceps unilateral com halter, em pé e inclinado', 'Dumbbell Standing Bent Over Single-Arm Triceps Extension', 'extensao-de-triceps-unilateral-com-halter-em-pe-e-inclinado', 'https://static.exercisedb.dev/media/CJwa0vD.gif', 'catalogo/extensao-de-triceps-unilateral-com-halter-em-pe-e-inclinado--CJwa0vD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-unilateral-com-halter-em-pe-e-inclinado--CJwa0vD.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides','costas'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand.","Step:2 Bend forward at the waist, with your spine steady and parallel to the ground.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:43:04.367902+00', '2026-10-31 19:43:04.236+00'), ('CMAxnsG', 'Flexão de braço relógio', 'clock push-up', 'flexao-de-braco-relogio', 'https://static.exercisedb.dev/media/CMAxnsG.gif', 'catalogo/flexao-de-braco-relogio--CMAxnsG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-relogio--CMAxnsG.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitoral'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your body toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:04.349265+00', '2026-10-31 19:43:04.216+00'), ('CmEr4pM', 'Puxada atrás da nuca na polia com pegada aberta', 'Cable Wide-Grip Rear Pulldown Behind Neck', 'puxada-atras-da-nuca-na-polia-com-pegada-aberta', 'https://static.exercisedb.dev/media/CmEr4pM.gif', 'catalogo/puxada-atras-da-nuca-na-polia-com-pegada-aberta--CmEr4pM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-atras-da-nuca-na-polia-com-pegada-aberta--CmEr4pM.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['dorsal'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Set the cable machine so that the pulldown bar is at a height above your head.","Step:2 Sit on the seat and grab the pulldown bar with a wide overhand grip.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Draw the bar toward the upper back behind your head only as far as the shoulders allow comfortably.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:04.517592+00', '2026-10-31 19:43:04.391+00'), ('CosupLu', 'Prancha frontal com rotação', 'front plank with twist', 'prancha-frontal-com-rotacao', 'https://static.exercisedb.dev/media/CosupLu.gif', 'catalogo/prancha-frontal-com-rotacao--CosupLu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-frontal-com-rotacao--CosupLu.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','deltoides'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Step:2 Brace your trunk and glutes to maintain a stable position.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:04.880285+00', '2026-10-31 19:43:04.745+00'), ('cQ19bBP', 'Barra fixa estilo Rocky', 'rocky pull-up pulldown', 'barra-fixa-estilo-rocky', 'https://static.exercisedb.dev/media/cQ19bBP.gif', 'catalogo/barra-fixa-estilo-rocky--cQ19bBP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-estilo-rocky--cQ19bBP.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Take your place in front of a pull-up bar with your feet about shoulder width.","Step:2 Reach up to hold the bar with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:04.680855+00', '2026-10-31 19:43:04.547+00'), ('CQHoDm0', 'Tríceps testa declinado com barra W', 'EZ-Bar Decline Triceps Extension', 'triceps-testa-declinado-com-barra-w', 'https://static.exercisedb.dev/media/CQHoDm0.gif', 'catalogo/triceps-testa-declinado-com-barra-w--CQHoDm0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-declinado-com-barra-w--CQHoDm0.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a decline bench with your head lower than your feet and your feet secured.","Step:2 Take hold of the ez barbell with palms facing down, hands about shoulder width.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:05.002101+00', '2026-10-31 19:43:04.866+00'), ('CqhoytW', 'Elevação de quadril no Smith', 'smith hip raise', 'elevacao-de-quadril-no-smith', 'https://static.exercisedb.dev/media/CqhoytW.gif', 'catalogo/elevacao-de-quadril-no-smith--CqhoytW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-no-smith--CqhoytW.gif', ARRAY['abdômen'], ARRAY['Smith'], ARRAY['abdominais'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set yourself on the smith machine with your back against the pad and your feet about shoulder width.","Step:2 Set your hands on the barbell, just beyond shoulder width.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:43:04.957284+00', '2026-10-31 19:43:04.825+00'), ('CuaWCmC', 'Puxada lateral na polia com corda', 'cable lateral pulldown (with rope attachment)', 'puxada-lateral-na-polia-com-corda', 'https://static.exercisedb.dev/media/CuaWCmC.gif', 'catalogo/puxada-lateral-na-polia-com-corda--CuaWCmC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-lateral-na-polia-com-corda--CuaWCmC.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Connect a rope attachment to the cable machine at a high position.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:05.104028+00', '2026-10-31 19:43:04.956+00'), ('cuKYxhu', 'Inclinação pélvica em pé', 'standing pelvic tilt', 'inclinacao-pelvica-em-pe', 'https://static.exercisedb.dev/media/cuKYxhu.gif', 'catalogo/inclinacao-pelvica-em-pe--cuKYxhu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/inclinacao-pelvica-em-pe--cuKYxhu.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['abdominais'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Set your arms at your sides, or set your hands at your waist.","Step:3 Relax the shoulders and find a comfortable neutral starting position.","Step:4 Gently roll the pelvis to flatten and release the lower back through a small range.","Step:5 Use a small range and avoid forcing the lower back into the floor.","Step:6 Release the tilt gently and repeat without forcing the range."]', '2026-10-31 19:43:05.425567+00', '2026-10-31 19:43:05.297+00'), ('CvPn9WV', 'Puxada em pé na polia com corda', 'cable standing pulldown (with rope)', 'puxada-em-pe-na-polia-com-corda', 'https://static.exercisedb.dev/media/CvPn9WV.gif', 'catalogo/puxada-em-pe-na-polia-com-corda--CvPn9WV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-em-pe-na-polia-com-corda--CvPn9WV.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Connect a rope to the cable machine at the highest setting.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:05.91488+00', '2026-10-31 19:43:05.781+00'), ('cWemPG8', 'Rosca martelo com halteres no banco inclinado, de bruços', 'dumbbell prone incline hammer curl', 'rosca-martelo-com-halteres-no-banco-inclinado-de-brucos', 'https://static.exercisedb.dev/media/cWemPG8.gif', 'catalogo/rosca-martelo-com-halteres-no-banco-inclinado-de-brucos--cWemPG8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-com-halteres-no-banco-inclinado-de-brucos--cWemPG8.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Set the bench to a 45-degree incline.","Step:2 Position yourself face down on the bench with a dumbbell in each hand, palms facing each other.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:05.615386+00', '2026-10-31 19:43:05.466+00'), ('cwsAI4G', 'Encolhimento com halteres no banco declinado', 'dumbbell decline shrug', 'encolhimento-com-halteres-no-banco-declinado', 'https://static.exercisedb.dev/media/cwsAI4G.gif', 'catalogo/encolhimento-com-halteres-no-banco-declinado--cwsAI4G.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-com-halteres-no-banco-declinado--cwsAI4G.gif', ARRAY['costas'], ARRAY['halteres'], ARRAY['trapézio'], ARRAY['deltoides','romboides'], '["Step:1 Prepare a decline bench at a 45-degree angle.","Step:2 Position yourself face down on the bench with your chest and stomach resting against it.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:05.706978+00', '2026-10-31 19:43:05.576+00'), ('d1GgzTU', 'Barra fixa em L', 'l-pull-up', 'barra-fixa-em-l', 'https://static.exercisedb.dev/media/d1GgzTU.gif', 'catalogo/barra-fixa-em-l--d1GgzTU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-em-l--d1GgzTU.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with palms facing down, just beyond shoulder width.","Step:2 Hang with your arms straight and your body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:05.857308+00', '2026-10-31 19:43:05.725+00'), ('D1xYJAU', 'Rosca de punho com halter sobre o banco', 'dumbbell over bench wrist curl', 'rosca-de-punho-com-halter-sobre-o-banco', 'https://static.exercisedb.dev/media/D1xYJAU.gif', 'catalogo/rosca-de-punho-com-halter-sobre-o-banco--D1xYJAU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-com-halter-sobre-o-banco--D1xYJAU.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Take a seat on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Step:2 Let your wrists to hang over the edge of the bench.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:43:06.0094+00', '2026-10-31 19:43:05.868+00'), ('d5bTEPV', 'Step-up com elástico', 'band step-up', 'step-up-com-elastico', 'https://static.exercisedb.dev/media/d5bTEPV.gif', 'catalogo/step-up-com-elastico--d5bTEPV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/step-up-com-elastico--d5bTEPV.gif', ARRAY['coxas'], ARRAY['faixa elástica'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set a band around your thighs, just above your knees.","Step:2 Face a step or platform with your feet about hip width.","Step:3 Put the lead foot fully on the platform before shifting your weight onto it.","Step:4 Step onto the platform and drive through the lead foot to stand tall on it.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:06.185799+00', '2026-10-31 19:43:06.058+00'), ('D5yqP2p', 'Mergulho de tríceps na máquina com pegada pronada', 'Machine Overhand Triceps Dip', 'mergulho-de-triceps-na-maquina-com-pegada-pronada', 'https://static.exercisedb.dev/media/D5yqP2p.gif', 'catalogo/mergulho-de-triceps-na-maquina-com-pegada-pronada--D5yqP2p.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-de-triceps-na-maquina-com-pegada-pronada--D5yqP2p.gif', ARRAY['braços'], ARRAY['máquina articulada'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Set the machine to the appropriate height and secure your body in position.","Step:2 Hold the handles with palms facing down and position your body so that your arms are straight.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:06.616926+00', '2026-10-31 19:43:06.49+00'), ('d7z1Y7V', 'Abraço na bola suíça', 'exercise ball hug', 'abraco-na-bola-suica', 'https://static.exercisedb.dev/media/d7z1Y7V.gif', 'catalogo/abraco-na-bola-suica--d7z1Y7V.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abraco-na-bola-suica--d7z1Y7V.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['eretores da espinha'], ARRAY['deltoides','peitoral'], '["Step:1 Take a seat on the stability ball with your feet planted and your back straight.","Step:2 Take hold of the stability ball with both hands, hugging it close to your chest.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:06.459989+00', '2026-10-31 19:43:06.327+00'), ('d960PgE', 'Good morning sentado com barra', 'barbell seated good morning', 'good-morning-sentado-com-barra', 'https://static.exercisedb.dev/media/d960PgE.gif', 'catalogo/good-morning-sentado-com-barra--d960PgE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/good-morning-sentado-com-barra--d960PgE.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Plant both feet while seated on a bench; a barbell resting on your upper back.","Step:2 Keep your spine in a comfortable neutral position and your chest up.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:06.985581+00', '2026-10-31 19:43:06.846+00'), ('D9qe7CM', 'Retroversão pélvica para ponte', 'pelvic tilt into bridge', 'retroversao-pelvica-para-ponte', 'https://static.exercisedb.dev/media/D9qe7CM.gif', 'catalogo/retroversao-pelvica-para-ponte--D9qe7CM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/retroversao-pelvica-para-ponte--D9qe7CM.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','core'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your arms by your sides with your palms facing down.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Tuck the pelvis gently, then push through the feet to raise the hips into a bridge.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:43:06.606462+00', '2026-10-31 19:43:06.471+00'), ('d9Xaxq6', 'Giro russo no cabo na bola suíça', 'cable russian twists (on stability ball)', 'giro-russo-no-cabo-na-bola-suica', 'https://static.exercisedb.dev/media/d9Xaxq6.gif', 'catalogo/giro-russo-no-cabo-na-bola-suica--d9Xaxq6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/giro-russo-no-cabo-na-bola-suica--d9Xaxq6.gif', ARRAY['abdômen'], ARRAY['cabo','bola suíça'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take hold of the cable handle with both hands and extend your arms straight out in front of you.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:07.040058+00', '2026-10-31 19:43:06.899+00'), ('da4cXST', 'Supino fechado com barra W', 'ez-bar close-grip bench press', 'supino-fechado-com-barra-w', 'https://static.exercisedb.dev/media/da4cXST.gif', 'catalogo/supino-fechado-com-barra-w--da4cXST.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-fechado-com-barra-w--da4cXST.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the ez barbell with a close grip, hands about shoulder width, palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:07.005311+00', '2026-10-31 19:43:06.875+00'), ('daBmy1Y', 'Levantamento terra unilateral com halter e apoio no step', 'dumbbell single leg deadlift with stepbox support', 'levantamento-terra-unilateral-com-halter-e-apoio-no-step', 'https://static.exercisedb.dev/media/daBmy1Y.gif', 'catalogo/levantamento-terra-unilateral-com-halter-e-apoio-no-step--daBmy1Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-unilateral-com-halter-e-apoio-no-step--daBmy1Y.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about hip width, holding a dumbbell in your right hand.","Step:2 Set your left foot on a stepbox or elevated surface behind you.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:07.196389+00', '2026-10-31 19:43:07.054+00'), ('dB07vDu', 'Elevação lateral curvado no cabo unilateral', 'Single-Arm Bent-Over Cable Lateral Raise', 'elevacao-lateral-curvado-no-cabo-unilateral', 'https://static.exercisedb.dev/media/dB07vDu.gif', 'catalogo/elevacao-lateral-curvado-no-cabo-unilateral--dB07vDu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-curvado-no-cabo-unilateral--dB07vDu.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitoral'], ARRAY['deltoides','trapézio'], '["Step:1 Stand and set your feet about shoulder width, facing a cable machine.","Step:2 Hold the handle with one hand and step back to create tension on the cable.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:43:07.7644+00', '2026-10-31 19:43:07.636+00'), ('DB0n8AG', 'Agachamento frontal com kettlebell', 'kettlebell front squat', 'agachamento-frontal-com-kettlebell', 'https://static.exercisedb.dev/media/DB0n8AG.gif', 'catalogo/agachamento-frontal-com-kettlebell--DB0n8AG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frontal-com-kettlebell--DB0n8AG.gif', ARRAY['coxas'], ARRAY['kettlebell'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, toes slightly turned out.","Step:2 Take hold of the kettlebell with both hands ahead of your chest, close to your body.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:07.603734+00', '2026-10-31 19:43:07.475+00'), ('Db7eEgw', 'Extensão de tríceps concentrada no cabo (apoiado no joelho)', 'cable concentration extension (on knee)', 'extensao-de-triceps-concentrada-no-cabo-apoiado-no-joelho', 'https://static.exercisedb.dev/media/Db7eEgw.gif', 'catalogo/extensao-de-triceps-concentrada-no-cabo-apoiado-no-joelho--Db7eEgw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-concentrada-no-cabo-apoiado-no-joelho--Db7eEgw.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench or chair with your knees bent and feet planted.","Step:2 Take hold of the cable handle with your right hand and place your elbow on the inside of your right knee.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:07.8949+00', '2026-10-31 19:43:07.763+00'), ('dCJnuVq', 'Arremesso de peito com medicine ball a partir da base de três apoios', 'medicine ball chest push from 3 point stance', 'arremesso-de-peito-com-medicine-ball-a-partir-da-base-de-tres-apoios', 'https://static.exercisedb.dev/media/dCJnuVq.gif', 'catalogo/arremesso-de-peito-com-medicine-ball-a-partir-da-base-de-tres-apoios--dCJnuVq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-de-peito-com-medicine-ball-a-partir-da-base-de-tres-apoios--dCJnuVq.gif', ARRAY['peito'], ARRAY['medicine ball'], ARRAY['peitoral'], ARRAY['deltoides','tríceps'], '["Step:1 Begin in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Step:2 Reach your legs and position your body in a straight line.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Follow through with the whole body while keeping control of the landing or catch.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:07.731952+00', '2026-10-31 19:43:07.604+00'), ('dCPESfR', 'Desenvolvimento Bradford em pé com barra', 'barbell standing bradford press', 'desenvolvimento-bradford-em-pe-com-barra', 'https://static.exercisedb.dev/media/dCPESfR.gif', 'catalogo/desenvolvimento-bradford-em-pe-com-barra--dCPESfR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-bradford-em-pe-com-barra--dCPESfR.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold the barbell ahead of your shoulders with palms facing down.","Step:2 Press the barbell overhead, straighten your arms.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:07.79288+00', '2026-10-31 19:43:07.664+00'), ('DeDThfG', 'Alongamento de glúteos sentado', 'seated glute stretch', 'alongamento-de-gluteos-sentado', 'https://static.exercisedb.dev/media/DeDThfG.gif', 'catalogo/alongamento-de-gluteos-sentado--DeDThfG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-gluteos-sentado--DeDThfG.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Before moving, bend your right knee and cross your right ankle over your left thigh.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:08.589284+00', '2026-10-31 19:43:08.457+00'), ('DEEqoI2', 'Alongamento do tibial posterior com corda', 'posterior tibialis stretch', 'alongamento-do-tibial-posterior-com-corda', 'https://static.exercisedb.dev/media/DEEqoI2.gif', 'catalogo/alongamento-do-tibial-posterior-com-corda--DEEqoI2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-do-tibial-posterior-com-corda--DEEqoI2.gif', ARRAY['panturrilhas'], ARRAY['corda'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Thread the rope around the ball of your foot and hold the ends of the rope with your hands.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:08.354007+00', '2026-10-31 19:43:08.217+00'), ('DFGXwZr', 'World''s Greatest Stretch', 'world greatest stretch', 'world-s-greatest-stretch', 'https://static.exercisedb.dev/media/DFGXwZr.gif', 'catalogo/world-s-greatest-stretch--DFGXwZr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/world-s-greatest-stretch--DFGXwZr.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos','quadríceps','panturrilhas'], '["Step:1 Begin in a lunge position with your right foot forward and your left foot back.","Step:2 Set your hands on the ground on either side of your right foot.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:08.718559+00', '2026-10-31 19:43:08.58+00'), ('dFSNDOA', 'Rotação de tronco sentado com barra', 'barbell seated twist', 'rotacao-de-tronco-sentado-com-barra', 'https://static.exercisedb.dev/media/dFSNDOA.gif', 'catalogo/rotacao-de-tronco-sentado-com-barra--dFSNDOA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-sentado-com-barra--dFSNDOA.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on a flat bench with your feet planted and your knees bent.","Step:2 Take a barbell with both hands ahead of your chest, keeping your elbows soft.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:08.701685+00', '2026-10-31 19:43:08.56+00'), ('dG5Smob', 'Snatch pull (puxada de arranco)', 'snatch pull', 'snatch-pull-puxada-de-arranco', 'https://static.exercisedb.dev/media/dG5Smob.gif', 'catalogo/snatch-pull-puxada-de-arranco--dG5Smob.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/snatch-pull-puxada-de-arranco--dG5Smob.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and the barbell on the ground in front of you.","Step:2 Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with palms facing down.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:43:08.49411+00', '2026-10-31 19:43:08.366+00'), ('dG7tG5y', 'Encolhimento com barra', 'barbell shrug', 'encolhimento-com-barra', 'https://static.exercisedb.dev/media/dG7tG5y.gif', 'catalogo/encolhimento-com-barra--dG7tG5y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-com-barra--dG7tG5y.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell in front of you with palms facing down.","Step:2 Keep your arms long and your spine steady throughout the exercise.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:08.966892+00', '2026-10-31 19:43:08.829+00'), ('DgZQ11d', 'Face press declinado com barra W e pegada fechada', 'EZ-Bar Decline Close-Grip Face Press', 'face-press-declinado-com-barra-w-e-pegada-fechada', 'https://static.exercisedb.dev/media/DgZQ11d.gif', 'catalogo/face-press-declinado-com-barra-w-e-pegada-fechada--DgZQ11d.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/face-press-declinado-com-barra-w-e-pegada-fechada--DgZQ11d.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Settle onto a decline bench with your head lower than your feet.","Step:2 Hold the ez barbell with a close grip, palms facing each other.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:09.132847+00', '2026-10-31 19:43:08.984+00'), ('DhMl549', 'Agachamento completo com barra (vista traseira)', 'barbell full squat (back pov)', 'agachamento-completo-com-barra-vista-traseira', 'https://static.exercisedb.dev/media/DhMl549.gif', 'catalogo/agachamento-completo-com-barra-vista-traseira--DhMl549.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-completo-com-barra-vista-traseira--DhMl549.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Stand and set your feet about shoulder width, toes slightly turned out.","Step:2 Rest the bar across the upper back and take a secure grip.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:09.483553+00', '2026-10-31 19:43:09.353+00'), ('DIVyqrU', 'Postura da esfinge', 'sphinx', 'postura-da-esfinge', 'https://static.exercisedb.dev/media/DIVyqrU.gif', 'catalogo/postura-da-esfinge--DIVyqrU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/postura-da-esfinge--DIVyqrU.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Position yourself face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Step:2 Brace your trunk and lift your chest off the ground, keeping your forearms and toes on the floor.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:09.6136+00', '2026-10-31 19:43:09.482+00'), ('dK9394r', 'Burpee', 'burpee', 'burpee', 'https://static.exercisedb.dev/media/dK9394r.gif', 'catalogo/burpee--dK9394r.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/burpee--dK9394r.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','deltoides','peitorais'], '["Step:1 Begin in a standing position with your feet about shoulder width.","Step:2 Before moving, lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:09.924791+00', '2026-10-31 19:43:09.794+00'), ('dmgMp3n', 'Remada inclinada com barra', 'barbell incline row', 'remada-inclinada-com-barra', 'https://static.exercisedb.dev/media/dmgMp3n.gif', 'catalogo/remada-inclinada-com-barra--dmgMp3n.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-inclinada-com-barra--dmgMp3n.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Position yourself face down on the bench with your chest against the pad and your feet planted.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:09.661322+00', '2026-10-31 19:43:09.528+00'), ('dNFYIU1', 'Desenvolvimento de ombros na máquina', 'Machine Shoulder Press', 'desenvolvimento-de-ombros-na-maquina', 'https://static.exercisedb.dev/media/dNFYIU1.gif', 'catalogo/desenvolvimento-de-ombros-na-maquina--dNFYIU1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-de-ombros-na-maquina--dNFYIU1.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Set the seat height and backrest of the leverage machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the backrest and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:09.789487+00', '2026-10-31 19:43:09.661+00'), ('DOoWcnA', 'Supino na máquina', 'Machine Chest Press', 'supino-na-maquina', 'https://static.exercisedb.dev/media/DOoWcnA.gif', 'catalogo/supino-na-maquina--DOoWcnA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-na-maquina--DOoWcnA.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and position your elbows at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:10.481104+00', '2026-10-31 19:43:10.333+00'), ('DotAgEF', 'Supino declinado com barra e pegada supinada', 'Barbell Reverse-Grip Decline Bench Press', 'supino-declinado-com-barra-e-pegada-supinada', 'https://static.exercisedb.dev/media/DotAgEF.gif', 'catalogo/supino-declinado-com-barra-e-pegada-supinada--DotAgEF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-com-barra-e-pegada-supinada--DotAgEF.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Secure the feet on a decline bench, keeping the head below the hips.","Step:2 Hold the barbell with a reverse grip, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:10.284803+00', '2026-10-31 19:43:10.149+00'), ('dPmaUaU', 'Panturrilha em pé com halteres', 'dumbbell standing calf raise', 'panturrilha-em-pe-com-halteres', 'https://static.exercisedb.dev/media/dPmaUaU.gif', 'catalogo/panturrilha-em-pe-com-halteres--dPmaUaU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-com-halteres--dPmaUaU.gif', ARRAY['panturrilhas'], ARRAY['halteres'], ARRAY['panturrilhas'], ARRAY['tornozelos'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Before moving, raise your heels off the ground as high as possible, using your calves.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:10.298911+00', '2026-10-31 19:43:10.167+00'), ('DptumMx', 'Puxada com pegada fechada no elástico', 'band close-grip pulldown', 'puxada-com-pegada-fechada-no-elastico', 'https://static.exercisedb.dev/media/DptumMx.gif', 'catalogo/puxada-com-pegada-fechada-no-elastico--DptumMx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-com-pegada-fechada-no-elastico--DptumMx.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Connect the band to a high anchor point, such as a pull-up bar or sturdy beam.","Step:2 Face the anchor point and grab the band with palms facing up, hands about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:10.269004+00', '2026-10-31 19:43:10.126+00'), ('DpWMFP5', 'Rosca acima da cabeça sentado no cabo', 'cable seated overhead curl', 'rosca-acima-da-cabeca-sentado-no-cabo', 'https://static.exercisedb.dev/media/DpWMFP5.gif', 'catalogo/rosca-acima-da-cabeca-sentado-no-cabo--DpWMFP5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-acima-da-cabeca-sentado-no-cabo--DpWMFP5.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Take a seat on a bench facing the cable machine with your feet planted.","Step:2 Hold the cable attachment with palms facing up, and your hands about shoulder width.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:10.499646+00', '2026-10-31 19:43:10.372+00'), ('DQ0cqkT', 'Mergulho em três bancos', 'three bench dip', 'mergulho-em-tres-bancos', 'https://static.exercisedb.dev/media/DQ0cqkT.gif', 'catalogo/mergulho-em-tres-bancos--DQ0cqkT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-em-tres-bancos--DQ0cqkT.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Move your butt off the bench, supporting your weight with your hands.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:11.101132+00', '2026-10-31 19:43:10.97+00'), ('dRTfGZT', 'Elevação lateral na máquina', 'Machine Lateral Raise', 'elevacao-lateral-na-maquina', 'https://static.exercisedb.dev/media/dRTfGZT.gif', 'catalogo/elevacao-lateral-na-maquina--dRTfGZT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-na-maquina--dRTfGZT.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['trapézio','parte superior das costas'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and keep your arms straight.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:11.224739+00', '2026-10-31 19:43:10.837+00'), ('Dsfz0Id', 'Rosca concentrada sentado com barra W e pegada fechada', 'EZ-Bar Seated Close-Grip Concentration Curl', 'rosca-concentrada-sentado-com-barra-w-e-pegada-fechada', 'https://static.exercisedb.dev/media/Dsfz0Id.gif', 'catalogo/rosca-concentrada-sentado-com-barra-w-e-pegada-fechada--Dsfz0Id.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-sentado-com-barra-w-e-pegada-fechada--Dsfz0Id.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; hold an EZ barbell with palms facing up.","Step:2 Set your elbow on the inside of your thigh, just above the knee.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:11.084861+00', '2026-10-31 19:43:10.951+00'), ('DsgkuIt', 'Elevação lateral com halteres', 'dumbbell lateral raise', 'elevacao-lateral-com-halteres', 'https://static.exercisedb.dev/media/DsgkuIt.gif', 'catalogo/elevacao-lateral-com-halteres--DsgkuIt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-com-halteres--DsgkuIt.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.","Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:11.122026+00', '2026-10-31 19:43:10.96+00'), ('DT14T9T', 'Pulldown com braços estendidos na corda', 'cable straight arm pulldown (with rope)', 'pulldown-com-bracos-estendidos-na-corda', 'https://static.exercisedb.dev/media/DT14T9T.gif', 'catalogo/pulldown-com-bracos-estendidos-na-corda--DT14T9T.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pulldown-com-bracos-estendidos-na-corda--DT14T9T.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Connect a rope to the cable machine at the highest setting.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:11.122984+00', '2026-10-31 19:43:10.992+00'), ('dTg95eZ', 'Abdominal tocando os joelhos', 'knee touch crunch', 'abdominal-tocando-os-joelhos', 'https://static.exercisedb.dev/media/dTg95eZ.gif', 'catalogo/abdominal-tocando-os-joelhos--dTg95eZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-tocando-os-joelhos--dTg95eZ.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:11.653752+00', '2026-10-31 19:43:11.522+00'), ('DU5Kkj2', 'Rosca inversa unilateral em pé com halter', 'Dumbbell Standing Single-Arm Reverse Curl', 'rosca-inversa-unilateral-em-pe-com-halter', 'https://static.exercisedb.dev/media/DU5Kkj2.gif', 'catalogo/rosca-inversa-unilateral-em-pe-com-halter--DU5Kkj2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-unilateral-em-pe-com-halter--DU5Kkj2.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a dumbbell in one hand with palms facing down.","Step:2 Keep your arm straight and close to your body, with your palm facing down.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:11.585748+00', '2026-10-31 19:43:11.455+00'), ('dU605di', 'Tríceps na polia com corda', 'cable pushdown (with rope attachment)', 'triceps-na-polia-com-corda', 'https://static.exercisedb.dev/media/dU605di.gif', 'catalogo/triceps-na-polia-com-corda--dU605di.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-na-polia-com-corda--dU605di.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Connect a rope attachment to a high pulley on a cable machine.","Step:2 Face the machine with your feet about shoulder width and a slight bend in your knees.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the elbows close to the body instead of letting the shoulders swing.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:12.247582+00', '2026-10-31 19:43:12.099+00'), ('DU7I633', 'Supino inclinado com barra e pegada supinada', 'Barbell Reverse-Grip Incline Bench Press', 'supino-inclinado-com-barra-e-pegada-supinada', 'https://static.exercisedb.dev/media/DU7I633.gif', 'catalogo/supino-inclinado-com-barra-e-pegada-supinada--DU7I633.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-barra-e-pegada-supinada--DU7I633.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Get onto the bench with your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:11.808085+00', '2026-10-31 19:43:11.676+00'), ('DwhEmmE', 'Supino declinado com halteres', 'dumbbell decline bench press', 'supino-declinado-com-halteres', 'https://static.exercisedb.dev/media/DwhEmmE.gif', 'catalogo/supino-declinado-com-halteres--DwhEmmE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-com-halteres--DwhEmmE.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Get onto a decline bench with your feet secured and your head lower than your hips.","Step:2 Take a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:12.276418+00', '2026-10-31 19:43:11.891+00'), ('dXz8zjF', 'Rosca drag no cabo', 'cable drag curl', 'rosca-drag-no-cabo', 'https://static.exercisedb.dev/media/dXz8zjF.gif', 'catalogo/rosca-drag-no-cabo--dXz8zjF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-drag-no-cabo--dXz8zjF.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the cable attachment with palms facing up, and arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:12.236531+00', '2026-10-31 19:43:12.105+00'), ('dZl9Q27', 'Tríceps testa em pé com barra', 'barbell standing overhead triceps extension', 'triceps-testa-em-pe-com-barra', 'https://static.exercisedb.dev/media/dZl9Q27.gif', 'catalogo/triceps-testa-em-pe-com-barra--dZl9Q27.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-em-pe-com-barra--dZl9Q27.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down.","Step:2 Raise the barbell overhead, straighten your arms.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:12.649968+00', '2026-10-31 19:43:12.516+00'), ('dzz6BiV', 'Agachamento sumô no Smith', 'smith sumo squat', 'agachamento-sumo-no-smith', 'https://static.exercisedb.dev/media/dzz6BiV.gif', 'catalogo/agachamento-sumo-no-smith--dzz6BiV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-sumo-no-smith--dzz6BiV.gif', ARRAY['coxas'], ARRAY['Smith (barra guiada)'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Prepare the smith machine with the barbell at hip height.","Step:2 Stand and set your feet wider than about shoulder width, toes pointing outwards.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:12.832663+00', '2026-10-31 19:43:12.699+00'), ('e1e76I2', 'Pular corda', 'jump rope', 'pular-corda', 'https://static.exercisedb.dev/media/e1e76I2.gif', 'catalogo/pular-corda--e1e76I2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pular-corda--e1e76I2.gif', ARRAY['cardio'], ARRAY['corda'], ARRAY['sistema cardiovascular'], ARRAY['panturrilhas','quadríceps','posteriores de coxa','glúteos'], '["Step:1 Take hold of the handles of the jump rope with your hands, palms facing inward.","Step:2 Stand and set your feet about shoulder width and knees soft.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:43:12.714131+00', '2026-10-31 19:43:12.583+00'), ('e25F58f', 'Crucifixo inverso unilateral com halter e apoio', 'Dumbbell Single-Arm Reverse Fly (With Support)', 'crucifixo-inverso-unilateral-com-halter-e-apoio', 'https://static.exercisedb.dev/media/e25F58f.gif', 'catalogo/crucifixo-inverso-unilateral-com-halter-e-apoio--e25F58f.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-unilateral-com-halter-e-apoio--e25F58f.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Plant both feet while seated on a bench; your back straight.","Step:2 Take a dumbbell in one hand with your palm facing inwards.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:43:12.860726+00', '2026-10-31 19:43:12.732+00'), ('e4aFmFY', 'Elevação frontal com peso', 'weighted front raise', 'elevacao-frontal-com-peso', 'https://static.exercisedb.dev/media/e4aFmFY.gif', 'catalogo/elevacao-frontal-com-peso--e4aFmFY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-peso--e4aFmFY.gif', ARRAY['ombros'], ARRAY['peso adicional'], ARRAY['deltoides'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.","Step:2 With your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:13.161077+00', '2026-10-31 19:43:13.024+00'), ('e4ojVhP', 'Rosca direta com halteres pegada invertida', 'Dumbbell Reverse-Grip Biceps Curl', 'rosca-direta-com-halteres-pegada-invertida', 'https://static.exercisedb.dev/media/e4ojVhP.gif', 'catalogo/rosca-direta-com-halteres-pegada-invertida--e4ojVhP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-pegada-invertida--e4ojVhP.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing down and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:13.243829+00', '2026-10-31 19:43:13.115+00'), ('E4PwJqI', 'Flexão de pernas invertida autoassistida', 'self assisted inverse leg curl', 'flexao-de-pernas-invertida-autoassistida', 'https://static.exercisedb.dev/media/E4PwJqI.gif', 'catalogo/flexao-de-pernas-invertida-autoassistida--E4PwJqI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-pernas-invertida-autoassistida--E4PwJqI.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos','panturrilhas'], '["Step:1 Position yourself face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Step:2 Set your hands on the side handles of the machine for support.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:13.678885+00', '2026-10-31 19:43:13.544+00'), ('E4R8Hz1', 'Elevação de quadril com elástico', 'band hip lift', 'elevacao-de-quadril-com-elastico', 'https://static.exercisedb.dev/media/E4R8Hz1.gif', 'catalogo/elevacao-de-quadril-com-elastico--E4R8Hz1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-com-elastico--E4R8Hz1.gif', ARRAY['coxas'], ARRAY['faixa elástica'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set a resistance band just above your knees.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:43:13.483473+00', '2026-10-31 19:43:13.355+00'), ('ealLwvX', 'Corrida elevando os joelhos contra a parede', 'high knee against wall', 'corrida-elevando-os-joelhos-contra-a-parede', 'https://static.exercisedb.dev/media/ealLwvX.gif', 'catalogo/corrida-elevando-os-joelhos-contra-a-parede--ealLwvX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-elevando-os-joelhos-contra-a-parede--ealLwvX.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Face a wall with your feet about hip width.","Step:2 Set your hands on the wall for support.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:13.315926+00', '2026-10-31 19:43:13.18+00'), ('EAs3xL9', 'Crucifixo inverso com halteres', 'dumbbell reverse fly', 'crucifixo-inverso-com-halteres', 'https://static.exercisedb.dev/media/EAs3xL9.gif', 'catalogo/crucifixo-inverso-com-halteres--EAs3xL9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres--EAs3xL9.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:43:13.797229+00', '2026-10-31 19:43:13.668+00'), ('EcaV7aL', 'Supino fechado com barra', 'barbell lying close-grip press', 'supino-fechado-com-barra', 'https://static.exercisedb.dev/media/EcaV7aL.gif', 'catalogo/supino-fechado-com-barra--EcaV7aL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-fechado-com-barra--EcaV7aL.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with a close grip, hands about shoulder width, palms facing toward your feet.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:13.787583+00', '2026-10-31 19:43:13.652+00'), ('ecl28tP', 'Avanço frontal contralateral com halteres', 'dumbbell contralateral forward lunge', 'avanco-frontal-contralateral-com-halteres', 'https://static.exercisedb.dev/media/ecl28tP.gif', 'catalogo/avanco-frontal-contralateral-com-halteres--ecl28tP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-frontal-contralateral-com-halteres--ecl28tP.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Step forward with your right foot, with your spine steady and core engaged.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:14.467777+00', '2026-10-31 19:43:14.334+00'), ('ecpY0rH', 'Puxada alta na máquina com pegada supinada', 'Reverse-Grip Machine Lat Pulldown', 'puxada-alta-na-maquina-com-pegada-supinada', 'https://static.exercisedb.dev/media/ecpY0rH.gif', 'catalogo/puxada-alta-na-maquina-com-pegada-supinada--ecpY0rH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-alta-na-maquina-com-pegada-supinada--ecpY0rH.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['grande dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing up, just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:14.612206+00', '2026-10-31 19:43:14.478+00'), ('Eg98Ft9', 'Encolhimento no cabo', 'cable shrug', 'encolhimento-no-cabo', 'https://static.exercisedb.dev/media/Eg98Ft9.gif', 'catalogo/encolhimento-no-cabo--Eg98Ft9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-no-cabo--Eg98Ft9.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the cable handles with palms facing down and let your arms hang down in front of you.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:14.221524+00', '2026-10-31 19:43:14.096+00'), ('eGDudUV', 'Levantamento terra no cabo', 'cable deadlift', 'levantamento-terra-no-cabo', 'https://static.exercisedb.dev/media/eGDudUV.gif', 'catalogo/levantamento-terra-no-cabo--eGDudUV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-no-cabo--eGDudUV.gif', ARRAY['coxas'], ARRAY['cabo'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','eretores da espinha'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Before moving, bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:14.381143+00', '2026-10-31 19:43:14.253+00'), ('Eh2v5Iu', 'Salto tesoura', 'Scissor Jumps', 'salto-tesoura', 'https://static.exercisedb.dev/media/Eh2v5Iu.gif', 'catalogo/salto-tesoura--Eh2v5Iu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/salto-tesoura--Eh2v5Iu.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Jump off the ground and simultaneously cross your right leg ahead of your left leg.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:43:14.455168+00', '2026-10-31 19:43:14.326+00'), ('eHBlPsa', 'Rosca Scott unilateral no cabo', 'Cable Single-Arm Preacher Curl', 'rosca-scott-unilateral-no-cabo', 'https://static.exercisedb.dev/media/eHBlPsa.gif', 'catalogo/rosca-scott-unilateral-no-cabo--eHBlPsa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-unilateral-no-cabo--eHBlPsa.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Set the cable machine so that the preacher curl pad is at chest height.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:15.036611+00', '2026-10-31 19:43:14.898+00'), ('EIeI8Vf', 'Supino reto com barra', 'barbell bench press', 'supino-reto-com-barra', 'https://static.exercisedb.dev/media/EIeI8Vf.gif', 'catalogo/supino-reto-com-barra--EIeI8Vf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-reto-com-barra--EIeI8Vf.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitoral'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with palms facing down just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:14.988356+00', '2026-10-31 19:43:14.86+00'), ('EIsE3u8', 'Remada curvada unilateral no cabo', 'Cable Single-Arm Bent Over Row', 'remada-curvada-unilateral-no-cabo', 'https://static.exercisedb.dev/media/EIsE3u8.gif', 'catalogo/remada-curvada-unilateral-no-cabo--EIsE3u8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-unilateral-no-cabo--EIsE3u8.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:15.066294+00', '2026-10-31 19:43:14.934+00'), ('EKXOMEh', 'Remada para deltoide posterior com halteres', 'dumbbell rear delt row (shoulder)', 'remada-para-deltoide-posterior-com-halteres', 'https://static.exercisedb.dev/media/EKXOMEh.gif', 'catalogo/remada-para-deltoide-posterior-com-halteres--EKXOMEh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-para-deltoide-posterior-com-halteres--EKXOMEh.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take a dumbbell in each hand with your palms facing your body.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:15.077028+00', '2026-10-31 19:43:14.925+00'), ('elhhVgj', 'Agachamento com barra e base estreita', 'barbell narrow stance squat', 'agachamento-com-barra-e-base-estreita', 'https://static.exercisedb.dev/media/elhhVgj.gif', 'catalogo/agachamento-com-barra-e-base-estreita--elhhVgj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-barra-e-base-estreita--elhhVgj.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and toes pointing slightly outward.","Step:2 Rest the bar across the upper back and take a secure grip.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:15.303646+00', '2026-10-31 19:43:15.176+00'), ('EmlJR2y', 'Rosca unilateral com halter em pé sobre banco inclinado', 'Dumbbell Standing Single-Arm Curl Over Incline Bench', 'rosca-unilateral-com-halter-em-pe-sobre-banco-inclinado', 'https://static.exercisedb.dev/media/EmlJR2y.gif', 'catalogo/rosca-unilateral-com-halter-em-pe-sobre-banco-inclinado--EmlJR2y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-unilateral-com-halter-em-pe-sobre-banco-inclinado--EmlJR2y.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand.","Step:2 Set your other hand on an incline bench for support.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:15.564846+00', '2026-10-31 19:43:15.427+00'), ('EMpUwRI', 'Tríceps testa com barra', 'barbell lying extension', 'triceps-testa-com-barra', 'https://static.exercisedb.dev/media/EMpUwRI.gif', 'catalogo/triceps-testa-com-barra--EMpUwRI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra--EMpUwRI.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take hold of the barbell with palms facing down, hands about shoulder width, and extend your arms straight up over your chest.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:15.870456+00', '2026-10-31 19:43:15.735+00'), ('en550rk', 'Tríceps coice sentado com halter', 'dumbbell seated kickback', 'triceps-coice-sentado-com-halter', 'https://static.exercisedb.dev/media/en550rk.gif', 'catalogo/triceps-coice-sentado-com-halter--en550rk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-sentado-com-halter--en550rk.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand.","Step:2 Bend your knees slightly and lean forward from your hips, with your spine steady.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:15.725964+00', '2026-10-31 19:43:15.598+00'), ('enxnJcM', 'Abdominal parcial (um quarto)', 'quarter sit-up', 'abdominal-parcial-um-quarto', 'https://static.exercisedb.dev/media/enxnJcM.gif', 'catalogo/abdominal-parcial-um-quarto--enxnJcM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-parcial-um-quarto--enxnJcM.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:15.76882+00', '2026-10-31 19:43:15.64+00'), ('eOCOwIR', 'Tate press com halteres', 'dumbbell lying elbow press', 'tate-press-com-halteres', 'https://static.exercisedb.dev/media/eOCOwIR.gif', 'catalogo/tate-press-com-halteres--eOCOwIR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/tate-press-com-halteres--eOCOwIR.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Tríceps'], ARRAY['Peitorais','Deltoides'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Step:2 Lower the dumbbells toward your shoulders by bending your elbows, With the upper arms still.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:15.943229+00', '2026-10-31 19:43:15.815+00'), ('eOG0r6v', 'Rosca inversa na polia', 'cable reverse curl', 'rosca-inversa-na-polia', 'https://static.exercisedb.dev/media/eOG0r6v.gif', 'catalogo/rosca-inversa-na-polia--eOG0r6v.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-na-polia--eOG0r6v.gif', ARRAY['Braços'], ARRAY['Polia'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Connect a straight bar to a low pulley cable machine.","Step:2 Face the machine with your feet about shoulder width and your knees soft.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:16.116666+00', '2026-10-31 19:43:15.988+00'), ('eOrFCnx', 'Desenvolvimento Arnold com halteres', 'dumbbell arnold press', 'desenvolvimento-arnold-com-halteres', 'https://static.exercisedb.dev/media/eOrFCnx.gif', 'catalogo/desenvolvimento-arnold-com-halteres--eOrFCnx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-arnold-com-halteres--eOrFCnx.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Tríceps','Peitorais'], '["Step:1 Take a seat on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Step:2 Press the dumbbells upward until your arms are straight and your palms are facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:16.292887+00', '2026-10-31 19:43:16.16+00'), ('epOSYUZ', 'Flexão hindu modificada', 'Modified Hindu Push-Up', 'flexao-hindu-modificada', 'https://static.exercisedb.dev/media/epOSYUZ.gif', 'catalogo/flexao-hindu-modificada--epOSYUZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-hindu-modificada--epOSYUZ.gif', ARRAY['Peito'], ARRAY['Peso corporal'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides','Core'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet about hip width.","Step:2 Lower your body toward the ground, bending your elbows and keeping your core engaged.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:16.499743+00', '2026-10-31 19:43:16.362+00'), ('ErqK3UL', 'Passo para trás com alcance acima da cabeça', 'posterior step to overhead reach', 'passo-para-tras-com-alcance-acima-da-cabeca', 'https://static.exercisedb.dev/media/ErqK3UL.gif', 'catalogo/passo-para-tras-com-alcance-acima-da-cabeca--ErqK3UL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/passo-para-tras-com-alcance-acima-da-cabeca--ErqK3UL.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Glúteos','Posteriores de coxa','Quadríceps','Deltoides'], '["Step:1 Stand and set your feet about hip width and your arms by your sides.","Step:2 Step back with your right foot, landing on the ball of your foot.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step back into a lunge while reaching both arms overhead, then drive forward to stand.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:16.746227+00', '2026-10-31 19:43:16.609+00'), ('ESOd5Pl', 'Crucifixo inclinado com halteres', 'dumbbell incline fly', 'crucifixo-inclinado-com-halteres', 'https://static.exercisedb.dev/media/ESOd5Pl.gif', 'catalogo/crucifixo-inclinado-com-halteres--ESOd5Pl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-com-halteres--ESOd5Pl.gif', ARRAY['Peito'], ARRAY['Halteres'], ARRAY['Peitorais'], ARRAY['Deltoides'], '["Step:1 Angle an incline bench to a 45-degree angle.","Step:2 Take a seat on the bench with a dumbbell in each hand, palms facing each other.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:43:16.729168+00', '2026-10-31 19:43:16.6+00'), ('ETZfAbZ', 'Supino declinado no Smith', 'smith decline bench press', 'supino-declinado-no-smith', 'https://static.exercisedb.dev/media/ETZfAbZ.gif', 'catalogo/supino-declinado-no-smith--ETZfAbZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-no-smith--ETZfAbZ.gif', ARRAY['Peito'], ARRAY['Smith'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides'], '["Step:1 Set the decline bench to the desired angle.","Step:2 Get onto the bench with your feet secured under the foot pads.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:16.759+00', '2026-10-31 19:43:16.627+00'), ('euI1BwR', 'Agachamento com barra em velocidade (speed squat)', 'barbell speed squat', 'agachamento-com-barra-em-velocidade-speed-squat', 'https://static.exercisedb.dev/media/euI1BwR.gif', 'catalogo/agachamento-com-barra-em-velocidade-speed-squat--euI1BwR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-barra-em-velocidade-speed-squat--euI1BwR.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de coxa','Panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, toes slightly turned out.","Step:2 Rest the bar across the upper back and take a secure grip.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:17.178588+00', '2026-10-31 19:43:17.044+00'), ('euq4pwp', 'Abdominal em pé com rotação com elástico', 'band standing twisting crunch', 'abdominal-em-pe-com-rotacao-com-elastico', 'https://static.exercisedb.dev/media/euq4pwp.gif', 'catalogo/abdominal-em-pe-com-rotacao-com-elastico--euq4pwp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-em-pe-com-rotacao-com-elastico--euq4pwp.gif', ARRAY['Abdômen'], ARRAY['Elástico'], ARRAY['Abdominais'], ARRAY['Oblíquos'], '["Step:1 Stand and set your feet about shoulder width and place the band around your upper back, crossing it ahead of your chest.","Step:2 Take hold of the ends of the band with your hands, keeping your elbows bent and close to your sides.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:17.069439+00', '2026-10-31 19:43:16.931+00'), ('eVxAzgz', 'Elevação de pernas e quadril no banco inclinado (pernas estendidas)', 'incline leg hip raise (leg straight)', 'elevacao-de-pernas-e-quadril-no-banco-inclinado-pernas-estendidas', 'https://static.exercisedb.dev/media/eVxAzgz.gif', 'catalogo/elevacao-de-pernas-e-quadril-no-banco-inclinado-pernas-estendidas--eVxAzgz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-e-quadril-no-banco-inclinado-pernas-estendidas--eVxAzgz.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Settle onto an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Step:2 Set your hands on the sides of the bench for support.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:43:17.493671+00', '2026-10-31 19:43:17.362+00'), ('eXFXCY0', 'Abdominal sentado na máquina', 'Machine Seated Crunch', 'abdominal-sentado-na-maquina', 'https://static.exercisedb.dev/media/eXFXCY0.gif', 'catalogo/abdominal-sentado-na-maquina--eXFXCY0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-sentado-na-maquina--eXFXCY0.gif', ARRAY['Abdômen'], ARRAY['Máquina articulada'], ARRAY['Abdominais'], ARRAY['Oblíquos','Flexores do quadril'], '["Step:1 Take a seat on the leverage machine with your back against the pad and your feet secured under the footpads.","Step:2 Set your hands on the handles or the sides of the seat for support.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:17.710194+00', '2026-10-31 19:43:17.583+00'), ('eXMFHww', 'Elevação lateral no landmine', 'landmine lateral raise', 'elevacao-lateral-no-landmine', 'https://static.exercisedb.dev/media/eXMFHww.gif', 'catalogo/elevacao-lateral-no-landmine--eXMFHww.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-no-landmine--eXMFHww.gif', ARRAY['Ombros'], ARRAY['Barra'], ARRAY['Deltoides'], ARRAY['Trapézio','Parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take hold of the barbell with palms facing down, resting it on the front of your shoulders.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:17.38124+00', '2026-10-31 19:43:17.248+00'), ('EyLrNC2', 'Elevação alternada de braços na bola suíça', 'exercise ball alternating arm ups', 'elevacao-alternada-de-bracos-na-bola-suica', 'https://static.exercisedb.dev/media/EyLrNC2.gif', 'catalogo/elevacao-alternada-de-bracos-na-bola-suica--EyLrNC2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-alternada-de-bracos-na-bola-suica--EyLrNC2.gif', ARRAY['Costas'], ARRAY['Bola suíça'], ARRAY['Grande dorsal'], ARRAY['Deltoides','Core'], '["Step:1 Take a seat on the stability ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:43:17.847887+00', '2026-10-31 19:43:17.714+00'), ('eYmsEPR', 'Rosca de punho inversa na polia', 'cable reverse wrist curl', 'rosca-de-punho-inversa-na-polia', 'https://static.exercisedb.dev/media/eYmsEPR.gif', 'catalogo/rosca-de-punho-inversa-na-polia--eYmsEPR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-na-polia--eYmsEPR.gif', ARRAY['Antebraços'], ARRAY['Polia'], ARRAY['Antebraços'], ARRAY['Antebraços','Punhos'], '["Step:1 Connect a cable to a low pulley and Take a seat on the bench facing the cable machine.","Step:2 Hold the cable handle with palms facing down.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:43:18.092871+00', '2026-10-31 19:43:17.959+00'), ('eYnzaCm', 'Puxada alta com barra na polia', 'cable bar lateral pulldown', 'puxada-alta-com-barra-na-polia', 'https://static.exercisedb.dev/media/eYnzaCm.gif', 'catalogo/puxada-alta-com-barra-na-polia--eYnzaCm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-alta-com-barra-na-polia--eYnzaCm.gif', ARRAY['Costas'], ARRAY['Polia'], ARRAY['Grande dorsal'], ARRAY['Bíceps','Romboides','Deltoides posteriores'], '["Step:1 Set the cable pulley to a high position and attach a straight bar.","Step:2 Sit facing the cable machine with your feet planted and your knees soft.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:17.977277+00', '2026-10-31 19:43:17.843+00'), ('EZeDVzO', 'Abdominal declinado com peso', 'weighted decline sit-up', 'abdominal-declinado-com-peso', 'https://static.exercisedb.dev/media/EZeDVzO.gif', 'catalogo/abdominal-declinado-com-peso--EZeDVzO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-declinado-com-peso--EZeDVzO.gif', ARRAY['Abdômen'], ARRAY['Peso adicional'], ARRAY['Abdominais'], ARRAY['Flexores do quadril','Eretores da espinha'], '["Step:1 Settle onto a decline bench with your feet secured under the foot pads.","Step:2 Set your hands behind your head or across your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:18.535142+00', '2026-10-31 19:43:18.405+00'), ('Ezpnw9d', 'Rosca de punho inversa com elástico', 'band reverse wrist curl', 'rosca-de-punho-inversa-com-elastico', 'https://static.exercisedb.dev/media/Ezpnw9d.gif', 'catalogo/rosca-de-punho-inversa-com-elastico--Ezpnw9d.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-com-elastico--Ezpnw9d.gif', ARRAY['Antebraços'], ARRAY['Elástico'], ARRAY['Antebraços'], ARRAY['Antebraços'], '["Step:1 Take a seat on a bench or chair with your feet planted.","Step:2 Take hold of the band with palms facing down, and wrap it around your fingers.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:43:18.399812+00', '2026-10-31 19:43:18.266+00'), ('ezTvXcr', 'Paralelas nas argolas', 'ring dips', 'paralelas-nas-argolas', 'https://static.exercisedb.dev/media/ezTvXcr.gif', 'catalogo/paralelas-nas-argolas--ezTvXcr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralelas-nas-argolas--ezTvXcr.gif', ARRAY['Braços'], ARRAY['Peso corporal'], ARRAY['Tríceps'], ARRAY['Peitorais','Deltoides'], '["Step:1 Begin by hanging from the rings with your arms straight and your body straight.","Step:2 Before moving, lower your body by bending your elbows until your shoulders are below your elbows.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:18.392741+00', '2026-10-31 19:43:18.258+00'), ('eZyBC3j', 'Remada curvada com barra', 'barbell bent over row', 'remada-curvada-com-barra', 'https://static.exercisedb.dev/media/eZyBC3j.gif', 'catalogo/remada-curvada-com-barra--eZyBC3j.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-com-barra--eZyBC3j.gif', ARRAY['Costas'], ARRAY['Barra'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Bend forward at the hips while with your spine steady and chest up.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:18.561127+00', '2026-10-31 19:43:18.425+00'), ('f1jf47L', 'Desenvolvimento sentado com halteres (pegada neutra)', 'dumbbell seated shoulder press (parallel grip)', 'desenvolvimento-sentado-com-halteres-pegada-neutra', 'https://static.exercisedb.dev/media/f1jf47L.gif', 'catalogo/desenvolvimento-sentado-com-halteres-pegada-neutra--f1jf47L.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-com-halteres-pegada-neutra--f1jf47L.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Tríceps','Parte superior das costas'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing inward.","Step:2 Before moving, raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:18.783171+00', '2026-10-31 19:43:18.649+00'), ('F1KxjBa', 'Rosca martelo Scott com halteres', 'dumbbell preacher hammer curl', 'rosca-martelo-scott-com-halteres', 'https://static.exercisedb.dev/media/F1KxjBa.gif', 'catalogo/rosca-martelo-scott-com-halteres--F1KxjBa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-scott-com-halteres--F1KxjBa.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.","Step:2 Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:18.979947+00', '2026-10-31 19:43:18.844+00'), ('f38OEuO', 'Alongamento de dorsal ajoelhado', 'kneeling lat stretch', 'alongamento-de-dorsal-ajoelhado', 'https://static.exercisedb.dev/media/f38OEuO.gif', 'catalogo/alongamento-de-dorsal-ajoelhado--f38OEuO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-dorsal-ajoelhado--f38OEuO.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['deltoides','tríceps'], '["Step:1 Get down on the ground with your knees about hip width and your toes pointing back.","Step:2 Reach your arms overhead and interlace your fingers.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:18.982509+00', '2026-10-31 19:43:18.85+00'), ('F3xgbjF', 'Rosca direta inclinada com halteres', 'dumbbell incline biceps curl', 'rosca-direta-inclinada-com-halteres', 'https://static.exercisedb.dev/media/F3xgbjF.gif', 'catalogo/rosca-direta-inclinada-com-halteres--F3xgbjF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-inclinada-com-halteres--F3xgbjF.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, palms facing forward, and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:19.52561+00', '2026-10-31 19:43:19.392+00'), ('f4xtKBj', 'Barra fixa assistida em pé', 'assisted standing pull-up', 'barra-fixa-assistida-em-pe', 'https://static.exercisedb.dev/media/f4xtKBj.gif', 'catalogo/barra-fixa-assistida-em-pe--f4xtKBj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-assistida-em-pe--f4xtKBj.gif', ARRAY['costas'], ARRAY['máquina de alavanca'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Set the machine to your desired weight and height settings.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:19.487626+00', '2026-10-31 19:43:19.356+00'), ('f7fnAIB', 'Remada agachada na polia com corda', 'cable squat row (with rope attachment)', 'remada-agachada-na-polia-com-corda', 'https://static.exercisedb.dev/media/f7fnAIB.gif', 'catalogo/remada-agachada-na-polia-com-corda--f7fnAIB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-agachada-na-polia-com-corda--f7fnAIB.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posterior'], '["Step:1 Connect a rope to a cable machine at waist height.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:19.625372+00', '2026-10-31 19:43:19.464+00'), ('F7vjXqT', 'Flexão de braço inclinada no caixote', 'incline push-up (on box)', 'flexao-de-braco-inclinada-no-caixote', 'https://static.exercisedb.dev/media/F7vjXqT.gif', 'catalogo/flexao-de-braco-inclinada-no-caixote--F7vjXqT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-inclinada-no-caixote--F7vjXqT.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set your hands on the edge of a box or elevated surface, just beyond shoulder width.","Step:2 Reach your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:19.96246+00', '2026-10-31 19:43:19.825+00'), ('f7Y9eDZ', 'Thruster com barra', 'barbell thruster', 'thruster-com-barra', 'https://static.exercisedb.dev/media/f7Y9eDZ.gif', 'catalogo/thruster-com-barra--f7Y9eDZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/thruster-com-barra--f7Y9eDZ.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['quadríceps','glúteos','posteriores de coxa','core'], '["Step:1 Begin by standing with your feet about shoulder width, holding a barbell at shoulder height with palms facing down.","Step:2 Before moving, lower into a squat position by bending your knees and pushing your hips back.","Step:3 Rack the weight securely and brace before dropping into the squat.","Step:4 Stand from the squat and use that leg drive to press the weight overhead.","Step:5 Let the leg drive start the press while keeping the ribs from flaring.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:43:19.936689+00', '2026-10-31 19:43:19.8+00'), ('f91FwXG', 'Encolhimento na máquina sem pegada', 'Machine Gripless Shrug', 'encolhimento-na-maquina-sem-pegada', 'https://static.exercisedb.dev/media/f91FwXG.gif', 'catalogo/encolhimento-na-maquina-sem-pegada--f91FwXG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-na-maquina-sem-pegada--f91FwXG.gif', ARRAY['costas'], ARRAY['máquina de alavanca'], ARRAY['trapézio'], ARRAY['deltoides','antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with your palms facing inwards and your arms straight.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:20.364668+00', '2026-10-31 19:43:20.224+00'), ('f9lVSSI', 'Polichinelo com afastamento frontal e lateral', 'Astride Jumps', 'polichinelo-com-afastamento-frontal-e-lateral', 'https://static.exercisedb.dev/media/f9lVSSI.gif', 'catalogo/polichinelo-com-afastamento-frontal-e-lateral--f9lVSSI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/polichinelo-com-afastamento-frontal-e-lateral--f9lVSSI.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, bend your knees and lower your body into a squat position.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:43:20.137238+00', '2026-10-31 19:43:19.991+00'), ('faHKVkK', 'Rosca direta com barra em pé pegada aberta', 'Barbell Standing Wide-Grip Biceps Curl', 'rosca-direta-com-barra-em-pe-pegada-aberta', 'https://static.exercisedb.dev/media/faHKVkK.gif', 'catalogo/rosca-direta-com-barra-em-pe-pegada-aberta--faHKVkK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra-em-pe-pegada-aberta--faHKVkK.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing up, hands wider than about shoulder width.","Step:2 Keep your spine in a comfortable neutral position and your elbows close to your torso.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:20.474124+00', '2026-10-31 19:43:20.344+00'), ('FAoIFMw', 'Mergulho unilateral', 'Single-Arm Dip', 'mergulho-unilateral', 'https://static.exercisedb.dev/media/FAoIFMw.gif', 'catalogo/mergulho-unilateral--FAoIFMw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-unilateral--FAoIFMw.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Face the away from a bench or chair, from a stable stance with feet about shoulder width.","Step:2 Set one hand on the bench or chair behind you, fingers pointing toward your body.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Press through the hands to rise, then reset the shoulders before another rep; switch sides when the set calls for it."]', '2026-10-31 19:43:20.811292+00', '2026-10-31 19:43:20.679+00'), ('Ff18ItA', 'Paralelas na barra reta com peso', 'weighted straight bar dip', 'paralelas-na-barra-reta-com-peso', 'https://static.exercisedb.dev/media/Ff18ItA.gif', 'catalogo/paralelas-na-barra-reta-com-peso--Ff18ItA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralelas-na-barra-reta-com-peso--Ff18ItA.gif', ARRAY['peito'], ARRAY['com peso adicional'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set yourself between parallel bars with your arms straight and your body straight.","Step:2 Before moving, lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:20.748591+00', '2026-10-31 19:43:20.617+00'), ('ffQsyBj', 'Rosca direta unilateral em pé com halter', 'Dumbbell Single-Arm Standing Curl', 'rosca-direta-unilateral-em-pe-com-halter', 'https://static.exercisedb.dev/media/ffQsyBj.gif', 'catalogo/rosca-direta-unilateral-em-pe-com-halter--ffQsyBj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-unilateral-em-pe-com-halter--ffQsyBj.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in one hand, palm facing forward and arm straight.","Step:2 With your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:20.923653+00', '2026-10-31 19:43:20.792+00'), ('FFRP97T', 'Abdominal sapinho', 'frog crunch', 'abdominal-sapinho', 'https://static.exercisedb.dev/media/FFRP97T.gif', 'catalogo/abdominal-sapinho--FFRP97T.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-sapinho--FFRP97T.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Bring the soles of your feet together, let the knees open, then curl your ribs toward your pelvis.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:21.22671+00', '2026-10-31 19:43:21.085+00'), ('fgc9Xdl', 'Panturrilha em pé unilateral na polia', 'Cable Standing Single-Leg Calf Raise', 'panturrilha-em-pe-unilateral-na-polia', 'https://static.exercisedb.dev/media/fgc9Xdl.gif', 'catalogo/panturrilha-em-pe-unilateral-na-polia--fgc9Xdl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-unilateral-na-polia--fgc9Xdl.gif', ARRAY['panturrilhas'], ARRAY['polia'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Use the cable machine for support.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:43:21.035002+00', '2026-10-31 19:43:20.9+00'), ('Fhdtwf3', 'Remada curvada unilateral na máquina', 'Machine Single-Arm Bent Over Row', 'remada-curvada-unilateral-na-maquina', 'https://static.exercisedb.dev/media/Fhdtwf3.gif', 'catalogo/remada-curvada-unilateral-na-maquina--Fhdtwf3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-unilateral-na-maquina--Fhdtwf3.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a barbell with palms facing down.","Step:2 Bend forward at the hips, with your spine steady and your head up.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:21.294577+00', '2026-10-31 19:43:21.166+00'), ('fhZQPlV', 'Rotação de tronco na polia (de cima para baixo)', 'cable twist (up-down)', 'rotacao-de-tronco-na-polia-de-cima-para-baixo', 'https://static.exercisedb.dev/media/fhZQPlV.gif', 'catalogo/rotacao-de-tronco-na-polia-de-cima-para-baixo--fhZQPlV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-na-polia-de-cima-para-baixo--fhZQPlV.gif', ARRAY['abdômen'], ARRAY['polia'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width, facing the cable machine.","Step:2 Take hold of the cable handle with both hands ahead of your chest, keeping your arms soft.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:21.373196+00', '2026-10-31 19:43:21.241+00'), ('fI18Rbc', 'Remada alta com barra', 'barbell upright row', 'remada-alta-com-barra', 'https://static.exercisedb.dev/media/fI18Rbc.gif', 'catalogo/remada-alta-com-barra--fI18Rbc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-com-barra--fI18Rbc.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down, hands just beyond shoulder width.","Step:2 Keep the barbell hanging ahead of your thighs, arms straight.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:21.68282+00', '2026-10-31 19:43:21.545+00'), ('FkBIE6a', 'Flexão de pernas deitado com halter', 'Lying Dumbbell Leg Curl', 'flexao-de-pernas-deitado-com-halter', 'https://static.exercisedb.dev/media/FkBIE6a.gif', 'catalogo/flexao-de-pernas-deitado-com-halter--FkBIE6a.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-pernas-deitado-com-halter--FkBIE6a.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['posteriores de coxa'], ARRAY['glúteos'], '["Step:1 Lie face down on a flat bench with your knees just past its edge.","Step:2 Hold a light dumbbell securely between your feet and keep your hips on the bench.","Step:3 Brace your trunk and keep the thighs resting on the bench.","Step:4 Bend your knees to draw your heels toward your glutes without lifting the hips.","Step:5 Lower the weight slowly until the legs are nearly straight, then reset your grip before repeating."]', '2026-10-31 19:43:21.807255+00', '2026-10-31 19:43:21.662+00'), ('fKZgDEO', 'Panturrilha unilateral com halter', 'single leg calf raise (on a dumbbell)', 'panturrilha-unilateral-com-halter', 'https://static.exercisedb.dev/media/fKZgDEO.gif', 'catalogo/panturrilha-unilateral-com-halter--fKZgDEO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-unilateral-com-halter--fKZgDEO.gif', ARRAY['panturrilhas'], ARRAY['halteres'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Stand and set your feet about hip width and hold a dumbbell in one hand.","Step:2 Before moving, lift one foot off the ground and balance on the other foot.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:21.9884+00', '2026-10-31 19:43:21.861+00'), ('fNGumX0', 'Passo para frente e para trás', 'back and forth step', 'passo-para-frente-e-para-tras', 'https://static.exercisedb.dev/media/fNGumX0.gif', 'catalogo/passo-para-frente-e-para-tras--fNGumX0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/passo-para-frente-e-para-tras--fNGumX0.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Move forward with your right foot, bending your knee and lowering your body into a lunge position.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:22.077567+00', '2026-10-31 19:43:21.947+00'), ('fprd84i', 'Desenvolvimento antigravidade com barra W', 'EZ-Bar Anti Gravity Press', 'desenvolvimento-antigravidade-com-barra-w', 'https://static.exercisedb.dev/media/fprd84i.gif', 'catalogo/desenvolvimento-antigravidade-com-barra-w--fprd84i.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-antigravidade-com-barra-w--fprd84i.gif', ARRAY['ombros'], ARRAY['barra W'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Begin by standing with your feet about shoulder width and holding the ez barbell with palms facing down.","Step:2 Raise the barbell to shoulder height, keeping your elbows soft and your palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:22.241722+00', '2026-10-31 19:43:22.11+00'), ('FQXdXzY', 'Tríceps testa sentado com halteres', 'dumbbells seated triceps extension', 'triceps-testa-sentado-com-halteres', 'https://static.exercisedb.dev/media/FQXdXzY.gif', 'catalogo/triceps-testa-sentado-com-halteres--FQXdXzY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-sentado-com-halteres--FQXdXzY.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in both hands with palms facing down, and raise it above your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:22.236992+00', '2026-10-31 19:43:22.103+00'), ('FS63wTN', 'Push press com halteres', 'dumbbell push press', 'push-press-com-halteres', 'https://static.exercisedb.dev/media/FS63wTN.gif', 'catalogo/push-press-com-halteres--FS63wTN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/push-press-com-halteres--FS63wTN.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level.","Step:2 Before moving, bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:22.439265+00', '2026-10-31 19:43:22.303+00'), ('FSD6PGL', 'Pullover com halter na bola suíça', 'dumbbell pullover on exercise ball', 'pullover-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/FSD6PGL.gif', 'catalogo/pullover-com-halter-na-bola-suica--FSD6PGL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-halter-na-bola-suica--FSD6PGL.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['tríceps','latíssimo do dorso'], '["Step:1 Take a seat on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Step:2 With control lower the dumbbell behind your head while keeping your arms straight.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:22.83279+00', '2026-10-31 19:43:22.697+00'), ('fSrPP6B', 'Tríceps press com peso corporal', 'triceps press', 'triceps-press-com-peso-corporal', 'https://static.exercisedb.dev/media/fSrPP6B.gif', 'catalogo/triceps-press-com-peso-corporal--fSrPP6B.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-press-com-peso-corporal--fSrPP6B.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Reach your arms straight out in front of you, parallel to the ground.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:23.30564+00', '2026-10-31 19:43:23.175+00'), ('fTlkJop', 'Elevação lateral deitado de lado com halter (um braço)', 'Dumbbell Side-Lying One Hand Raise', 'elevacao-lateral-deitado-de-lado-com-halter-um-braco', 'https://static.exercisedb.dev/media/fTlkJop.gif', 'catalogo/elevacao-lateral-deitado-de-lado-com-halter-um-braco--fTlkJop.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-deitado-de-lado-com-halter-um-braco--fTlkJop.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Settle onto your side with your legs extended and your head supported by your arm.","Step:2 Take a dumbbell in your top hand with your palm facing down.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:23.125031+00', '2026-10-31 19:43:22.74+00'), ('fUBheHs', 'Remada sentada na polia baixa', 'cable seated row', 'remada-sentada-na-polia-baixa', 'https://static.exercisedb.dev/media/fUBheHs.gif', 'catalogo/remada-sentada-na-polia-baixa--fUBheHs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-na-polia-baixa--fUBheHs.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the cable row machine with your feet flat on the footrests and your knees soft.","Step:2 Hold the handles with palms facing down, with your spine steady and your shoulders relaxed.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:22.970683+00', '2026-10-31 19:43:22.836+00'), ('FVM1AUZ', 'Remada cavalinho na máquina com pegada supinada', 'Machine T-Bar Reverse-Grip Row', 'remada-cavalinho-na-maquina-com-pegada-supinada', 'https://static.exercisedb.dev/media/FVM1AUZ.gif', 'catalogo/remada-cavalinho-na-maquina-com-pegada-supinada--FVM1AUZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-cavalinho-na-maquina-com-pegada-supinada--FVM1AUZ.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down, just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:23.003794+00', '2026-10-31 19:43:22.873+00'), ('FVmZVhk', 'Crucifixo na polia baixa', 'cable low fly', 'crucifixo-na-polia-baixa', 'https://static.exercisedb.dev/media/FVmZVhk.gif', 'catalogo/crucifixo-na-polia-baixa--FVmZVhk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-na-polia-baixa--FVmZVhk.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Connect the handles to the low pulleys of a cable machine and select an appropriate weight.","Step:2 Take your place in the middle of the machine with your feet about shoulder width and a slight bend in your knees.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:43:23.401712+00', '2026-10-31 19:43:23.265+00'), ('FWdVhcW', 'Rotação externa de ombro em pé na polia', 'cable standing shoulder external rotation', 'rotacao-externa-de-ombro-em-pe-na-polia', 'https://static.exercisedb.dev/media/FWdVhcW.gif', 'catalogo/rotacao-externa-de-ombro-em-pe-na-polia--FWdVhcW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-externa-de-ombro-em-pe-na-polia--FWdVhcW.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['manguito rotador','trapézio'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Take hold of the cable handle with your arm extended in front of you, parallel to the ground.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:23.566001+00', '2026-10-31 19:43:23.428+00'), ('fXfqg1E', 'Barra fixa unilateral com peso', 'Weighted One Hand Pull-Up', 'barra-fixa-unilateral-com-peso', 'https://static.exercisedb.dev/media/fXfqg1E.gif', 'catalogo/barra-fixa-unilateral-com-peso--fXfqg1E.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-unilateral-com-peso--fXfqg1E.gif', ARRAY['costas'], ARRAY['com peso adicional'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with palms facing down, just beyond shoulder width.","Step:2 Suspend yourself from the bar with your arm straight and your body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:23.62039+00', '2026-10-31 19:43:23.488+00'), ('FxhcxUW', 'Panturrilha sentado unilateral com halter - pegada martelo', 'Dumbbell Seated Single-Leg Calf Raise - Hammer Grip', 'panturrilha-sentado-unilateral-com-halter-pegada-martelo', 'https://static.exercisedb.dev/media/FxhcxUW.gif', 'catalogo/panturrilha-sentado-unilateral-com-halter-pegada-martelo--FxhcxUW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-unilateral-com-halter-pegada-martelo--FxhcxUW.gif', ARRAY['panturrilhas'], ARRAY['halter'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Take a seat on a bench or chair with your feet planted and a dumbbell resting on your thighs.","Step:2 Set one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:43:24.064066+00', '2026-10-31 19:43:23.933+00'), ('FY3UdNT', 'Panturrilha em pé com bola suíça na parede (bola de tênis entre os tornozelos)', 'exercise ball on the wall calf raise (tennis ball between ankles)', 'panturrilha-em-pe-com-bola-suica-na-parede-bola-de-tenis-entre-os-tornozelos', 'https://static.exercisedb.dev/media/FY3UdNT.gif', 'catalogo/panturrilha-em-pe-com-bola-suica-na-parede-bola-de-tenis-entre-os-tornozelos--FY3UdNT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-com-bola-suica-na-parede-bola-de-tenis-entre-os-tornozelos--FY3UdNT.gif', ARRAY['panturrilhas'], ARRAY['halter','bola suíça','bola de tênis'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Face the wall from a stable stance with feet about shoulder width.","Step:2 Set an exercise ball between the wall and your lower back.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:23.894579+00', '2026-10-31 19:43:23.76+00'), ('fY68AyX', 'Rosca martelo com halteres na bola suíça', 'dumbbell hammer curl on exercise ball', 'rosca-martelo-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/fY68AyX.gif', 'catalogo/rosca-martelo-com-halteres-na-bola-suica--fY68AyX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-com-halteres-na-bola-suica--fY68AyX.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing your body and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:24.069389+00', '2026-10-31 19:43:23.935+00'), ('fy7Tgy4', 'Rosca martelo alternada no banco Scott com halteres', 'dumbbell alternate hammer preacher curl', 'rosca-martelo-alternada-no-banco-scott-com-halteres', 'https://static.exercisedb.dev/media/fy7Tgy4.gif', 'catalogo/rosca-martelo-alternada-no-banco-scott-com-halteres--fy7Tgy4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-alternada-no-banco-scott-com-halteres--fy7Tgy4.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with a dumbbell in each hand, palms facing your torso and arms straight.","Step:2 Let the elbows do the moving while the upper arms stay put and Breathe out and curl the weights while contracting your biceps.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:24.156102+00', '2026-10-31 19:43:24.028+00'), ('fZFZ704', 'Rotação russa com peso', 'weighted russian twist', 'rotacao-russa-com-peso', 'https://static.exercisedb.dev/media/fZFZ704.gif', 'catalogo/rotacao-russa-com-peso--fZFZ704.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-russa-com-peso--fZFZ704.gif', ARRAY['abdômen'], ARRAY['com peso adicional'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on the ground with your knees bent and your feet planted.","Step:2 Take a weight or medicine ball with both hands ahead of your chest.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:24.031128+00', '2026-10-31 19:43:23.902+00'), ('G08RZcQ', 'Rosca direta na polia', 'cable curl', 'rosca-direta-na-polia', 'https://static.exercisedb.dev/media/G08RZcQ.gif', 'catalogo/rosca-direta-na-polia--G08RZcQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-na-polia--G08RZcQ.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the cable attachment with palms facing up.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:24.501324+00', '2026-10-31 19:43:24.372+00'), ('g2oKspu', 'Abdominal curto (curl-up)', 'curl-up', 'abdominal-curto-curl-up', 'https://static.exercisedb.dev/media/g2oKspu.gif', 'catalogo/abdominal-curto-curl-up--g2oKspu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-curto-curl-up--g2oKspu.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:24.53385+00', '2026-10-31 19:43:24.403+00'), ('g376LuL', 'Panturrilha deitado no sled', 'sled lying calf press', 'panturrilha-deitado-no-sled', 'https://static.exercisedb.dev/media/g376LuL.gif', 'catalogo/panturrilha-deitado-no-sled--g376LuL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-deitado-no-sled--g376LuL.gif', ARRAY['panturrilhas'], ARRAY['máquina sled'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set the sled machine to a comfortable weight.","Step:2 Take a seat on the sled machine with your back against the pad and your feet on the platform.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:24.892226+00', '2026-10-31 19:43:24.758+00'), ('G61cXLk', 'Remada ajoelhado para deltoide posterior na polia com corda', 'Cable Kneeling Rear Delt Row (With Rope)', 'remada-ajoelhado-para-deltoide-posterior-na-polia-com-corda', 'https://static.exercisedb.dev/media/G61cXLk.gif', 'catalogo/remada-ajoelhado-para-deltoide-posterior-na-polia-com-corda--G61cXLk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-ajoelhado-para-deltoide-posterior-na-polia-com-corda--G61cXLk.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['trapézio','romboides','bíceps'], '["Step:1 Connect a rope handle to a low cable pulley and kneel down facing the machine.","Step:2 Hold the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:25.106191+00', '2026-10-31 19:43:24.975+00'), ('G70mEAJ', 'Barra fixa supinada com pegada fechada paralela', 'chin-ups (narrow parallel grip)', 'barra-fixa-supinada-com-pegada-fechada-paralela', 'https://static.exercisedb.dev/media/G70mEAJ.gif', 'catalogo/barra-fixa-supinada-com-pegada-fechada-paralela--G70mEAJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-com-pegada-fechada-paralela--G70mEAJ.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Suspend yourself from a pull-up bar with a narrow parallel grip, palms facing toward you.","Step:2 Engage your back muscles and pull your body up toward the bar, keeping your elbows close to your body.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:24.864219+00', '2026-10-31 19:43:24.73+00'), ('G7PXMlT', 'Pallof press vertical com elástico', 'band vertical pallof press', 'pallof-press-vertical-com-elastico', 'https://static.exercisedb.dev/media/G7PXMlT.gif', 'catalogo/pallof-press-vertical-com-elastico--G7PXMlT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pallof-press-vertical-com-elastico--G7PXMlT.gif', ARRAY['abdômen'], ARRAY['elástico'], ARRAY['abdominais'], ARRAY['oblíquos','glúteos'], '["Step:1 Stand and set your feet about shoulder width and wrap the band around a sturdy object at chest height.","Step:2 Take hold of the band with both hands and step away from the anchor point, creating tension in the band.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:25.110705+00', '2026-10-31 19:43:24.977+00'), ('G7xoEzr', 'Elevação de pernas alternada sentado com barra', 'Barbell Seated Alternate Leg Raise', 'elevacao-de-pernas-alternada-sentado-com-barra', 'https://static.exercisedb.dev/media/G7xoEzr.gif', 'catalogo/elevacao-de-pernas-alternada-sentado-com-barra--G7xoEzr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-alternada-sentado-com-barra--G7xoEzr.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Take a seat on a bench with your back straight and hold a barbell across your thighs.","Step:2 With your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the legs slowly without swinging or losing your trunk position; switch sides when the set calls for it."]', '2026-10-31 19:43:25.13172+00', '2026-10-31 19:43:24.996+00'), ('G8dXpNG', 'Remada curvada com barra W e pegada supinada', 'EZ-Bar Reverse-Grip Bent Over Row', 'remada-curvada-com-barra-w-e-pegada-supinada', 'https://static.exercisedb.dev/media/G8dXpNG.gif', 'catalogo/remada-curvada-com-barra-w-e-pegada-supinada--G8dXpNG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-com-barra-w-e-pegada-supinada--G8dXpNG.gif', ARRAY['costas'], ARRAY['barra W'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take hold of the ez barbell with palms facing up, and hands about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:25.738617+00', '2026-10-31 19:43:25.6+00'), ('g9AsZ8P', 'Remada unilateral com kettlebell', 'Kettlebell Single-Arm Row', 'remada-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/g9AsZ8P.gif', 'catalogo/remada-unilateral-com-kettlebell--g9AsZ8P.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-unilateral-com-kettlebell--g9AsZ8P.gif', ARRAY['costas'], ARRAY['kettlebell'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:25.431307+00', '2026-10-31 19:43:25.296+00'), ('GaSzzuh', 'Back lever', 'back lever', 'back-lever', 'https://static.exercisedb.dev/media/GaSzzuh.gif', 'catalogo/back-lever--GaSzzuh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/back-lever--GaSzzuh.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços','core'], '["Step:1 Begin by hanging from a pull-up bar with palms facing down, hands just beyond shoulder width.","Step:2 Brace your trunk and pull your shoulder blades down and back.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:25.725602+00', '2026-10-31 19:43:25.592+00'), ('gAwDzB3', 'Tríceps pulley com barra V', 'cable triceps pushdown (v-bar)', 'triceps-pulley-com-barra-v', 'https://static.exercisedb.dev/media/gAwDzB3.gif', 'catalogo/triceps-pulley-com-barra-v--gAwDzB3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-pulley-com-barra-v--gAwDzB3.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Connect a v-bar attachment to the cable machine at the highest setting.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the elbows close to the body instead of letting the shoulders swing.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:43:25.672143+00', '2026-10-31 19:43:25.537+00'), ('Gchi5Tr', 'Extensão de tríceps alternada na polia', 'cable alternate triceps extension', 'extensao-de-triceps-alternada-na-polia', 'https://static.exercisedb.dev/media/Gchi5Tr.gif', 'catalogo/extensao-de-triceps-alternada-na-polia--Gchi5Tr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-alternada-na-polia--Gchi5Tr.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:43:25.60838+00', '2026-10-31 19:43:25.475+00'), ('GdMa1ET', 'Flexão escapular inclinada', 'incline scapula push up', 'flexao-escapular-inclinada', 'https://static.exercisedb.dev/media/GdMa1ET.gif', 'catalogo/flexao-escapular-inclinada--GdMa1ET.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-escapular-inclinada--GdMa1ET.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['serrátil anterior'], ARRAY['tríceps','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Set your hands on the bench just beyond shoulder width.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:26.235188+00', '2026-10-31 19:43:26.103+00'), ('gEyURal', 'Levantamento terra unilateral com barra', 'barbell single leg deadlift', 'levantamento-terra-unilateral-com-barra', 'https://static.exercisedb.dev/media/gEyURal.gif', 'catalogo/levantamento-terra-unilateral-com-barra--gEyURal.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-unilateral-com-barra--gEyURal.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about hip width, holding a barbell ahead of your thighs with palms facing down.","Step:2 Transfer your weight onto your left foot and lift your right foot slightly off the ground.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:26.231339+00', '2026-10-31 19:43:26.105+00'), ('gf3ZjB9', 'Agachamento hack na máquina com pés juntos', 'sled closer hack squat', 'agachamento-hack-na-maquina-com-pes-juntos', 'https://static.exercisedb.dev/media/gf3ZjB9.gif', 'catalogo/agachamento-hack-na-maquina-com-pes-juntos--gf3ZjB9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-hack-na-maquina-com-pes-juntos--gf3ZjB9.gif', ARRAY['coxas'], ARRAY['máquina hack'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the sled machine to a comfortable weight and position yourself with your back against the pad.","Step:2 Set your feet about shoulder width on the platform, toes slightly pointed outwards.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:26.321745+00', '2026-10-31 19:43:26.192+00'), ('gfk9kD4', 'Agachamento overhead com barra', 'barbell overhead squat', 'agachamento-overhead-com-barra', 'https://static.exercisedb.dev/media/gfk9kD4.gif', 'catalogo/agachamento-overhead-com-barra--gfk9kD4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-overhead-com-barra--gfk9kD4.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas','core'], '["Step:1 Stand and set your feet about shoulder width and toes slightly turned out.","Step:2 Take hold of the barbell with a wide grip, positioning it overhead with your arms straight.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:26.377788+00', '2026-10-31 19:43:26.245+00'), ('gFyFj9z', 'Avanço com step-up com halteres', 'dumbbell step-up lunge', 'avanco-com-step-up-com-halteres', 'https://static.exercisedb.dev/media/gFyFj9z.gif', 'catalogo/avanco-com-step-up-com-halteres--gFyFj9z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-step-up-com-halteres--gFyFj9z.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Take your place in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Step:2 Set your right foot on the step, ensuring your entire foot is on the surface.","Step:3 Put the lead foot fully on the platform before shifting your weight onto it.","Step:4 Step onto the platform and drive through the lead foot to stand tall on it.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:26.472312+00', '2026-10-31 19:43:26.34+00'), ('gGNQmVt', 'Agachamento búlgaro com barra', 'barbell single leg split squat', 'agachamento-bulgaro-com-barra', 'https://static.exercisedb.dev/media/gGNQmVt.gif', 'catalogo/agachamento-bulgaro-com-barra--gGNQmVt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-bulgaro-com-barra--gGNQmVt.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a barbell across your upper back.","Step:2 Step far forward with one leg, keeping your torso upright.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:26.797751+00', '2026-10-31 19:43:26.665+00'), ('gH5fRsC', 'Elevação frontal alternada sentado com halteres', 'dumbbell seated alternate front raise', 'elevacao-frontal-alternada-sentado-com-halteres', 'https://static.exercisedb.dev/media/gH5fRsC.gif', 'catalogo/elevacao-frontal-alternada-sentado-com-halteres--gH5fRsC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-alternada-sentado-com-halteres--gH5fRsC.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:43:27.107992+00', '2026-10-31 19:43:26.966+00'), ('Gi2BXfK', 'Tríceps coice alternado em pé com halteres', 'Dumbbell Standing Alternating Triceps Kickback', 'triceps-coice-alternado-em-pe-com-halteres', 'https://static.exercisedb.dev/media/Gi2BXfK.gif', 'catalogo/triceps-coice-alternado-em-pe-com-halteres--Gi2BXfK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-alternado-em-pe-com-halteres--Gi2BXfK.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:43:26.922971+00', '2026-10-31 19:43:26.788+00'), ('GibBPPg', 'Elevação pélvica com marcha', 'glute bridge march', 'elevacao-pelvica-com-marcha', 'https://static.exercisedb.dev/media/GibBPPg.gif', 'catalogo/elevacao-pelvica-com-marcha--GibBPPg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-pelvica-com-marcha--GibBPPg.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Tighten your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:43:27.224429+00', '2026-10-31 19:43:27.092+00'), ('Gk1r408', 'Barra fixa supinada pegada fechada com peso na barra de paralelas', 'Weighted Close-Grip Chin-Up On Dip Cage', 'barra-fixa-supinada-pegada-fechada-com-peso-na-barra-de-paralelas', 'https://static.exercisedb.dev/media/Gk1r408.gif', 'catalogo/barra-fixa-supinada-pegada-fechada-com-peso-na-barra-de-paralelas--Gk1r408.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-pegada-fechada-com-peso-na-barra-de-paralelas--Gk1r408.gif', ARRAY['costas'], ARRAY['com peso'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take your place in front of the dip cage and grab the parallel bars with palms facing up, hands about shoulder width.","Step:2 Suspend yourself from the bars with your arms straight, feet off the ground, and body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:27.066875+00', '2026-10-31 19:43:26.932+00'), ('GKEH6jj', 'Supino inclinado unilateral na polia', 'Cable Single-Arm Incline Press', 'supino-inclinado-unilateral-na-polia', 'https://static.exercisedb.dev/media/GKEH6jj.gif', 'catalogo/supino-inclinado-unilateral-na-polia--GKEH6jj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-unilateral-na-polia--GKEH6jj.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the cable machine to a low pulley position.","Step:2 Take a seat on an incline bench turned away from the cable machine.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:27.369666+00', '2026-10-31 19:43:27.238+00'), ('gKozT8X', 'Levantamento terra unilateral com halter', 'dumbbell single leg deadlift', 'levantamento-terra-unilateral-com-halter', 'https://static.exercisedb.dev/media/gKozT8X.gif', 'catalogo/levantamento-terra-unilateral-com-halter--gKozT8X.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-unilateral-com-halter--gKozT8X.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about hip width, holding a dumbbell in your right hand.","Step:2 Transfer your weight onto your left leg and lift your right foot slightly off the ground.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:27.476455+00', '2026-10-31 19:43:27.343+00'), ('Gm2Uv1z', 'Tríceps testa com halteres na bola suíça', 'exercise ball supine triceps extension', 'triceps-testa-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/Gm2Uv1z.gif', 'catalogo/triceps-testa-com-halteres-na-bola-suica--Gm2Uv1z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-halteres-na-bola-suica--Gm2Uv1z.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on an exercise ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a dumbbell with both hands and extend your arms straight up toward the ceiling.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:27.666968+00', '2026-10-31 19:43:27.537+00'), ('Gn5FwYT', 'Abdominal na bola suíça com amplitude total e mãos atrás da cabeça', 'stability ball crunch (full range hands behind head)', 'abdominal-na-bola-suica-com-amplitude-total-e-maos-atras-da-cabeca', 'https://static.exercisedb.dev/media/Gn5FwYT.gif', 'catalogo/abdominal-na-bola-suica-com-amplitude-total-e-maos-atras-da-cabeca--Gn5FwYT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-na-bola-suica-com-amplitude-total-e-maos-atras-da-cabeca--Gn5FwYT.gif', ARRAY['abdômen'], ARRAY['bola suíça'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:28.103958+00', '2026-10-31 19:43:27.971+00'), ('Gnfo4FM', 'Agachamento livre com barra alta', 'barbell high bar squat', 'agachamento-livre-com-barra-alta', 'https://static.exercisedb.dev/media/Gnfo4FM.gif', 'catalogo/agachamento-livre-com-barra-alta--Gnfo4FM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-livre-com-barra-alta--Gnfo4FM.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Stand and set your feet about shoulder width, toes slightly turned out.","Step:2 Set the barbell on your upper back, resting it on your traps.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:27.931799+00', '2026-10-31 19:43:27.8+00'), ('GNhAeJ0', 'Rosca martelo com halteres usando arm blaster', 'dumbbell hammer curls (with arm blaster)', 'rosca-martelo-com-halteres-usando-arm-blaster', 'https://static.exercisedb.dev/media/GNhAeJ0.gif', 'catalogo/rosca-martelo-com-halteres-usando-arm-blaster--GNhAeJ0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-com-halteres-usando-arm-blaster--GNhAeJ0.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.","Step:2 Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:28.150395+00', '2026-10-31 19:43:28.016+00'), ('goJ6ezq', 'Elevação lateral na polia', 'cable lateral raise', 'elevacao-lateral-na-polia', 'https://static.exercisedb.dev/media/goJ6ezq.gif', 'catalogo/elevacao-lateral-na-polia--goJ6ezq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-na-polia--goJ6ezq.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Stand and set your feet about shoulder width and Hold the cable handles with palms facing down.","Step:2 Maintain straight arms and your core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:28.121446+00', '2026-10-31 19:43:27.983+00'), ('GOJKFfO', 'Flexão de posterior na bola suíça unilateral com chute diagonal', 'Exercise Ball Single-Legged Diagonal Kick Hamstring Curl', 'flexao-de-posterior-na-bola-suica-unilateral-com-chute-diagonal', 'https://static.exercisedb.dev/media/GOJKFfO.gif', 'catalogo/flexao-de-posterior-na-bola-suica-unilateral-com-chute-diagonal--GOJKFfO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-posterior-na-bola-suica-unilateral-com-chute-diagonal--GOJKFfO.gif', ARRAY['coxas'], ARRAY['bola suíça'], ARRAY['glúteos'], ARRAY['posteriores de coxa','panturrilhas'], '["Step:1 Begin by lying on your back with your legs extended and your heels resting on top of the stability ball.","Step:2 Set your arms by your sides for stability.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:28.238384+00', '2026-10-31 19:43:28.107+00'), ('Gpn4ADc', 'Desenvolvimento atrás da nuca no Smith', 'smith behind neck press', 'desenvolvimento-atras-da-nuca-no-smith', 'https://static.exercisedb.dev/media/Gpn4ADc.gif', 'catalogo/desenvolvimento-atras-da-nuca-no-smith--Gpn4ADc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-atras-da-nuca-no-smith--Gpn4ADc.gif', ARRAY['ombros'], ARRAY['Smith'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Set the seat height of the smith machine so that the bar is at shoulder level.","Step:2 Stand and set your feet about shoulder width and your knees soft.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:29.114159+00', '2026-10-31 19:43:28.984+00'), ('GrO65fd', 'Supino declinado com barra', 'barbell decline bench press', 'supino-declinado-com-barra', 'https://static.exercisedb.dev/media/GrO65fd.gif', 'catalogo/supino-declinado-com-barra--GrO65fd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-com-barra--GrO65fd.gif', ARRAY['peitoral'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Secure the feet on a decline bench, keeping the head below the hips.","Step:2 Hold the barbell with palms facing down just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:28.754942+00', '2026-10-31 19:43:28.626+00'), ('gscGLOU', 'Rosca bíceps deitado de lado com peso corporal', 'Bodyweight Side-Lying Biceps Curl', 'rosca-biceps-deitado-de-lado-com-peso-corporal', 'https://static.exercisedb.dev/media/gscGLOU.gif', 'catalogo/rosca-biceps-deitado-de-lado-com-peso-corporal--gscGLOU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-deitado-de-lado-com-peso-corporal--gscGLOU.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Settle onto your side with your legs extended and your head supported by your arm.","Step:2 Hold your upper arm against your side and bend your elbow to curl your forearm toward your shoulder.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:28.684168+00', '2026-10-31 19:43:28.548+00'), ('GSDioYu', 'Alongamento de parte superior das costas', 'upper back stretch', 'alongamento-de-parte-superior-das-costas', 'https://static.exercisedb.dev/media/GSDioYu.gif', 'catalogo/alongamento-de-parte-superior-das-costas--GSDioYu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-parte-superior-das-costas--GSDioYu.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['deltoides'], '["Step:1 Stand tall with your feet about shoulder width.","Step:2 Reach your arms straight in front of you, parallel to the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:28.720357+00', '2026-10-31 19:43:28.591+00'), ('gSw59a4', 'Crucifixo inverso deitado unilateral com halter', 'Dumbbell Lying Single-Arm Deltoid Rear', 'crucifixo-inverso-deitado-unilateral-com-halter', 'https://static.exercisedb.dev/media/gSw59a4.gif', 'catalogo/crucifixo-inverso-deitado-unilateral-com-halter--gSw59a4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-deitado-unilateral-com-halter--gSw59a4.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Position yourself face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Step:2 Extend your arm straight down toward the floor, keeping it close to your body.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:43:29.081642+00', '2026-10-31 19:43:28.947+00'), ('gtO1ErP', 'Mergulho em três bancos com peso', 'weighted three bench dips', 'mergulho-em-tres-bancos-com-peso', 'https://static.exercisedb.dev/media/gtO1ErP.gif', 'catalogo/mergulho-em-tres-bancos-com-peso--gtO1ErP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-em-tres-bancos-com-peso--gtO1ErP.gif', ARRAY['braços'], ARRAY['peso adicional'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Step your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:29.263106+00', '2026-10-31 19:43:29.134+00'), ('Gu2rNJd', 'Agachamento na parede no Smith (cadeirinha)', 'smith chair squat', 'agachamento-na-parede-no-smith-cadeirinha', 'https://static.exercisedb.dev/media/Gu2rNJd.gif', 'catalogo/agachamento-na-parede-no-smith-cadeirinha--Gu2rNJd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-na-parede-no-smith-cadeirinha--Gu2rNJd.gif', ARRAY['coxas'], ARRAY['Smith machine'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Set the height of the smith machine bar to a comfortable position.","Step:2 Stand and set your feet about shoulder width, toes slightly turned out.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:29.854677+00', '2026-10-31 19:43:29.719+00'), ('gUjqdei', 'Agachamento cruzado (reverência)', 'curtsey squat', 'agachamento-cruzado-reverencia', 'https://static.exercisedb.dev/media/gUjqdei.gif', 'catalogo/agachamento-cruzado-reverencia--gUjqdei.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-cruzado-reverencia--gUjqdei.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:29.97228+00', '2026-10-31 19:43:29.837+00'), ('GUT8I22', 'Levantamento terra na máquina', 'Machine Deadlift', 'levantamento-terra-na-maquina', 'https://static.exercisedb.dev/media/GUT8I22.gif', 'catalogo/levantamento-terra-na-maquina--GUT8I22.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-na-maquina--GUT8I22.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Set the seat height and foot platform to your desired position.","Step:2 Take a seat on the machine with your back against the pad and your feet flat on the foot platform.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:29.666351+00', '2026-10-31 19:43:29.532+00'), ('guT8YnS', 'Barra fixa com foco no bíceps', 'biceps pull-up', 'barra-fixa-com-foco-no-biceps', 'https://static.exercisedb.dev/media/guT8YnS.gif', 'catalogo/barra-fixa-com-foco-no-biceps--guT8YnS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-foco-no-biceps--guT8YnS.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Suspend yourself from a pull-up bar with your palms turned away from you and your hands about shoulder width.","Step:2 Brace your trunk and pull yourself up by bending your elbows, bringing your chest toward the bar.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:29.663921+00', '2026-10-31 19:43:29.53+00'), ('gVlnLIJ', 'Rosca inversa unilateral na polia', 'Cable Reverse Single-Arm Curl', 'rosca-inversa-unilateral-na-polia', 'https://static.exercisedb.dev/media/gVlnLIJ.gif', 'catalogo/rosca-inversa-unilateral-na-polia--gVlnLIJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-unilateral-na-polia--gVlnLIJ.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the cable handle with palms facing up, palm facing down.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:29.996597+00', '2026-10-31 19:43:29.866+00'), ('gvsWLQw', 'Rosca concentrada com halter', 'dumbbell concentration curl', 'rosca-concentrada-com-halter', 'https://static.exercisedb.dev/media/gvsWLQw.gif', 'catalogo/rosca-concentrada-com-halter--gvsWLQw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-com-halter--gvsWLQw.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Step:2 Fully extend your arm and hold the dumbbell with palms facing up.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:30.488149+00', '2026-10-31 19:43:30.353+00'), ('Gw2HFvW', 'Crucifixo inclinado unilateral com halter', 'Dumbbell Incline Single-Arm Fly', 'crucifixo-inclinado-unilateral-com-halter', 'https://static.exercisedb.dev/media/Gw2HFvW.gif', 'catalogo/crucifixo-inclinado-unilateral-com-halter--Gw2HFvW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-unilateral-com-halter--Gw2HFvW.gif', ARRAY['peitoral'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the incline bench to a 30-45 degree angle.","Step:2 Take a seat on the bench with a dumbbell in one hand, resting it on your thigh.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:43:30.214216+00', '2026-10-31 19:43:30.08+00'), ('gw9PqGk', 'Flexão planche completa', 'full planche push-up', 'flexao-planche-completa', 'https://static.exercisedb.dev/media/gw9PqGk.gif', 'catalogo/flexao-planche-completa--gw9PqGk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-planche-completa--gw9PqGk.gif', ARRAY['peitoral'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['deltoides','tríceps','core'], '["Step:1 Place your palms near the hips and lean forward until the shoulders pass the wrists.","Step:2 Lift both feet clear of the floor with straight legs and a firm trunk.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:30.313954+00', '2026-10-31 19:43:30.18+00'), ('GWoKnIm', 'Agachamento cossaco com peso', 'Weighted Cossack Squats', 'agachamento-cossaco-com-peso', 'https://static.exercisedb.dev/media/GWoKnIm.gif', 'catalogo/agachamento-cossaco-com-peso--GWoKnIm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-cossaco-com-peso--GWoKnIm.gif', ARRAY['coxas'], ARRAY['peso adicional'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet wider than about shoulder width and toes pointing slightly outward.","Step:2 Take a weight ahead of your chest with both hands.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Shift into one hip and bend that knee while the other leg stays long; keep both feet in contact with the floor.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:31.02192+00', '2026-10-31 19:43:30.836+00'), ('GwYwElT', 'Mesa flexora inversa autoassistida', 'self assisted inverse leg curl', 'mesa-flexora-inversa-autoassistida', 'https://static.exercisedb.dev/media/GwYwElT.gif', 'catalogo/mesa-flexora-inversa-autoassistida--GwYwElT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mesa-flexora-inversa-autoassistida--GwYwElT.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos','panturrilhas'], '["Step:1 Settle onto your back on a mat or bench with your legs extended.","Step:2 Set your hands by your sides or under your glutes for support.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:30.794789+00', '2026-10-31 19:43:30.667+00'), ('gx7s7uF', 'Supino inclinado com pegada fechada com barra', 'Barbell Incline Close-Grip Bench Press', 'supino-inclinado-com-pegada-fechada-com-barra', 'https://static.exercisedb.dev/media/gx7s7uF.gif', 'catalogo/supino-inclinado-com-pegada-fechada-com-barra--gx7s7uF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-pegada-fechada-com-barra--gx7s7uF.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Get onto the bench with your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:31.154559+00', '2026-10-31 19:43:31.01+00'), ('GxDwDX0', 'Alongamento de panturrilha deitado assistido', 'assisted lying calves stretch', 'alongamento-de-panturrilha-deitado-assistido', 'https://static.exercisedb.dev/media/GxDwDX0.gif', 'catalogo/alongamento-de-panturrilha-deitado-assistido--GxDwDX0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-panturrilha-deitado-assistido--GxDwDX0.gif', ARRAY['panturrilhas'], ARRAY['assistido'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Settle onto your back with your legs extended.","Step:2 Before moving, bend one knee and place your foot flat on the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:30.909582+00', '2026-10-31 19:43:30.775+00'), ('Gxg9lDc', 'Roda abdominal com barra a partir do banco', 'Barbell Rollout From Bench', 'roda-abdominal-com-barra-a-partir-do-banco', 'https://static.exercisedb.dev/media/Gxg9lDc.gif', 'catalogo/roda-abdominal-com-barra-a-partir-do-banco--Gxg9lDc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/roda-abdominal-com-barra-a-partir-do-banco--Gxg9lDc.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['deltoides','tríceps'], '["Step:1 Begin by kneeling on the floor with a barbell placed on a bench in front of you.","Step:2 Hold the barbell with palms facing down, just beyond shoulder width.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:43:30.980016+00', '2026-10-31 19:43:30.838+00'), ('GXoaSgn', 'Supino guilhotina com barra', 'barbell guillotine bench press', 'supino-guilhotina-com-barra', 'https://static.exercisedb.dev/media/GXoaSgn.gif', 'catalogo/supino-guilhotina-com-barra--GXoaSgn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-guilhotina-com-barra--GXoaSgn.gif', ARRAY['peitoral'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:31.4484+00', '2026-10-31 19:43:31.308+00'), ('h1ezqSu', 'Prancha com joelhos apoiados tocando o ombro', 'Kneeling Plank Tap Shoulder', 'prancha-com-joelhos-apoiados-tocando-o-ombro', 'https://static.exercisedb.dev/media/h1ezqSu.gif', 'catalogo/prancha-com-joelhos-apoiados-tocando-o-ombro--h1ezqSu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-com-joelhos-apoiados-tocando-o-ombro--h1ezqSu.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','tríceps'], '["Step:1 Begin in a kneeling position with your hands on the ground, about shoulder width.","Step:2 Reach your legs behind you, resting on your toes, and lift your body into a plank position.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:31.560419+00', '2026-10-31 19:43:31.425+00'), ('H1PESYI', 'Corrida na bicicleta ergométrica', 'stationary bike run', 'corrida-na-bicicleta-ergometrica', 'https://static.exercisedb.dev/media/H1PESYI.gif', 'catalogo/corrida-na-bicicleta-ergometrica--H1PESYI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-na-bicicleta-ergometrica--H1PESYI.gif', ARRAY['cardio'], ARRAY['bicicleta ergométrica'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat height and position to ensure proper alignment.","Step:2 Set your feet on the pedals and secure them with the straps if available.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:31.567886+00', '2026-10-31 19:43:31.435+00'), ('H1XAdpk', 'Rosca direta com halteres em V sentado na bola Bosu', 'dumbbell biceps curl v sit on bosu ball', 'rosca-direta-com-halteres-em-v-sentado-na-bola-bosu', 'https://static.exercisedb.dev/media/H1XAdpk.gif', 'catalogo/rosca-direta-com-halteres-em-v-sentado-na-bola-bosu--H1XAdpk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-em-v-sentado-na-bola-bosu--H1XAdpk.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Take a seat on a bosu ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a dumbbell in each hand with your palms facing forward and your arms straight down by your sides.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:31.621145+00', '2026-10-31 19:43:31.491+00'), ('H6ETwO9', 'Abdominal V-up com elástico', 'band v-up', 'abdominal-v-up-com-elastico', 'https://static.exercisedb.dev/media/H6ETwO9.gif', 'catalogo/abdominal-v-up-com-elastico--H6ETwO9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-v-up-com-elastico--H6ETwO9.gif', ARRAY['abdômen'], ARRAY['elástico de resistência'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands toward your toes.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Raise your straight legs and torso together, reaching toward the feet before lowering under control.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:31.618451+00', '2026-10-31 19:43:31.488+00'), ('H6ybluc', 'Agachamento unilateral com halteres', 'dumbbell single leg squat', 'agachamento-unilateral-com-halteres', 'https://static.exercisedb.dev/media/H6ybluc.gif', 'catalogo/agachamento-unilateral-com-halteres--H6ybluc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-unilateral-com-halteres--H6ybluc.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Reach one leg forward and keep it off the ground throughout the exercise.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:31.998823+00', '2026-10-31 19:43:31.865+00'), ('h8LFzo9', 'Tríceps testa com barra', 'barbell lying triceps extension skull crusher', 'triceps-testa-com-barra', 'https://static.exercisedb.dev/media/h8LFzo9.gif', 'catalogo/triceps-testa-com-barra--h8LFzo9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra--h8LFzo9.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take hold of the barbell with palms facing down, hands about shoulder width, and extend your arms straight up over your chest.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:32.155184+00', '2026-10-31 19:43:32.028+00'), ('H9y3Dkr', 'Rosca bilateral no cabo no banco inclinado', 'Cable Two-Arm Curl On Incline Bench', 'rosca-bilateral-no-cabo-no-banco-inclinado', 'https://static.exercisedb.dev/media/H9y3Dkr.gif', 'catalogo/rosca-bilateral-no-cabo-no-banco-inclinado--H9y3Dkr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-bilateral-no-cabo-no-banco-inclinado--H9y3Dkr.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an incline bench with your back against the pad and your feet planted.","Step:2 Hold the cable handles with palms facing up, and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:32.435882+00', '2026-10-31 19:43:32.304+00'), ('Ha7SZ3y', 'Levantamento turco com kettlebell (estilo agachamento)', 'Kettlebell Turkish Get-Up (Squat Style)', 'levantamento-turco-com-kettlebell-estilo-agachamento', 'https://static.exercisedb.dev/media/Ha7SZ3y.gif', 'catalogo/levantamento-turco-com-kettlebell-estilo-agachamento--Ha7SZ3y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-turco-com-kettlebell-estilo-agachamento--Ha7SZ3y.gif', ARRAY['coxas'], ARRAY['kettlebell'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','core'], '["Step:1 Begin by lying on your back with your legs extended and the kettlebell held in your right hand, arm straight above your shoulder.","Step:2 Before moving, bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Step:3 Fix your gaze on the load and stack the working wrist above its shoulder.","Step:4 Move from lying to standing in stages, watching the weight and keeping the supporting arm stacked.","Step:5 Move one stage at a time instead of rushing from floor to standing.","Step:6 Reverse the same stages to return to the floor, keeping the load steady throughout."]', '2026-10-31 19:43:32.275707+00', '2026-10-31 19:43:32.147+00'), ('hacCyUv', 'Rosca Scott com barra W pegada fechada', 'EZ-Bar Close-Grip Preacher Curl', 'rosca-scott-com-barra-w-pegada-fechada', 'https://static.exercisedb.dev/media/hacCyUv.gif', 'catalogo/rosca-scott-com-barra-w-pegada-fechada--hacCyUv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-com-barra-w-pegada-fechada--hacCyUv.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with palms facing up.","Step:2 Set your triceps on the pad and straighten your arms, with your spine steady.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:32.229508+00', '2026-10-31 19:43:32.091+00'), ('hBGWILP', 'Adução de quadril no cabo', 'cable hip adduction', 'aducao-de-quadril-no-cabo', 'https://static.exercisedb.dev/media/hBGWILP.gif', 'catalogo/aducao-de-quadril-no-cabo--hBGWILP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/aducao-de-quadril-no-cabo--hBGWILP.gif', ARRAY['coxas'], ARRAY['cabo'], ARRAY['adutores'], ARRAY['glúteos','quadríceps'], '["Step:1 Connect the ankle cuff to your ankle and stand facing the cable machine.","Step:2 Set yourself far enough away from the machine so that there is tension on the cable.","Step:3 Square the pelvis before moving the working leg.","Step:4 Draw the working leg inward against resistance without leaning sideways.","Step:5 Move only as far as the pelvis can remain steady.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:32.851666+00', '2026-10-31 19:43:32.711+00'), ('HbSG1Pw', 'Contração isométrica de peitoral', 'isometric chest squeeze', 'contracao-isometrica-de-peitoral', 'https://static.exercisedb.dev/media/HbSG1Pw.gif', 'catalogo/contracao-isometrica-de-peitoral--HbSG1Pw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/contracao-isometrica-de-peitoral--HbSG1Pw.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Reach your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:32.780187+00', '2026-10-31 19:43:32.647+00'), ('hbY9wqG', 'Repetições de front lever', 'front lever reps', 'repeticoes-de-front-lever', 'https://static.exercisedb.dev/media/hbY9wqG.gif', 'catalogo/repeticoes-de-front-lever--hbY9wqG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/repeticoes-de-front-lever--hbY9wqG.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['costas superiores'], ARRAY['core','deltoides'], '["Step:1 Suspend yourself from a pull-up bar with palms facing down, palms turned away from you.","Step:2 Brace your trunk and pull your shoulder blades down and back.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:32.81135+00', '2026-10-31 19:43:32.669+00'), ('HBYyX94', 'Afundo estático com barra', 'barbell split squat', 'afundo-estatico-com-barra', 'https://static.exercisedb.dev/media/HBYyX94.gif', 'catalogo/afundo-estatico-com-barra--HBYyX94.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-estatico-com-barra--HBYyX94.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width, holding a barbell across your upper back.","Step:2 Step far forward with your right foot, keeping your torso upright.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:32.907307+00', '2026-10-31 19:43:32.766+00'), ('hC6oYY5', 'Alongamento assistido de adutores deitado de lado', 'Assisted Side-Lying Adductor Stretch', 'alongamento-assistido-de-adutores-deitado-de-lado', 'https://static.exercisedb.dev/media/hC6oYY5.gif', 'catalogo/alongamento-assistido-de-adutores-deitado-de-lado--hC6oYY5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-assistido-de-adutores-deitado-de-lado--hC6oYY5.gif', ARRAY['coxas'], ARRAY['assistido'], ARRAY['adutores'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Settle onto your side with your legs straight and stacked on top of each other.","Step:2 Before moving, bend your bottom leg slightly for stability.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:33.067456+00', '2026-10-31 19:43:32.937+00'), ('hCjGsRQ', 'Prancha power point', 'power point plank', 'prancha-power-point', 'https://static.exercisedb.dev/media/hCjGsRQ.gif', 'catalogo/prancha-power-point--hCjGsRQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-power-point--hCjGsRQ.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','tríceps','glúteos'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Step:2 Brace your trunk and squeeze your glutes to maintain a stable position.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:33.417105+00', '2026-10-31 19:43:33.289+00'), ('HDYiZcY', 'Rosca martelo cruzada com halteres', 'dumbbell cross body hammer curl', 'rosca-martelo-cruzada-com-halteres', 'https://static.exercisedb.dev/media/HDYiZcY.gif', 'catalogo/rosca-martelo-cruzada-com-halteres--HDYiZcY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-cruzada-com-halteres--HDYiZcY.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your body.","Step:2 Hold your elbows near your torso and your upper arms stationary.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl each weight across the torso toward the opposite shoulder, keeping the palm facing inward.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:33.692917+00', '2026-10-31 19:43:33.561+00'), ('HEJ6DIX', 'Tríceps coice no cabo', 'cable kickback', 'triceps-coice-no-cabo', 'https://static.exercisedb.dev/media/HEJ6DIX.gif', 'catalogo/triceps-coice-no-cabo--HEJ6DIX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-no-cabo--HEJ6DIX.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable handle with your right hand and step back to create tension in the cable.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:33.716377+00', '2026-10-31 19:43:33.583+00'), ('hfmQ0Tz', 'Rosca de punho inversa por trás em pé no Smith', 'smith standing back wrist curl', 'rosca-de-punho-inversa-por-tras-em-pe-no-smith', 'https://static.exercisedb.dev/media/hfmQ0Tz.gif', 'catalogo/rosca-de-punho-inversa-por-tras-em-pe-no-smith--hfmQ0Tz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-por-tras-em-pe-no-smith--hfmQ0Tz.gif', ARRAY['antebraços'], ARRAY['Smith'], ARRAY['antebraços'], ARRAY['bíceps','tríceps'], '["Step:1 Face the smith machine from a stable stance with feet about shoulder width.","Step:2 Hold the barbell with palms facing down, hands about shoulder width.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:43:33.521878+00', '2026-10-31 19:43:33.39+00'), ('HfqciZF', 'Maltese com pernas afastadas', 'straddle maltese', 'maltese-com-pernas-afastadas', 'https://static.exercisedb.dev/media/HfqciZF.gif', 'catalogo/maltese-com-pernas-afastadas--HfqciZF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/maltese-com-pernas-afastadas--HfqciZF.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','peitorais'], '["Step:1 Begin by hanging from a pair of rings with your arms straight and your body in a straight line.","Step:2 Move your legs wide apart, forming a straddle position.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:33.545388+00', '2026-10-31 19:43:33.416+00'), ('Hgs6Nl1', 'Elevação de pernas sentado', 'seated leg raise', 'elevacao-de-pernas-sentado', 'https://static.exercisedb.dev/media/Hgs6Nl1.gif', 'catalogo/elevacao-de-pernas-sentado--Hgs6Nl1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-sentado--Hgs6Nl1.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Take a seat on a flat bench with your back straight and your feet planted.","Step:2 Set your hands on the sides of the bench for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:43:34.474249+00', '2026-10-31 19:43:34.345+00'), ('hHy8tQG', 'Crucifixo unilateral no cabo na bola suíça', 'Cable Single-Arm Fly On Exercise Ball', 'crucifixo-unilateral-no-cabo-na-bola-suica', 'https://static.exercisedb.dev/media/hHy8tQG.gif', 'catalogo/crucifixo-unilateral-no-cabo-na-bola-suica--hHy8tQG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-unilateral-no-cabo-na-bola-suica--hHy8tQG.gif', ARRAY['peito'], ARRAY['cabo','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:43:34.358021+00', '2026-10-31 19:43:34.227+00'), ('HIgYKAB', 'Sequência de postura sentada com pernas afastadas', 'seated wide angle pose sequence', 'sequencia-de-postura-sentada-com-pernas-afastadas', 'https://static.exercisedb.dev/media/HIgYKAB.gif', 'catalogo/sequencia-de-postura-sentada-com-pernas-afastadas--HIgYKAB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/sequencia-de-postura-sentada-com-pernas-afastadas--HIgYKAB.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['quadríceps','panturrilhas'], '["Step:1 Take a seat on the ground with your legs extended in a wide angle.","Step:2 Pull your toes toward you and engage your quadriceps.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:34.614323+00', '2026-10-31 19:43:34.479+00'), ('Hj4FOCd', 'Pullover declinado com barra pegada aberta', 'barbell decline wide-grip pullover', 'pullover-declinado-com-barra-pegada-aberta', 'https://static.exercisedb.dev/media/Hj4FOCd.gif', 'catalogo/pullover-declinado-com-barra-pegada-aberta--Hj4FOCd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-declinado-com-barra-pegada-aberta--Hj4FOCd.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['latíssimo do dorso'], ARRAY['tríceps','peitorais'], '["Step:1 Settle onto a decline bench with your head lower than your hips and your feet secured.","Step:2 Take a barbell with a wide grip and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:34.270865+00', '2026-10-31 19:43:34.108+00'), ('HJ63mSO', 'Tríceps testa com barra pegada fechada', 'barbell lying close-grip triceps extension', 'triceps-testa-com-barra-pegada-fechada', 'https://static.exercisedb.dev/media/HJ63mSO.gif', 'catalogo/triceps-testa-com-barra-pegada-fechada--HJ63mSO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra-pegada-fechada--HJ63mSO.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Hold the barbell with a close grip, hands about shoulder width, palms facing up.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:34.440679+00', '2026-10-31 19:43:34.307+00'), ('HjdqmZa', 'Barra fixa supinada unilateral', 'Single-Arm Chin-Up', 'barra-fixa-supinada-unilateral', 'https://static.exercisedb.dev/media/HjdqmZa.gif', 'catalogo/barra-fixa-supinada-unilateral--HjdqmZa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-unilateral--HjdqmZa.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Face the pull-up bar from a stable stance with feet about shoulder width.","Step:2 Reach up to hold the bar with palms facing up, with one hand gripping the bar and the other hand holding your wrist for support.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower to long arms without dropping suddenly from the top; switch sides when the set calls for it."]', '2026-10-31 19:43:35.120934+00', '2026-10-31 19:43:34.992+00'), ('hl8DUh8', 'Supino declinado com barra pegada aberta', 'barbell decline wide-grip press', 'supino-declinado-com-barra-pegada-aberta', 'https://static.exercisedb.dev/media/hl8DUh8.gif', 'catalogo/supino-declinado-com-barra-pegada-aberta--hl8DUh8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-com-barra-pegada-aberta--hl8DUh8.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Secure the feet on a decline bench, keeping the head below the hips.","Step:2 Hold the barbell with a wide grip, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:35.040774+00', '2026-10-31 19:43:34.899+00'), ('hMEptv0', 'Pullover declinado com barra (braços flexionados)', 'barbell decline bent arm pullover', 'pullover-declinado-com-barra-bracos-flexionados', 'https://static.exercisedb.dev/media/hMEptv0.gif', 'catalogo/pullover-declinado-com-barra-bracos-flexionados--hMEptv0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-declinado-com-barra-bracos-flexionados--hMEptv0.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['latíssimo do dorso'], ARRAY['tríceps','peitorais'], '["Step:1 Get onto a decline bench with your head lower than your hips and your feet secured.","Step:2 Take a barbell with a pronated grip (palms turned away from you) and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:35.49441+00', '2026-10-31 19:43:35.361+00'), ('HMzLjXx', 'Barra fixa com peso', 'weighted pull-up', 'barra-fixa-com-peso', 'https://static.exercisedb.dev/media/HMzLjXx.gif', 'catalogo/barra-fixa-com-peso--HMzLjXx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-peso--HMzLjXx.gif', ARRAY['costas'], ARRAY['peso adicional'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with palms facing down, just beyond shoulder width.","Step:2 Suspend yourself from the bar with your arms straight and your body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:35.219322+00', '2026-10-31 19:43:35.089+00'), ('hnOYgH3', 'JM Press com barra W', 'EZ-Bar Jm Bench Press', 'jm-press-com-barra-w', 'https://static.exercisedb.dev/media/hnOYgH3.gif', 'catalogo/jm-press-com-barra-w--hnOYgH3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/jm-press-com-barra-w--hnOYgH3.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the ez barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:35.604824+00', '2026-10-31 19:43:35.471+00'), ('hoXt6wv', 'Gancho de esquerda (boxe)', 'left hook (boxing)', 'gancho-de-esquerda-boxe', 'https://static.exercisedb.dev/media/hoXt6wv.gif', 'catalogo/gancho-de-esquerda-boxe--hoXt6wv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/gancho-de-esquerda-boxe--hoXt6wv.gif', ARRAY['ombros'], ARRAY['peso corporal'], ARRAY['deltoides'], ARRAY['bíceps','tríceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Keep the left hand up to protect your face and your right hand by your chin.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Pivot through the hips and feet as the left arm travels across at chest height.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:35.90515+00', '2026-10-31 19:43:35.777+00'), ('HPlPoQA', 'Rosca martelo na polia com corda', 'cable hammer curl (with rope)', 'rosca-martelo-na-polia-com-corda', 'https://static.exercisedb.dev/media/HPlPoQA.gif', 'catalogo/rosca-martelo-na-polia-com-corda--HPlPoQA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-na-polia-com-corda--HPlPoQA.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand upright with your feet about shoulder width and a slight bend in your knees.","Step:2 Take hold of the cable rope attachment with palms facing up, palms facing each other, and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:35.711453+00', '2026-10-31 19:43:35.58+00'), ('hq2hyDH', 'Rosca Scott em pé com halteres', 'dumbbell standing preacher curl', 'rosca-scott-em-pe-com-halteres', 'https://static.exercisedb.dev/media/hq2hyDH.gif', 'catalogo/rosca-scott-em-pe-com-halteres--hq2hyDH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-em-pe-com-halteres--hq2hyDH.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand upright with your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.","Step:2 Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows soft.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:35.783555+00', '2026-10-31 19:43:35.654+00'), ('hrrS0Ed', 'Elevação lateral sentado com halteres', 'dumbbell seated lateral raise', 'elevacao-lateral-sentado-com-halteres', 'https://static.exercisedb.dev/media/hrrS0Ed.gif', 'catalogo/elevacao-lateral-sentado-com-halteres--hrrS0Ed.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-sentado-com-halteres--hrrS0Ed.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Plant both feet while seated on a bench; a dumbbell in each hand, resting on your thighs.","Step:2 Keep your spine in a comfortable neutral position and core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:36.399177+00', '2026-10-31 19:43:36.262+00'), ('hrVQWvE', 'Stiff com barra', 'Barbell Straight-Leg Deadlift', 'stiff-com-barra', 'https://static.exercisedb.dev/media/hrVQWvE.gif', 'catalogo/stiff-com-barra--hrVQWvE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stiff-com-barra--hrVQWvE.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['posteriores de coxa'], ARRAY['glúteos','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and your toes pointing forward.","Step:2 Take hold of the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:36.387009+00', '2026-10-31 19:43:36.258+00'), ('HsjbB1z', 'Afundo sprint no Smith', 'smith sprint lunge', 'afundo-sprint-no-smith', 'https://static.exercisedb.dev/media/HsjbB1z.gif', 'catalogo/afundo-sprint-no-smith--HsjbB1z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-sprint-no-smith--HsjbB1z.gif', ARRAY['coxas'], ARRAY['máquina Smith'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Prepare the smith machine with the barbell at hip height.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:36.311795+00', '2026-10-31 19:43:36.177+00'), ('HsvHqgf', 'Agachamento com halteres', 'dumbbell squat', 'agachamento-com-halteres', 'https://static.exercisedb.dev/media/HsvHqgf.gif', 'catalogo/agachamento-com-halteres--HsvHqgf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-halteres--HsvHqgf.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at your sides.","Step:2 With your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:36.329051+00', '2026-10-31 19:43:36.196+00'), ('ht8xDrP', 'Desenvolvimento militar em pé atrás da nuca no Smith', 'smith standing behind head military press', 'desenvolvimento-militar-em-pe-atras-da-nuca-no-smith', 'https://static.exercisedb.dev/media/ht8xDrP.gif', 'catalogo/desenvolvimento-militar-em-pe-atras-da-nuca-no-smith--ht8xDrP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-em-pe-atras-da-nuca-no-smith--ht8xDrP.gif', ARRAY['ombros'], ARRAY['máquina Smith'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Set the seat height of the smith machine so that the bar is at shoulder level.","Step:2 Stand and set your feet about shoulder width and your knees soft.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:36.488804+00', '2026-10-31 19:43:36.356+00'), ('HtfCpfi', 'Salto estrela', 'Star Jump', 'salto-estrela', 'https://static.exercisedb.dev/media/HtfCpfi.gif', 'catalogo/salto-estrela--HtfCpfi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/salto-estrela--HtfCpfi.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and your arms by your sides.","Step:2 Before moving, bend your knees slightly and jump up explosively.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:43:37.23655+00', '2026-10-31 19:43:37.099+00'), ('HUEqZ1y', 'Agachamento lateral com barra', 'barbell side split squat', 'agachamento-lateral-com-barra', 'https://static.exercisedb.dev/media/HUEqZ1y.gif', 'catalogo/agachamento-lateral-com-barra--HUEqZ1y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-lateral-com-barra--HUEqZ1y.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointing slightly outwards.","Step:2 Take a barbell across your upper back, resting it on your shoulders.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:36.969154+00', '2026-10-31 19:43:36.838+00'), ('hvHhCv8', 'Elevação frontal na polia', 'cable forward raise', 'elevacao-frontal-na-polia', 'https://static.exercisedb.dev/media/hvHhCv8.gif', 'catalogo/elevacao-frontal-na-polia--hvHhCv8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-na-polia--hvHhCv8.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['tríceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Take hold of the cable handle with palms facing down, and your arms straight in front of you.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:36.989497+00', '2026-10-31 19:43:36.857+00'), ('hvV79Si', 'Remada baixa na polia', 'cable low seated row', 'remada-baixa-na-polia', 'https://static.exercisedb.dev/media/hvV79Si.gif', 'catalogo/remada-baixa-na-polia--hvV79Si.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-baixa-na-polia--hvV79Si.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the machine with your feet flat on the footrests and your knees soft.","Step:2 Hold the handles with palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:37.338277+00', '2026-10-31 19:43:37.207+00'), ('hwygydB', 'Rosca Scott com halteres na bola suíça', 'dumbbell preacher curl over exercise ball', 'rosca-scott-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/hwygydB.gif', 'catalogo/rosca-scott-com-halteres-na-bola-suica--hwygydB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-com-halteres-na-bola-suica--hwygydB.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand with palms facing up, resting your elbow on the exercise ball.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:37.341613+00', '2026-10-31 19:43:37.208+00'), ('Hx1WC8I', 'Extensão de tríceps inclinada na polia', 'cable incline triceps extension', 'extensao-de-triceps-inclinada-na-polia', 'https://static.exercisedb.dev/media/Hx1WC8I.gif', 'catalogo/extensao-de-triceps-inclinada-na-polia--Hx1WC8I.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-inclinada-na-polia--Hx1WC8I.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Set the cable machine to a low pulley position.","Step:2 Connect a straight bar to the cable.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:37.561144+00', '2026-10-31 19:43:37.428+00'), ('hxyTtWj', 'Elevação lateral sentado com halteres', 'dumbbell seated lateral raise', 'elevacao-lateral-sentado-com-halteres', 'https://static.exercisedb.dev/media/hxyTtWj.gif', 'catalogo/elevacao-lateral-sentado-com-halteres--hxyTtWj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-sentado-com-halteres--hxyTtWj.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Plant both feet while seated on a bench; a dumbbell in each hand, resting on your thighs.","Step:2 Keep your spine in a comfortable neutral position and core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:37.757127+00', '2026-10-31 19:43:37.619+00'), ('Hy9D21L', 'Flexão lateral de tronco a 45°', '45° side bend', 'flexao-lateral-de-tronco-a-45', 'https://static.exercisedb.dev/media/Hy9D21L.gif', 'catalogo/flexao-lateral-de-tronco-a-45--Hy9D21L.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-lateral-de-tronco-a-45--Hy9D21L.gif', ARRAY['cintura'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Stand and set your feet about shoulder width and your arms extended straight down by your sides.","Step:2 With your back straight and your core engaged, With control bend your torso to one side, lowering your hand toward your knee.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Let the side of the trunk work; do not twist or shift the hips.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:38.04193+00', '2026-10-31 19:43:37.912+00'), ('HYe1ZqR', 'Crucifixo inclinado com halteres na bola suíça', 'dumbbell incline fly on exercise ball', 'crucifixo-inclinado-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/HYe1ZqR.gif', 'catalogo/crucifixo-inclinado-com-halteres-na-bola-suica--HYe1ZqR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-com-halteres-na-bola-suica--HYe1ZqR.gif', ARRAY['peito'], ARRAY['halteres','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on an exercise ball and roll forward until your upper back is resting on the incline bench.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:43:37.935749+00', '2026-10-31 19:43:37.806+00'), ('i11JWU7', 'Extensão de tríceps unilateral acima da cabeça na polia, em pé, pegada supinada', 'Cable Standing Reverse-Grip Single-Arm Overhead Triceps Extension', 'extensao-de-triceps-unilateral-acima-da-cabeca-na-polia-em-pe-pegada-supinada', 'https://static.exercisedb.dev/media/i11JWU7.gif', 'catalogo/extensao-de-triceps-unilateral-acima-da-cabeca-na-polia-em-pe-pegada-supinada--i11JWU7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-unilateral-acima-da-cabeca-na-polia-em-pe-pegada-supinada--i11JWU7.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Face the away from the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable handle with palms facing up and extend your arm overhead, keeping your elbow close to your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:43:38.141573+00', '2026-10-31 19:43:37.985+00'), ('I1OBLnn', 'Svend Press com peso', 'weighted svend press', 'svend-press-com-peso', 'https://static.exercisedb.dev/media/I1OBLnn.gif', 'catalogo/svend-press-com-peso--I1OBLnn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/svend-press-com-peso--I1OBLnn.gif', ARRAY['peito'], ARRAY['peso adicional'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Stand and set your feet about shoulder width and hold a weight plate ahead of your chest with both hands.","Step:2 Keep your elbows soft and your palms facing each other.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:38.357385+00', '2026-10-31 19:43:38.224+00'), ('I3tsCnC', 'Elevação de pernas na barra fixa', 'hanging leg raise', 'elevacao-de-pernas-na-barra-fixa', 'https://static.exercisedb.dev/media/I3tsCnC.gif', 'catalogo/elevacao-de-pernas-na-barra-fixa--I3tsCnC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-na-barra-fixa--I3tsCnC.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your legs up in front of you, keeping them straight.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:43:38.493799+00', '2026-10-31 19:43:38.364+00'), ('I4hDWkc', 'Flexão de braço', 'push-up', 'flexao-de-braco', 'https://static.exercisedb.dev/media/I4hDWkc.gif', 'catalogo/flexao-de-braco--I4hDWkc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco--I4hDWkc.gif', ARRAY['Peito'], ARRAY['Peso corporal'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides','Core'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your feet together.","Step:2 Brace your trunk and lower your body toward the ground by bending your elbows, keeping your body in a straight line.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:38.597215+00', '2026-10-31 19:43:38.468+00'), ('i4JkUaL', 'Inclinação lateral com barra', 'barbell side bent', 'inclinacao-lateral-com-barra', 'https://static.exercisedb.dev/media/i4JkUaL.gif', 'catalogo/inclinacao-lateral-com-barra--i4JkUaL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/inclinacao-lateral-com-barra--i4JkUaL.gif', ARRAY['Abdômen'], ARRAY['Barra'], ARRAY['Abdominais'], ARRAY['Oblíquos','Eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with both hands, palms facing down.","Step:2 Keep your spine in a comfortable neutral position and core engaged throughout the exercise.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Let the side of the trunk work; do not twist or shift the hips.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:39.068639+00', '2026-10-31 19:43:38.938+00'), ('I4KkPdl', 'Push press com dois kettlebells', 'kettlebell double push press', 'push-press-com-dois-kettlebells', 'https://static.exercisedb.dev/media/I4KkPdl.gif', 'catalogo/push-press-com-dois-kettlebells--I4KkPdl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/push-press-com-dois-kettlebells--I4KkPdl.gif', ARRAY['Ombros'], ARRAY['Kettlebell'], ARRAY['Deltoides'], ARRAY['Tríceps','Core'], '["Step:1 Begin by standing with your feet about shoulder width, holding a kettlebell in each hand at shoulder height.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:38.71288+00', '2026-10-31 19:43:38.577+00'), ('I4tibZG', 'Hang clean alternado com kettlebell', 'kettlebell alternating hang clean', 'hang-clean-alternado-com-kettlebell', 'https://static.exercisedb.dev/media/I4tibZG.gif', 'catalogo/hang-clean-alternado-com-kettlebell--I4tibZG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/hang-clean-alternado-com-kettlebell--I4tibZG.gif', ARRAY['Antebraços'], ARRAY['Kettlebell'], ARRAY['Antebraços'], ARRAY['Deltoides','Trapézio','Core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:43:39.353144+00', '2026-10-31 19:43:39.221+00'), ('i5cEhka', 'Flexão de braço declinada', 'decline push-up', 'flexao-de-braco-declinada', 'https://static.exercisedb.dev/media/i5cEhka.gif', 'catalogo/flexao-de-braco-declinada--i5cEhka.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-declinada--i5cEhka.gif', ARRAY['Peito'], ARRAY['Peso corporal'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides'], '["Step:1 Set your hands on the ground just beyond shoulder width, with your feet elevated on a stable surface.","Step:2 Hold your body in a straight line from head to toe, engaging your core muscles.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:39.456268+00', '2026-10-31 19:43:39.329+00'), ('i6LWjok', 'Pullover com barra', 'barbell pullover', 'pullover-com-barra', 'https://static.exercisedb.dev/media/i6LWjok.gif', 'catalogo/pullover-com-barra--i6LWjok.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-barra--i6LWjok.gif', ARRAY['Costas'], ARRAY['Barra'], ARRAY['Grande dorsal'], ARRAY['Peitorais','Tríceps'], '["Step:1 Settle onto a bench with your head at one end and your feet on the floor.","Step:2 Take a barbell with a shoulder-width grip and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:39.58979+00', '2026-10-31 19:43:39.452+00'), ('i8BdLTK', 'Pullover com halter e braços estendidos', 'dumbbell straight arm pullover', 'pullover-com-halter-e-bracos-estendidos', 'https://static.exercisedb.dev/media/i8BdLTK.gif', 'catalogo/pullover-com-halter-e-bracos-estendidos--i8BdLTK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-halter-e-bracos-estendidos--i8BdLTK.gif', ARRAY['Peito'], ARRAY['Halter'], ARRAY['Peitorais'], ARRAY['Grande dorsal','Tríceps'], '["Step:1 Settle onto a bench with your head at one end and your feet planted firmly on the ground.","Step:2 Take a dumbbell with both hands and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:39.824217+00', '2026-10-31 19:43:39.684+00'), ('ia6kIIl', 'Meia flexão de joelhos', 'Half Knee Bends', 'meia-flexao-de-joelhos', 'https://static.exercisedb.dev/media/ia6kIIl.gif', 'catalogo/meia-flexao-de-joelhos--ia6kIIl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/meia-flexao-de-joelhos--ia6kIIl.gif', ARRAY['Cardio'], ARRAY['Peso corporal'], ARRAY['Sistema cardiovascular'], ARRAY['Quadríceps','Posteriores de coxa','Glúteos'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, bend your knees and lower your body down as if you were sitting back into a chair.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:40.326096+00', '2026-10-31 19:43:40.193+00'), ('Ia7tumC', 'Panturrilha sentado unilateral com halter', 'Dumbbell Seated Single-Leg Calf Raise', 'panturrilha-sentado-unilateral-com-halter', 'https://static.exercisedb.dev/media/Ia7tumC.gif', 'catalogo/panturrilha-sentado-unilateral-com-halter--Ia7tumC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-unilateral-com-halter--Ia7tumC.gif', ARRAY['Panturrilhas'], ARRAY['Halter'], ARRAY['Panturrilhas'], ARRAY['Posteriores de coxa','Glúteos'], '["Step:1 Take a seat on a bench or chair with your feet planted and a dumbbell resting on your right thigh.","Step:2 Reach your left leg straight out in front of you, keeping your foot flexed.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:43:39.934689+00', '2026-10-31 19:43:39.806+00'), ('iaapw0g', 'Tríceps francês sentado com barra W', 'EZ-Bar Seated Triceps Extension', 'triceps-frances-sentado-com-barra-w', 'https://static.exercisedb.dev/media/iaapw0g.gif', 'catalogo/triceps-frances-sentado-com-barra-w--iaapw0g.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-sentado-com-barra-w--iaapw0g.gif', ARRAY['Braços'], ARRAY['Barra W'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take hold of the ez barbell with palms facing down, hands about shoulder width.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:40.096205+00', '2026-10-31 19:43:39.959+00'), ('IaGQCrC', 'Flexão de braço na suspensão (TRX)', 'suspended push-up', 'flexao-de-braco-na-suspensao-trx', 'https://static.exercisedb.dev/media/IaGQCrC.gif', 'catalogo/flexao-de-braco-na-suspensao-trx--IaGQCrC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-na-suspensao-trx--IaGQCrC.gif', ARRAY['Peito'], ARRAY['Peso corporal','Fitas de suspensão (TRX)'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides','Core'], '["Step:1 Choose a suspension trainer and adjust it to an appropriate height.","Step:2 Face away from the anchor point and hold the handles with palms facing down.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:40.292549+00', '2026-10-31 19:43:40.165+00'), ('Ie9UGty', 'Panturrilha sentado na máquina', 'Machine Seated Calf Press', 'panturrilha-sentado-na-maquina', 'https://static.exercisedb.dev/media/Ie9UGty.gif', 'catalogo/panturrilha-sentado-na-maquina--Ie9UGty.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-na-maquina--Ie9UGty.gif', ARRAY['Panturrilhas'], ARRAY['Máquina articulada'], ARRAY['Panturrilhas'], ARRAY['Sóleo','Posteriores de coxa'], '["Step:1 Set the seat of the machine so that your shoulders are aligned with the lever pad.","Step:2 Set your toes on the lower portion of the platform and position your knees under the lever pad.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:40.745274+00', '2026-10-31 19:43:40.609+00'), ('IeDEXTe', 'Elevação de panturrilha no leg press sentado', 'Machine Seated Squat Calf Raise On Leg Press Machine', 'elevacao-de-panturrilha-no-leg-press-sentado', 'https://static.exercisedb.dev/media/IeDEXTe.gif', 'catalogo/elevacao-de-panturrilha-no-leg-press-sentado--IeDEXTe.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-no-leg-press-sentado--IeDEXTe.gif', ARRAY['Panturrilhas'], ARRAY['Máquina articulada'], ARRAY['Panturrilhas'], ARRAY['Quadríceps','Posteriores de coxa','Glúteos'], '["Step:1 Move the leg-press seat until the knees remain soft at the start.","Step:2 Take a seat on the machine with your back against the backrest and your feet flat on the footplate, about shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:41.095685+00', '2026-10-31 19:43:40.954+00'), ('IENzBdA', 'Rosca drag com barra', 'barbell drag curl', 'rosca-drag-com-barra', 'https://static.exercisedb.dev/media/IENzBdA.gif', 'catalogo/rosca-drag-com-barra--IENzBdA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-drag-com-barra--IENzBdA.gif', ARRAY['Braços'], ARRAY['Barra'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing up.","Step:2 Keep the barbell hanging at arm''s length ahead of your thighs.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:40.912728+00', '2026-10-31 19:43:40.78+00'), ('IeTIEqg', 'Agachamento frontal com barra', 'barbell front chest squat', 'agachamento-frontal-com-barra', 'https://static.exercisedb.dev/media/IeTIEqg.gif', 'catalogo/agachamento-frontal-com-barra--IeTIEqg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frontal-com-barra--IeTIEqg.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de coxa','Panturrilhas','Core'], '["Step:1 Begin by standing with your feet about shoulder width, toes slightly turned out.","Step:2 Take hold of the barbell ahead of your chest with your hands about shoulder width, elbows pointing forward.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:41.239623+00', '2026-10-31 19:43:41.107+00'), ('IGjKj1v', 'Remada sentada na máquina com pegada fechada', 'Machine Narrow Grip Seated Row', 'remada-sentada-na-maquina-com-pegada-fechada', 'https://static.exercisedb.dev/media/IGjKj1v.gif', 'catalogo/remada-sentada-na-maquina-com-pegada-fechada--IGjKj1v.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-na-maquina-com-pegada-fechada--IGjKj1v.gif', ARRAY['Costas'], ARRAY['Máquina articulada'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Set the seat height and footrests to ensure proper form.","Step:2 Take a seat on the machine with your feet flat on the footrests and your knees soft.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:41.525773+00', '2026-10-31 19:43:41.392+00'), ('IGtBdNT', 'Rosca martelo sentado com halteres', 'dumbbell seated hammer curl', 'rosca-martelo-sentado-com-halteres', 'https://static.exercisedb.dev/media/IGtBdNT.gif', 'catalogo/rosca-martelo-sentado-com-halteres--IGtBdNT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-sentado-com-halteres--IGtBdNT.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:41.625459+00', '2026-10-31 19:43:41.484+00'), ('iK59oEA', 'Pullover com halter deitado na bola suíça', 'dumbbell lying pullover on exercise ball', 'pullover-com-halter-deitado-na-bola-suica', 'https://static.exercisedb.dev/media/iK59oEA.gif', 'catalogo/pullover-com-halter-deitado-na-bola-suica--iK59oEA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-halter-deitado-na-bola-suica--iK59oEA.gif', ARRAY['Peito'], ARRAY['Halter','Bola suíça'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides','Costas'], '["Step:1 Take a seat on an exercise ball and roll forward until your upper back is resting on the ball.","Step:2 Take a dumbbell with both hands and extend your arms straight up over your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:43:41.694008+00', '2026-10-31 19:43:41.559+00'), ('IL0JUxR', 'Barra Fixa Supinada Gironda (até o Esterno)', 'Gironda Sternum Chin-Up', 'barra-fixa-supinada-gironda-ate-o-esterno', 'https://static.exercisedb.dev/media/IL0JUxR.gif', 'catalogo/barra-fixa-supinada-gironda-ate-o-esterno--IL0JUxR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-gironda-ate-o-esterno--IL0JUxR.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoide posterior'], '["Step:1 Face the high bar from a stable stance with feet about shoulder width.","Step:2 Reach up to hold the bar with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Lean back as you pull, aiming the sternum toward the bar and drawing your elbows behind you.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:41.698707+00', '2026-10-31 19:43:41.558+00'), ('ila4NZS', 'Levantamento Terra com Barra', 'barbell deadlift', 'levantamento-terra-com-barra', 'https://static.exercisedb.dev/media/ila4NZS.gif', 'catalogo/levantamento-terra-com-barra--ila4NZS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-com-barra--ila4NZS.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and the barbell on the ground in front of you.","Step:2 Bend your knees and hinge at the hips to lower your torso and grip the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:41.857371+00', '2026-10-31 19:43:41.723+00'), ('IMRsOCn', 'Squat Jerk', 'squat jerk', 'squat-jerk', 'https://static.exercisedb.dev/media/IMRsOCn.gif', 'catalogo/squat-jerk--IMRsOCn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/squat-jerk--IMRsOCn.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas','core'], '["Step:1 Start with the barbell resting on your shoulders, with your feet about shoulder width.","Step:2 Before moving, lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:43:42.144238+00', '2026-10-31 19:43:42.016+00'), ('iny3m5y', 'Dead Bug (Inseto Morto)', 'dead bug', 'dead-bug-inseto-morto', 'https://static.exercisedb.dev/media/iny3m5y.gif', 'catalogo/dead-bug-inseto-morto--iny3m5y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/dead-bug-inseto-morto--iny3m5y.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto your back with your arms extended toward the ceiling.","Step:2 Before moving, bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:43:42.307355+00', '2026-10-31 19:43:42.173+00'), ('Ion0XWz', 'Elevação Posterior de Ombro com Halteres Deitado no Chão', 'dumbbell lying on floor rear delt raise', 'elevacao-posterior-de-ombro-com-halteres-deitado-no-chao', 'https://static.exercisedb.dev/media/Ion0XWz.gif', 'catalogo/elevacao-posterior-de-ombro-com-halteres-deitado-no-chao--Ion0XWz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-posterior-de-ombro-com-halteres-deitado-no-chao--Ion0XWz.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Position yourself face down on the floor with a dumbbell in each hand, palms facing each other.","Step:2 Reach your arms straight out in front of you, keeping a slight bend in your elbows.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms out and back with soft elbows, letting the rear shoulders do the work.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:42.314651+00', '2026-10-31 19:43:42.173+00'), ('ioTf098', 'Rosca Overhead no Cabo na Bola Suíça', 'cable overhead curl on exercise ball', 'rosca-overhead-no-cabo-na-bola-suica', 'https://static.exercisedb.dev/media/ioTf098.gif', 'catalogo/rosca-overhead-no-cabo-na-bola-suica--ioTf098.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-overhead-no-cabo-na-bola-suica--ioTf098.gif', ARRAY['braços'], ARRAY['cabo','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Take a seat on an exercise ball and hold the cable handle with palms facing up.","Step:2 Reach your arms fully overhead, keeping your elbows close to your ears.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:42.315504+00', '2026-10-31 19:43:42.183+00'), ('iPm26QU', 'Salto Descendo da Caixa com Estabilização Unilateral', 'Box Jump Down With Single-Leg Stabilization', 'salto-descendo-da-caixa-com-estabilizacao-unilateral', 'https://static.exercisedb.dev/media/iPm26QU.gif', 'catalogo/salto-descendo-da-caixa-com-estabilizacao-unilateral--iPm26QU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/salto-descendo-da-caixa-com-estabilizacao-unilateral--iPm26QU.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['quadríceps','posteriores de coxa','glúteos'], '["Step:1 Take your place in front of a box or platform with your feet about shoulder width.","Step:2 Before moving, bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Absorb the landing through the hips and knees before repeating; switch sides when the set calls for it."]', '2026-10-31 19:43:42.467251+00', '2026-10-31 19:43:42.336+00'), ('IpONWYv', 'Flexão Lateral de Tronco com Halter', 'dumbbell side bend', 'flexao-lateral-de-tronco-com-halter', 'https://static.exercisedb.dev/media/IpONWYv.gif', 'catalogo/flexao-lateral-de-tronco-com-halter--IpONWYv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-lateral-de-tronco-com-halter--IpONWYv.gif', ARRAY['abdômen'], ARRAY['halter'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Stand tall with your feet about shoulder width and hold a dumbbell in one hand, letting it hang down by your side.","Step:2 With your back straight and your core engaged, With control bend sideways at the waist toward the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Let the side of the trunk work; do not twist or shift the hips.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:42.756106+00', '2026-10-31 19:43:42.621+00'), ('Iptlv6x', 'Remada Alta com Halteres (Vista Posterior)', 'dumbbell upright row (back pov)', 'remada-alta-com-halteres-vista-posterior', 'https://static.exercisedb.dev/media/Iptlv6x.gif', 'catalogo/remada-alta-com-halteres-vista-posterior--Iptlv6x.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-com-halteres-vista-posterior--Iptlv6x.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 Let the dumbbells hang ahead of your thighs, with your arms straight and your palms facing your body.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:42.870502+00', '2026-10-31 19:43:42.732+00'), ('ipvgBnC', 'Panturrilha Sentado com Barra', 'barbell seated calf raise', 'panturrilha-sentado-com-barra', 'https://static.exercisedb.dev/media/ipvgBnC.gif', 'catalogo/panturrilha-sentado-com-barra--ipvgBnC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-com-barra--ipvgBnC.gif', ARRAY['panturrilhas'], ARRAY['barra'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Plant both feet while seated on a bench; a barbell resting on your thighs.","Step:2 Set the balls of your feet on a raised platform, such as a block or step.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:43.140287+00', '2026-10-31 19:43:43.004+00'), ('iQ241UP', 'Abdominal Parcial', 'Half Sit-Up', 'abdominal-parcial', 'https://static.exercisedb.dev/media/iQ241UP.gif', 'catalogo/abdominal-parcial--iQ241UP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-parcial--iQ241UP.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:43.085009+00', '2026-10-31 19:43:42.951+00'), ('isAAZWA', 'Barra Fixa Supinada com Deslocamento Lateral', 'side-to-side chin', 'barra-fixa-supinada-com-deslocamento-lateral', 'https://static.exercisedb.dev/media/isAAZWA.gif', 'catalogo/barra-fixa-supinada-com-deslocamento-lateral--isAAZWA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-com-deslocamento-lateral--isAAZWA.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Hold a pull-up bar with palms facing down, hands just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:43.993231+00', '2026-10-31 19:43:43.857+00'), ('isofgzg', 'Alongamento de Costas no Rolo', 'roller back stretch', 'alongamento-de-costas-no-rolo', 'https://static.exercisedb.dev/media/isofgzg.gif', 'catalogo/alongamento-de-costas-no-rolo--isofgzg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-costas-no-rolo--isofgzg.gif', ARRAY['costas'], ARRAY['rolo'], ARRAY['eretores da espinha'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Begin by sitting on the ground with your legs extended in front of you.","Step:2 Set the roller perpendicular to your body, just below your glutes.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:43.367691+00', '2026-10-31 19:43:43.237+00'), ('IvV6C9M', 'Rosca Unilateral com Halter Pegada Neutra sobre o Banco', 'Dumbbell Over Bench Single-Arm Neutral Wrist Curl', 'rosca-unilateral-com-halter-pegada-neutra-sobre-o-banco', 'https://static.exercisedb.dev/media/IvV6C9M.gif', 'catalogo/rosca-unilateral-com-halter-pegada-neutra-sobre-o-banco--IvV6C9M.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-unilateral-com-halter-pegada-neutra-sobre-o-banco--IvV6C9M.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Step:2 Keep your upper arm stationary and curl the dumbbell toward your shoulder, keeping your wrist in a neutral position.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:43:43.700136+00', '2026-10-31 19:43:43.566+00'), ('IwX5NqK', 'Rosca Scott Inversa no Cabo', 'cable reverse preacher curl', 'rosca-scott-inversa-no-cabo', 'https://static.exercisedb.dev/media/IwX5NqK.gif', 'catalogo/rosca-scott-inversa-no-cabo--IwX5NqK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-inversa-no-cabo--IwX5NqK.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Set the cable machine so that the preacher curl pad is at chest height.","Step:2 Take a seat on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows straight.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:44.26982+00', '2026-10-31 19:43:44.137+00'), ('iYzB0Cz', 'Agachamento Completo com Barra', 'Barbell Full Squat', 'agachamento-completo-com-barra', 'https://static.exercisedb.dev/media/iYzB0Cz.gif', 'catalogo/agachamento-completo-com-barra--iYzB0Cz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-completo-com-barra--iYzB0Cz.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Stand and set your feet about shoulder width, toes slightly turned out.","Step:2 Rest the bar across the upper back and take a secure grip.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:44.05632+00', '2026-10-31 19:43:43.922+00'), ('izMnLqz', 'Desenvolvimento Lateral Alternado com Halteres', 'dumbbell alternate side press', 'desenvolvimento-lateral-alternado-com-halteres', 'https://static.exercisedb.dev/media/izMnLqz.gif', 'catalogo/desenvolvimento-lateral-alternado-com-halteres--izMnLqz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-lateral-alternado-com-halteres--izMnLqz.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder height.","Step:2 Before moving, press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:44.176007+00', '2026-10-31 19:43:44.045+00'), ('iZop9xO', 'Tríceps Testa com Barra', 'barbell lying triceps extension', 'triceps-testa-com-barra', 'https://static.exercisedb.dev/media/iZop9xO.gif', 'catalogo/triceps-testa-com-barra--iZop9xO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra--iZop9xO.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take hold of the barbell with palms facing down, hands about shoulder width, and extend your arms straight up over your chest.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:44.886308+00', '2026-10-31 19:43:44.757+00'), ('IZVHb27', 'Avanço Caminhando', 'walking lunge', 'avanco-caminhando', 'https://static.exercisedb.dev/media/IZVHb27.gif', 'catalogo/avanco-caminhando--IZVHb27.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-caminhando--IZVHb27.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Step forward with your right leg, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:44.607747+00', '2026-10-31 19:43:44.468+00'), ('J60bN17', 'Mergulho para Tríceps Assistido (Ajoelhado)', 'assisted triceps dip (kneeling)', 'mergulho-para-triceps-assistido-ajoelhado', 'https://static.exercisedb.dev/media/J60bN17.gif', 'catalogo/mergulho-para-triceps-assistido-ajoelhado--J60bN17.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-para-triceps-assistido-ajoelhado--J60bN17.gif', ARRAY['braços'], ARRAY['máquina articulada'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set the machine to your desired weight and height.","Step:2 Get down on the pad facing the machine, with your hands gripping the handles.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:45.078858+00', '2026-10-31 19:43:44.948+00'), ('J6Dx1Mu', 'Supino Fechado com Barra', 'barbell close-grip bench press', 'supino-fechado-com-barra', 'https://static.exercisedb.dev/media/J6Dx1Mu.gif', 'catalogo/supino-fechado-com-barra--J6Dx1Mu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-fechado-com-barra--J6Dx1Mu.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with a close grip, slightly narrower than about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:44.908247+00', '2026-10-31 19:43:44.776+00'), ('j74M6Zn', 'Elevação de Panturrilha com Bola Suíça na Parede (Bola de Tênis entre os Joelhos)', 'exercise ball on the wall calf raise (tennis ball between knees)', 'elevacao-de-panturrilha-com-bola-suica-na-parede-bola-de-tenis-entre-os-joelhos', 'https://static.exercisedb.dev/media/j74M6Zn.gif', 'catalogo/elevacao-de-panturrilha-com-bola-suica-na-parede-bola-de-tenis-entre-os-joelhos--j74M6Zn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-com-bola-suica-na-parede-bola-de-tenis-entre-os-joelhos--j74M6Zn.gif', ARRAY['panturrilhas'], ARRAY['halter','bola suíça'], ARRAY['panturrilhas'], ARRAY['quadríceps','posteriores de coxa'], '["Step:1 Stand and set your back against a wall and place an exercise ball between your lower back and the wall.","Step:2 Set your feet about shoulder width and slightly in front of you.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:45.358772+00', '2026-10-31 19:43:45.227+00'), ('J74XlNf', 'Rosca Direta Alternada com Halteres Sentado na Bola Suíça', 'Dumbbell Alternating Seated Biceps Curl On Exercise Ball', 'rosca-direta-alternada-com-halteres-sentado-na-bola-suica', 'https://static.exercisedb.dev/media/J74XlNf.gif', 'catalogo/rosca-direta-alternada-com-halteres-sentado-na-bola-suica--J74XlNf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-alternada-com-halteres-sentado-na-bola-suica--J74XlNf.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing forward and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:45.334991+00', '2026-10-31 19:43:45.199+00'), ('j7XMAyn', 'Crucifixo no Cabo para Peitoral Superior (Crossover Baixo para Alto)', 'cable upper chest crossovers', 'crucifixo-no-cabo-para-peitoral-superior-crossover-baixo-para-alto', 'https://static.exercisedb.dev/media/j7XMAyn.gif', 'catalogo/crucifixo-no-cabo-para-peitoral-superior-crossover-baixo-para-alto--j7XMAyn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-no-cabo-para-peitoral-superior-crossover-baixo-para-alto--j7XMAyn.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitoral'], ARRAY['deltoides','tríceps'], '["Step:1 Connect the handles to the cables at chest height.","Step:2 Take your place in the center of the cable machine with one foot slightly in front of the other.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:43:45.485516+00', '2026-10-31 19:43:45.348+00'), ('j9Q5crt', 'Caminhada na Máquina Escada (Stepmill)', 'walking on stepmill', 'caminhada-na-maquina-escada-stepmill', 'https://static.exercisedb.dev/media/j9Q5crt.gif', 'catalogo/caminhada-na-maquina-escada-stepmill--j9Q5crt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-na-maquina-escada-stepmill--j9Q5crt.gif', ARRAY['cardio'], ARRAY['máquina escada (stepmill)'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Set the stepmill machine to a comfortable level.","Step:2 Get onto the machine and place your hands on the handrails for support.","Step:3 Stand tall with the load secure and the shoulders level.","Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.","Step:5 Keep steps even and avoid leaning away from the load.","Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk."]', '2026-10-31 19:43:45.578657+00', '2026-10-31 19:43:45.442+00'), ('J9zIWig', 'Avanço Caminhando com Elevação de Joelho', 'walking high knees lunge', 'avanco-caminhando-com-elevacao-de-joelho', 'https://static.exercisedb.dev/media/J9zIWig.gif', 'catalogo/avanco-caminhando-com-elevacao-de-joelho--J9zIWig.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-caminhando-com-elevacao-de-joelho--J9zIWig.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Stand and set your feet about hip width.","Step:2 Lift your right knee up toward your chest as high as you can while balancing on your left leg.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:45.72389+00', '2026-10-31 19:43:45.583+00'), ('JbC2iaV', 'Alongamento da Coluna (Spine Stretch)', 'spine stretch', 'alongamento-da-coluna-spine-stretch', 'https://static.exercisedb.dev/media/JbC2iaV.gif', 'catalogo/alongamento-da-coluna-spine-stretch--JbC2iaV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-da-coluna-spine-stretch--JbC2iaV.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Set your hands on the ground behind you, fingers pointing toward your body.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:45.9735+00', '2026-10-31 19:43:45.83+00'), ('jCrtE9b', 'Arremesso no Chão Unilateral com Medicine Ball (Slam)', 'Single-Arm Slam (With Medicine Ball)', 'arremesso-no-chao-unilateral-com-medicine-ball-slam', 'https://static.exercisedb.dev/media/jCrtE9b.gif', 'catalogo/arremesso-no-chao-unilateral-com-medicine-ball-slam--jCrtE9b.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-no-chao-unilateral-com-medicine-ball-slam--jCrtE9b.gif', ARRAY['abdômen'], ARRAY['medicine ball'], ARRAY['abdominais'], ARRAY['deltoides','costas'], '["Step:1 Stand and set your feet about shoulder width, holding the medicine ball with one hand ahead of your waist.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Return along the same path at a controlled pace; switch sides when the set calls for it."]', '2026-10-31 19:43:46.074347+00', '2026-10-31 19:43:45.945+00'), ('jdiExfW', 'Remada Invertida com Fitas (TRX)', 'inverted row with straps', 'remada-invertida-com-fitas-trx', 'https://static.exercisedb.dev/media/jdiExfW.gif', 'catalogo/remada-invertida-com-fitas-trx--jdiExfW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-invertida-com-fitas-trx--jdiExfW.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Prepare a suspension trainer or straps at chest height.","Step:2 Face the anchor point and grab the handles with palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:46.207261+00', '2026-10-31 19:43:46.072+00'), ('jDnrkar', 'Tríceps Unilateral com Pegada Martelo no Banco Inclinado com Bola Suíça', 'Dumbbell Incline Single-Arm Hammer Press On Exercise Ball', 'triceps-unilateral-com-pegada-martelo-no-banco-inclinado-com-bola-suica', 'https://static.exercisedb.dev/media/jDnrkar.gif', 'catalogo/triceps-unilateral-com-pegada-martelo-no-banco-inclinado-com-bola-suica--jDnrkar.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-unilateral-com-pegada-martelo-no-banco-inclinado-com-bola-suica--jDnrkar.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['tríceps'], ARRAY['deltoides','peitoral'], '["Step:1 Take a seat on an exercise ball with a dumbbell in one hand.","Step:2 Step your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:46.529429+00', '2026-10-31 19:43:46.391+00'), ('jDOKRM5', 'Alongamento Deitado de Lado no Chão', 'Side-Lying Floor Stretch', 'alongamento-deitado-de-lado-no-chao', 'https://static.exercisedb.dev/media/jDOKRM5.gif', 'catalogo/alongamento-deitado-de-lado-no-chao--jDOKRM5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-deitado-de-lado-no-chao--jDOKRM5.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['oblíquos','glúteos'], '["Step:1 Settle onto your side with your legs straight and your bottom arm extended straight overhead.","Step:2 Bend your top knee and place your foot on the ground ahead of your bottom leg.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:46.23067+00', '2026-10-31 19:43:46.1+00'), ('jeHtrlO', 'Arremesso de Medicine Ball no Peito (Repetição Única)', 'medicine ball chest push single response', 'arremesso-de-medicine-ball-no-peito-repeticao-unica', 'https://static.exercisedb.dev/media/jeHtrlO.gif', 'catalogo/arremesso-de-medicine-ball-no-peito-repeticao-unica--jeHtrlO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-de-medicine-ball-no-peito-repeticao-unica--jeHtrlO.gif', ARRAY['peito'], ARRAY['medicine ball'], ARRAY['peitoral'], ARRAY['tríceps','deltoides'], '["Step:1 Stand and set your feet about shoulder width, holding the medicine ball at chest level.","Step:2 Reach your arms forward, pushing the medicine ball away from your chest.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Follow through with the whole body while keeping control of the landing or catch.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:43:46.64608+00', '2026-10-31 19:43:46.512+00'), ('JF8AkMX', 'Arqueiro em Pé', 'standing archer', 'arqueiro-em-pe', 'https://static.exercisedb.dev/media/JF8AkMX.gif', 'catalogo/arqueiro-em-pe--JF8AkMX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arqueiro-em-pe--JF8AkMX.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['deltoides','bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Reach your arms straight out in front of you at shoulder height, parallel to the ground.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:47.349274+00', '2026-10-31 19:43:46.963+00'), ('jFtipLl', 'Agachamento no Smith', 'smith squat', 'agachamento-no-smith', 'https://static.exercisedb.dev/media/jFtipLl.gif', 'catalogo/agachamento-no-smith--jFtipLl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-no-smith--jFtipLl.gif', ARRAY['coxas'], ARRAY['Smith machine'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Prepare the smith machine with the barbell at an appropriate height for your squat.","Step:2 Stand and set your feet about shoulder width, toes slightly turned out.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:46.846618+00', '2026-10-31 19:43:46.703+00'), ('jgbvVJ0', 'Elevação em T com Halteres no Banco Inclinado', 'dumbbell incline t-raise', 'elevacao-em-t-com-halteres-no-banco-inclinado', 'https://static.exercisedb.dev/media/jgbvVJ0.gif', 'catalogo/elevacao-em-t-com-halteres-no-banco-inclinado--jgbvVJ0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-em-t-com-halteres-no-banco-inclinado--jgbvVJ0.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Step:2 Tip forward and let your arms hang straight down, perpendicular to the floor.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Open the arms sideways into a T shape, keeping the torso steady on the bench.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:47.109203+00', '2026-10-31 19:43:46.975+00'), ('JGKowMS', 'Remada com Pegada Fechada no Smith', 'smith narrow row', 'remada-com-pegada-fechada-no-smith', 'https://static.exercisedb.dev/media/JGKowMS.gif', 'catalogo/remada-com-pegada-fechada-no-smith--JGKowMS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-com-pegada-fechada-no-smith--JGKowMS.gif', ARRAY['costas'], ARRAY['Smith machine'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoide posterior'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down, slightly narrower than about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:47.469316+00', '2026-10-31 19:43:47.339+00'), ('jHAnWmT', 'Supino Inclinado na Máquina', 'Machine Incline Chest Press', 'supino-inclinado-na-maquina', 'https://static.exercisedb.dev/media/jHAnWmT.gif', 'catalogo/supino-inclinado-na-maquina--jHAnWmT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-na-maquina--jHAnWmT.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitoral'], ARRAY['deltoides','tríceps'], '["Step:1 Set the seat and backrest of the leverage machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the backrest and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:47.279764+00', '2026-10-31 19:43:47.149+00'), ('JhYSVwT', 'Tríceps Francês com Halter Sentado no Banco', 'dumbbell seated bench extension', 'triceps-frances-com-halter-sentado-no-banco', 'https://static.exercisedb.dev/media/JhYSVwT.gif', 'catalogo/triceps-frances-com-halter-sentado-no-banco--JhYSVwT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-com-halter-sentado-no-banco--JhYSVwT.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell with both hands and extend your arms straight up above your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:47.670598+00', '2026-10-31 19:43:47.309+00'), ('jivWf8n', 'Rosca Scott com Halter', 'dumbbell preacher curl', 'rosca-scott-com-halter', 'https://static.exercisedb.dev/media/jivWf8n.gif', 'catalogo/rosca-scott-com-halter--jivWf8n.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-com-halter--jivWf8n.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Step:2 Take a dumbbell in each hand with your palms facing up and your arms straight.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:47.753187+00', '2026-10-31 19:43:47.617+00'), ('jjUPrze', 'Desenvolvimento Militar em Pé no Smith', 'smith standing military press', 'desenvolvimento-militar-em-pe-no-smith', 'https://static.exercisedb.dev/media/jjUPrze.gif', 'catalogo/desenvolvimento-militar-em-pe-no-smith--jjUPrze.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-em-pe-no-smith--jjUPrze.gif', ARRAY['ombros'], ARRAY['Smith machine'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Hold the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:48.177875+00', '2026-10-31 19:43:48.048+00'), ('jK2hZ6n', 'Rosca Martelo Unilateral com Halter Sentado', 'Dumbbell Single-Arm Seated Hammer Curl', 'rosca-martelo-unilateral-com-halter-sentado', 'https://static.exercisedb.dev/media/jK2hZ6n.gif', 'catalogo/rosca-martelo-unilateral-com-halter-sentado--jK2hZ6n.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-unilateral-com-halter-sentado--jK2hZ6n.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in one hand with a neutral grip (palms facing each other).","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:48.390959+00', '2026-10-31 19:43:48.24+00'), ('jl6uxZV', 'Elevação de Panturrilha com Elástico (Elástico sob Ambos os Pés)', 'Band Two-Leg Calf Raise - (Band Under Both Legs)', 'elevacao-de-panturrilha-com-elastico-elastico-sob-ambos-os-pes', 'https://static.exercisedb.dev/media/jl6uxZV.gif', 'catalogo/elevacao-de-panturrilha-com-elastico-elastico-sob-ambos-os-pes--jl6uxZV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-com-elastico-elastico-sob-ambos-os-pes--jl6uxZV.gif', ARRAY['panturrilhas'], ARRAY['elástico de resistência'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Stand and set your feet about shoulder width and place a resistance band under both feet.","Step:2 Take hold of the ends of the band with your hands for stability.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:48.03787+00', '2026-10-31 19:43:47.908+00'), ('JmMVpR3', 'Flexão de Braço com Pegada Aberta', 'wide hand push up', 'flexao-de-braco-com-pegada-aberta', 'https://static.exercisedb.dev/media/JmMVpR3.gif', 'catalogo/flexao-de-braco-com-pegada-aberta--JmMVpR3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-pegada-aberta--JmMVpR3.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitoral'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands wider than about shoulder width.","Step:2 Hold your body in a straight line from head to toe.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:48.273571+00', '2026-10-31 19:43:48.143+00'), ('jNU1gFQ', 'Flexão de Braço com Chute Lateral da Perna', 'outside leg kick push-up', 'flexao-de-braco-com-chute-lateral-da-perna', 'https://static.exercisedb.dev/media/jNU1gFQ.gif', 'catalogo/flexao-de-braco-com-chute-lateral-da-perna--jNU1gFQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-chute-lateral-da-perna--jNU1gFQ.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.","Step:2 Lower your body toward the ground by bending your elbows, with your spine steady and core engaged.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:48.424095+00', '2026-10-31 19:43:48.287+00'), ('JOZhu2h', 'Remada em pé com rotação no cabo (barra V)', 'cable standing twist row (v-bar)', 'remada-em-pe-com-rotacao-no-cabo-barra-v', 'https://static.exercisedb.dev/media/JOZhu2h.gif', 'catalogo/remada-em-pe-com-rotacao-no-cabo-barra-v--JOZhu2h.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-com-rotacao-no-cabo-barra-v--JOZhu2h.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Connect a v-bar attachment to a cable machine at chest height.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:48.701028+00', '2026-10-31 19:43:48.572+00'), ('jpgqxiS', 'Abdominal em pé no cabo', 'cable standing crunch', 'abdominal-em-pe-no-cabo', 'https://static.exercisedb.dev/media/jpgqxiS.gif', 'catalogo/abdominal-em-pe-no-cabo--jpgqxiS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-em-pe-no-cabo--jpgqxiS.gif', ARRAY['abdômen'], ARRAY['cabo'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Connect a cable handle to a high pulley and stand turned away from the machine.","Step:2 Take hold of the handle with both hands and place it behind your head, keeping your elbows bent.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:49.175848+00', '2026-10-31 19:43:49.045+00'), ('jQGwmxN', 'Levantamento terra com barra hexagonal', 'trap bar deadlift', 'levantamento-terra-com-barra-hexagonal', 'https://static.exercisedb.dev/media/jQGwmxN.gif', 'catalogo/levantamento-terra-com-barra-hexagonal--jQGwmxN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-com-barra-hexagonal--jQGwmxN.gif', ARRAY['coxas'], ARRAY['barra hexagonal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and the trap bar on the ground in front of you.","Step:2 Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with palms facing down.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:49.25281+00', '2026-10-31 19:43:49.117+00'), ('JrOHAZc', 'Good morning com barra e pernas estendidas (stiff)', 'barbell stiff leg good morning', 'good-morning-com-barra-e-pernas-estendidas-stiff', 'https://static.exercisedb.dev/media/JrOHAZc.gif', 'catalogo/good-morning-com-barra-e-pernas-estendidas-stiff--JrOHAZc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/good-morning-com-barra-e-pernas-estendidas-stiff--JrOHAZc.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Take hold of the barbell across your upper back, resting it on your traps.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:49.171506+00', '2026-10-31 19:43:49.037+00'), ('Jsgsc27', 'Remada curvada unilateral com barra', 'Barbell Single-Arm Bent Over Row', 'remada-curvada-unilateral-com-barra', 'https://static.exercisedb.dev/media/Jsgsc27.gif', 'catalogo/remada-curvada-unilateral-com-barra--Jsgsc27.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-unilateral-com-barra--Jsgsc27.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a barbell with one hand using an overhand grip.","Step:2 Bend forward at the hips, with your spine steady and your head in a neutral position.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:49.290509+00', '2026-10-31 19:43:49.146+00'), ('JsKq9so', 'Supino reto com barra pegada aberta', 'barbell wide bench press', 'supino-reto-com-barra-pegada-aberta', 'https://static.exercisedb.dev/media/JsKq9so.gif', 'catalogo/supino-reto-com-barra-pegada-aberta--JsKq9so.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-reto-com-barra-pegada-aberta--JsKq9so.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with a wide grip, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:49.654301+00', '2026-10-31 19:43:49.518+00'), ('JsOV1SU', 'Muscle up com peso', 'weighted muscle up', 'muscle-up-com-peso', 'https://static.exercisedb.dev/media/JsOV1SU.gif', 'catalogo/muscle-up-com-peso--JsOV1SU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/muscle-up-com-peso--JsOV1SU.gif', ARRAY['costas'], ARRAY['peso adicional'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','tríceps','deltoides','peitorais'], '["Step:1 Begin by hanging from a pull-up bar with your palms turned away from you and your hands just beyond shoulder width.","Step:2 Brace your trunk and pull your body up toward the bar, leading with your chest.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:49.680988+00', '2026-10-31 19:43:49.545+00'), ('jtFKbt5', 'Rosca sentado com barra W', 'EZ-Bar Seated Curls', 'rosca-sentado-com-barra-w', 'https://static.exercisedb.dev/media/jtFKbt5.gif', 'catalogo/rosca-sentado-com-barra-w--jtFKbt5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-sentado-com-barra-w--jtFKbt5.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; your back straight.","Step:2 Take hold of the ez barbell with palms facing up, and your hands about shoulder width.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:50.132415+00', '2026-10-31 19:43:49.996+00'), ('jTkSc6o', 'Elevação lateral de quadril nas barras paralelas', 'side hip (on parallel bars)', 'elevacao-lateral-de-quadril-nas-barras-paralelas', 'https://static.exercisedb.dev/media/jTkSc6o.gif', 'catalogo/elevacao-lateral-de-quadril-nas-barras-paralelas--jTkSc6o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-de-quadril-nas-barras-paralelas--jTkSc6o.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Stand between two parallel bars with your feet about shoulder width.","Step:2 Set your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:43:49.824725+00', '2026-10-31 19:43:49.695+00'), ('jV65tKx', 'Flexão escapular', 'scapula push-up', 'flexao-escapular', 'https://static.exercisedb.dev/media/jV65tKx.gif', 'catalogo/flexao-escapular--jV65tKx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-escapular--jV65tKx.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['serrátil anterior'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your chest toward the ground, keeping your elbows close to your body.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:50.134361+00', '2026-10-31 19:43:49.977+00'), ('jvp6DiD', 'Abdominal cotovelo ao joelho', 'elbow-to-knee', 'abdominal-cotovelo-ao-joelho', 'https://static.exercisedb.dev/media/jvp6DiD.gif', 'catalogo/abdominal-cotovelo-ao-joelho--jvp6DiD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-cotovelo-ao-joelho--jvp6DiD.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Begin by lying flat on your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:50.256047+00', '2026-10-31 19:43:50.125+00'), ('JWjujiY', 'Rosca unilateral com halter deitado de bruços no banco', 'Dumbbell Single-Arm Prone Curl', 'rosca-unilateral-com-halter-deitado-de-brucos-no-banco', 'https://static.exercisedb.dev/media/JWjujiY.gif', 'catalogo/rosca-unilateral-com-halter-deitado-de-brucos-no-banco--JWjujiY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-unilateral-com-halter-deitado-de-brucos-no-banco--JWjujiY.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Position yourself face down on a flat bench with a dumbbell in one hand, palm facing down.","Step:2 Extend your arm fully, letting it hang straight down toward the floor.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:50.452141+00', '2026-10-31 19:43:50.313+00'), ('JymLInS', 'Encolhimento inclinado com halteres', 'dumbbell incline shrug', 'encolhimento-inclinado-com-halteres', 'https://static.exercisedb.dev/media/JymLInS.gif', 'catalogo/encolhimento-inclinado-com-halteres--JymLInS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-inclinado-com-halteres--JymLInS.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Step:2 Set your feet planted and let your arms hang straight down with your palms facing your body.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:50.691444+00', '2026-10-31 19:43:50.558+00'), ('JzQbv7J', 'Elevação lateral sentado com cotovelos flexionados e halteres', 'dumbbell seated bent arm lateral raise', 'elevacao-lateral-sentado-com-cotovelos-flexionados-e-halteres', 'https://static.exercisedb.dev/media/JzQbv7J.gif', 'catalogo/elevacao-lateral-sentado-com-cotovelos-flexionados-e-halteres--JzQbv7J.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-sentado-com-cotovelos-flexionados-e-halteres--JzQbv7J.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:50.758878+00', '2026-10-31 19:43:50.624+00'), ('JZuApnB', 'Agachamento com peso adicional', 'weighted squat', 'agachamento-com-peso-adicional', 'https://static.exercisedb.dev/media/JZuApnB.gif', 'catalogo/agachamento-com-peso-adicional--JZuApnB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-peso-adicional--JZuApnB.gif', ARRAY['coxas'], ARRAY['peso adicional'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, toes pointing slightly outward.","Step:2 Take a weight ahead of your chest or on your shoulders.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:43:50.796275+00', '2026-10-31 19:43:50.664+00'), ('K1vlode', 'Mergulho de tríceps com peso nas paralelas altas', 'weighted triceps dip on high parallel bars', 'mergulho-de-triceps-com-peso-nas-paralelas-altas', 'https://static.exercisedb.dev/media/K1vlode.gif', 'catalogo/mergulho-de-triceps-com-peso-nas-paralelas-altas--K1vlode.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-de-triceps-com-peso-nas-paralelas-altas--K1vlode.gif', ARRAY['braços'], ARRAY['peso adicional'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set yourself between two parallel bars with your hands gripping the bars and your arms straight.","Step:2 Before moving, bend your elbows and lower your body until your upper arms are parallel to the ground.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:50.850295+00', '2026-10-31 19:43:50.721+00'), ('K3dIO25', 'Supino unilateral com halter', 'Dumbbell Lying Single-Arm Press', 'supino-unilateral-com-halter', 'https://static.exercisedb.dev/media/K3dIO25.gif', 'catalogo/supino-unilateral-com-halter--K3dIO25.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-com-halter--K3dIO25.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with your back supported and feet planted.","Step:2 Take a dumbbell in one hand with your palm facing toward your feet.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:51.35434+00', '2026-10-31 19:43:51.226+00'), ('k5IpyHg', 'Rosca concentrada unilateral com halter na bola suíça', 'Dumbbell Single-Arm Concentration Curl (On Stability Ball)', 'rosca-concentrada-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/k5IpyHg.gif', 'catalogo/rosca-concentrada-unilateral-com-halter-na-bola-suica--k5IpyHg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-unilateral-com-halter-na-bola-suica--k5IpyHg.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a dumbbell in one hand with your palm facing up and your arm extended down toward the floor.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:51.328738+00', '2026-10-31 19:43:51.176+00'), ('K5xgdvI', 'Alongamento deitado do dedão do pé com corda', 'reclining big toe pose with rope', 'alongamento-deitado-do-dedao-do-pe-com-corda', 'https://static.exercisedb.dev/media/K5xgdvI.gif', 'catalogo/alongamento-deitado-do-dedao-do-pe-com-corda--K5xgdvI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-deitado-do-dedao-do-pe-com-corda--K5xgdvI.gif', ARRAY['coxas'], ARRAY['corda'], ARRAY['posteriores de coxa'], ARRAY['panturrilhas','glúteos'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Thread the rope around the ball of your right foot and hold the ends of the rope with your hands.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:43:51.669665+00', '2026-10-31 19:43:51.535+00'), ('k6tUeqS', 'Puxada com pegada supinada no elástico', 'band underhand pulldown', 'puxada-com-pegada-supinada-no-elastico', 'https://static.exercisedb.dev/media/k6tUeqS.gif', 'catalogo/puxada-com-pegada-supinada-no-elastico--k6tUeqS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-com-pegada-supinada-no-elastico--k6tUeqS.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Connect the band to a high anchor point, such as a pull-up bar or sturdy beam.","Step:2 Face the anchor point from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:51.296959+00', '2026-10-31 19:43:51.166+00'), ('K9VL0Jq', 'Avanço com rotação de tronco', 'lunge with twist', 'avanco-com-rotacao-de-tronco', 'https://static.exercisedb.dev/media/K9VL0Jq.gif', 'catalogo/avanco-com-rotacao-de-tronco--K9VL0Jq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-rotacao-de-tronco--K9VL0Jq.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['quadríceps','glúteos','posteriores de coxa'], '["Step:1 Begin by standing with your feet about shoulder width.","Step:2 Step forward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:51.421803+00', '2026-10-31 19:43:51.294+00'), ('Kal9cQQ', 'Windmill avançado com kettlebell', 'kettlebell advanced windmill', 'windmill-avancado-com-kettlebell', 'https://static.exercisedb.dev/media/Kal9cQQ.gif', 'catalogo/windmill-avancado-com-kettlebell--Kal9cQQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/windmill-avancado-com-kettlebell--Kal9cQQ.gif', ARRAY['abdômen'], ARRAY['kettlebell'], ARRAY['abdominais'], ARRAY['oblíquos','deltoides'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointing slightly outward.","Step:2 Take a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:51.928122+00', '2026-10-31 19:43:51.796+00'), ('KCBKjma', 'Abdominal canivete com elástico', 'band jack knife sit-up', 'abdominal-canivete-com-elastico', 'https://static.exercisedb.dev/media/KCBKjma.gif', 'catalogo/abdominal-canivete-com-elastico--KCBKjma.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-canivete-com-elastico--KCBKjma.gif', ARRAY['abdômen'], ARRAY['elástico'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Tighten your midsection and lift your legs and upper body simultaneously, bringing your hands toward your feet.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:51.806552+00', '2026-10-31 19:43:51.678+00'), ('kesXOpB', 'Remada sentada na polia com pegada aberta em declive', 'cable decline seated wide-grip row', 'remada-sentada-na-polia-com-pegada-aberta-em-declive', 'https://static.exercisedb.dev/media/kesXOpB.gif', 'catalogo/remada-sentada-na-polia-com-pegada-aberta-em-declive--kesXOpB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-na-polia-com-pegada-aberta-em-declive--kesXOpB.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the decline bench facing the cable machine with your feet securely placed on the footrests.","Step:2 Hold the cable attachment with a wide overhand grip, palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:43:52.552326+00', '2026-10-31 19:43:52.416+00'), ('KgI0tqW', 'Levantamento terra sumô com barra', 'barbell sumo deadlift', 'levantamento-terra-sumo-com-barra', 'https://static.exercisedb.dev/media/KgI0tqW.gif', 'catalogo/levantamento-terra-sumo-com-barra--KgI0tqW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-sumo-com-barra--KgI0tqW.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','eretores da espinha'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointing outwards.","Step:2 Set a barbell on the ground in front of you, centered between your feet.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:52.659685+00', '2026-10-31 19:43:52.531+00'), ('KHGNa16', 'Supino declinado unilateral na polia', 'Cable Decline Single-Arm Press', 'supino-declinado-unilateral-na-polia', 'https://static.exercisedb.dev/media/KHGNa16.gif', 'catalogo/supino-declinado-unilateral-na-polia--KHGNa16.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-unilateral-na-polia--KHGNa16.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the cable machine to a decline position.","Step:2 Face away from the machine and grab the handle with one hand.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:52.304378+00', '2026-10-31 19:43:52.163+00'), ('KhHJ338', 'Flexão de braço com transição para prancha lateral', 'push-up to side plank', 'flexao-de-braco-com-transicao-para-prancha-lateral', 'https://static.exercisedb.dev/media/KhHJ338.gif', 'catalogo/flexao-de-braco-com-transicao-para-prancha-lateral--KhHJ338.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-transicao-para-prancha-lateral--KhHJ338.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','peitorais','tríceps'], '["Step:1 Begin in a push-up position with your hands about shoulder width and your body in a straight line.","Step:2 Lower your body toward the ground by bending your elbows, keeping your core engaged.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:43:52.500566+00', '2026-10-31 19:43:52.359+00'), ('khlHMqs', 'Supino reto com elástico', 'band bench press', 'supino-reto-com-elastico', 'https://static.exercisedb.dev/media/khlHMqs.gif', 'catalogo/supino-reto-com-elastico--khlHMqs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-reto-com-elastico--khlHMqs.gif', ARRAY['peito'], ARRAY['elástico'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the band handles with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:52.811632+00', '2026-10-31 19:43:52.675+00'), ('KHPZL0b', 'Desenvolvimento alternado na polia', 'cable alternate shoulder press', 'desenvolvimento-alternado-na-polia', 'https://static.exercisedb.dev/media/KHPZL0b.gif', 'catalogo/desenvolvimento-alternado-na-polia--KHPZL0b.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-alternado-na-polia--KHPZL0b.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and Hold the handles of the cable machine with palms facing down.","Step:2 Set your hands at shoulder height, with your palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:52.867448+00', '2026-10-31 19:43:52.736+00'), ('KI1DjNN', 'Rosca de punho unilateral com halter apoiado no banco', 'Dumbbell Over Bench Single-Arm Wrist Curl', 'rosca-de-punho-unilateral-com-halter-apoiado-no-banco', 'https://static.exercisedb.dev/media/KI1DjNN.gif', 'catalogo/rosca-de-punho-unilateral-com-halter-apoiado-no-banco--KI1DjNN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-unilateral-com-halter-apoiado-no-banco--KI1DjNN.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['bíceps','deltoides'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing down.","Step:2 Set your forearm on the bench with your wrist hanging off the edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:43:53.46288+00', '2026-10-31 19:43:53.313+00'), ('kiJ4Z2K', 'Barra fixa assistida', 'assisted pull-up', 'barra-fixa-assistida', 'https://static.exercisedb.dev/media/kiJ4Z2K.gif', 'catalogo/barra-fixa-assistida--kiJ4Z2K.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-assistida--kiJ4Z2K.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Set the machine to your desired weight and height settings.","Step:2 Hold the handles with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:53.498453+00', '2026-10-31 19:43:53.365+00'), ('kj3hy6W', 'Rosca Scott com pegada invertida na máquina', 'Machine Reverse-Grip Preacher Curl', 'rosca-scott-com-pegada-invertida-na-maquina', 'https://static.exercisedb.dev/media/kj3hy6W.gif', 'catalogo/rosca-scott-com-pegada-invertida-na-maquina--kj3hy6W.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-com-pegada-invertida-na-maquina--kj3hy6W.gif', ARRAY['braços'], ARRAY['máquina articulada'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing up.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:53.427627+00', '2026-10-31 19:43:53.287+00'), ('kjE55n5', 'Bent press com kettlebell', 'kettlebell bent press', 'bent-press-com-kettlebell', 'https://static.exercisedb.dev/media/kjE55n5.gif', 'catalogo/bent-press-com-kettlebell--kjE55n5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/bent-press-com-kettlebell--kjE55n5.gif', ARRAY['abdômen'], ARRAY['kettlebell'], ARRAY['abdominais'], ARRAY['deltoides','tríceps','oblíquos'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in your right hand.","Step:2 Before moving, bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:53.979713+00', '2026-10-31 19:43:53.844+00'), ('kjJ3VoQ', 'Abdominal crunch com braços estendidos acima da cabeça', 'crunch (hands overhead)', 'abdominal-crunch-com-bracos-estendidos-acima-da-cabeca', 'https://static.exercisedb.dev/media/kjJ3VoQ.gif', 'catalogo/abdominal-crunch-com-bracos-estendidos-acima-da-cabeca--kjJ3VoQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-crunch-com-bracos-estendidos-acima-da-cabeca--kjJ3VoQ.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Reach your arms straight above your head.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:53.910764+00', '2026-10-31 19:43:53.775+00'), ('km0sQC0', 'Remada baixa unilateral em pé com elástico', 'Band Single-Arm Standing Low Row', 'remada-baixa-unilateral-em-pe-com-elastico', 'https://static.exercisedb.dev/media/km0sQC0.gif', 'catalogo/remada-baixa-unilateral-em-pe-com-elastico--km0sQC0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-baixa-unilateral-em-pe-com-elastico--km0sQC0.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Connect the band to a stable anchor point at waist height.","Step:2 Face the anchor point from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:43:54.54704+00', '2026-10-31 19:43:54.393+00'), ('km2Ljzj', 'Corrida na roda', 'wheel run', 'corrida-na-roda', 'https://static.exercisedb.dev/media/km2Ljzj.gif', 'catalogo/corrida-na-roda--km2Ljzj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-na-roda--km2Ljzj.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin in a plank position with your hands on the wheel and your body straight.","Step:2 Brace your trunk and start rolling the wheel forward by extending your arms.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:43:54.869493+00', '2026-10-31 19:43:54.731+00'), ('kmVVAfu', 'Rosca concentrada com elástico', 'band concentration curl', 'rosca-concentrada-com-elastico', 'https://static.exercisedb.dev/media/kmVVAfu.gif', 'catalogo/rosca-concentrada-com-elastico--kmVVAfu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-com-elastico--kmVVAfu.gif', ARRAY['braços'], ARRAY['elástico'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench or chair with your legs spread apart and your feet planted.","Step:2 Keep one end of the band in your hand and step on the other end with your foot on the same side.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:54.332294+00', '2026-10-31 19:43:54.172+00'), ('kMzUs9Y', 'Avanço frontal', 'Forward Lunge', 'avanco-frontal', 'https://static.exercisedb.dev/media/kMzUs9Y.gif', 'catalogo/avanco-frontal--kMzUs9Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-frontal--kMzUs9Y.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about hip width and hands on your hips.","Step:2 Step wide forward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:54.810266+00', '2026-10-31 19:43:54.676+00'), ('kont8Ut', 'Tríceps francês sentado com halter', 'dumbbell seated triceps extension', 'triceps-frances-sentado-com-halter', 'https://static.exercisedb.dev/media/kont8Ut.gif', 'catalogo/triceps-frances-sentado-com-halter--kont8Ut.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-sentado-com-halter--kont8Ut.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell with both hands and extend your arms straight up overhead.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:54.53328+00', '2026-10-31 19:43:54.392+00'), ('KOpzGBL', 'Rosca bíceps com halter na posição garçom', 'dumbbell waiter biceps curl', 'rosca-biceps-com-halter-na-posicao-garcom', 'https://static.exercisedb.dev/media/KOpzGBL.gif', 'catalogo/rosca-biceps-com-halter-na-posicao-garcom--KOpzGBL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-com-halter-na-posicao-garcom--KOpzGBL.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward.","Step:2 Keep the upper arms close to your body and your elbows tucked in.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:54.929095+00', '2026-10-31 19:43:54.792+00'), ('Kpajagk', 'Extensão de quadril em pé na polia', 'cable standing hip extension', 'extensao-de-quadril-em-pe-na-polia', 'https://static.exercisedb.dev/media/Kpajagk.gif', 'catalogo/extensao-de-quadril-em-pe-na-polia--Kpajagk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-quadril-em-pe-na-polia--Kpajagk.gif', ARRAY['coxas'], ARRAY['polia'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Connect a cable to a low pulley and stand turned away from the machine.","Step:2 Set the cable around your ankle and stand with your feet about shoulder width.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:43:55.117382+00', '2026-10-31 19:43:54.976+00'), ('kprile3', 'Mergulho na bola suíça', 'exercise ball dip', 'mergulho-na-bola-suica', 'https://static.exercisedb.dev/media/kprile3.gif', 'catalogo/mergulho-na-bola-suica--kprile3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-na-bola-suica--kprile3.gif', ARRAY['braços'], ARRAY['bola suíça'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Set your hands on the ball beside your hips, fingers pointing forward.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:43:55.131995+00', '2026-10-31 19:43:54.998+00'), ('Krmb3cB', 'Extensão reversa de quadril na máquina', 'Machine Reverse Hyperextension', 'extensao-reversa-de-quadril-na-maquina', 'https://static.exercisedb.dev/media/Krmb3cB.gif', 'catalogo/extensao-reversa-de-quadril-na-maquina--Krmb3cB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-reversa-de-quadril-na-maquina--Krmb3cB.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Set the leverage machine to fit your body and secure your feet in the foot pads.","Step:2 Position yourself face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Finish in a straight body line, before the lower back overarches.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:43:55.488495+00', '2026-10-31 19:43:55.356+00'), ('kTbSH9h', 'Desenvolvimento sentado com barra', 'barbell seated overhead press', 'desenvolvimento-sentado-com-barra', 'https://static.exercisedb.dev/media/kTbSH9h.gif', 'catalogo/desenvolvimento-sentado-com-barra--kTbSH9h.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-com-barra--kTbSH9h.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take hold of the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:55.846684+00', '2026-10-31 19:43:55.716+00'), ('ktf3nvW', 'Flexão pliométrica com kettlebell', 'kettlebell plyo push-up', 'flexao-pliometrica-com-kettlebell', 'https://static.exercisedb.dev/media/ktf3nvW.gif', 'catalogo/flexao-pliometrica-com-kettlebell--ktf3nvW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-pliometrica-com-kettlebell--ktf3nvW.gif', ARRAY['peito'], ARRAY['kettlebell'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a high plank position with your hands on the kettlebells, about shoulder width.","Step:2 Lower your chest toward the ground, keeping your elbows close to your body.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:55.637595+00', '2026-10-31 19:43:55.506+00'), ('KtRomty', 'Rollout em pé com roda abdominal', 'Standing Wheel Rollout', 'rollout-em-pe-com-roda-abdominal', 'https://static.exercisedb.dev/media/KtRomty.gif', 'catalogo/rollout-em-pe-com-roda-abdominal--KtRomty.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rollout-em-pe-com-roda-abdominal--KtRomty.gif', ARRAY['abdômen'], ARRAY['roda abdominal'], ARRAY['abdominais'], ARRAY['eretores da espinha','deltoides'], '["Step:1 Begin by standing tall with your feet about shoulder width and the wheel roller in front of you.","Step:2 Bend at your waist and With control roll the wheel forward, with your spine steady and your core engaged.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:43:55.652774+00', '2026-10-31 19:43:55.517+00'), ('ktsFQAZ', 'Panturrilha sentado com barra', 'barbell seated calf raise', 'panturrilha-sentado-com-barra', 'https://static.exercisedb.dev/media/ktsFQAZ.gif', 'catalogo/panturrilha-sentado-com-barra--ktsFQAZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-com-barra--ktsFQAZ.gif', ARRAY['panturrilhas'], ARRAY['barra'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Plant both feet while seated on a bench; a barbell resting on your thighs.","Step:2 Set the balls of your feet on a raised platform, such as a block or step.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:43:55.733845+00', '2026-10-31 19:43:55.603+00'), ('KUaoUV8', 'Levantamento terra com pernas estendidas com elástico', 'Band Straight-Leg Deadlift', 'levantamento-terra-com-pernas-estendidas-com-elastico', 'https://static.exercisedb.dev/media/KUaoUV8.gif', 'catalogo/levantamento-terra-com-pernas-estendidas-com-elastico--KUaoUV8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-com-pernas-estendidas-com-elastico--KUaoUV8.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['eretores da espinha'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width and place the band around your feet.","Step:2 Take hold of the band with both hands, palms facing your body, and keep your arms straight.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:56.08117+00', '2026-10-31 19:43:55.941+00'), ('KUaZst7', 'Rosca deitada supinada com halteres', 'dumbbell lying supine curl', 'rosca-deitada-supinada-com-halteres', 'https://static.exercisedb.dev/media/KUaZst7.gif', 'catalogo/rosca-deitada-supinada-com-halteres--KUaZst7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-deitada-supinada-com-halteres--KUaZst7.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing up and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:56.498624+00', '2026-10-31 19:43:56.107+00'), ('kuMiR2T', 'Stiff com elástico', 'band stiff leg deadlift', 'stiff-com-elastico', 'https://static.exercisedb.dev/media/kuMiR2T.gif', 'catalogo/stiff-com-elastico--kuMiR2T.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stiff-com-elastico--kuMiR2T.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and place the band around your ankles.","Step:2 Take hold of the band with both hands ahead of your thighs, palms facing your body.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:43:56.236482+00', '2026-10-31 19:43:56.103+00'), ('kuXhl0o', 'Desenvolvimento unilateral com kettlebell', 'Single-Arm Kettlebell Overhead Press', 'desenvolvimento-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/kuXhl0o.gif', 'catalogo/desenvolvimento-unilateral-com-kettlebell--kuXhl0o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-unilateral-com-kettlebell--kuXhl0o.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Bring the kettlebell to the rack position, then press it overhead with the wrist stacked above the shoulder.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:43:56.282879+00', '2026-10-31 19:43:56.14+00'), ('KWdF2JI', 'Tríceps ajoelhado na polia', 'cable kneeling triceps extension', 'triceps-ajoelhado-na-polia', 'https://static.exercisedb.dev/media/KWdF2JI.gif', 'catalogo/triceps-ajoelhado-na-polia--KWdF2JI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-ajoelhado-na-polia--KWdF2JI.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Connect a rope handle to a high pulley and kneel down facing the cable machine.","Step:2 Hold the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:56.445443+00', '2026-10-31 19:43:56.314+00'), ('KwFGiEP', 'Elevação lateral posterior unilateral deitado com halter', 'Dumbbell Lying Single-Arm Rear Lateral Raise', 'elevacao-lateral-posterior-unilateral-deitado-com-halter', 'https://static.exercisedb.dev/media/KwFGiEP.gif', 'catalogo/elevacao-lateral-posterior-unilateral-deitado-com-halter--KwFGiEP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-posterior-unilateral-deitado-com-halter--KwFGiEP.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Position yourself face down on a flat bench with a dumbbell in one hand, hanging toward the floor.","Step:2 Keep the arm straight and lift the dumbbell out to the side, away from your body.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:43:56.994405+00', '2026-10-31 19:43:56.862+00'), ('kXaIn5A', 'Rosca Zottman com halteres', 'dumbbell zottman curl', 'rosca-zottman-com-halteres', 'https://static.exercisedb.dev/media/kXaIn5A.gif', 'catalogo/rosca-zottman-com-halteres--kXaIn5A.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-zottman-com-halteres--kXaIn5A.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your body.","Step:2 Hold your elbows near your torso and rotate your palms to face forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl palms-up, turn the palms down at the top, and lower with that overhand grip.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:56.979854+00', '2026-10-31 19:43:56.841+00'), ('Kxquu2E', 'Step-up com barra', 'barbell step-up', 'step-up-com-barra', 'https://static.exercisedb.dev/media/Kxquu2E.gif', 'catalogo/step-up-com-barra--Kxquu2E.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/step-up-com-barra--Kxquu2E.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Take your place in front of a bench or step with a barbell resting on your upper back.","Step:2 Set one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step:3 Put the lead foot fully on the platform before shifting your weight onto it.","Step:4 Step onto the platform and drive through the lead foot to stand tall on it.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:43:57.070702+00', '2026-10-31 19:43:56.932+00'), ('KXyoEtA', 'Rosca sentado com halteres com foco na parte interna do bíceps', 'dumbbell seated inner biceps curl', 'rosca-sentado-com-halteres-com-foco-na-parte-interna-do-biceps', 'https://static.exercisedb.dev/media/KXyoEtA.gif', 'catalogo/rosca-sentado-com-halteres-com-foco-na-parte-interna-do-biceps--KXyoEtA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-sentado-com-halteres-com-foco-na-parte-interna-do-biceps--KXyoEtA.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.","Step:2 Set your upper arms on your thighs, letting the dumbbells to hang down.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:57.206604+00', '2026-10-31 19:43:57.072+00'), ('ky8FLU8', 'Puxada na máquina com pegada supinada', 'Machine Reverse-Grip Lateral Pulldown', 'puxada-na-maquina-com-pegada-supinada', 'https://static.exercisedb.dev/media/ky8FLU8.gif', 'catalogo/puxada-na-maquina-com-pegada-supinada--ky8FLU8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-na-maquina-com-pegada-supinada--ky8FLU8.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down, just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:43:57.898446+00', '2026-10-31 19:43:57.767+00'), ('Kyd9Rz5', 'Desenvolvimento militar em pé com pegada aberta com barra', 'barbell standing wide military press', 'desenvolvimento-militar-em-pe-com-pegada-aberta-com-barra', 'https://static.exercisedb.dev/media/Kyd9Rz5.gif', 'catalogo/desenvolvimento-militar-em-pe-com-pegada-aberta-com-barra--Kyd9Rz5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-em-pe-com-pegada-aberta-com-barra--Kyd9Rz5.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold the barbell with palms facing down, slightly wider than shoulder-width.","Step:2 Before moving, lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:43:57.566976+00', '2026-10-31 19:43:57.425+00'), ('KyLtiLT', 'Tríceps testa inclinado com barra W', 'EZ-Bar Incline Triceps Extension', 'triceps-testa-inclinado-com-barra-w', 'https://static.exercisedb.dev/media/KyLtiLT.gif', 'catalogo/triceps-testa-inclinado-com-barra-w--KyLtiLT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-inclinado-com-barra-w--KyLtiLT.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your back against the pad and hold the ez barbell with palms facing down.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:57.967138+00', '2026-10-31 19:43:57.834+00'), ('Kzg30R7', 'Abdominal em pé com elástico', 'band standing crunch', 'abdominal-em-pe-com-elastico', 'https://static.exercisedb.dev/media/Kzg30R7.gif', 'catalogo/abdominal-em-pe-com-elastico--Kzg30R7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-em-pe-com-elastico--Kzg30R7.gif', ARRAY['abdômen'], ARRAY['elástico'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Connect the band to a sturdy anchor point at waist height.","Step:2 Face the away from the anchor point from a stable stance with feet about shoulder width.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:57.712487+00', '2026-10-31 19:43:57.578+00'), ('KZn52RC', 'Abdominal com pernas flexionadas e braços estendidos', 'flexion leg sit up (straight arm)', 'abdominal-com-pernas-flexionadas-e-bracos-estendidos', 'https://static.exercisedb.dev/media/KZn52RC.gif', 'catalogo/abdominal-com-pernas-flexionadas-e-bracos-estendidos--KZn52RC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-pernas-flexionadas-e-bracos-estendidos--KZn52RC.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','quadríceps'], '["Step:1 Settle onto your back with your legs extended and arms straight above your head.","Step:2 Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs toward your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:43:57.69489+00', '2026-10-31 19:43:57.563+00'), ('KZXAtKQ', 'Flexão fechada apoiada em halteres', 'push-up close-grip off dumbbell', 'flexao-fechada-apoiada-em-halteres', 'https://static.exercisedb.dev/media/KZXAtKQ.gif', 'catalogo/flexao-fechada-apoiada-em-halteres--KZXAtKQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-fechada-apoiada-em-halteres--KZXAtKQ.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Begin in a push-up position with your hands placed close together, directly under your shoulders.","Step:2 Take a dumbbell in each hand, resting them on the ground.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:58.34532+00', '2026-10-31 19:43:58.208+00'), ('L2V5Nan', 'Tríceps deitado com halter cruzando o rosto', 'dumbbell lying extension (across face)', 'triceps-deitado-com-halter-cruzando-o-rosto', 'https://static.exercisedb.dev/media/L2V5Nan.gif', 'catalogo/triceps-deitado-com-halter-cruzando-o-rosto--L2V5Nan.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-deitado-com-halter-cruzando-o-rosto--L2V5Nan.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:43:58.649858+00', '2026-10-31 19:43:58.507+00'), ('L4ay0PW', 'Oito com kettlebell', 'kettlebell figure 8', 'oito-com-kettlebell', 'https://static.exercisedb.dev/media/L4ay0PW.gif', 'catalogo/oito-com-kettlebell--L4ay0PW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/oito-com-kettlebell--L4ay0PW.gif', ARRAY['abdômen'], ARRAY['kettlebell'], ARRAY['abdominais'], ARRAY['deltoides','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:43:58.651013+00', '2026-10-31 19:43:58.521+00'), ('laVRfDf', 'Elevação frontal em pé com halteres acima da cabeça', 'dumbbell standing front raise above head', 'elevacao-frontal-em-pe-com-halteres-acima-da-cabeca', 'https://static.exercisedb.dev/media/laVRfDf.gif', 'catalogo/elevacao-frontal-em-pe-com-halteres-acima-da-cabeca--laVRfDf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-em-pe-com-halteres-acima-da-cabeca--laVRfDf.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 Maintain straight arms and lift the dumbbells in front of you, raising them above your head.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:43:58.69259+00', '2026-10-31 19:43:58.551+00'), ('lBDjFxJ', 'Barra fixa', 'pull-up', 'barra-fixa', 'https://static.exercisedb.dev/media/lBDjFxJ.gif', 'catalogo/barra-fixa--lBDjFxJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa--lBDjFxJ.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Suspend yourself from a pull-up bar with your palms turned away from you and your arms straight.","Step:2 Brace your trunk and draw your shoulder blades toward each other.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:43:59.156892+00', '2026-10-31 19:43:59.017+00'), ('lCKm4Rs', 'Elevação de perna unilateral na bola suíça (lombar)', 'Exercise Ball Prsingle-Leg Raise', 'elevacao-de-perna-unilateral-na-bola-suica-lombar', 'https://static.exercisedb.dev/media/lCKm4Rs.gif', 'catalogo/elevacao-de-perna-unilateral-na-bola-suica-lombar--lCKm4Rs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-perna-unilateral-na-bola-suica-lombar--lCKm4Rs.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['eretores da espinha'], ARRAY['abdômen','glúteos'], '["Step:1 Position yourself face down on a mat with your legs extended and your toes resting on top of the stability ball.","Step:2 Set your hands on the ground, about shoulder width, and Brace your trunk muscles.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the legs slowly without swinging or losing your trunk position; switch sides when the set calls for it."]', '2026-10-31 19:43:59.304141+00', '2026-10-31 19:43:59.17+00'), ('LCtQPn8', 'Rosca bíceps inclinada com pegada interna com halteres', 'dumbbell incline inner biceps curl', 'rosca-biceps-inclinada-com-pegada-interna-com-halteres', 'https://static.exercisedb.dev/media/LCtQPn8.gif', 'catalogo/rosca-biceps-inclinada-com-pegada-interna-com-halteres--LCtQPn8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-inclinada-com-pegada-interna-com-halteres--LCtQPn8.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, palms facing each other.","Step:2 Set your upper arms on the bench, letting your elbows to hang down and your palms to face forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:43:59.33025+00', '2026-10-31 19:43:59.194+00'), ('LeaZOIz', 'Rosca martelo alternada em pé com desenvolvimento com halteres', 'dumbbell standing alternate hammer curl and press', 'rosca-martelo-alternada-em-pe-com-desenvolvimento-com-halteres', 'https://static.exercisedb.dev/media/LeaZOIz.gif', 'catalogo/rosca-martelo-alternada-em-pe-com-desenvolvimento-com-halteres--LeaZOIz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-alternada-em-pe-com-desenvolvimento-com-halteres--LeaZOIz.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your body.","Step:2 Hold your elbows near your torso and your back straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:43:59.256369+00', '2026-10-31 19:43:59.122+00'), ('LEH9jxP', 'Flexão de braços na parede', 'push-up (wall)', 'flexao-de-bracos-na-parede', 'https://static.exercisedb.dev/media/LEH9jxP.gif', 'catalogo/flexao-de-bracos-na-parede--LEH9jxP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-bracos-na-parede--LEH9jxP.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Face a wall, about arm''s length away.","Step:2 Set your hands on the wall at shoulder height, just beyond shoulder width.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:43:59.699432+00', '2026-10-31 19:43:59.566+00'), ('LEprlgG', 'Puxada alta na polia com amplitude completa', 'cable lat pulldown full range of motion', 'puxada-alta-na-polia-com-amplitude-completa', 'https://static.exercisedb.dev/media/LEprlgG.gif', 'catalogo/puxada-alta-na-polia-com-amplitude-completa--LEprlgG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-alta-na-polia-com-amplitude-completa--LEprlgG.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posterior'], '["Step:1 Take a seat on the lat pulldown machine with your knees positioned under the pads.","Step:2 Hold the cable bar with palms facing down, just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:44:00.11153+00', '2026-10-31 19:43:59.975+00'), ('lFhb2Rw', 'Agachamento frontal no Smith (pegada clean)', 'smith front squat (clean grip)', 'agachamento-frontal-no-smith-pegada-clean', 'https://static.exercisedb.dev/media/lFhb2Rw.gif', 'catalogo/agachamento-frontal-no-smith-pegada-clean--lFhb2Rw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frontal-no-smith-pegada-clean--lFhb2Rw.gif', ARRAY['coxas'], ARRAY['Smith machine'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Prepare the smith machine with the barbell at shoulder height.","Step:2 Face the barbell from a stable stance with feet about shoulder width.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:43:59.958223+00', '2026-10-31 19:43:59.83+00'), ('lHeUULr', 'Stiff com elástico', 'band straight back stiff leg deadlift', 'stiff-com-elastico', 'https://static.exercisedb.dev/media/lHeUULr.gif', 'catalogo/stiff-com-elastico--lHeUULr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stiff-com-elastico--lHeUULr.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and place the band around your upper legs.","Step:2 Take hold of the band with both hands ahead of your thighs, palms facing your body.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:00.098984+00', '2026-10-31 19:43:59.962+00'), ('LHWF7us', 'Hang clean com kettlebell', 'kettlebell hang clean', 'hang-clean-com-kettlebell', 'https://static.exercisedb.dev/media/LHWF7us.gif', 'catalogo/hang-clean-com-kettlebell--LHWF7us.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/hang-clean-com-kettlebell--LHWF7us.gif', ARRAY['coxas'], ARRAY['kettlebell'], ARRAY['posteriores de coxa'], ARRAY['glúteos','quadríceps','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell ahead of your thighs.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:44:00.704685+00', '2026-10-31 19:44:00.568+00'), ('lI7easp', 'Pullover com halter e extensão de quadril na bola suíça', 'dumbbell pullover hip extension on exercise ball', 'pullover-com-halter-e-extensao-de-quadril-na-bola-suica', 'https://static.exercisedb.dev/media/lI7easp.gif', 'catalogo/pullover-com-halter-e-extensao-de-quadril-na-bola-suica--lI7easp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-halter-e-extensao-de-quadril-na-bola-suica--lI7easp.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Take a seat on an exercise ball with your feet planted and the dumbbell resting on your thighs.","Step:2 With control walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:44:00.491256+00', '2026-10-31 19:44:00.355+00'), ('LIGZSTA', 'Rosca martelo unilateral de bruços com halter', 'Dumbbell Single-Arm Prone Hammer Curl', 'rosca-martelo-unilateral-de-brucos-com-halter', 'https://static.exercisedb.dev/media/LIGZSTA.gif', 'catalogo/rosca-martelo-unilateral-de-brucos-com-halter--LIGZSTA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-unilateral-de-brucos-com-halter--LIGZSTA.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Position yourself face down on a flat bench with a dumbbell in one hand, palm facing your body and arm straight.","Step:2 Keep your upper arm stationary and curl the dumbbell toward your shoulder, contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:00.63617+00', '2026-10-31 19:44:00.508+00'), ('LIlE5Tn', 'Agachamento com salto', 'jump squat', 'agachamento-com-salto', 'https://static.exercisedb.dev/media/LIlE5Tn.gif', 'catalogo/agachamento-com-salto--LIlE5Tn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-salto--LIlE5Tn.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:00.717152+00', '2026-10-31 19:44:00.582+00'), ('lJJ7Yq8', 'Crucifixo deitado na polia', 'cable lying fly', 'crucifixo-deitado-na-polia', 'https://static.exercisedb.dev/media/lJJ7Yq8.gif', 'catalogo/crucifixo-deitado-na-polia--lJJ7Yq8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-deitado-na-polia--lJJ7Yq8.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Connect the handles to the cables and Lie back on the bench with your feet planted.","Step:2 Take hold of the handles with your palms facing each other and your arms extended straight above your chest.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:00.760665+00', '2026-10-31 19:44:00.626+00'), ('LkoAWAE', 'Mergulho com apoio nos cotovelos', 'elbow dips', 'mergulho-com-apoio-nos-cotovelos', 'https://static.exercisedb.dev/media/LkoAWAE.gif', 'catalogo/mergulho-com-apoio-nos-cotovelos--LkoAWAE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-com-apoio-nos-cotovelos--LkoAWAE.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge next to your hips.","Step:2 Move your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:01.075636+00', '2026-10-31 19:44:00.943+00'), ('LL1UiTX', 'Supino inclinado unilateral com pegada martelo com halter', 'Dumbbell Incline Single-Arm Hammer Press', 'supino-inclinado-unilateral-com-pegada-martelo-com-halter', 'https://static.exercisedb.dev/media/LL1UiTX.gif', 'catalogo/supino-inclinado-unilateral-com-pegada-martelo-com-halter--LL1UiTX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-unilateral-com-pegada-martelo-com-halter--LL1UiTX.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides','peitorais'], '["Step:1 Take a seat on an incline bench with a dumbbell in one hand, resting on your thigh.","Step:2 Recline on the bench and use your thigh to help raise the dumbbell to shoulder height.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:01.250115+00', '2026-10-31 19:44:01.115+00'), ('LLNh6q5', 'Crucifixo inclinado unilateral com halter na bola suíça', 'Dumbbell Incline Single-Arm Fly On Exercise Ball', 'crucifixo-inclinado-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/LLNh6q5.gif', 'catalogo/crucifixo-inclinado-unilateral-com-halter-na-bola-suica--LLNh6q5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-unilateral-com-halter-na-bola-suica--LLNh6q5.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Take a seat on an exercise ball with a dumbbell in one hand.","Step:2 Step your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:44:01.400656+00', '2026-10-31 19:44:01.264+00'), ('LmaFNZS', 'Panturrilha burrinho com peso', 'weighted donkey calf raise', 'panturrilha-burrinho-com-peso', 'https://static.exercisedb.dev/media/LmaFNZS.gif', 'catalogo/panturrilha-burrinho-com-peso--LmaFNZS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-burrinho-com-peso--LmaFNZS.gif', ARRAY['panturrilhas'], ARRAY['peso adicional'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Step onto a raised platform with your toes on the edge and your heels hanging off.","Step:2 Use a stable object for support.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:01.629432+00', '2026-10-31 19:44:01.486+00'), ('LMGXZn8', 'Supino declinado pegada fechada até a testa com barra (tríceps testa)', 'Barbell Decline Close-Grip To Skull Press', 'supino-declinado-pegada-fechada-ate-a-testa-com-barra-triceps-testa', 'https://static.exercisedb.dev/media/LMGXZn8.gif', 'catalogo/supino-declinado-pegada-fechada-ate-a-testa-com-barra-triceps-testa--LMGXZn8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-pegada-fechada-ate-a-testa-com-barra-triceps-testa--LMGXZn8.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a decline bench with your head lower than your feet and hold a barbell with a close grip.","Step:2 Lower the barbell toward your forehead by bending your elbows, With the upper arms still.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:01.805588+00', '2026-10-31 19:44:01.673+00'), ('Ln9iTbU', 'Elevação posterior com barra', 'barbell rear delt raise', 'elevacao-posterior-com-barra', 'https://static.exercisedb.dev/media/Ln9iTbU.gif', 'catalogo/elevacao-posterior-com-barra--Ln9iTbU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-posterior-com-barra--Ln9iTbU.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms out and back with soft elbows, letting the rear shoulders do the work.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:02.087468+00', '2026-10-31 19:44:01.953+00'), ('LNE3wfo', 'Deslizamento unilateral na plataforma', 'single leg platform slide', 'deslizamento-unilateral-na-plataforma', 'https://static.exercisedb.dev/media/LNE3wfo.gif', 'catalogo/deslizamento-unilateral-na-plataforma--LNE3wfo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/deslizamento-unilateral-na-plataforma--LNE3wfo.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos','quadríceps'], '["Step:1 Begin by standing with one foot on a platform or slide board.","Step:2 Before moving, bend your knee slightly and slide the foot on the platform backward, extending your leg.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:01.825918+00', '2026-10-31 19:44:01.695+00'), ('LQFOrMn', 'Mergulho para peitoral na barra reta', 'chest dip on straight bar', 'mergulho-para-peitoral-na-barra-reta', 'https://static.exercisedb.dev/media/LQFOrMn.gif', 'catalogo/mergulho-para-peitoral-na-barra-reta--LQFOrMn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-para-peitoral-na-barra-reta--LQFOrMn.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Take hold of the parallel bars with your palms facing down and your arms straight.","Step:2 Before moving, bend your knees and cross your ankles.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:01.996769+00', '2026-10-31 19:44:01.864+00'), ('LrV4s90', 'Rosca de punho na polia', 'cable wrist curl', 'rosca-de-punho-na-polia', 'https://static.exercisedb.dev/media/LrV4s90.gif', 'catalogo/rosca-de-punho-na-polia--LrV4s90.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-na-polia--LrV4s90.gif', ARRAY['antebraços'], ARRAY['polia'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Connect a straight bar to a low pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:02.407134+00', '2026-10-31 19:44:02.277+00'), ('Lsqrgh4', 'Elevação de panturrilha invertida no Smith', 'smith reverse calf raises', 'elevacao-de-panturrilha-invertida-no-smith', 'https://static.exercisedb.dev/media/Lsqrgh4.gif', 'catalogo/elevacao-de-panturrilha-invertida-no-smith--Lsqrgh4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-invertida-no-smith--Lsqrgh4.gif', ARRAY['Panturrilhas'], ARRAY['Smith'], ARRAY['Panturrilhas'], ARRAY['Posteriores de coxa'], '["Step:1 Set the smith machine bar to a height just below your shoulders.","Step:2 Face the bar with your feet about hip width and toes pointing forward.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:02.657497+00', '2026-10-31 19:44:02.519+00'), ('LSTChY9', 'Agachamento Zercher com barra', 'barbell zercher squat', 'agachamento-zercher-com-barra', 'https://static.exercisedb.dev/media/LSTChY9.gif', 'catalogo/agachamento-zercher-com-barra--LSTChY9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-zercher-com-barra--LSTChY9.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de coxa','Panturrilhas','Core'], '["Step:1 Stand and set your feet about shoulder width and toes slightly turned out.","Step:2 Take hold of the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:02.471655+00', '2026-10-31 19:44:02.339+00'), ('LsZkfU6', 'Rosca de punho inversa com barra', 'barbell reverse wrist curl', 'rosca-de-punho-inversa-com-barra', 'https://static.exercisedb.dev/media/LsZkfU6.gif', 'catalogo/rosca-de-punho-inversa-com-barra--LsZkfU6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-com-barra--LsZkfU6.gif', ARRAY['Antebraços'], ARRAY['Barra'], ARRAY['Antebraços'], ARRAY['Bíceps','Braquial'], '["Step:1 Plant both feet while seated on a bench; hold a barbell with palms facing down.","Step:2 Set your forearms on your thighs, letting your wrists hang off the edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:02.650937+00', '2026-10-31 19:44:02.518+00'), ('Lt3iWnf', 'Crucifixo com halteres na bola suíça', 'dumbbell fly on exercise ball', 'crucifixo-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/Lt3iWnf.gif', 'catalogo/crucifixo-com-halteres-na-bola-suica--Lt3iWnf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-com-halteres-na-bola-suica--Lt3iWnf.gif', ARRAY['Peitoral'], ARRAY['Halteres','Bola suíça'], ARRAY['Peitoral'], ARRAY['Deltoides','Tríceps'], '["Step:1 Take a seat on an exercise ball and hold a dumbbell in each hand.","Step:2 Step your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:03.033896+00', '2026-10-31 19:44:02.884+00'), ('LuBEORI', 'Remada curvada na máquina com barra V', 'Machine Bent-Over Row With V-Bar', 'remada-curvada-na-maquina-com-barra-v', 'https://static.exercisedb.dev/media/LuBEORI.gif', 'catalogo/remada-curvada-na-maquina-com-barra-v--LuBEORI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-na-maquina-com-barra-v--LuBEORI.gif', ARRAY['Costas'], ARRAY['Máquina articulada'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the v-bar with palms facing down, with your spine steady and your knees soft.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:02.906201+00', '2026-10-31 19:44:02.773+00'), ('LWuA3aZ', 'Rosca direta inversa em pé com barra', 'Barbell Standing Reverse-Grip Curl', 'rosca-direta-inversa-em-pe-com-barra', 'https://static.exercisedb.dev/media/LWuA3aZ.gif', 'catalogo/rosca-direta-inversa-em-pe-com-barra--LWuA3aZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-inversa-em-pe-com-barra--LWuA3aZ.gif', ARRAY['Braços'], ARRAY['Barra'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing up.","Step:2 Hold your elbows near your torso and your upper arms stationary.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:03.412346+00', '2026-10-31 19:44:03.281+00'), ('LYJodFS', 'Lean planche', 'lean planche', 'lean-planche', 'https://static.exercisedb.dev/media/LYJodFS.gif', 'catalogo/lean-planche--LYJodFS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/lean-planche--LYJodFS.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Deltoides','Peitoral','Tríceps'], '["Step:1 Begin in a push-up position with your hands about shoulder width and your body straight.","Step:2 Brace your trunk and With control shift your weight forward, bringing your shoulders past your hands.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:03.096886+00', '2026-10-31 19:44:02.967+00'), ('lyKCLmK', 'Rosca concentrada inversa sentado com halter', 'Dumbbell Seated Reverse-Grip Concentration Curl', 'rosca-concentrada-inversa-sentado-com-halter', 'https://static.exercisedb.dev/media/lyKCLmK.gif', 'catalogo/rosca-concentrada-inversa-sentado-com-halter--lyKCLmK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-inversa-sentado-com-halter--lyKCLmK.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Sit with both feet grounded and hold one dumbbell with the palm facing down.","Step:2 Set your elbow on the inside of your thigh, just above the knee.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the dumbbell with the palm facing down while the upper arm stays braced against the inner thigh.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:03.289664+00', '2026-10-31 19:44:03.157+00'), ('m0tCHqc', 'Alongamento de panturrilha com as mãos na parede', 'calf stretch with hands against wall', 'alongamento-de-panturrilha-com-as-maos-na-parede', 'https://static.exercisedb.dev/media/m0tCHqc.gif', 'catalogo/alongamento-de-panturrilha-com-as-maos-na-parede--m0tCHqc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-panturrilha-com-as-maos-na-parede--m0tCHqc.gif', ARRAY['Panturrilhas'], ARRAY['Peso corporal'], ARRAY['Panturrilhas'], ARRAY['Posteriores de coxa'], '["Step:1 Face a wall with your feet about hip width.","Step:2 Set your hands against the wall at shoulder height.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:03.765638+00', '2026-10-31 19:44:03.609+00'), ('M2Pm3zj', 'Supinação deitado com halter', 'dumbbell lying supination', 'supinacao-deitado-com-halter', 'https://static.exercisedb.dev/media/M2Pm3zj.gif', 'catalogo/supinacao-deitado-com-halter--M2Pm3zj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supinacao-deitado-com-halter--M2Pm3zj.gif', ARRAY['Antebraços'], ARRAY['Halter'], ARRAY['Antebraços'], ARRAY['Bíceps','Deltoides'], '["Step:1 Settle onto a bench with your feet planted.","Step:2 Take a dumbbell in each hand with your palms facing up and your arms straight.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:03.676861+00', '2026-10-31 19:44:03.534+00'), ('M5Y7GPg', 'Rosca direta em pé com peso', 'weighted standing curl', 'rosca-direta-em-pe-com-peso', 'https://static.exercisedb.dev/media/M5Y7GPg.gif', 'catalogo/rosca-direta-em-pe-com-peso--M5Y7GPg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-em-pe-com-peso--M5Y7GPg.gif', ARRAY['Braços'], ARRAY['Com peso'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.","Step:2 Hold your elbows near your torso and Breathe out and curl the weights up to shoulder level.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:03.777719+00', '2026-10-31 19:44:03.647+00'), ('M72BExt', 'Rotação de membros inferiores unilateral de bruços na bola suíça', 'Exercise Ball Single-Leg Prone Lower Body Rotation', 'rotacao-de-membros-inferiores-unilateral-de-brucos-na-bola-suica', 'https://static.exercisedb.dev/media/M72BExt.gif', 'catalogo/rotacao-de-membros-inferiores-unilateral-de-brucos-na-bola-suica--M72BExt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-membros-inferiores-unilateral-de-brucos-na-bola-suica--M72BExt.gif', ARRAY['Coxas'], ARRAY['Bola suíça'], ARRAY['Glúteos'], ARRAY['Posteriores de coxa','Quadríceps','Core'], '["Step:1 Position yourself face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Step:2 Set your hands on the ground in front of you for support.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Return through center before turning to the other side; switch sides when the set calls for it."]', '2026-10-31 19:44:03.881187+00', '2026-10-31 19:44:03.748+00'), ('M74kdvm', 'Arranco duplo com kettlebell', 'kettlebell double snatch', 'arranco-duplo-com-kettlebell', 'https://static.exercisedb.dev/media/M74kdvm.gif', 'catalogo/arranco-duplo-com-kettlebell--M74kdvm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arranco-duplo-com-kettlebell--M74kdvm.gif', ARRAY['Ombros'], ARRAY['Kettlebell'], ARRAY['Deltoides'], ARRAY['Trapézio','Antebraços','Core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at arm''s length ahead of your thighs.","Step:2 Before moving, bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:44:03.984565+00', '2026-10-31 19:44:03.852+00'), ('MaMuGH6', 'Barra fixa assistida na máquina', 'Machine Assisted Pull-Up', 'barra-fixa-assistida-na-maquina', 'https://static.exercisedb.dev/media/MaMuGH6.gif', 'catalogo/barra-fixa-assistida-na-maquina--MaMuGH6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-assistida-na-maquina--MaMuGH6.gif', ARRAY['Costas'], ARRAY['Máquina articulada'], ARRAY['Latíssimo do dorso'], ARRAY['Bíceps','Antebraços'], '["Step:1 Set the leverage machine to your desired resistance level.","Step:2 Step onto the foot platform and grip the handles with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:04.666634+00', '2026-10-31 19:44:04.524+00'), ('mbkgB44', 'Abdominal canivete', 'jackknife sit-up', 'abdominal-canivete', 'https://static.exercisedb.dev/media/mbkgB44.gif', 'catalogo/abdominal-canivete--mbkgB44.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-canivete--mbkgB44.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Settle onto your back with your legs extended and your arms overhead.","Step:2 Brace your trunk and lift your legs and upper body simultaneously, reaching your hands toward your toes.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:04.366767+00', '2026-10-31 19:44:04.221+00'), ('MCkqdKE', 'Muscle-up na barra com peso', 'weighted muscle up (on bar)', 'muscle-up-na-barra-com-peso', 'https://static.exercisedb.dev/media/MCkqdKE.gif', 'catalogo/muscle-up-na-barra-com-peso--MCkqdKE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/muscle-up-na-barra-com-peso--MCkqdKE.gif', ARRAY['Costas'], ARRAY['Com peso'], ARRAY['Latíssimo do dorso'], ARRAY['Bíceps','Tríceps','Deltoides','Antebraços'], '["Step:1 Begin by hanging from a pull-up bar with your palms turned away from you and your hands just beyond shoulder width.","Step:2 Brace your trunk and pull your shoulder blades down and back.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:04.42873+00', '2026-10-31 19:44:04.296+00'), ('MCUhf1F', 'Abdominal crunch na bola suíça', 'crunch (on stability ball)', 'abdominal-crunch-na-bola-suica', 'https://static.exercisedb.dev/media/MCUhf1F.gif', 'catalogo/abdominal-crunch-na-bola-suica--MCUhf1F.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-crunch-na-bola-suica--MCUhf1F.gif', ARRAY['Abdômen'], ARRAY['Bola suíça'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Recline on the ball until your lower back is supported and your upper body is parallel to the floor.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:04.906733+00', '2026-10-31 19:44:04.772+00'), ('mExgrF9', 'Barra fixa com banco', 'bench pull-ups', 'barra-fixa-com-banco', 'https://static.exercisedb.dev/media/mExgrF9.gif', 'catalogo/barra-fixa-com-banco--mExgrF9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-banco--mExgrF9.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Latíssimo do dorso'], ARRAY['Bíceps','Antebraços'], '["Step:1 Set yourself under a bar or a sturdy horizontal surface that is at chest height.","Step:2 Take hold of the bar or surface with palms facing down, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:04.898292+00', '2026-10-31 19:44:04.764+00'), ('mgejmGP', 'Meio abdominal com mãos atrás da cabeça', 'Prisoner Half Sit-Up', 'meio-abdominal-com-maos-atras-da-cabeca', 'https://static.exercisedb.dev/media/mgejmGP.gif', 'catalogo/meio-abdominal-com-maos-atras-da-cabeca--mgejmGP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/meio-abdominal-com-maos-atras-da-cabeca--mgejmGP.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:05.275149+00', '2026-10-31 19:44:05.144+00'), ('MgKwAAo', 'Remada no banco inclinado com corda na polia', 'cable rope extension incline bench row', 'remada-no-banco-inclinado-com-corda-na-polia', 'https://static.exercisedb.dev/media/MgKwAAo.gif', 'catalogo/remada-no-banco-inclinado-com-corda-na-polia--MgKwAAo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-no-banco-inclinado-com-corda-na-polia--MgKwAAo.gif', ARRAY['Costas'], ARRAY['Polia'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Deltoides'], '["Step:1 Prepare an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Step:2 Connect a rope handle to the cable machine and sit on the incline bench facing the machine.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:05.26451+00', '2026-10-31 19:44:05.126+00'), ('MKIelrR', 'Supino unilateral na polia na bola suíça', 'Cable Single-Arm Press On Exercise Ball', 'supino-unilateral-na-polia-na-bola-suica', 'https://static.exercisedb.dev/media/MKIelrR.gif', 'catalogo/supino-unilateral-na-polia-na-bola-suica--MKIelrR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-na-polia-na-bola-suica--MKIelrR.gif', ARRAY['Peitoral'], ARRAY['Polia','Bola suíça'], ARRAY['Peitoral'], ARRAY['Deltoides','Tríceps'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a cable handle in one hand and position your arm at chest height, elbow bent.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:05.266732+00', '2026-10-31 19:44:05.138+00'), ('mKwcrHn', 'Aperto de mão na máquina (hand gripper)', 'Machine Gripper Hands', 'aperto-de-mao-na-maquina-hand-gripper', 'https://static.exercisedb.dev/media/mKwcrHn.gif', 'catalogo/aperto-de-mao-na-maquina-hand-gripper--mKwcrHn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/aperto-de-mao-na-maquina-hand-gripper--mKwcrHn.gif', ARRAY['antebraços'], ARRAY['máquina articulada'], ARRAY['antebraços'], ARRAY['bíceps','tríceps'], '["Step:1 Set the seat height and grip the handles of the leverage machine.","Step:2 Keep your spine in a comfortable neutral position and your feet planted.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:05.869181+00', '2026-10-31 19:44:05.733+00'), ('mnzcrIB', 'Agachamento no banco com halteres', 'dumbbell bench squat', 'agachamento-no-banco-com-halteres', 'https://static.exercisedb.dev/media/mnzcrIB.gif', 'catalogo/agachamento-no-banco-com-halteres--mnzcrIB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-no-banco-com-halteres--mnzcrIB.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set a dumbbell on the ground in front of a bench.","Step:2 Face the away from the bench from a stable stance with feet about shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:05.826813+00', '2026-10-31 19:44:05.695+00'), ('mpKZGWz', 'Tríceps testa com halteres', 'dumbbell lying triceps extension', 'triceps-testa-com-halteres', 'https://static.exercisedb.dev/media/mpKZGWz.gif', 'catalogo/triceps-testa-com-halteres--mpKZGWz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-halteres--mpKZGWz.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other.","Step:2 Reach your arms straight up over your chest, keeping your elbows close to your body.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:05.882266+00', '2026-10-31 19:44:05.732+00'), ('mQ1tBXn', 'Abdução de quadril com perna estendida', 'Straight-Leg Outer Hip Abductor', 'abducao-de-quadril-com-perna-estendida', 'https://static.exercisedb.dev/media/mQ1tBXn.gif', 'catalogo/abducao-de-quadril-com-perna-estendida--mQ1tBXn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abducao-de-quadril-com-perna-estendida--mQ1tBXn.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['abdutores'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Settle onto your side with your legs straight and stacked on top of each other.","Step:2 Set your bottom arm under your head for support.","Step:3 Square the pelvis before moving the working leg.","Step:4 Move the working leg sideways from the hip without swinging your torso.","Step:5 Move only as far as the pelvis can remain steady.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:44:05.895949+00', '2026-10-31 19:44:05.762+00'), ('mr7pkqP', 'Burpee com polichinelo', 'jack burpee', 'burpee-com-polichinelo', 'https://static.exercisedb.dev/media/mr7pkqP.gif', 'catalogo/burpee-com-polichinelo--mr7pkqP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/burpee-com-polichinelo--mr7pkqP.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','deltoides','tríceps','core'], '["Step:1 Begin in a standing position with your feet about shoulder width.","Step:2 Before moving, lower your body into a squat position, placing your hands on the ground in front of you.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:06.333253+00', '2026-10-31 19:44:06.2+00'), ('MrgP9L6', 'Panturrilha rotativa na máquina', 'Machine Rotary Calf', 'panturrilha-rotativa-na-maquina', 'https://static.exercisedb.dev/media/MrgP9L6.gif', 'catalogo/panturrilha-rotativa-na-maquina--MrgP9L6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-rotativa-na-maquina--MrgP9L6.gif', ARRAY['panturrilhas'], ARRAY['máquina articulada'], ARRAY['panturrilhas'], ARRAY['sóleo','estabilizadores do tornozelo'], '["Step:1 Set the seat height so that your knees are soft and your feet are flat on the footplate.","Step:2 Set your toes on the footplate, with your heels hanging off the edge.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:06.453503+00', '2026-10-31 19:44:06.315+00'), ('ms7tjSG', 'Flexão de pernas inversa (apoio no banco)', 'inverse leg curl (bench support)', 'flexao-de-pernas-inversa-apoio-no-banco', 'https://static.exercisedb.dev/media/ms7tjSG.gif', 'catalogo/flexao-de-pernas-inversa-apoio-no-banco--ms7tjSG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-pernas-inversa-apoio-no-banco--ms7tjSG.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos','panturrilhas'], '["Step:1 Position yourself face down on a bench with your hips at the edge and your legs extended straight behind you.","Step:2 Use the bench for support.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:06.467544+00', '2026-10-31 19:44:06.338+00'), ('MSfvriJ', 'Skin the cat (giro na barra)', 'skin the cat', 'skin-the-cat-giro-na-barra', 'https://static.exercisedb.dev/media/MSfvriJ.gif', 'catalogo/skin-the-cat-giro-na-barra--MSfvriJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/skin-the-cat-giro-na-barra--MSfvriJ.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['deltoides','core'], '["Step:1 Begin by hanging from a bar with your arms straight and your body relaxed.","Step:2 Brace your trunk and lift your legs up, bringing your knees toward your chest.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:06.939638+00', '2026-10-31 19:44:06.799+00'), ('mTT3KLn', 'Elevação frontal na polia', 'cable front shoulder raise', 'elevacao-frontal-na-polia', 'https://static.exercisedb.dev/media/mTT3KLn.gif', 'catalogo/elevacao-frontal-na-polia--mTT3KLn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-na-polia--mTT3KLn.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width and Hold the cable handle with palms facing down.","Step:2 Keep your spine in a comfortable neutral position and your core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:07.12045+00', '2026-10-31 19:44:06.983+00'), ('mtXengz', 'Rosca de dedos com halteres', 'dumbbell finger curls', 'rosca-de-dedos-com-halteres', 'https://static.exercisedb.dev/media/mtXengz.gif', 'catalogo/rosca-de-dedos-com-halteres--mtXengz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-dedos-com-halteres--mtXengz.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['flexores do punho','extensores do punho'], '["Step:1 Take a seat on a bench or chair with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand with palms facing up, resting your forearm on your thigh, palm facing up.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Let the bar roll toward your fingertips, then close your fingers firmly around it.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:07.311181+00', '2026-10-31 19:44:07.167+00'), ('mu5Guxt', 'Crucifixo inverso com halteres', 'dumbbell rear delt raise', 'crucifixo-inverso-com-halteres', 'https://static.exercisedb.dev/media/mu5Guxt.gif', 'catalogo/crucifixo-inverso-com-halteres--mu5Guxt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres--mu5Guxt.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms out and back with soft elbows, letting the rear shoulders do the work.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:07.028143+00', '2026-10-31 19:44:06.888+00'), ('MU9HnE7', 'Mergulho no banco com peso', 'weighted bench dip', 'mergulho-no-banco-com-peso', 'https://static.exercisedb.dev/media/MU9HnE7.gif', 'catalogo/mergulho-no-banco-com-peso--MU9HnE7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-no-banco-com-peso--MU9HnE7.gif', ARRAY['braços'], ARRAY['com peso'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Move your butt off the bench, supporting your weight with your hands.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:07.387767+00', '2026-10-31 19:44:07.249+00'), ('MUic5zN', 'Flexão de braço unilateral', 'single arm push-up', 'flexao-de-braco-unilateral', 'https://static.exercisedb.dev/media/MUic5zN.gif', 'catalogo/flexao-de-braco-unilateral--MUic5zN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-unilateral--MUic5zN.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a push-up position with your hands about shoulder width and one hand placed slightly wider than the other.","Step:2 Brace your trunk and lower your body toward the ground by bending your elbows, with your spine steady.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:07.562563+00', '2026-10-31 19:44:07.433+00'), ('MvQPqVW', 'Judo flip na polia', 'cable judo flip', 'judo-flip-na-polia', 'https://static.exercisedb.dev/media/MvQPqVW.gif', 'catalogo/judo-flip-na-polia--MvQPqVW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/judo-flip-na-polia--MvQPqVW.gif', ARRAY['abdômen'], ARRAY['polia'], ARRAY['abdominais'], ARRAY['oblíquos','deltoides'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable handle with both hands at chest level, palms facing down.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:07.622865+00', '2026-10-31 19:44:07.486+00'), ('mWBtgmb', 'Caminhada com halter acima da cabeça (unilateral)', 'dumbbell single arm overhead carry', 'caminhada-com-halter-acima-da-cabeca-unilateral', 'https://static.exercisedb.dev/media/mWBtgmb.gif', 'catalogo/caminhada-com-halter-acima-da-cabeca-unilateral--mWBtgmb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-com-halter-acima-da-cabeca-unilateral--mWBtgmb.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','core'], '["Step:1 Stand tall and set your feet about shoulder width, holding a dumbbell in one hand.","Step:2 Before moving, raise the dumbbell overhead, fully extending your arm.","Step:3 Stand tall with the load secure and the shoulders level.","Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.","Step:5 Keep steps even and avoid leaning away from the load.","Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk."]', '2026-10-31 19:44:07.835857+00', '2026-10-31 19:44:07.694+00'), ('mweqJin', 'Corrida rápida no lugar (quick feet)', 'quick feet', 'corrida-rapida-no-lugar-quick-feet', 'https://static.exercisedb.dev/media/mweqJin.gif', 'catalogo/corrida-rapida-no-lugar-quick-feet--mweqJin.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-rapida-no-lugar-quick-feet--mweqJin.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['panturrilhas','posteriores de coxa'], '["Step:1 Stand and set your feet about shoulder width and your arms by your sides.","Step:2 Start by rapidly moving your feet up and down, as if you were running in place.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:07.889472+00', '2026-10-31 19:44:07.739+00'), ('mWppALS', 'Abdominal para adutores (groin crunch)', 'groin crunch', 'abdominal-para-adutores-groin-crunch', 'https://static.exercisedb.dev/media/mWppALS.gif', 'catalogo/abdominal-para-adutores-groin-crunch--mWppALS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-para-adutores-groin-crunch--mWppALS.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','adutores'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:08.152648+00', '2026-10-31 19:44:08.011+00'), ('mwpPcr1', 'Rosca inclinada de bruços com halteres', 'dumbbell prone incline curl', 'rosca-inclinada-de-brucos-com-halteres', 'https://static.exercisedb.dev/media/mwpPcr1.gif', 'catalogo/rosca-inclinada-de-brucos-com-halteres--mwpPcr1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inclinada-de-brucos-com-halteres--mwpPcr1.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Set the bench to a 45-degree incline.","Step:2 Position yourself face down on the bench with your chest and stomach resting against it.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:08.198762+00', '2026-10-31 19:44:08.066+00'), ('Mxa7Cr8', 'Remada invertida no banco', 'inverted row on bench', 'remada-invertida-no-banco', 'https://static.exercisedb.dev/media/Mxa7Cr8.gif', 'catalogo/remada-invertida-no-banco--Mxa7Cr8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-invertida-no-banco--Mxa7Cr8.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Prepare a bench at a height that allows your body to hang freely underneath it.","Step:2 Lie face up on the ground with your head toward the bench.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:08.458093+00', '2026-10-31 19:44:08.324+00'), ('my33uHU', 'Cadeira extensora', 'Machine Leg Extension', 'cadeira-extensora', 'https://static.exercisedb.dev/media/my33uHU.gif', 'catalogo/cadeira-extensora--my33uHU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cadeira-extensora--my33uHU.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['quadríceps'], ARRAY['posteriores de coxa'], '["Step:1 Set the seat height and backrest of the machine to fit your body.","Step:2 Take a seat on the machine with your back against the backrest and your feet on the footpad.","Step:3 Set the pad just above the ankles and keep the thighs against the seat.","Step:4 Straighten your knees to lift the pad, keeping your hips against the seat.","Step:5 Lift without swinging and avoid snapping the knees straight.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:08.511809+00', '2026-10-31 19:44:08.368+00'), ('MY9P1WA', 'Supino declinado com pegada supinada no Smith', 'smith decline reverse-grip press', 'supino-declinado-com-pegada-supinada-no-smith', 'https://static.exercisedb.dev/media/MY9P1WA.gif', 'catalogo/supino-declinado-com-pegada-supinada-no-smith--MY9P1WA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-com-pegada-supinada-no-smith--MY9P1WA.gif', ARRAY['peito'], ARRAY['Smith'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the smith machine to a decline position.","Step:2 Get onto the bench with your feet secured under the foot pads.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:08.491862+00', '2026-10-31 19:44:08.352+00'), ('myfUsKf', 'Crucifixo Inverso na Máquina (Sentado)', 'Machine Seated Reverse Fly', 'crucifixo-inverso-na-maquina-sentado', 'https://static.exercisedb.dev/media/myfUsKf.gif', 'catalogo/crucifixo-inverso-na-maquina-sentado--myfUsKf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-na-maquina-sentado--myfUsKf.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and keep your arms soft.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:09.043626+00', '2026-10-31 19:44:08.902+00'), ('mym4hJo', 'Pronação com Halter Deitado', 'dumbbell lying pronation', 'pronacao-com-halter-deitado', 'https://static.exercisedb.dev/media/mym4hJo.gif', 'catalogo/pronacao-com-halter-deitado--mym4hJo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pronacao-com-halter-deitado--mym4hJo.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['bíceps','deltoides'], '["Step:1 Settle onto a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Step:2 Before moving, rotate your palms so they are facing up.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:08.978616+00', '2026-10-31 19:44:08.846+00'), ('Mz6lLcW', 'Afundo com Rosca Direta com Halteres', 'Dumbbell Lunge With Biceps Curl', 'afundo-com-rosca-direta-com-halteres', 'https://static.exercisedb.dev/media/Mz6lLcW.gif', 'catalogo/afundo-com-rosca-direta-com-halteres--Mz6lLcW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-com-rosca-direta-com-halteres--Mz6lLcW.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['quadríceps','posteriores de coxa'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing forward.","Step:2 Step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:09.039733+00', '2026-10-31 19:44:08.895+00'), ('MzNnwx9', 'Encolhimento Atrás no Smith', 'smith back shrug', 'encolhimento-atras-no-smith', 'https://static.exercisedb.dev/media/MzNnwx9.gif', 'catalogo/encolhimento-atras-no-smith--MzNnwx9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-atras-no-smith--MzNnwx9.gif', ARRAY['costas'], ARRAY['Smith'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Hold the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:44:09.439186+00', '2026-10-31 19:44:09.303+00'), ('n5cWCsI', 'Elevação Lateral Unilateral com Halter', 'Dumbbell Single-Arm Lateral Raise', 'elevacao-lateral-unilateral-com-halter', 'https://static.exercisedb.dev/media/n5cWCsI.gif', 'catalogo/elevacao-lateral-unilateral-com-halter--n5cWCsI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-unilateral-com-halter--n5cWCsI.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand with your palm facing your body.","Step:2 Keep your spine in a comfortable neutral position and your core engaged throughout the exercise.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:44:09.570629+00', '2026-10-31 19:44:09.415+00'), ('NAgVB3t', 'Roda Abdominal', 'wheel rollout', 'roda-abdominal', 'https://static.exercisedb.dev/media/NAgVB3t.gif', 'catalogo/roda-abdominal--NAgVB3t.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/roda-abdominal--NAgVB3t.gif', ARRAY['abdômen'], ARRAY['roda abdominal'], ARRAY['abdominais'], ARRAY['eretores da espinha'], '["Step:1 Get down on the floor and place the wheel roller in front of you.","Step:2 Set your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:44:09.574345+00', '2026-10-31 19:44:09.441+00'), ('NAkmgdx', 'Abdominal Completo com Braços Estendidos acima da Cabeça', 'Arms Overhead Full Sit-Up', 'abdominal-completo-com-bracos-estendidos-acima-da-cabeca', 'https://static.exercisedb.dev/media/NAkmgdx.gif', 'catalogo/abdominal-completo-com-bracos-estendidos-acima-da-cabeca--NAkmgdx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-completo-com-bracos-estendidos-acima-da-cabeca--NAkmgdx.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Reach your arms overhead, keeping them straight.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:09.800333+00', '2026-10-31 19:44:09.655+00'), ('nAuHPcD', 'Tríceps Unilateral com Halter no Banco', 'Dumbbell Single-Arm Triceps Extension (On Bench)', 'triceps-unilateral-com-halter-no-banco', 'https://static.exercisedb.dev/media/nAuHPcD.gif', 'catalogo/triceps-unilateral-com-halter-no-banco--nAuHPcD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-unilateral-com-halter-no-banco--nAuHPcD.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in one hand and place your other hand on the bench for support.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:44:09.782409+00', '2026-10-31 19:44:09.648+00'), ('NbVPDMW', 'Rosca Direta com Halteres', 'dumbbell biceps curl', 'rosca-direta-com-halteres', 'https://static.exercisedb.dev/media/NbVPDMW.gif', 'catalogo/rosca-direta-com-halteres--NbVPDMW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres--NbVPDMW.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:10.018015+00', '2026-10-31 19:44:09.883+00'), ('NCmbLCw', 'Flexão de Braço na Parede', 'push-up (wall)', 'flexao-de-braco-na-parede', 'https://static.exercisedb.dev/media/NCmbLCw.gif', 'catalogo/flexao-de-braco-na-parede--NCmbLCw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-na-parede--NCmbLCw.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Face a wall, about arm''s length away.","Step:2 Set your hands on the wall at shoulder height, just beyond shoulder width.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:10.152868+00', '2026-10-31 19:44:10.024+00'), ('nCU1Ekp', 'Abdominal Invertido', 'reverse crunch', 'abdominal-invertido', 'https://static.exercisedb.dev/media/nCU1Ekp.gif', 'catalogo/abdominal-invertido--nCU1Ekp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-invertido--nCU1Ekp.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your arms extended along your sides.","Step:2 Before moving, bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:10.515846+00', '2026-10-31 19:44:10.372+00'), ('NdIb5Z1', 'Rosca Direta com Barra Pegada Aberta em Pé', 'barbell standing wide-grip curl', 'rosca-direta-com-barra-pegada-aberta-em-pe', 'https://static.exercisedb.dev/media/NdIb5Z1.gif', 'catalogo/rosca-direta-com-barra-pegada-aberta-em-pe--NdIb5Z1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra-pegada-aberta-em-pe--NdIb5Z1.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing down, hands wider than about shoulder width.","Step:2 Keep the barbell hanging at arm''s length ahead of your thighs, with your palms turned away from your body.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:10.879312+00', '2026-10-31 19:44:10.74+00'), ('nDK1HJ0', 'Pullover com Barra W Deitado e Cotovelos Flexionados', 'EZ-Bar Lying Bent Arms Pullover', 'pullover-com-barra-w-deitado-e-cotovelos-flexionados', 'https://static.exercisedb.dev/media/nDK1HJ0.gif', 'catalogo/pullover-com-barra-w-deitado-e-cotovelos-flexionados--nDK1HJ0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-barra-w-deitado-e-cotovelos-flexionados--nDK1HJ0.gif', ARRAY['costas'], ARRAY['barra W'], ARRAY['latíssimo do dorso'], ARRAY['tríceps','peitorais'], '["Step:1 Settle onto a bench with your head at one end and your feet on the floor.","Step:2 Take hold of the EZ barbell with a pronated grip (palms turned away from you) and your hands about shoulder width.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:44:10.427199+00', '2026-10-31 19:44:10.285+00'), ('neonEDL', 'Crucifixo no Chão com Barra', 'floor fly (with barbell)', 'crucifixo-no-chao-com-barra', 'https://static.exercisedb.dev/media/neonEDL.gif', 'catalogo/crucifixo-no-chao-com-barra--neonEDL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-no-chao-com-barra--neonEDL.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Settle onto your back on the floor with your knees bent and feet planted.","Step:2 Take a barbell with palms facing down, arms extended straight up over your chest.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:10.604167+00', '2026-10-31 19:44:10.465+00'), ('nFc4FyV', 'Rosca Inversa com Halteres', 'dumbbell biceps curl reverse', 'rosca-inversa-com-halteres', 'https://static.exercisedb.dev/media/nFc4FyV.gif', 'catalogo/rosca-inversa-com-halteres--nFc4FyV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-com-halteres--nFc4FyV.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing down and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:11.132865+00', '2026-10-31 19:44:11.004+00'), ('NfP83rA', 'Tríceps Alternado com Halteres Deitado', 'dumbbell lying alternate extension', 'triceps-alternado-com-halteres-deitado', 'https://static.exercisedb.dev/media/NfP83rA.gif', 'catalogo/triceps-alternado-com-halteres-deitado--NfP83rA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-alternado-com-halteres-deitado--NfP83rA.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other.","Step:2 Reach your arms straight up over your chest, keeping a slight bend in your elbows.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:44:11.15152+00', '2026-10-31 19:44:11.012+00'), ('nFUwqG6', 'Remada para Deltoide Posterior no Smith', 'smith rear delt row', 'remada-para-deltoide-posterior-no-smith', 'https://static.exercisedb.dev/media/nFUwqG6.gif', 'catalogo/remada-para-deltoide-posterior-no-smith--nFUwqG6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-para-deltoide-posterior-no-smith--nFUwqG6.gif', ARRAY['ombros'], ARRAY['Smith'], ARRAY['deltoides'], ARRAY['trapézio','romboides','bíceps'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down, just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:11.485317+00', '2026-10-31 19:44:11.339+00'), ('ngPpyRS', 'Desenvolvimento Militar Atrás da Nuca com Barra Sentado', 'barbell seated behind head military press', 'desenvolvimento-militar-atras-da-nuca-com-barra-sentado', 'https://static.exercisedb.dev/media/ngPpyRS.gif', 'catalogo/desenvolvimento-militar-atras-da-nuca-com-barra-sentado--ngPpyRS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-atras-da-nuca-com-barra-sentado--ngPpyRS.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take hold of the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:11.535731+00', '2026-10-31 19:44:11.405+00'), ('Nh3mvOO', 'Remada com Halter Pegada Supinada', 'Dumbbell Reverse-Grip Row', 'remada-com-halter-pegada-supinada', 'https://static.exercisedb.dev/media/Nh3mvOO.gif', 'catalogo/remada-com-halter-pegada-supinada--Nh3mvOO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-com-halter-pegada-supinada--Nh3mvOO.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take a dumbbell in each hand with palms facing down, palms facing your body.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:11.516216+00', '2026-10-31 19:44:11.383+00'), ('nIR4Rwl', 'Supino Sentado no Cabo', 'cable seated chest press', 'supino-sentado-no-cabo', 'https://static.exercisedb.dev/media/nIR4Rwl.gif', 'catalogo/supino-sentado-no-cabo--nIR4Rwl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-sentado-no-cabo--nIR4Rwl.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the seat height and cable handles to a comfortable position.","Step:2 Take a seat on the bench with your back straight and feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:11.763719+00', '2026-10-31 19:44:11.625+00'), ('niXESDw', 'Agachamento com rosca direta com halteres', 'dumbbell biceps curl squat', 'agachamento-com-rosca-direta-com-halteres', 'https://static.exercisedb.dev/media/niXESDw.gif', 'catalogo/agachamento-com-rosca-direta-com-halteres--niXESDw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-rosca-direta-com-halteres--niXESDw.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing forward.","Step:2 With your back straight and your elbows close to your sides, exhale and curl the dumbbells up toward your shoulders.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:12.167665+00', '2026-10-31 19:44:12.026+00'), ('NJzBsGJ', 'Encolhimento com halteres', 'dumbbell shrug', 'encolhimento-com-halteres', 'https://static.exercisedb.dev/media/NJzBsGJ.gif', 'catalogo/encolhimento-com-halteres--NJzBsGJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-com-halteres--NJzBsGJ.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand with your palms facing your body.","Step:2 Maintain straight arms and let the dumbbells hang by your sides.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:12.428721+00', '2026-10-31 19:44:12.291+00'), ('NKJ8o6x', 'Inclinação pélvica', 'pelvic tilt', 'inclinacao-pelvica', 'https://static.exercisedb.dev/media/NKJ8o6x.gif', 'catalogo/inclinacao-pelvica--NKJ8o6x.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/inclinacao-pelvica--NKJ8o6x.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands by your sides.","Step:3 Relax the shoulders and find a comfortable neutral starting position.","Step:4 Gently roll the pelvis to flatten and release the lower back through a small range.","Step:5 Use a small range and avoid forcing the lower back into the floor.","Step:6 Release the tilt gently and repeat without forcing the range."]', '2026-10-31 19:44:12.352741+00', '2026-10-31 19:44:12.208+00'), ('NL6YBwN', 'Crucifixo declinado unilateral com halter', 'Dumbbell Decline Single-Arm Fly', 'crucifixo-declinado-unilateral-com-halter', 'https://static.exercisedb.dev/media/NL6YBwN.gif', 'catalogo/crucifixo-declinado-unilateral-com-halter--NL6YBwN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-declinado-unilateral-com-halter--NL6YBwN.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Get onto a decline bench with a dumbbell in one hand, resting it on your thigh.","Step:2 Use your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:44:12.44339+00', '2026-10-31 19:44:12.024+00'), ('NlfIbzq', 'Rosca Scott alternada com halteres', 'dumbbell alternate preacher curl', 'rosca-scott-alternada-com-halteres', 'https://static.exercisedb.dev/media/NlfIbzq.gif', 'catalogo/rosca-scott-alternada-com-halteres--NlfIbzq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-alternada-com-halteres--NlfIbzq.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with a dumbbell in each hand, palms facing up.","Step:2 Set your upper arms on the pad of the preacher bench, letting your arms to fully extend.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:12.695252+00', '2026-10-31 19:44:12.557+00'), ('nlJsbkW', 'Rosca direta com halteres (com arm blaster)', 'dumbbell biceps curl (with arm blaster)', 'rosca-direta-com-halteres-com-arm-blaster', 'https://static.exercisedb.dev/media/nlJsbkW.gif', 'catalogo/rosca-direta-com-halteres-com-arm-blaster--nlJsbkW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-com-arm-blaster--nlJsbkW.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward.","Step:2 Hold your elbows near your torso and your upper arms stationary.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:13.016585+00', '2026-10-31 19:44:12.883+00'), ('NN8nSNT', 'Tríceps testa na polia alta com corda (acima da cabeça)', 'Cable Rope High Pulley Overhead Triceps Extension', 'triceps-testa-na-polia-alta-com-corda-acima-da-cabeca', 'https://static.exercisedb.dev/media/NN8nSNT.gif', 'catalogo/triceps-testa-na-polia-alta-com-corda-acima-da-cabeca--NN8nSNT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-na-polia-alta-com-corda-acima-da-cabeca--NN8nSNT.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Connect a rope to a high pulley and adjust the weight accordingly.","Step:2 Face the away from the pulley machine from a stable stance with feet about shoulder width.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:12.947642+00', '2026-10-31 19:44:12.803+00'), ('nnmCTLN', 'Mesa flexora ajoelhado na máquina', 'Machine Kneeling Leg Curl', 'mesa-flexora-ajoelhado-na-maquina', 'https://static.exercisedb.dev/media/nnmCTLN.gif', 'catalogo/mesa-flexora-ajoelhado-na-maquina--nnmCTLN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mesa-flexora-ajoelhado-na-maquina--nnmCTLN.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['posteriores de coxa'], ARRAY['glúteos'], '["Step:1 Set the machine to fit your body and select the desired weight.","Step:2 Get down on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:13.35501+00', '2026-10-31 19:44:13.213+00'), ('NNoHCEA', 'Agachamento completo no Smith', 'smith full squat', 'agachamento-completo-no-smith', 'https://static.exercisedb.dev/media/NNoHCEA.gif', 'catalogo/agachamento-completo-no-smith--NNoHCEA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-completo-no-smith--NNoHCEA.gif', ARRAY['coxas'], ARRAY['Smith'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Prepare the smith machine with the barbell at shoulder height.","Step:2 Stand and set your feet about shoulder width, toes slightly turned out.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:13.341747+00', '2026-10-31 19:44:13.199+00'), ('nqs5HGV', 'Agachamento unilateral (pistol)', 'Single Leg Squat (Pistol)', 'agachamento-unilateral-pistol', 'https://static.exercisedb.dev/media/nqs5HGV.gif', 'catalogo/agachamento-unilateral-pistol--nqs5HGV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-unilateral-pistol--nqs5HGV.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and arms extended in front of you.","Step:2 Before moving, lift your right foot off the ground and extend it forward.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Extend the free leg ahead of you as you squat on the standing leg, keeping its heel grounded.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:13.504909+00', '2026-10-31 19:44:13.363+00'), ('ns0SIbU', 'Supino inclinado com halteres', 'dumbbell incline bench press', 'supino-inclinado-com-halteres', 'https://static.exercisedb.dev/media/ns0SIbU.gif', 'catalogo/supino-inclinado-com-halteres--ns0SIbU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-halteres--ns0SIbU.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your feet planted and your back pressed firmly against the bench.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:13.581533+00', '2026-10-31 19:44:13.446+00'), ('Nu7jqFE', 'Remada sentada com elástico', 'Band Seated Straight Back Row', 'remada-sentada-com-elastico', 'https://static.exercisedb.dev/media/Nu7jqFE.gif', 'catalogo/remada-sentada-com-elastico--Nu7jqFE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-com-elastico--Nu7jqFE.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Take a seat on the floor with your legs extended and loop the resistance band around your feet.","Step:2 Take hold of the ends of the resistance band with your hands, palms facing each other.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:14.08108+00', '2026-10-31 19:44:13.947+00'), ('nuBF9MO', 'Elevação de pernas na barra em pike', 'hanging pike', 'elevacao-de-pernas-na-barra-em-pike', 'https://static.exercisedb.dev/media/nuBF9MO.gif', 'catalogo/elevacao-de-pernas-na-barra-em-pike--nuBF9MO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-na-barra-em-pike--nuBF9MO.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','deltoides'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your legs up toward the bar, keeping them straight.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:44:13.906436+00', '2026-10-31 19:44:13.77+00'), ('nUwVh7b', 'Levantamento terra com halteres', 'dumbbell deadlift', 'levantamento-terra-com-halteres', 'https://static.exercisedb.dev/media/nUwVh7b.gif', 'catalogo/levantamento-terra-com-halteres--nUwVh7b.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-com-halteres--nUwVh7b.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width, toes pointing forward.","Step:2 Take a dumbbell in each hand, palms facing your body, arms extended downwards.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:14.147535+00', '2026-10-31 19:44:14.017+00'), ('NvfE43H', 'Rosca concentrada na polia', 'cable concentration curl', 'rosca-concentrada-na-polia', 'https://static.exercisedb.dev/media/NvfE43H.gif', 'catalogo/rosca-concentrada-na-polia--NvfE43H.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-na-polia--NvfE43H.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench or chair with your feet planted and your knees soft.","Step:2 Take hold of the cable handle with palms facing up and rest your elbow against the inside of your thigh.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:14.158066+00', '2026-10-31 19:44:14.022+00'), ('nxW6BkN', 'Elevação com halteres no banco inclinado', 'dumbbell incline raise', 'elevacao-com-halteres-no-banco-inclinado', 'https://static.exercisedb.dev/media/nxW6BkN.gif', 'catalogo/elevacao-com-halteres-no-banco-inclinado--nxW6BkN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-com-halteres-no-banco-inclinado--nxW6BkN.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, resting on your thighs.","Step:2 Recline on the bench and raise the dumbbells to shoulder height, palms facing forward.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:14.764972+00', '2026-10-31 19:44:14.351+00'), ('NZ5Qqkz', 'Mergulho invertido (tríceps no banco)', 'reverse dip', 'mergulho-invertido-triceps-no-banco', 'https://static.exercisedb.dev/media/NZ5Qqkz.gif', 'catalogo/mergulho-invertido-triceps-no-banco--NZ5Qqkz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-invertido-triceps-no-banco--NZ5Qqkz.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set yourself between two parallel bars with your arms straight and your body straight.","Step:2 Before moving, lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:14.756999+00', '2026-10-31 19:44:14.612+00'), ('nZZZy9m', 'Remada alta na máquina', 'Machine High Row', 'remada-alta-na-maquina', 'https://static.exercisedb.dev/media/nZZZy9m.gif', 'catalogo/remada-alta-na-maquina--nZZZy9m.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-na-maquina--nZZZy9m.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides posteriores'], '["Step:1 Set the seat height and foot platform to a comfortable position.","Step:2 Take a seat on the machine with your chest against the pad and your feet flat on the foot platform.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:14.980179+00', '2026-10-31 19:44:14.848+00'), ('o17Jfkt', 'Supino inclinado na máquina', 'Machine Incline Chest Press', 'supino-inclinado-na-maquina', 'https://static.exercisedb.dev/media/o17Jfkt.gif', 'catalogo/supino-inclinado-na-maquina--o17Jfkt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-na-maquina--o17Jfkt.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the seat height and backrest angle on the leverage machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the backrest and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:14.833824+00', '2026-10-31 19:44:14.69+00'), ('o1HGDSq', 'Extensão lombar na bola suíça com mãos atrás da cabeça', 'exercise ball back extension with hands behind head', 'extensao-lombar-na-bola-suica-com-maos-atras-da-cabeca', 'https://static.exercisedb.dev/media/o1HGDSq.gif', 'catalogo/extensao-lombar-na-bola-suica-com-maos-atras-da-cabeca--o1HGDSq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar-na-bola-suica-com-maos-atras-da-cabeca--o1HGDSq.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the stability ball on the ground and Position yourself face down on top of it with your hips resting on the ball.","Step:2 Set your feet against a wall or other stable surface for support.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:14.784964+00', '2026-10-31 19:44:14.651+00'), ('o1ntciW', 'Rosca martelo com barra olímpica', 'olympic barbell hammer curl', 'rosca-martelo-com-barra-olimpica', 'https://static.exercisedb.dev/media/o1ntciW.gif', 'catalogo/rosca-martelo-com-barra-olimpica--o1ntciW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-com-barra-olimpica--o1ntciW.gif', ARRAY['braços'], ARRAY['barra olímpica'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold an Olympic barbell with palms facing down.","Step:2 Keep the barbell hanging at arm''s length ahead of your thighs, with your palms facing your body.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:15.370815+00', '2026-10-31 19:44:15.241+00'), ('O2K9Vb5', 'Paralelas para peito com pegada aberta', 'wide-grip chest dip on high parallel bars', 'paralelas-para-peito-com-pegada-aberta', 'https://static.exercisedb.dev/media/O2K9Vb5.gif', 'catalogo/paralelas-para-peito-com-pegada-aberta--O2K9Vb5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralelas-para-peito-com-pegada-aberta--O2K9Vb5.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set yourself on the parallel bars with your arms straight and your body suspended in the air.","Step:2 Tip forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:15.32922+00', '2026-10-31 19:44:15.191+00'), ('O4oIqQD', 'Remada em Pé Unilateral com Toalha (Peso Corporal)', 'Bodyweight Standing Single-Arm Row (With Towel)', 'remada-em-pe-unilateral-com-toalha-peso-corporal', 'https://static.exercisedb.dev/media/O4oIqQD.gif', 'catalogo/remada-em-pe-unilateral-com-toalha-peso-corporal--O4oIqQD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-unilateral-com-toalha-peso-corporal--O4oIqQD.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a towel with one hand.","Step:2 Bend forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:44:15.478729+00', '2026-10-31 19:44:15.338+00'), ('o5Jsk92', 'Crucifixo Unilateral com Halter no Banco', 'Dumbbell Single-Arm Bench Fly', 'crucifixo-unilateral-com-halter-no-banco', 'https://static.exercisedb.dev/media/o5Jsk92.gif', 'catalogo/crucifixo-unilateral-com-halter-no-banco--o5Jsk92.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-unilateral-com-halter-no-banco--o5Jsk92.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Take a seat on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Step:2 Recline on the bench, keeping the dumbbell pressed against your thigh.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:44:15.614879+00', '2026-10-31 19:44:15.473+00'), ('o8aOcrz', 'Tríceps Testa Inclinado no Smith', 'Smith Machine Incline Triceps Extension', 'triceps-testa-inclinado-no-smith', 'https://static.exercisedb.dev/media/o8aOcrz.gif', 'catalogo/triceps-testa-inclinado-no-smith--o8aOcrz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-inclinado-no-smith--o8aOcrz.gif', ARRAY['parte superior dos braços'], ARRAY['Smith machine'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Set the seat of the smith machine so that the bar is at shoulder height.","Step:2 Take a seat on the bench with your back against the pad and your feet planted.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:16.267513+00', '2026-10-31 19:44:16.137+00'), ('O8Aq69u', 'Rosca Scott Inversa com Halter', 'dumbbell reverse preacher curl', 'rosca-scott-inversa-com-halter', 'https://static.exercisedb.dev/media/O8Aq69u.gif', 'catalogo/rosca-scott-inversa-com-halter--O8Aq69u.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-inversa-com-halter--O8Aq69u.gif', ARRAY['parte superior dos braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with your upper arms resting on the pad and your chest against the support.","Step:2 Take a dumbbell in each hand with palms facing up.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:15.9173+00', '2026-10-31 19:44:15.784+00'), ('O8o7q4d', 'Supino com Halteres na Bola Suíça', 'dumbbell press on exercise ball', 'supino-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/O8o7q4d.gif', 'catalogo/supino-com-halteres-na-bola-suica--O8o7q4d.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-com-halteres-na-bola-suica--O8o7q4d.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with your feet planted and dumbbells in each hand, resting on your thighs.","Step:2 With control walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:16.521153+00', '2026-10-31 19:44:16.383+00'), ('O95afRA', 'Caminhada Monstro com Elástico', 'monster walk', 'caminhada-monstro-com-elastico', 'https://static.exercisedb.dev/media/O95afRA.gif', 'catalogo/caminhada-monstro-com-elastico--O95afRA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-monstro-com-elastico--O95afRA.gif', ARRAY['parte superior das pernas'], ARRAY['peso corporal','faixa elástica'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Set a resistance band around your ankles.","Step:2 Stand and set your feet about shoulder width and slightly bend your knees.","Step:3 Stand tall with the load secure and the shoulders level.","Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.","Step:5 Keep steps even and avoid leaning away from the load.","Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk."]', '2026-10-31 19:44:16.288789+00', '2026-10-31 19:44:16.158+00'), ('OaE7CpD', 'Moinho de Vento Duplo com Kettlebell', 'kettlebell double windmill', 'moinho-de-vento-duplo-com-kettlebell', 'https://static.exercisedb.dev/media/OaE7CpD.gif', 'catalogo/moinho-de-vento-duplo-com-kettlebell--OaE7CpD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/moinho-de-vento-duplo-com-kettlebell--OaE7CpD.gif', ARRAY['abdômen'], ARRAY['kettlebell'], ARRAY['abdominais'], ARRAY['deltoides','posteriores de coxa'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in your right hand.","Step:2 Reach your right arm overhead, keeping your eyes on the kettlebell.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:16.50738+00', '2026-10-31 19:44:16.363+00'), ('OAguZoG', 'Rosca Scott Pegada Martelo na Máquina', 'Machine Hammer Grip Preacher Curl', 'rosca-scott-pegada-martelo-na-maquina', 'https://static.exercisedb.dev/media/OAguZoG.gif', 'catalogo/rosca-scott-pegada-martelo-na-maquina--OAguZoG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-pegada-martelo-na-maquina--OAguZoG.gif', ARRAY['parte superior dos braços'], ARRAY['máquina articulada'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Set your upper arms on the preacher pad, ensuring your chest is pressed against it.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:16.83177+00', '2026-10-31 19:44:16.698+00'), ('obe5LMq', 'Tríceps Lateral com Elástico', 'band side triceps extension', 'triceps-lateral-com-elastico', 'https://static.exercisedb.dev/media/obe5LMq.gif', 'catalogo/triceps-lateral-com-elastico--obe5LMq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-lateral-com-elastico--obe5LMq.gif', ARRAY['parte superior dos braços'], ARRAY['faixa elástica'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold the band with both hands, palms facing down.","Step:2 Reach your arms straight out to the sides, keeping them parallel to the ground.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:17.212731+00', '2026-10-31 19:44:17.06+00'), ('ocYc6Db', 'Desenvolvimento Unilateral em Pé com Halter (Pegada Neutra)', 'Dumbbell Standing Single-Arm Palm In Press', 'desenvolvimento-unilateral-em-pe-com-halter-pegada-neutra', 'https://static.exercisedb.dev/media/ocYc6Db.gif', 'catalogo/desenvolvimento-unilateral-em-pe-com-halter-pegada-neutra--ocYc6Db.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-unilateral-em-pe-com-halter-pegada-neutra--ocYc6Db.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Step:2 Brace your trunk and Keep your spine in a comfortable neutral position.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:16.877665+00', '2026-10-31 19:44:16.748+00'), ('OeL23VY', 'Rosca Direta Sentado com Desenvolvimento de Ombros com Halteres', 'dumbbell seated biceps curl to shoulder press', 'rosca-direta-sentado-com-desenvolvimento-de-ombros-com-halteres', 'https://static.exercisedb.dev/media/OeL23VY.gif', 'catalogo/rosca-direta-sentado-com-desenvolvimento-de-ombros-com-halteres--OeL23VY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-sentado-com-desenvolvimento-de-ombros-com-halteres--OeL23VY.gif', ARRAY['parte superior dos braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in each hand with your palms facing forward and arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:17.118371+00', '2026-10-31 19:44:16.975+00'), ('oHg8eop', 'Arremesso Overhead com Medicine Ball no Chão (Slam)', 'medicine ball overhead slam', 'arremesso-overhead-com-medicine-ball-no-chao-slam', 'https://static.exercisedb.dev/media/oHg8eop.gif', 'catalogo/arremesso-overhead-com-medicine-ball-no-chao-slam--oHg8eop.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-overhead-com-medicine-ball-no-chao-slam--oHg8eop.gif', ARRAY['costas'], ARRAY['medicine ball'], ARRAY['parte superior das costas'], ARRAY['deltoides','core'], '["Step:1 Stand and set your feet about shoulder width, holding a medicine ball with both hands above your head.","Step:2 Brace your trunk and Keep your spine in a comfortable neutral position.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Follow through with the whole body while keeping control of the landing or catch.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:16.998823+00', '2026-10-31 19:44:16.868+00'), ('oHsrypV', 'Cadeira Adutora', 'Machine Seated Hip Adduction', 'cadeira-adutora', 'https://static.exercisedb.dev/media/oHsrypV.gif', 'catalogo/cadeira-adutora--oHsrypV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cadeira-adutora--oHsrypV.gif', ARRAY['parte superior das pernas'], ARRAY['máquina articulada'], ARRAY['adutores'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Set your feet on the footrests and Hold the handles for stability.","Step:3 Square the pelvis before moving the working leg.","Step:4 Draw the working leg inward against resistance without leaning sideways.","Step:5 Move only as far as the pelvis can remain steady.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:44:17.437362+00', '2026-10-31 19:44:17.305+00'), ('OIFMAp1', 'Remada Alta Lateral Unilateral na Máquina', 'Machine Single-Arm Lateral High Row', 'remada-alta-lateral-unilateral-na-maquina', 'https://static.exercisedb.dev/media/OIFMAp1.gif', 'catalogo/remada-alta-lateral-unilateral-na-maquina--OIFMAp1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-lateral-unilateral-na-maquina--OIFMAp1.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handle with one hand and Keep your spine in a comfortable neutral position.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:44:17.544074+00', '2026-10-31 19:44:17.403+00'), ('oLrKqDH', 'Corrida', 'run', 'corrida', 'https://static.exercisedb.dev/media/oLrKqDH.gif', 'catalogo/corrida--oLrKqDH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida--oLrKqDH.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing upright with your feet about hip width.","Step:2 Brace your trunk and keep your upper body relaxed.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:17.718874+00', '2026-10-31 19:44:17.582+00'), ('OM46QHm', 'Pull Through na Polia com Corda', 'cable pull through (with rope)', 'pull-through-na-polia-com-corda', 'https://static.exercisedb.dev/media/OM46QHm.gif', 'catalogo/pull-through-na-polia-com-corda--OM46QHm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pull-through-na-polia-com-corda--OM46QHm.gif', ARRAY['parte superior das pernas'], ARRAY['polia'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand facing away from the low pulley with the rope passing between your legs.","Step:2 Take hold of the rope attachment with both hands and step forward, creating tension in the cable.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:17.799734+00', '2026-10-31 19:44:17.667+00'), ('OmQ8w0p', 'Remada Rotacional na Polia com Pegada Supinada', 'cable palm rotational row', 'remada-rotacional-na-polia-com-pegada-supinada', 'https://static.exercisedb.dev/media/OmQ8w0p.gif', 'catalogo/remada-rotacional-na-polia-com-pegada-supinada--OmQ8w0p.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-rotacional-na-polia-com-pegada-supinada--OmQ8w0p.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Connect a handle to a cable machine at waist height.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:17.826138+00', '2026-10-31 19:44:17.683+00'), ('oMypNrz', 'Alongamento de Quadril no Rolo', 'roller hip stretch', 'alongamento-de-quadril-no-rolo', 'https://static.exercisedb.dev/media/oMypNrz.gif', 'catalogo/alongamento-de-quadril-no-rolo--oMypNrz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-quadril-no-rolo--oMypNrz.gif', ARRAY['parte superior das pernas'], ARRAY['rolo'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Begin by sitting on the ground with your legs extended in front of you.","Step:2 Set the roller under your glutes, just above your knees.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:18.330849+00', '2026-10-31 19:44:18.198+00'), ('oom75KC', 'Stiff com Halteres', 'Dumbbell Straight-Leg Deadlift', 'stiff-com-halteres', 'https://static.exercisedb.dev/media/oom75KC.gif', 'catalogo/stiff-com-halteres--oom75KC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stiff-com-halteres--oom75KC.gif', ARRAY['parte superior das pernas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 With your back straight and your core engaged, hinge at the hips and lower the dumbbells toward the ground, letting your torso to lean forward.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:18.721546+00', '2026-10-31 19:44:18.575+00'), ('OPqShYN', 'Extensão de quadril na máquina', 'Machine Hip Extension', 'extensao-de-quadril-na-maquina', 'https://static.exercisedb.dev/media/OPqShYN.gif', 'catalogo/extensao-de-quadril-na-maquina--OPqShYN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-quadril-na-maquina--OPqShYN.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['glúteos'], ARRAY['posteriores de coxa'], '["Step:1 Set the machine to fit your body and sit on it with your back against the backrest.","Step:2 Set your feet on the footrests and grip the handles for stability.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:18.790555+00', '2026-10-31 19:44:18.648+00'), ('OQ1otBN', 'Puxada lateral com cruzamento no cabo', 'Cable Crossover Lateral Pulldown', 'puxada-lateral-com-cruzamento-no-cabo', 'https://static.exercisedb.dev/media/OQ1otBN.gif', 'catalogo/puxada-lateral-com-cruzamento-no-cabo--OQ1otBN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-lateral-com-cruzamento-no-cabo--OQ1otBN.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['grande dorsal'], ARRAY['bíceps','romboides','deltoide posterior'], '["Step:1 Connect a cable handle to each side of a cable machine at shoulder height.","Step:2 Take your place in the middle of the machine with your feet about shoulder width.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:18.39538+00', '2026-10-31 19:44:18.261+00'), ('oQRJYkC', 'Alongamento lateral do pescoço com empurrão', 'side push neck stretch', 'alongamento-lateral-do-pescoco-com-empurrao', 'https://static.exercisedb.dev/media/oQRJYkC.gif', 'catalogo/alongamento-lateral-do-pescoco-com-empurrao--oQRJYkC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lateral-do-pescoco-com-empurrao--oQRJYkC.gif', ARRAY['pescoço'], ARRAY['peso corporal'], ARRAY['levantador da escápula'], ARRAY['trapézio','esternocleidomastoideo'], '["Step:1 Either stand or sit up straight with your shoulders relaxed.","Step:2 Tilt your head to the right, bringing your right ear toward your right shoulder.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:18.608101+00', '2026-10-31 19:44:18.456+00'), ('oR7O9LW', 'Agachamento com barra de joelhos', 'barbell squat (on knees)', 'agachamento-com-barra-de-joelhos', 'https://static.exercisedb.dev/media/oR7O9LW.gif', 'catalogo/agachamento-com-barra-de-joelhos--oR7O9LW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-barra-de-joelhos--oR7O9LW.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Begin by kneeling on the ground with your knees about hip width and your toes pointing forward.","Step:2 Set a barbell across your shoulders, gripping it with palms facing down and your hands just beyond shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:18.920545+00', '2026-10-31 19:44:18.785+00'), ('OrETs32', 'Extensão de quadril reversa no banco reto', 'reverse hyper on flat bench', 'extensao-de-quadril-reversa-no-banco-reto', 'https://static.exercisedb.dev/media/OrETs32.gif', 'catalogo/extensao-de-quadril-reversa-no-banco-reto--OrETs32.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-quadril-reversa-no-banco-reto--OrETs32.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Position yourself face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Step:2 Use the bench for stability.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Finish in a straight body line, before the lower back overarches.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:18.949813+00', '2026-10-31 19:44:18.818+00'), ('oROuvrX', 'Remada unilateral na máquina', 'Machine Unilateral Row', 'remada-unilateral-na-maquina', 'https://static.exercisedb.dev/media/oROuvrX.gif', 'catalogo/remada-unilateral-na-maquina--oROuvrX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-unilateral-na-maquina--oROuvrX.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and Keep your spine in a comfortable neutral position.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:19.247177+00', '2026-10-31 19:44:19.105+00'), ('osdXT3K', 'Push press unilateral com kettlebell', 'Kettlebell Single-Arm Push Press', 'push-press-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/osdXT3K.gif', 'catalogo/push-press-unilateral-com-kettlebell--osdXT3K.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/push-press-unilateral-com-kettlebell--osdXT3K.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand at shoulder level.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:19.629118+00', '2026-10-31 19:44:19.491+00'), ('OTgkHwR', 'Tríceps testa declinado com halteres', 'dumbbell decline triceps extension', 'triceps-testa-declinado-com-halteres', 'https://static.exercisedb.dev/media/OTgkHwR.gif', 'catalogo/triceps-testa-declinado-com-halteres--OTgkHwR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-declinado-com-halteres--OTgkHwR.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Step:2 Reach your arms fully, keeping your elbows close to your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:19.67494+00', '2026-10-31 19:44:19.536+00'), ('otqIxU4', 'Rosca bíceps deitado no cabo', 'Cable Lying Biceps Curl', 'rosca-biceps-deitado-no-cabo', 'https://static.exercisedb.dev/media/otqIxU4.gif', 'catalogo/rosca-biceps-deitado-no-cabo--otqIxU4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-deitado-no-cabo--otqIxU4.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Connect a straight bar to a low pulley cable machine.","Step:2 Lie face up on a flat bench with your feet planted.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:19.582869+00', '2026-10-31 19:44:19.449+00'), ('OUQ0ZyW', 'Encolhimento no Smith', 'smith shrug', 'encolhimento-no-smith', 'https://static.exercisedb.dev/media/OUQ0ZyW.gif', 'catalogo/encolhimento-no-smith--OUQ0ZyW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-no-smith--OUQ0ZyW.gif', ARRAY['costas'], ARRAY['Smith machine'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Hold the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:44:19.885026+00', '2026-10-31 19:44:19.726+00'), ('OVIKwsd', 'Tríceps testa inclinado com halteres', 'dumbbell incline triceps extension', 'triceps-testa-inclinado-com-halteres', 'https://static.exercisedb.dev/media/OVIKwsd.gif', 'catalogo/triceps-testa-inclinado-com-halteres--OVIKwsd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-inclinado-com-halteres--OVIKwsd.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, palms facing inwards.","Step:2 Reach your arms fully overhead, keeping your elbows close to your head.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:19.856889+00', '2026-10-31 19:44:19.717+00'), ('OVLmUuL', 'Supino inclinado com halteres pegada neutra', 'dumbbell incline palm-in press', 'supino-inclinado-com-halteres-pegada-neutra', 'https://static.exercisedb.dev/media/OVLmUuL.gif', 'catalogo/supino-inclinado-com-halteres-pegada-neutra--OVLmUuL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-com-halteres-pegada-neutra--OVLmUuL.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with a dumbbell in each hand, palms facing each other.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:20.472527+00', '2026-10-31 19:44:20.336+00'), ('OVTZ65k', 'Rosca direta em pé com barra W pegada aberta', 'EZ-Barbell Standing Wide-Grip Biceps Curl', 'rosca-direta-em-pe-com-barra-w-pegada-aberta', 'https://static.exercisedb.dev/media/OVTZ65k.gif', 'catalogo/rosca-direta-em-pe-com-barra-w-pegada-aberta--OVTZ65k.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-em-pe-com-barra-w-pegada-aberta--OVTZ65k.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up, hands wider than about shoulder width.","Step:2 Hold your elbows near your torso and your upper arms stationary throughout the movement.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:20.198048+00', '2026-10-31 19:44:20.067+00'), ('OxJk1fg', 'Tríceps pulley com barra V e arm blaster', 'cable triceps pushdown (v-bar) (with arm blaster)', 'triceps-pulley-com-barra-v-e-arm-blaster', 'https://static.exercisedb.dev/media/OxJk1fg.gif', 'catalogo/triceps-pulley-com-barra-v-e-arm-blaster--OxJk1fg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-pulley-com-barra-v-e-arm-blaster--OxJk1fg.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Connect a v-bar attachment to the cable machine at the highest setting.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the elbows close to the body instead of letting the shoulders swing.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:44:20.276085+00', '2026-10-31 19:44:20.136+00'), ('OYFhXVD', 'Barra fixa pegada aberta por trás da nuca', 'Wide-Grip Rear Pull-Up', 'barra-fixa-pegada-aberta-por-tras-da-nuca', 'https://static.exercisedb.dev/media/OYFhXVD.gif', 'catalogo/barra-fixa-pegada-aberta-por-tras-da-nuca--OYFhXVD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-pegada-aberta-por-tras-da-nuca--OYFhXVD.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['grande dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with a wide overhand grip, hands just beyond shoulder width.","Step:2 Suspend yourself from the bar with your arms straight and your body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull up with control, keeping the head neutral and the elbows moving down beside the torso.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:20.350659+00', '2026-10-31 19:44:20.21+00'), ('OyoZ3Pu', 'Abdominal com recolhimento de pernas no banco reto', 'leg pull in flat bench', 'abdominal-com-recolhimento-de-pernas-no-banco-reto', 'https://static.exercisedb.dev/media/OyoZ3Pu.gif', 'catalogo/abdominal-com-recolhimento-de-pernas-no-banco-reto--OyoZ3Pu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-recolhimento-de-pernas-no-banco-reto--OyoZ3Pu.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Take a seat on a flat bench with your legs extended straight out in front of you.","Step:2 Set your hands on the bench beside your hips for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:44:21.008878+00', '2026-10-31 19:44:20.869+00'), ('oZjMu1t', 'Virada de pneu', 'tire flip', 'virada-de-pneu', 'https://static.exercisedb.dev/media/oZjMu1t.gif', 'catalogo/virada-de-pneu--oZjMu1t.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/virada-de-pneu--oZjMu1t.gif', ARRAY['coxas'], ARRAY['pneu'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','core'], '["Step:1 Stand and set your feet about shoulder width, facing the tire.","Step:2 Before moving, bend your knees and hinge at the hips, lowering into a squat position.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:20.87231+00', '2026-10-31 19:44:20.74+00'), ('P14Dz9D', 'Crucifixo inclinado unilateral no cabo na bola suíça', 'Cable Single-Arm Incline Fly On Exercise Ball', 'crucifixo-inclinado-unilateral-no-cabo-na-bola-suica', 'https://static.exercisedb.dev/media/P14Dz9D.gif', 'catalogo/crucifixo-inclinado-unilateral-no-cabo-na-bola-suica--P14Dz9D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-unilateral-no-cabo-na-bola-suica--P14Dz9D.gif', ARRAY['peito'], ARRAY['cabo','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back against an incline bench.","Step:2 Take a cable handle in one hand with your arm extended and palm facing inward.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:44:20.92953+00', '2026-10-31 19:44:20.787+00'), ('p195zsJ', 'Toque nos pés com as duas pernas', 'Two Toe Touch', 'toque-nos-pes-com-as-duas-pernas', 'https://static.exercisedb.dev/media/p195zsJ.gif', 'catalogo/toque-nos-pes-com-as-duas-pernas--p195zsJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/toque-nos-pes-com-as-duas-pernas--p195zsJ.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width and your arms extended out to the sides.","Step:2 Bend forward at the waist, with your spine steady and your knees soft.","Step:3 Soften the knees and let the hips start the fold.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Keep the movement controlled throughout the range.","Step:6 Hold briefly at a comfortable depth, then rise by extending the hips."]', '2026-10-31 19:44:21.165088+00', '2026-10-31 19:44:21.017+00'), ('P2lNrGL', 'Rosca Scott no cabo', 'cable preacher curl', 'rosca-scott-no-cabo', 'https://static.exercisedb.dev/media/P2lNrGL.gif', 'catalogo/rosca-scott-no-cabo--P2lNrGL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-no-cabo--P2lNrGL.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Set the cable machine so that the preacher curl pad is at chest height.","Step:2 Take a seat on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with palms facing up.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:21.426882+00', '2026-10-31 19:44:21.295+00'), ('P2nRiUa', 'Rosca Scott Zottman em pé com halteres', 'dumbbell standing zottman preacher curl', 'rosca-scott-zottman-em-pe-com-halteres', 'https://static.exercisedb.dev/media/P2nRiUa.gif', 'catalogo/rosca-scott-zottman-em-pe-com-halteres--P2nRiUa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-zottman-em-pe-com-halteres--P2nRiUa.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward.","Step:2 Set your upper arms against the preacher bench and keep your elbows soft.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl palms-up, turn the palms down at the top, and lower with that overhand grip.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:21.452262+00', '2026-10-31 19:44:21.313+00'), ('P5p0j8B', 'Crucifixo inverso em pé com cruzamento alto no cabo', 'Cable Standing Crossover High Reverse Fly', 'crucifixo-inverso-em-pe-com-cruzamento-alto-no-cabo', 'https://static.exercisedb.dev/media/P5p0j8B.gif', 'catalogo/crucifixo-inverso-em-pe-com-cruzamento-alto-no-cabo--P5p0j8B.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-em-pe-com-cruzamento-alto-no-cabo--P5p0j8B.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['trapézio','romboides','deltoide posterior'], '["Step:1 Connect a D-handle to each side of a cable machine at shoulder height.","Step:2 Take your place in the middle of the cable machine with your feet about shoulder width.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:21.448087+00', '2026-10-31 19:44:21.308+00'), ('p9cCe2r', 'Spell caster com halter', 'spell caster', 'spell-caster-com-halter', 'https://static.exercisedb.dev/media/p9cCe2r.gif', 'catalogo/spell-caster-com-halter--p9cCe2r.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/spell-caster-com-halter--p9cCe2r.gif', ARRAY['abdômen'], ARRAY['halter'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand.","Step:2 Bend your knees slightly and hinge forward at the waist, with your spine steady.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:21.827737+00', '2026-10-31 19:44:21.688+00'), ('P9GFBME', 'Flexão de braço spider crawl', 'spider crawl push up', 'flexao-de-braco-spider-crawl', 'https://static.exercisedb.dev/media/P9GFBME.gif', 'catalogo/flexao-de-braco-spider-crawl--P9GFBME.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-spider-crawl--P9GFBME.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['core','peitorais','deltoides'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.","Step:2 Bring your right knee toward your right elbow, keeping it off the ground.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:21.974806+00', '2026-10-31 19:44:21.829+00'), ('P9ZRyLT', 'Crucifixo com halteres (hyght)', 'hyght dumbbell fly', 'crucifixo-com-halteres-hyght', 'https://static.exercisedb.dev/media/P9ZRyLT.gif', 'catalogo/crucifixo-com-halteres-hyght--P9ZRyLT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-com-halteres-hyght--P9ZRyLT.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other.","Step:2 Reach your arms straight up over your chest, with a slight bend in your elbows.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:22.08928+00', '2026-10-31 19:44:21.945+00'), ('PAgTVaK', 'Mergulho para peito assistido na máquina (ajoelhado)', 'assisted chest dip (kneeling)', 'mergulho-para-peito-assistido-na-maquina-ajoelhado', 'https://static.exercisedb.dev/media/PAgTVaK.gif', 'catalogo/mergulho-para-peito-assistido-na-maquina-ajoelhado--PAgTVaK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-para-peito-assistido-na-maquina-ajoelhado--PAgTVaK.gif', ARRAY['peito'], ARRAY['máquina de alavanca'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the machine to your desired height and secure your knees on the pad.","Step:2 Hold the handles with your palms facing down and your arms straight.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:21.988189+00', '2026-10-31 19:44:21.853+00'), ('pAIWRGu', 'Bicicleta de braços', 'hands bike', 'bicicleta-de-bracos', 'https://static.exercisedb.dev/media/pAIWRGu.gif', 'catalogo/bicicleta-de-bracos--pAIWRGu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/bicicleta-de-bracos--pAIWRGu.gif', ARRAY['peito'], ARRAY['ergômetro de membros superiores'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the seat height and handlebar position to a comfortable level.","Step:2 Take a seat on the ergometer with your back straight and feet on the pedals.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:22.337451+00', '2026-10-31 19:44:22.198+00'), ('PbzNu7c', 'Elevação em Y com halteres no banco inclinado', 'dumbbell incline y-raise', 'elevacao-em-y-com-halteres-no-banco-inclinado', 'https://static.exercisedb.dev/media/PbzNu7c.gif', 'catalogo/elevacao-em-y-com-halteres-no-banco-inclinado--PbzNu7c.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-em-y-com-halteres-no-banco-inclinado--PbzNu7c.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['parte superior das costas'], ARRAY['deltoides','deltoides posteriores'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Step:2 Tip forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms diagonally into a Y shape while keeping the shoulders away from your ears.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:22.731279+00', '2026-10-31 19:44:22.602+00'), ('PcPe0P5', 'Rosca martelo scott na polia com corda', 'cable rope hammer preacher curl', 'rosca-martelo-scott-na-polia-com-corda', 'https://static.exercisedb.dev/media/PcPe0P5.gif', 'catalogo/rosca-martelo-scott-na-polia-com-corda--PcPe0P5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-scott-na-polia-com-corda--PcPe0P5.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Connect a rope attachment to a low pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:22.630786+00', '2026-10-31 19:44:22.499+00'), ('PDaMuyV', 'Supino inclinado unilateral com halter', 'Dumbbell Single-Arm Incline Chest Press', 'supino-inclinado-unilateral-com-halter', 'https://static.exercisedb.dev/media/PDaMuyV.gif', 'catalogo/supino-inclinado-unilateral-com-halter--PDaMuyV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-unilateral-com-halter--PDaMuyV.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the incline bench to a 45-degree angle.","Step:2 Take a seat on the bench with your back against the pad and feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:23.047688+00', '2026-10-31 19:44:22.914+00'), ('PdmaD0N', 'Tríceps em pé com halter', 'dumbbell standing triceps extension', 'triceps-em-pe-com-halter', 'https://static.exercisedb.dev/media/PdmaD0N.gif', 'catalogo/triceps-em-pe-com-halter--PdmaD0N.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-em-pe-com-halter--PdmaD0N.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand.","Step:2 Before moving, raise the dumbbell overhead, keeping your arm straight.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:23.40028+00', '2026-10-31 19:44:23.26+00'), ('peAeMR3', 'Desenvolvimento de ombros com elástico', 'band shoulder press', 'desenvolvimento-de-ombros-com-elastico', 'https://static.exercisedb.dev/media/peAeMR3.gif', 'catalogo/desenvolvimento-de-ombros-com-elastico--peAeMR3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-de-ombros-com-elastico--peAeMR3.gif', ARRAY['ombros'], ARRAY['elástico de resistência'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and place the band under your feet.","Step:2 Take hold of the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:23.174264+00', '2026-10-31 19:44:23.042+00'), ('PERjVm8', 'Extensão lombar na bola suíça com braços estendidos', 'exercise ball back extension with arms extended', 'extensao-lombar-na-bola-suica-com-bracos-estendidos', 'https://static.exercisedb.dev/media/PERjVm8.gif', 'catalogo/extensao-lombar-na-bola-suica-com-bracos-estendidos--PERjVm8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar-na-bola-suica-com-bracos-estendidos--PERjVm8.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the stability ball on the ground and Position yourself face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Step:2 Reach your arms straight out in front of you, with your palms facing down.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:23.223423+00', '2026-10-31 19:44:23.083+00'), ('PG1kcIb', 'Supino inclinado pegada neutra com halteres', 'dumbbell incline hammer press', 'supino-inclinado-pegada-neutra-com-halteres', 'https://static.exercisedb.dev/media/PG1kcIb.gif', 'catalogo/supino-inclinado-pegada-neutra-com-halteres--PG1kcIb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-pegada-neutra-com-halteres--PG1kcIb.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Step:2 Recline on the bench and position the dumbbells at shoulder level with your palms facing each other.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:23.605488+00', '2026-10-31 19:44:23.474+00'), ('pH2x2jj', 'Crucifixo com halteres na bola suíça com uma perna', 'Dumbbell Single-Leg Fly On Exercise Ball', 'crucifixo-com-halteres-na-bola-suica-com-uma-perna', 'https://static.exercisedb.dev/media/pH2x2jj.gif', 'catalogo/crucifixo-com-halteres-na-bola-suica-com-uma-perna--pH2x2jj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-com-halteres-na-bola-suica-com-uma-perna--pH2x2jj.gif', ARRAY['peito'], ARRAY['halter','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an exercise ball with a dumbbell in each hand, palms facing each other.","Step:2 Set one foot on the ground and extend the other leg straight out in front of you.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:44:23.782118+00', '2026-10-31 19:44:23.643+00'), ('pj0X0tF', 'Elevação de pernas retas na barra fixa', 'Hanging Straight-Leg Hip Raise', 'elevacao-de-pernas-retas-na-barra-fixa', 'https://static.exercisedb.dev/media/pj0X0tF.gif', 'catalogo/elevacao-de-pernas-retas-na-barra-fixa--pj0X0tF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-retas-na-barra-fixa--pj0X0tF.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your legs up in front of you until they are parallel to the ground.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:44:24.047517+00', '2026-10-31 19:44:23.919+00'), ('Pjbc0Kt', 'Elevação pélvica com elástico de joelhos', 'Band Hip Thrusts On Knees', 'elevacao-pelvica-com-elastico-de-joelhos', 'https://static.exercisedb.dev/media/Pjbc0Kt.gif', 'catalogo/elevacao-pelvica-com-elastico-de-joelhos--Pjbc0Kt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-pelvica-com-elastico-de-joelhos--Pjbc0Kt.gif', ARRAY['coxas'], ARRAY['elástico de resistência'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Begin by kneeling on the ground with your knees about hip width and your feet flexed.","Step:2 Loop the resistance band around your thighs, just above your knees.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:24.026346+00', '2026-10-31 19:44:23.889+00'), ('PkCN2lv', 'Front lever', 'front lever', 'front-lever', 'https://static.exercisedb.dev/media/PkCN2lv.gif', 'catalogo/front-lever--PkCN2lv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/front-lever--PkCN2lv.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['latíssimo do dorso','deltoides','antebraços'], '["Step:1 Begin by hanging from a pull-up bar with palms facing down, hands about shoulder width.","Step:2 Brace your trunk and pull your shoulder blades down and back.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:24.322693+00', '2026-10-31 19:44:24.193+00'), ('pkSoCW9', 'Agachamento Jefferson com barra', 'barbell jefferson squat', 'agachamento-jefferson-com-barra', 'https://static.exercisedb.dev/media/pkSoCW9.gif', 'catalogo/agachamento-jefferson-com-barra--pkSoCW9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-jefferson-com-barra--pkSoCW9.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and toes slightly turned out.","Step:2 Take hold of the barbell with palms facing down, resting it on the front of your body, just below your waist.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:24.385096+00', '2026-10-31 19:44:24.251+00'), ('pM07UxU', 'Muscle up com kipping', 'kipping muscle up', 'muscle-up-com-kipping', 'https://static.exercisedb.dev/media/pM07UxU.gif', 'catalogo/muscle-up-com-kipping--pM07UxU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/muscle-up-com-kipping--pM07UxU.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','tríceps','deltoides','core'], '["Step:1 Begin by hanging from a pull-up bar with palms facing down, hands just beyond shoulder width.","Step:2 Brace your trunk and use a swinging motion to generate momentum.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:24.278739+00', '2026-10-31 19:44:24.147+00'), ('PM1PZjg', 'Afundo com salto', 'lunge with jump', 'afundo-com-salto', 'https://static.exercisedb.dev/media/PM1PZjg.gif', 'catalogo/afundo-com-salto--PM1PZjg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-com-salto--PM1PZjg.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width.","Step:2 Step forward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:24.97562+00', '2026-10-31 19:44:24.842+00'), ('pmnrOp0', 'Puxada unilateral ajoelhado com elástico', 'Band Kneeling Single-Arm Pulldown', 'puxada-unilateral-ajoelhado-com-elastico', 'https://static.exercisedb.dev/media/pmnrOp0.gif', 'catalogo/puxada-unilateral-ajoelhado-com-elastico--pmnrOp0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-unilateral-ajoelhado-com-elastico--pmnrOp0.gif', ARRAY['costas'], ARRAY['elástico de resistência'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides'], '["Step:1 Connect the band to a sturdy anchor point above your head.","Step:2 Kneel and hold the band with one hand, palm facing down.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it."]', '2026-10-31 19:44:24.794117+00', '2026-10-31 19:44:24.649+00'), ('PNtsX17', 'Remada alta sentada na polia com pegada supinada e costas retas', 'cable reverse-grip straight back seated high row', 'remada-alta-sentada-na-polia-com-pegada-supinada-e-costas-retas', 'https://static.exercisedb.dev/media/PNtsX17.gif', 'catalogo/remada-alta-sentada-na-polia-com-pegada-supinada-e-costas-retas--PNtsX17.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-sentada-na-polia-com-pegada-supinada-e-costas-retas--PNtsX17.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the seat facing the cable machine with your feet planted.","Step:2 Hold the cable attachment with palms facing up, and your hands about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:24.925744+00', '2026-10-31 19:44:24.794+00'), ('PnZJIrk', 'Paralelas assistida com pegada aberta para peito (ajoelhado)', 'assisted wide-grip chest dip (kneeling)', 'paralelas-assistida-com-pegada-aberta-para-peito-ajoelhado', 'https://static.exercisedb.dev/media/PnZJIrk.gif', 'catalogo/paralelas-assistida-com-pegada-aberta-para-peito-ajoelhado--PnZJIrk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralelas-assistida-com-pegada-aberta-para-peito-ajoelhado--PnZJIrk.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the machine to your desired height and secure your knees on the pad.","Step:2 Hold the handles with a wide grip and keep your elbows soft.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:24.947161+00', '2026-10-31 19:44:24.806+00'), ('pP8wP2P', 'Supino com halteres pegada neutra', 'dumbbell neutral grip bench press', 'supino-com-halteres-pegada-neutra', 'https://static.exercisedb.dev/media/pP8wP2P.gif', 'catalogo/supino-com-halteres-pegada-neutra--pP8wP2P.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-com-halteres-pegada-neutra--pP8wP2P.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Take a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:25.348432+00', '2026-10-31 19:44:25.208+00'), ('pQ0Mx1Z', 'Bandeira humana', 'flag', 'bandeira-humana', 'https://static.exercisedb.dev/media/pQ0Mx1Z.gif', 'catalogo/bandeira-humana--pQ0Mx1Z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/bandeira-humana--pQ0Mx1Z.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','deltoides'], '["Step:1 Begin by gripping a vertical pole with both hands, palms facing each other, and arms straight.","Step:2 Brace your trunk and lift your legs off the ground, keeping them straight.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:25.290899+00', '2026-10-31 19:44:25.159+00'), ('PQ2AtC3', 'Abdominal com elevação de pernas na máquina sentado', 'Machine Seated Leg Raise Crunch', 'abdominal-com-elevacao-de-pernas-na-maquina-sentado', 'https://static.exercisedb.dev/media/PQ2AtC3.gif', 'catalogo/abdominal-com-elevacao-de-pernas-na-maquina-sentado--PQ2AtC3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-elevacao-de-pernas-na-maquina-sentado--PQ2AtC3.gif', ARRAY['abdômen'], ARRAY['máquina articulada'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Take a seat on the leverage machine with your back against the backrest and your feet on the footrests.","Step:2 Hold the handles or sidebars for stability.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:25.607369+00', '2026-10-31 19:44:25.477+00'), ('PQcUlDi', 'Crucifixo inverso deitado na polia', 'cable supine reverse fly', 'crucifixo-inverso-deitado-na-polia', 'https://static.exercisedb.dev/media/PQcUlDi.gif', 'catalogo/crucifixo-inverso-deitado-na-polia--PQcUlDi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-deitado-na-polia--PQcUlDi.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Connect a D-handle to a low pulley cable machine and Position yourself face down on a flat bench.","Step:2 Hold the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:25.58667+00', '2026-10-31 19:44:25.451+00'), ('PQStVXH', 'Remada alta na polia', 'cable upper row', 'remada-alta-na-polia', 'https://static.exercisedb.dev/media/PQStVXH.gif', 'catalogo/remada-alta-na-polia--PQStVXH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-na-polia--PQStVXH.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Fit a straight bar to the pulley at chest level.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:25.518786+00', '2026-10-31 19:44:25.387+00'), ('Pr9Rhf4', 'Crucifixo em pé na polia', 'cable standing fly', 'crucifixo-em-pe-na-polia', 'https://static.exercisedb.dev/media/Pr9Rhf4.gif', 'catalogo/crucifixo-em-pe-na-polia--Pr9Rhf4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-em-pe-na-polia--Pr9Rhf4.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Connect the handles to the cables at chest height.","Step:2 Stand and set your feet about shoulder width, turned away from the cable machine.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:26.129617+00', '2026-10-31 19:44:25.997+00'), ('prbWx1D', 'Crucifixo inverso com halteres e rotação', 'dumbbell rotation reverse fly', 'crucifixo-inverso-com-halteres-e-rotacao', 'https://static.exercisedb.dev/media/prbWx1D.gif', 'catalogo/crucifixo-inverso-com-halteres-e-rotacao--prbWx1D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres-e-rotacao--prbWx1D.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing inwards.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:25.932935+00', '2026-10-31 19:44:25.793+00'), ('PrQbjvB', 'Flexão para corrida', 'push to run', 'flexao-para-corrida', 'https://static.exercisedb.dev/media/PrQbjvB.gif', 'catalogo/flexao-para-corrida--PrQbjvB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-para-corrida--PrQbjvB.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin in a push-up position with your hands about shoulder width and your body in a straight line.","Step:2 Lower your chest toward the ground by bending your elbows, keeping your body straight.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:26.191794+00', '2026-10-31 19:44:26.061+00'), ('PskORrA', 'Pulldown na polia com braços estendidos', 'cable pushdown (straight arm)', 'pulldown-na-polia-com-bracos-estendidos', 'https://static.exercisedb.dev/media/PskORrA.gif', 'catalogo/pulldown-na-polia-com-bracos-estendidos--PskORrA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pulldown-na-polia-com-bracos-estendidos--PskORrA.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['tríceps','deltoides'], '["Step:1 Connect a straight bar to a high pulley cable machine.","Step:2 Face the machine with your feet about shoulder width and a slight bend in your knees.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the elbows close to the body instead of letting the shoulders swing.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:44:26.091314+00', '2026-10-31 19:44:25.962+00'), ('PSlvNMs', 'Flexão com queda e carga', 'weighted drop push up', 'flexao-com-queda-e-carga', 'https://static.exercisedb.dev/media/PSlvNMs.gif', 'catalogo/flexao-com-queda-e-carga--PSlvNMs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-com-queda-e-carga--PSlvNMs.gif', ARRAY['peito'], ARRAY['com peso'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your feet together.","Step:2 Lower your chest toward the ground, keeping your elbows close to your body.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:26.647886+00', '2026-10-31 19:44:26.518+00'), ('PsVS1QP', 'Recepção e arremesso de medicine ball acima da cabeça', 'medicine ball catch and overhead throw', 'recepcao-e-arremesso-de-medicine-ball-acima-da-cabeca', 'https://static.exercisedb.dev/media/PsVS1QP.gif', 'catalogo/recepcao-e-arremesso-de-medicine-ball-acima-da-cabeca--PsVS1QP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/recepcao-e-arremesso-de-medicine-ball-acima-da-cabeca--PsVS1QP.gif', ARRAY['costas'], ARRAY['medicine ball'], ARRAY['latíssimo do dorso'], ARRAY['deltoides','core'], '["Step:1 Stand and set your feet about shoulder width, holding a medicine ball in both hands at chest level.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Brace and settle into a stable starting position.","Step:4 Move through the intended path under control, keeping the joints aligned with the resistance.","Step:5 Keep the movement controlled throughout the range.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:44:26.796392+00', '2026-10-31 19:44:26.665+00'), ('pvBMLHA', 'Flexão de braço com protração escapular', 'push-up plus', 'flexao-de-braco-com-protracao-escapular', 'https://static.exercisedb.dev/media/pvBMLHA.gif', 'catalogo/flexao-de-braco-com-protracao-escapular--pvBMLHA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-protracao-escapular--pvBMLHA.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your body in a straight line from head to heels.","Step:2 Lower your body toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:27.178331+00', '2026-10-31 19:44:26.805+00'), ('pwt0pnM', 'Remada alta sentada na polia com barra V', 'cable seated high row (v-bar)', 'remada-alta-sentada-na-polia-com-barra-v', 'https://static.exercisedb.dev/media/pwt0pnM.gif', 'catalogo/remada-alta-sentada-na-polia-com-barra-v--pwt0pnM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-sentada-na-polia-com-barra-v--pwt0pnM.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Take a seat on the cable machine with your feet planted and your knees soft.","Step:2 Hold the v-bar attachment with palms facing down, palms facing each other, and your hands about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:26.707042+00', '2026-10-31 19:44:26.566+00'), ('pX9Elbe', 'Arremesso de medicine ball do peito com saída em corrida', 'medicine ball chest push with run release', 'arremesso-de-medicine-ball-do-peito-com-saida-em-corrida', 'https://static.exercisedb.dev/media/pX9Elbe.gif', 'catalogo/arremesso-de-medicine-ball-do-peito-com-saida-em-corrida--pX9Elbe.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-de-medicine-ball-do-peito-com-saida-em-corrida--pX9Elbe.gif', ARRAY['peito'], ARRAY['medicine ball'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Stand and set your feet about shoulder width, holding a medicine ball at chest level.","Step:2 Move forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","Step:3 Set a firm stance and leave enough clear space for the ball to travel.","Step:4 Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.","Step:5 Follow through with the whole body while keeping control of the landing or catch.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:44:26.896722+00', '2026-10-31 19:44:26.764+00'), ('PXTIwgu', 'Balanço de braços suspenso com pernas estendidas', 'Arm Slingers Hanging Straight-Legs', 'balanco-de-bracos-suspenso-com-pernas-estendidas', 'https://static.exercisedb.dev/media/PXTIwgu.gif', 'catalogo/balanco-de-bracos-suspenso-com-pernas-estendidas--PXTIwgu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/balanco-de-bracos-suspenso-com-pernas-estendidas--PXTIwgu.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','costas'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your legs straight down.","Step:2 Brace your trunk and lift your legs up in front of you until they are parallel to the ground.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:44:27.256814+00', '2026-10-31 19:44:27.124+00'), ('py1HSzx', 'Afundo lateral com barra', 'barbell lateral lunge', 'afundo-lateral-com-barra', 'https://static.exercisedb.dev/media/py1HSzx.gif', 'catalogo/afundo-lateral-com-barra--py1HSzx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-lateral-com-barra--py1HSzx.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a barbell across your upper back.","Step:2 Step wide to the side with your right foot, keeping your left foot planted.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:27.320168+00', '2026-10-31 19:44:27.182+00'), ('PzNxakt', 'Alongamento de panturrilha com as mãos na parede', 'calf push stretch with hands against wall', 'alongamento-de-panturrilha-com-as-maos-na-parede', 'https://static.exercisedb.dev/media/PzNxakt.gif', 'catalogo/alongamento-de-panturrilha-com-as-maos-na-parede--PzNxakt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-panturrilha-com-as-maos-na-parede--PzNxakt.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Face a wall with your feet about hip width.","Step:2 Set your hands against the wall at shoulder height.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:27.318956+00', '2026-10-31 19:44:27.179+00'), ('PzQanLE', 'Desenvolvimento de ombros na polia', 'cable shoulder press', 'desenvolvimento-de-ombros-na-polia', 'https://static.exercisedb.dev/media/PzQanLE.gif', 'catalogo/desenvolvimento-de-ombros-na-polia--PzQanLE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-de-ombros-na-polia--PzQanLE.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Set the cable machine so that the handles are at shoulder height.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:27.56037+00', '2026-10-31 19:44:27.423+00'), ('pZwUsKB', 'Alongamento cruz de ferro', 'iron cross stretch', 'alongamento-cruz-de-ferro', 'https://static.exercisedb.dev/media/pZwUsKB.gif', 'catalogo/alongamento-cruz-de-ferro--pZwUsKB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-cruz-de-ferro--pZwUsKB.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Settle onto your back with your arms extended out to the sides.","Step:2 Raise your legs up toward the ceiling, keeping them straight.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Open the arms out to the sides to form a T, then bring them back under control.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:27.759849+00', '2026-10-31 19:44:27.621+00'), ('q2ADGqV', 'Abdominal lateral na polia', 'cable side crunch', 'abdominal-lateral-na-polia', 'https://static.exercisedb.dev/media/q2ADGqV.gif', 'catalogo/abdominal-lateral-na-polia--q2ADGqV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-lateral-na-polia--q2ADGqV.gif', ARRAY['abdômen'], ARRAY['polia'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Connect a cable handle to a low pulley and stand sideways to the machine.","Step:2 Hold the handle with the hand furthest from the machine and place your other hand on your hip.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:27.7236+00', '2026-10-31 19:44:27.591+00'), ('Q2Eu1Ax', 'Pullover deitado na polia com corda', 'cable lying extension pullover (with rope attachment)', 'pullover-deitado-na-polia-com-corda', 'https://static.exercisedb.dev/media/Q2Eu1Ax.gif', 'catalogo/pullover-deitado-na-polia-com-corda--Q2Eu1Ax.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-deitado-na-polia-com-corda--Q2Eu1Ax.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['tríceps','deltoides'], '["Step:1 Connect a rope to a cable machine and set the pulley at the highest position.","Step:2 Get onto a bench with your head toward the cable machine.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:44:27.878886+00', '2026-10-31 19:44:27.736+00'), ('Q497lAE', 'Flexão com queda', 'drop push up', 'flexao-com-queda', 'https://static.exercisedb.dev/media/Q497lAE.gif', 'catalogo/flexao-com-queda--Q497lAE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-com-queda--Q497lAE.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width.","Step:2 Lower your chest toward the ground, keeping your elbows close to your body.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:27.987401+00', '2026-10-31 19:44:27.854+00'), ('Q4DSJPC', 'Remada Unilateral no Smith', 'Smith Single-Arm Row', 'remada-unilateral-no-smith', 'https://static.exercisedb.dev/media/Q4DSJPC.gif', 'catalogo/remada-unilateral-no-smith--Q4DSJPC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-unilateral-no-smith--Q4DSJPC.gif', ARRAY['costas'], ARRAY['smith'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Set the height of the smith machine bar to waist level.","Step:2 Face the smith machine from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:44:28.444064+00', '2026-10-31 19:44:28.304+00'), ('Q6bvyen', 'Elevação de Pernas na Barra Fixa com Rotação', 'hanging straight twisting leg hip raise', 'elevacao-de-pernas-na-barra-fixa-com-rotacao', 'https://static.exercisedb.dev/media/Q6bvyen.gif', 'catalogo/elevacao-de-pernas-na-barra-fixa-com-rotacao--Q6bvyen.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-na-barra-fixa-com-rotacao--Q6bvyen.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your legs straight.","Step:2 Brace your trunk and lift your legs up toward your chest, keeping them straight.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:28.593205+00', '2026-10-31 19:44:28.45+00'), ('q6y3OhV', 'Rosca Bíceps na Máquina', 'Machine Biceps Curl', 'rosca-biceps-na-maquina', 'https://static.exercisedb.dev/media/q6y3OhV.gif', 'catalogo/rosca-biceps-na-maquina--q6y3OhV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-na-maquina--q6y3OhV.gif', ARRAY['braços'], ARRAY['máquina de alavanca'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing up, and Keep your elbows near your ribs.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:28.442724+00', '2026-10-31 19:44:28.314+00'), ('q7qkONO', 'Desenvolvimento Alternado com Halteres Sentado', 'Alternating Seated Dumbbell Shoulder Press', 'desenvolvimento-alternado-com-halteres-sentado', 'https://static.exercisedb.dev/media/q7qkONO.gif', 'catalogo/desenvolvimento-alternado-com-halteres-sentado--q7qkONO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-alternado-com-halteres-sentado--q7qkONO.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:28.489891+00', '2026-10-31 19:44:28.339+00'), ('q8aHNoF', 'Rosca de Punho Unilateral com Halter', 'Dumbbell Single-Arm Wrist Curl', 'rosca-de-punho-unilateral-com-halter', 'https://static.exercisedb.dev/media/q8aHNoF.gif', 'catalogo/rosca-de-punho-unilateral-com-halter--q8aHNoF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-unilateral-com-halter--q8aHNoF.gif', ARRAY['antebraços'], ARRAY['halteres'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Take a seat on a bench or chair with your feet planted.","Step:2 Take a dumbbell in one hand with palms facing up, resting your forearm on your thigh.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:44:28.839457+00', '2026-10-31 19:44:28.697+00'), ('Qa55kX1', 'Agachamento Hack na Máquina', 'sled hack squat', 'agachamento-hack-na-maquina', 'https://static.exercisedb.dev/media/Qa55kX1.gif', 'catalogo/agachamento-hack-na-maquina--Qa55kX1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-hack-na-maquina--Qa55kX1.gif', ARRAY['coxas'], ARRAY['máquina hack'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the sled machine to a comfortable position for your height.","Step:2 Stand and set your feet about shoulder width on the platform, toes slightly pointed outwards.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:29.071544+00', '2026-10-31 19:44:28.929+00'), ('qAmNMJY', 'Rosca Alta com Halteres', 'dumbbell high curl', 'rosca-alta-com-halteres', 'https://static.exercisedb.dev/media/qAmNMJY.gif', 'catalogo/rosca-alta-com-halteres--qAmNMJY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-alta-com-halteres--qAmNMJY.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing forward.","Step:2 Let the elbows do the moving while the upper arms stay put and curl the dumbbells as high as possible while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:29.303812+00', '2026-10-31 19:44:29.164+00'), ('qatbkEd', 'Abdominal com Inclinação Lateral no Cabo (Bosu)', 'cable side bend crunch (bosu ball)', 'abdominal-com-inclinacao-lateral-no-cabo-bosu', 'https://static.exercisedb.dev/media/qatbkEd.gif', 'catalogo/abdominal-com-inclinacao-lateral-no-cabo-bosu--qatbkEd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-inclinacao-lateral-no-cabo-bosu--qatbkEd.gif', ARRAY['abdômen'], ARRAY['cabo'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Stand and set your feet about shoulder width, holding a cable handle in one hand.","Step:2 Set the other hand on your hip.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Let the side of the trunk work; do not twist or shift the hips.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:44:29.398278+00', '2026-10-31 19:44:29.257+00'), ('qaZVsGk', 'Abdominal Alternado Tocando os Calcanhares', 'alternate heel touchers', 'abdominal-alternado-tocando-os-calcanhares', 'https://static.exercisedb.dev/media/qaZVsGk.gif', 'catalogo/abdominal-alternado-tocando-os-calcanhares--qaZVsGk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-alternado-tocando-os-calcanhares--qaZVsGk.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Reach your arms straight out to the sides, parallel to the ground.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Bring the weight or body back to its starting position without rushing; switch sides when the set calls for it."]', '2026-10-31 19:44:29.200181+00', '2026-10-31 19:44:29.039+00'), ('qBcKorM', 'Alongamento de Quadríceps de Quatro Apoios', 'all fours squad stretch', 'alongamento-de-quadriceps-de-quatro-apoios', 'https://static.exercisedb.dev/media/qBcKorM.gif', 'catalogo/alongamento-de-quadriceps-de-quatro-apoios--qBcKorM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-quadriceps-de-quatro-apoios--qBcKorM.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Get onto hands and knees with your hands directly under your shoulders and your knees directly under your hips.","Step:2 Reach one leg straight back, keeping your knee bent and your foot flexed.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:29.420917+00', '2026-10-31 19:44:29.287+00'), ('QChZi3x', 'Agachamento com Alcance Acima da Cabeça', 'squat to overhead reach', 'agachamento-com-alcance-acima-da-cabeca', 'https://static.exercisedb.dev/media/QChZi3x.gif', 'catalogo/agachamento-com-alcance-acima-da-cabeca--QChZi3x.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-alcance-acima-da-cabeca--QChZi3x.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','core'], '["Step:1 Stand and set your feet about shoulder width and toes slightly turned out.","Step:2 Before moving, lower your body down into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:29.671111+00', '2026-10-31 19:44:29.529+00'), ('qcNN2FN', 'Elevação de Quadril em Prancha (Butt-Ups)', 'butt-ups', 'elevacao-de-quadril-em-prancha-butt-ups', 'https://static.exercisedb.dev/media/qcNN2FN.gif', 'catalogo/elevacao-de-quadril-em-prancha-butt-ups--qcNN2FN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-em-prancha-butt-ups--qcNN2FN.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands by your sides, palms facing down.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:29.959578+00', '2026-10-31 19:44:29.827+00'), ('qCNVnaU', 'Panturrilha no Leg Press 45°', 'sled 45° calf press', 'panturrilha-no-leg-press-45', 'https://static.exercisedb.dev/media/qCNVnaU.gif', 'catalogo/panturrilha-no-leg-press-45--qCNVnaU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-no-leg-press-45--qCNVnaU.gif', ARRAY['panturrilhas'], ARRAY['leg press'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Set the sled machine to a 45-degree angle.","Step:2 Set your feet on the sled platform with your toes pointing forward.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:30.307624+00', '2026-10-31 19:44:30.166+00'), ('qcY50ZD', 'Remada Sentada no Cabo com Pegada Aberta', 'cable seated wide-grip row', 'remada-sentada-no-cabo-com-pegada-aberta', 'https://static.exercisedb.dev/media/qcY50ZD.gif', 'catalogo/remada-sentada-no-cabo-com-pegada-aberta--qcY50ZD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-no-cabo-com-pegada-aberta--qcY50ZD.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the cable row machine with your feet flat on the footrests and your knees soft.","Step:2 Hold the handle with a wide overhand grip, palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:30.655061+00', '2026-10-31 19:44:30.27+00'), ('qDnGfDb', 'Rosca de Punho Inversa com Barra', 'barbell reverse wrist curl', 'rosca-de-punho-inversa-com-barra', 'https://static.exercisedb.dev/media/qDnGfDb.gif', 'catalogo/rosca-de-punho-inversa-com-barra--qDnGfDb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-inversa-com-barra--qDnGfDb.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; your knees bent.","Step:2 Take a barbell with palms facing down, and your hands about shoulder width.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:30.032852+00', '2026-10-31 19:44:29.901+00'), ('qdRxqCj', 'Puxada no Cabo com Barra Pro Lat', 'cable pulldown (pro lat bar)', 'puxada-no-cabo-com-barra-pro-lat', 'https://static.exercisedb.dev/media/qdRxqCj.gif', 'catalogo/puxada-no-cabo-com-barra-pro-lat--qdRxqCj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-no-cabo-com-barra-pro-lat--qdRxqCj.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Set the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Step:2 Hold the lat bar with palms facing down, just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:44:30.52528+00', '2026-10-31 19:44:30.394+00'), ('qEse6fe', 'Flexão de Braço com Toque no Ombro', 'shoulder tap push-up', 'flexao-de-braco-com-toque-no-ombro', 'https://static.exercisedb.dev/media/qEse6fe.gif', 'catalogo/flexao-de-braco-com-toque-no-ombro--qEse6fe.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-com-toque-no-ombro--qEse6fe.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','core'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your body in a straight line from head to heels.","Step:2 Lower your body toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:44:30.992068+00', '2026-10-31 19:44:30.852+00'), ('QfAKy1G', 'Desenvolvimento Cubano com Halteres', 'dumbbell cuban press', 'desenvolvimento-cubano-com-halteres', 'https://static.exercisedb.dev/media/QfAKy1G.gif', 'catalogo/desenvolvimento-cubano-com-halteres--QfAKy1G.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-cubano-com-halteres--QfAKy1G.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder height with your palms facing down.","Step:2 With your core engaged and your elbows soft, press the dumbbells up and overhead until your arms are straight.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:31.047118+00', '2026-10-31 19:44:30.91+00'), ('QFmz6ch', 'Alongamento Sentado para a Lombar', 'seated lower back stretch', 'alongamento-sentado-para-a-lombar', 'https://static.exercisedb.dev/media/QFmz6ch.gif', 'catalogo/alongamento-sentado-para-a-lombar--QFmz6ch.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-sentado-para-a-lombar--QFmz6ch.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Take a seat on the edge of a chair with your feet planted.","Step:2 Set your hands on your thighs or on the sides of the chair for support.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:31.103312+00', '2026-10-31 19:44:30.971+00'), ('qFpAkpP', 'Elevação em Pé no Cabo (Lift)', 'cable standing lift', 'elevacao-em-pe-no-cabo-lift', 'https://static.exercisedb.dev/media/qFpAkpP.gif', 'catalogo/elevacao-em-pe-no-cabo-lift--qFpAkpP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-em-pe-no-cabo-lift--qFpAkpP.gif', ARRAY['abdômen'], ARRAY['cabo'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable handle with both hands and position it at waist height.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:31.149698+00', '2026-10-31 19:44:31.006+00'), ('qg2PGl6', 'Elevação Pélvica com Barra Apoiado no Banco', 'Barbell Glute Bridge Two-Leg On Bench', 'elevacao-pelvica-com-barra-apoiado-no-banco', 'https://static.exercisedb.dev/media/qg2PGl6.gif', 'catalogo/elevacao-pelvica-com-barra-apoiado-no-banco--qg2PGl6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-pelvica-com-barra-apoiado-no-banco--qg2PGl6.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','core'], '["Step:1 Begin by sitting on the edge of a bench with your upper back resting against it and your feet planted, about hip width.","Step:2 Set a barbell across your hips, holding it securely with both hands.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:31.680345+00', '2026-10-31 19:44:31.539+00'), ('qi996YS', 'Agachamento Frontal com Barra (Pegada Clean)', 'barbell clean-grip front squat', 'agachamento-frontal-com-barra-pegada-clean', 'https://static.exercisedb.dev/media/qi996YS.gif', 'catalogo/agachamento-frontal-com-barra-pegada-clean--qi996YS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frontal-com-barra-pegada-clean--qi996YS.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Begin by standing with your feet about shoulder width and the barbell resting on your upper chest, with your elbows pointing forward.","Step:2 Before moving, lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:44:31.443628+00', '2026-10-31 19:44:31.299+00'), ('QjE2DcA', 'Afundo com step-up com halteres', 'dumbbell step-up split squat', 'afundo-com-step-up-com-halteres', 'https://static.exercisedb.dev/media/QjE2DcA.gif', 'catalogo/afundo-com-step-up-com-halteres--QjE2DcA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-com-step-up-com-halteres--QjE2DcA.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Take your place in front of a bench or step with a dumbbell in each hand, palms facing your body.","Step:2 Set your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step:3 Put the lead foot fully on the platform before shifting your weight onto it.","Step:4 Step onto the platform and drive through the lead foot to stand tall on it.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:31.987719+00', '2026-10-31 19:44:31.841+00'), ('qKBpF7I', 'Elevação pélvica com barra', 'barbell glute bridge', 'elevacao-pelvica-com-barra', 'https://static.exercisedb.dev/media/qKBpF7I.gif', 'catalogo/elevacao-pelvica-com-barra--qKBpF7I.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-pelvica-com-barra--qKBpF7I.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Begin by lying flat on your back on the ground with your knees bent and feet planted.","Step:2 Set a barbell across your hips, holding it securely with both hands.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:32.069469+00', '2026-10-31 19:44:31.938+00'), ('QLL2gdc', 'Abdominal declinado', 'decline sit-up', 'abdominal-declinado', 'https://static.exercisedb.dev/media/QLL2gdc.gif', 'catalogo/abdominal-declinado--QLL2gdc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-declinado--QLL2gdc.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto a decline bench with your feet secured and your knees bent.","Step:2 Set your hands behind your head or across your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:32.196622+00', '2026-10-31 19:44:32.067+00'), ('qLpO4vV', 'Extensão lombar na bola suíça', 'back extension on exercise ball', 'extensao-lombar-na-bola-suica', 'https://static.exercisedb.dev/media/qLpO4vV.gif', 'catalogo/extensao-lombar-na-bola-suica--qLpO4vV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar-na-bola-suica--qLpO4vV.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the stability ball on the ground and Position yourself face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Step:2 Set your hands behind your head or crossed over your chest.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:44:32.405267+00', '2026-10-31 19:44:32.275+00'), ('QLRmNeT', 'Rosca martelo alternada sentado na bola suíça com halteres', 'dumbbell seated alternate hammer curl on exercise ball', 'rosca-martelo-alternada-sentado-na-bola-suica-com-halteres', 'https://static.exercisedb.dev/media/QLRmNeT.gif', 'catalogo/rosca-martelo-alternada-sentado-na-bola-suica-com-halteres--QLRmNeT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-alternada-sentado-na-bola-suica-com-halteres--QLRmNeT.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing your body and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:32.589682+00', '2026-10-31 19:44:32.452+00'), ('qm9veZw', 'Rosca deitado com pegada aberta com halteres', 'dumbbell lying wide curl', 'rosca-deitado-com-pegada-aberta-com-halteres', 'https://static.exercisedb.dev/media/qm9veZw.gif', 'catalogo/rosca-deitado-com-pegada-aberta-com-halteres--qm9veZw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-deitado-com-pegada-aberta-com-halteres--qm9veZw.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing up and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:32.684505+00', '2026-10-31 19:44:32.544+00'), ('QOA0FD0', 'Elevação de pernas na barra fixa com peso', 'weighted hanging leg-hip raise', 'elevacao-de-pernas-na-barra-fixa-com-peso', 'https://static.exercisedb.dev/media/QOA0FD0.gif', 'catalogo/elevacao-de-pernas-na-barra-fixa-com-peso--QOA0FD0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-na-barra-fixa-com-peso--QOA0FD0.gif', ARRAY['abdômen'], ARRAY['com peso'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your legs up in front of you, keeping them straight.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:32.809642+00', '2026-10-31 19:44:32.665+00'), ('qOgPVf6', 'Rosca Scott com barra', 'barbell preacher curl', 'rosca-scott-com-barra', 'https://static.exercisedb.dev/media/qOgPVf6.gif', 'catalogo/rosca-scott-com-barra--qOgPVf6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-com-barra--qOgPVf6.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with your upper arms resting on the pad and your chest against the support.","Step:2 Hold the barbell with palms facing up, just beyond shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:33.163784+00', '2026-10-31 19:44:33.033+00'), ('QoHIhPl', 'Alongamento de peito com mãos atrás da cabeça', 'behind head chest stretch', 'alongamento-de-peito-com-maos-atras-da-cabeca', 'https://static.exercisedb.dev/media/QoHIhPl.gif', 'catalogo/alongamento-de-peito-com-maos-atras-da-cabeca--QoHIhPl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-peito-com-maos-atras-da-cabeca--QoHIhPl.gif', ARRAY['peito'], ARRAY['assistido'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Stand tall and set your feet about shoulder width.","Step:2 Lace your fingers behind your head with your elbows pointing outwards.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:33.291141+00', '2026-10-31 19:44:33.159+00'), ('qOKcgVP', 'Alongamento de panturrilha em pé', 'standing calves calf stretch', 'alongamento-de-panturrilha-em-pe', 'https://static.exercisedb.dev/media/qOKcgVP.gif', 'catalogo/alongamento-de-panturrilha-em-pe--qOKcgVP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-panturrilha-em-pe--qOKcgVP.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Face a wall or sturdy object, about an arm''s length away.","Step:2 Set your hands on the wall or object at shoulder height.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:33.195245+00', '2026-10-31 19:44:33.051+00'), ('Qoujh3Q', 'Corrida de velocidade com mudança de direção', 'wind sprints', 'corrida-de-velocidade-com-mudanca-de-direcao', 'https://static.exercisedb.dev/media/Qoujh3Q.gif', 'catalogo/corrida-de-velocidade-com-mudanca-de-direcao--Qoujh3Q.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-de-velocidade-com-mudanca-de-direcao--Qoujh3Q.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Choose an open space or a track to perform the exercise.","Step:2 Begin by standing with your feet about shoulder width.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:33.86917+00', '2026-10-31 19:44:33.481+00'), ('qPEzJjA', 'Caminhada do fazendeiro', 'farmers walk', 'caminhada-do-fazendeiro', 'https://static.exercisedb.dev/media/qPEzJjA.gif', 'catalogo/caminhada-do-fazendeiro--qPEzJjA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-do-fazendeiro--qPEzJjA.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['quadríceps'], ARRAY['panturrilhas','antebraços','core'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your sides.","Step:2 Keep your spine in a comfortable neutral position and your shoulders back.","Step:3 Stand tall with the load secure and the shoulders level.","Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.","Step:5 Keep steps even and avoid leaning away from the load.","Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk."]', '2026-10-31 19:44:33.534717+00', '2026-10-31 19:44:33.403+00'), ('QpXqiq8', 'Agachamento búlgaro suspenso', 'suspended split squat', 'agachamento-bulgaro-suspenso', 'https://static.exercisedb.dev/media/QpXqiq8.gif', 'catalogo/agachamento-bulgaro-suspenso--QpXqiq8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-bulgaro-suspenso--QpXqiq8.gif', ARRAY['coxas'], ARRAY['peso corporal','TRX'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Face the away from a suspension trainer from a stable stance with feet about shoulder width.","Step:2 Reach one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:33.752093+00', '2026-10-31 19:44:33.616+00'), ('Qqi7bko', 'Barra fixa pegada aberta', 'Wide-Grip Pull-Up', 'barra-fixa-pegada-aberta', 'https://static.exercisedb.dev/media/Qqi7bko.gif', 'catalogo/barra-fixa-pegada-aberta--Qqi7bko.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-pegada-aberta--Qqi7bko.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Suspend yourself from a pull-up bar with your palms turned away from you and your hands wider than about shoulder width.","Step:2 Brace your trunk and draw your shoulder blades toward each other.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:33.754742+00', '2026-10-31 19:44:33.617+00'), ('qRZ5S1N', 'Tríceps pulley unilateral', 'Cable Single-Arm Triceps Pushdown', 'triceps-pulley-unilateral', 'https://static.exercisedb.dev/media/qRZ5S1N.gif', 'catalogo/triceps-pulley-unilateral--qRZ5S1N.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-pulley-unilateral--qRZ5S1N.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Face a cable machine with a straight bar attachment at chest height.","Step:2 Hold the bar with palms facing down and step back to create tension in the cable.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Return along the same path at a controlled pace; switch sides when the set calls for it."]', '2026-10-31 19:44:34.123666+00', '2026-10-31 19:44:33.991+00'), ('QsSQWbf', 'Panturrilha unilateral invertida com elástico', 'band single leg reverse calf raise', 'panturrilha-unilateral-invertida-com-elastico', 'https://static.exercisedb.dev/media/QsSQWbf.gif', 'catalogo/panturrilha-unilateral-invertida-com-elastico--QsSQWbf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-unilateral-invertida-com-elastico--QsSQWbf.gif', ARRAY['panturrilhas'], ARRAY['elástico de resistência'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about hip width and place the band around the ball of your foot.","Step:2 Use a stable object for balance.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:34.146211+00', '2026-10-31 19:44:34.012+00'), ('QT5Q0nK', 'Desenvolvimento alternado sentado com halteres', 'dumbbell seated alternate press', 'desenvolvimento-alternado-sentado-com-halteres', 'https://static.exercisedb.dev/media/QT5Q0nK.gif', 'catalogo/desenvolvimento-alternado-sentado-com-halteres--QT5Q0nK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-alternado-sentado-com-halteres--QT5Q0nK.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing forward.","Step:2 Before moving, raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:34.489613+00', '2026-10-31 19:44:34.358+00'), ('QTXKWPh', 'Rosca bíceps com pulldown no cabo', 'Cable Pulldown Biceps Curl', 'rosca-biceps-com-pulldown-no-cabo', 'https://static.exercisedb.dev/media/QTXKWPh.gif', 'catalogo/rosca-biceps-com-pulldown-no-cabo--QTXKWPh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-com-pulldown-no-cabo--QTXKWPh.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Connect a straight bar to the cable machine at the highest setting.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:44:34.326341+00', '2026-10-31 19:44:34.19+00'), ('QUDd8WS', 'Abdominal oblíquo no solo', 'oblique crunches floor', 'abdominal-obliquo-no-solo', 'https://static.exercisedb.dev/media/QUDd8WS.gif', 'catalogo/abdominal-obliquo-no-solo--QUDd8WS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-obliquo-no-solo--QUDd8WS.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head or cross them over your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:34.939644+00', '2026-10-31 19:44:34.799+00'), ('qx4fgX7', 'Agachamento búlgaro com halter', 'dumbbell single leg split squat', 'agachamento-bulgaro-com-halter', 'https://static.exercisedb.dev/media/qx4fgX7.gif', 'catalogo/agachamento-bulgaro-com-halter--qx4fgX7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-bulgaro-com-halter--qx4fgX7.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:35.081267+00', '2026-10-31 19:44:34.947+00'), ('qXTaZnJ', 'Agachamento livre profundo com barra', 'barbell full squat', 'agachamento-livre-profundo-com-barra', 'https://static.exercisedb.dev/media/qXTaZnJ.gif', 'catalogo/agachamento-livre-profundo-com-barra--qXTaZnJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-livre-profundo-com-barra--qXTaZnJ.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Stand and set your feet about shoulder width, toes slightly turned out.","Step:2 Rest the bar across the upper back and take a secure grip.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:35.641616+00', '2026-10-31 19:44:35.489+00'), ('QY39eBr', 'Alongamento de piriforme sentado', 'seated piriformis stretch', 'alongamento-de-piriforme-sentado', 'https://static.exercisedb.dev/media/QY39eBr.gif', 'catalogo/alongamento-de-piriforme-sentado--QY39eBr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-piriforme-sentado--QY39eBr.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Before moving, bend your right knee and place your right foot on the outside of your left knee.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:35.621508+00', '2026-10-31 19:44:35.463+00'), ('Qyk5J3p', 'Rosca martelo cruzada com halteres', 'dumbbell cross body hammer curl', 'rosca-martelo-cruzada-com-halteres', 'https://static.exercisedb.dev/media/Qyk5J3p.gif', 'catalogo/rosca-martelo-cruzada-com-halteres--Qyk5J3p.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-cruzada-com-halteres--Qyk5J3p.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your body.","Step:2 Hold your elbows near your torso and your upper arms stationary.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl each weight across the torso toward the opposite shoulder, keeping the palm facing inward.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:35.083711+00', '2026-10-31 19:44:34.952+00'), ('QyO6Uma', 'Supino declinado pegada fechada invertida no Smith', 'Smith Machine Reverse Decline Close-Grip Bench Press', 'supino-declinado-pegada-fechada-invertida-no-smith', 'https://static.exercisedb.dev/media/QyO6Uma.gif', 'catalogo/supino-declinado-pegada-fechada-invertida-no-smith--QyO6Uma.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-pegada-fechada-invertida-no-smith--QyO6Uma.gif', ARRAY['peito'], ARRAY['Smith machine'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the smith machine to a decline position.","Step:2 Get onto the bench with your feet secured under the foot pads.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:35.541434+00', '2026-10-31 19:44:35.408+00'), ('QYysSLV', 'Landmine 180 (rotação com barra)', 'landmine 180', 'landmine-180-rotacao-com-barra', 'https://static.exercisedb.dev/media/QYysSLV.gif', 'catalogo/landmine-180-rotacao-com-barra--QYysSLV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/landmine-180-rotacao-com-barra--QYysSLV.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['oblíquos','quadríceps'], '["Step:1 Stand and set your feet about shoulder width and hold the barbell with both hands ahead of your chest.","Step:2 Bend your knees slightly and rotate your torso to the right, swinging the barbell down toward your right hip.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:35.89886+00', '2026-10-31 19:44:35.767+00'), ('QZFv5ui', 'Supino unilateral com halter na bola suíça', 'Dumbbell Single-Arm Press On Exercise Ball', 'supino-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/QZFv5ui.gif', 'catalogo/supino-unilateral-com-halter-na-bola-suica--QZFv5ui.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-com-halter-na-bola-suica--QZFv5ui.gif', ARRAY['peito'], ARRAY['halteres','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps','core'], '["Step:1 Take a seat on an exercise ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:35.669575+00', '2026-10-31 19:44:35.531+00'), ('r0z6xzQ', 'Remada Pendlay com barra', 'barbell pendlay row', 'remada-pendlay-com-barra', 'https://static.exercisedb.dev/media/r0z6xzQ.gif', 'catalogo/remada-pendlay-com-barra--r0z6xzQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-pendlay-com-barra--r0z6xzQ.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Bend forward at the hips, with your spine steady and your chest up.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:36.141897+00', '2026-10-31 19:44:35.996+00'), ('R1WYG5D', 'Abdominal infra suspenso (elevação de pernas invertida) no TRX', 'suspended reverse crunch', 'abdominal-infra-suspenso-elevacao-de-pernas-invertida-no-trx', 'https://static.exercisedb.dev/media/R1WYG5D.gif', 'catalogo/abdominal-infra-suspenso-elevacao-de-pernas-invertida-no-trx--R1WYG5D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-infra-suspenso-elevacao-de-pernas-invertida-no-trx--R1WYG5D.gif', ARRAY['abdômen'], ARRAY['peso corporal','TRX'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your knees up toward your chest, curling your pelvis toward your ribcage.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:36.437136+00', '2026-10-31 19:44:36.297+00'), ('r1XNRYB', 'Barra fixa assistida com elástico', 'band assisted pull-up', 'barra-fixa-assistida-com-elastico', 'https://static.exercisedb.dev/media/r1XNRYB.gif', 'catalogo/barra-fixa-assistida-com-elastico--r1XNRYB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-assistida-com-elastico--r1XNRYB.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Connect the band to a pull-up bar or sturdy anchor point.","Step:2 Step onto the band and grip the bar with your palms turned away from you, hands just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:36.330096+00', '2026-10-31 19:44:36.197+00'), ('r29jP7S', 'Panturrilha sentado com halter', 'dumbbell seated calf raise', 'panturrilha-sentado-com-halter', 'https://static.exercisedb.dev/media/r29jP7S.gif', 'catalogo/panturrilha-sentado-com-halter--r29jP7S.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-com-halter--r29jP7S.gif', ARRAY['panturrilhas'], ARRAY['halteres'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Take a seat on a bench or chair with your feet planted and a dumbbell resting on your thighs.","Step:2 Set the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:36.548651+00', '2026-10-31 19:44:36.416+00'), ('r5DgrW9', 'Agachamento com apoio e halter', 'dumbbell supported squat', 'agachamento-com-apoio-e-halter', 'https://static.exercisedb.dev/media/r5DgrW9.gif', 'catalogo/agachamento-com-apoio-e-halter--r5DgrW9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-apoio-e-halter--r5DgrW9.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at your sides.","Step:2 With your chest up and core engaged, With control lower your body down by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:36.699133+00', '2026-10-31 19:44:36.564+00'), ('R5swFnc', 'Remada deitado com barra W', 'cambered bar lying row', 'remada-deitado-com-barra-w', 'https://static.exercisedb.dev/media/R5swFnc.gif', 'catalogo/remada-deitado-com-barra-w--R5swFnc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-deitado-com-barra-w--R5swFnc.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Prepare a barbell on the floor and Position yourself face down on a bench with your chest just off the edge.","Step:2 Reach down and grab the barbell with palms facing down, just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:36.755354+00', '2026-10-31 19:44:36.615+00'), ('r7cT9YD', 'Rotação russa assistida com medicine ball', 'assisted motion russian twist', 'rotacao-russa-assistida-com-medicine-ball', 'https://static.exercisedb.dev/media/r7cT9YD.gif', 'catalogo/rotacao-russa-assistida-com-medicine-ball--r7cT9YD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-russa-assistida-com-medicine-ball--r7cT9YD.gif', ARRAY['abdômen'], ARRAY['medicine ball'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on the ground with your knees bent and feet planted.","Step:2 Take hold of the medicine ball with both hands ahead of your chest.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:36.907775+00', '2026-10-31 19:44:36.77+00'), ('RaflbWD', 'Rosca inclinada com halteres', 'dumbbell incline curl', 'rosca-inclinada-com-halteres', 'https://static.exercisedb.dev/media/RaflbWD.gif', 'catalogo/rosca-inclinada-com-halteres--RaflbWD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inclinada-com-halteres--RaflbWD.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, palms facing forward and arms straight.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:37.386023+00', '2026-10-31 19:44:37.242+00'), ('rbu5UUb', 'Abdominal cruzado', 'cross body crunch', 'abdominal-cruzado', 'https://static.exercisedb.dev/media/rbu5UUb.gif', 'catalogo/abdominal-cruzado--rbu5UUb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-cruzado--rbu5UUb.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:37.750921+00', '2026-10-31 19:44:37.62+00'), ('rDAiRf9', 'Supino inclinado unilateral com halter', 'Dumbbell Incline Single-Arm Press', 'supino-inclinado-unilateral-com-halter', 'https://static.exercisedb.dev/media/rDAiRf9.gif', 'catalogo/supino-inclinado-unilateral-com-halter--rDAiRf9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-unilateral-com-halter--rDAiRf9.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an incline bench with a dumbbell in one hand, resting on your thigh.","Step:2 Recline on the bench and position the dumbbell at shoulder level, palm facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:37.334212+00', '2026-10-31 19:44:37.194+00'), ('reFHapa', 'Crucifixo declinado com rotação de halteres', 'dumbbell decline twist fly', 'crucifixo-declinado-com-rotacao-de-halteres', 'https://static.exercisedb.dev/media/reFHapa.gif', 'catalogo/crucifixo-declinado-com-rotacao-de-halteres--reFHapa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-declinado-com-rotacao-de-halteres--reFHapa.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Get onto a decline bench with your head lower than your hips.","Step:2 Take a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:37.389322+00', '2026-10-31 19:44:37.247+00'), ('REGM1dE', 'Supino declinado unilateral com halter', 'Dumbbell Single-Arm Decline Chest Press', 'supino-declinado-unilateral-com-halter', 'https://static.exercisedb.dev/media/REGM1dE.gif', 'catalogo/supino-declinado-unilateral-com-halter--REGM1dE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-unilateral-com-halter--REGM1dE.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a decline bench with a dumbbell in one hand, resting on your chest.","Step:2 Set your feet planted and keep your back pressed against the bench.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:38.383201+00', '2026-10-31 19:44:38.244+00'), ('rEhi2o5', 'Supinação de antebraço com halter deitado no chão', 'dumbbell lying supination on floor', 'supinacao-de-antebraco-com-halter-deitado-no-chao', 'https://static.exercisedb.dev/media/rEhi2o5.gif', 'catalogo/supinacao-de-antebraco-com-halter-deitado-no-chao--rEhi2o5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supinacao-de-antebraco-com-halter-deitado-no-chao--rEhi2o5.gif', ARRAY['antebraços'], ARRAY['halteres'], ARRAY['antebraços'], ARRAY['bíceps','deltoides'], '["Step:1 Settle onto your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Step:2 Before moving, rotate your palms to face up, keeping your elbows close to your sides.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:38.005707+00', '2026-10-31 19:44:37.874+00'), ('REXmfVC', 'Marretada (golpe com marreta)', 'sledge hammer', 'marretada-golpe-com-marreta', 'https://static.exercisedb.dev/media/REXmfVC.gif', 'catalogo/marretada-golpe-com-marreta--REXmfVC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/marretada-golpe-com-marreta--REXmfVC.gif', ARRAY['abdômen'], ARRAY['marreta'], ARRAY['abdominais'], ARRAY['antebraços','deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold the sledge hammer with both hands.","Step:2 Brace your trunk and Keep your spine in a comfortable neutral position.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Swing the hammer down with a coordinated hip turn, then reset your grip and stance.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:37.972904+00', '2026-10-31 19:44:37.834+00'), ('rg59QCH', 'Supino no chão unilateral com kettlebell', 'Kettlebell Single-Arm Floor Press', 'supino-no-chao-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/rg59QCH.gif', 'catalogo/supino-no-chao-unilateral-com-kettlebell--rg59QCH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-no-chao-unilateral-com-kettlebell--rg59QCH.gif', ARRAY['peito'], ARRAY['kettlebell'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto your back on the floor with your knees bent and feet planted.","Step:2 Take hold of the kettlebell in one hand with your palm facing toward your feet and your arm extended straight up toward the ceiling.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:37.976949+00', '2026-10-31 19:44:37.841+00'), ('RgJDRR1', 'Remada alta pegada aberta com barra', 'barbell wide-grip upright row', 'remada-alta-pegada-aberta-com-barra', 'https://static.exercisedb.dev/media/RgJDRR1.gif', 'catalogo/remada-alta-pegada-aberta-com-barra--RgJDRR1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-pegada-aberta-com-barra--RgJDRR1.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down, hands wider than about shoulder width.","Step:2 Keep the barbell hanging ahead of your thighs, arms straight.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:38.35815+00', '2026-10-31 19:44:38.216+00'), ('RGLscZM', 'Agachamento no Smith com barra baixa', 'smith low bar squat', 'agachamento-no-smith-com-barra-baixa', 'https://static.exercisedb.dev/media/RGLscZM.gif', 'catalogo/agachamento-no-smith-com-barra-baixa--RGLscZM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-no-smith-com-barra-baixa--RGLscZM.gif', ARRAY['coxas'], ARRAY['Smith machine'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Prepare the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Step:2 Stand and set your feet about shoulder width, toes slightly turned outwards.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:38.865666+00', '2026-10-31 19:44:38.73+00'), ('rGwhJ5o', 'Panturrilha em pé com barra', 'barbell standing leg calf raise', 'panturrilha-em-pe-com-barra', 'https://static.exercisedb.dev/media/rGwhJ5o.gif', 'catalogo/panturrilha-em-pe-com-barra--rGwhJ5o.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-com-barra--rGwhJ5o.gif', ARRAY['panturrilhas'], ARRAY['barra'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width and place a barbell across your upper back.","Step:2 Before moving, raise your heels off the ground as high as possible, using your calves.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:38.588922+00', '2026-10-31 19:44:38.46+00'), ('RJa4tCo', 'Corda naval', 'battling ropes', 'corda-naval', 'https://static.exercisedb.dev/media/RJa4tCo.gif', 'catalogo/corda-naval--RJa4tCo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corda-naval--RJa4tCo.gif', ARRAY['ombros'], ARRAY['corda'], ARRAY['deltoides'], ARRAY['antebraços','core'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Keep one end of the rope in each hand, with your palms facing each other.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:44:39.049663+00', '2026-10-31 19:44:38.908+00'), ('RJgzwny', 'Escalador', 'mountain climber', 'escalador', 'https://static.exercisedb.dev/media/RJgzwny.gif', 'catalogo/escalador--RJgzwny.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/escalador--RJgzwny.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['core','deltoides','tríceps'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Brace your trunk and bring your right knee toward your chest, then quickly switch and bring your left knee toward your chest.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:44:38.958823+00', '2026-10-31 19:44:38.828+00'), ('rjiM4L3', 'Caminhada na esteira inclinada', 'walking on incline treadmill', 'caminhada-na-esteira-inclinada', 'https://static.exercisedb.dev/media/rjiM4L3.gif', 'catalogo/caminhada-na-esteira-inclinada--rjiM4L3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-na-esteira-inclinada--rjiM4L3.gif', ARRAY['cardio'], ARRAY['máquina de alavanca'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the incline level on the treadmill to your desired intensity.","Step:2 Step onto the treadmill with your feet about shoulder width.","Step:3 Stand tall with the load secure and the shoulders level.","Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.","Step:5 Keep steps even and avoid leaning away from the load.","Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk."]', '2026-10-31 19:44:39.331115+00', '2026-10-31 19:44:39.2+00'), ('rjtuP6X', 'Caminhada no elíptico', 'walk elliptical cross trainer', 'caminhada-no-eliptico', 'https://static.exercisedb.dev/media/rjtuP6X.gif', 'catalogo/caminhada-no-eliptico--rjtuP6X.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/caminhada-no-eliptico--rjtuP6X.gif', ARRAY['cardio'], ARRAY['elíptico'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Set the resistance level and incline of the elliptical machine to your desired settings.","Step:2 Get onto the pedals of the machine and grip the handles lightly.","Step:3 Stand tall with the load secure and the shoulders level.","Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.","Step:5 Keep steps even and avoid leaning away from the load.","Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk."]', '2026-10-31 19:44:39.237851+00', '2026-10-31 19:44:39.109+00'), ('rkg41Fb', 'Puxada alta com triângulo duplo de pegada neutra', 'twin handle parallel grip lat pulldown', 'puxada-alta-com-triangulo-duplo-de-pegada-neutra', 'https://static.exercisedb.dev/media/rkg41Fb.gif', 'catalogo/puxada-alta-com-triangulo-duplo-de-pegada-neutra--rkg41Fb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-alta-com-triangulo-duplo-de-pegada-neutra--rkg41Fb.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['grande dorsal'], ARRAY['bíceps','romboides','deltoides posterior'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down, hands about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:44:39.765118+00', '2026-10-31 19:44:39.622+00'), ('RKjH6Lt', 'Prancha lateral', 'side bridge', 'prancha-lateral', 'https://static.exercisedb.dev/media/RKjH6Lt.gif', 'catalogo/prancha-lateral--RKjH6Lt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-lateral--RKjH6Lt.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','glúteos'], '["Step:1 Settle onto your side with your legs extended and stacked on top of each other.","Step:2 Set your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:39.540304+00', '2026-10-31 19:44:39.405+00'), ('rmEukuS', 'Elevação pélvica unilateral com perna estendida', 'single leg bridge with outstretched leg', 'elevacao-pelvica-unilateral-com-perna-estendida', 'https://static.exercisedb.dev/media/rmEukuS.gif', 'catalogo/elevacao-pelvica-unilateral-com-perna-estendida--rmEukuS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-pelvica-unilateral-com-perna-estendida--rmEukuS.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Reach one leg straight out in front of you.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:39.602971+00', '2026-10-31 19:44:39.469+00'), ('RoV1Rfa', 'Alongamento assistido de peitoral maior sentado com bola suíça', 'assisted seated pectoralis major stretch with stability ball', 'alongamento-assistido-de-peitoral-maior-sentado-com-bola-suica', 'https://static.exercisedb.dev/media/RoV1Rfa.gif', 'catalogo/alongamento-assistido-de-peitoral-maior-sentado-com-bola-suica--RoV1Rfa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-assistido-de-peitoral-maior-sentado-com-bola-suica--RoV1Rfa.gif', ARRAY['peito'], ARRAY['assistido','bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on a stability ball with your feet planted and your back straight.","Step:2 Take a stability ball with both hands and extend your arms straight out in front of you.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:39.859423+00', '2026-10-31 19:44:39.725+00'), ('rQhGcin', 'Prancha frog (planche sapo)', 'frog planche', 'prancha-frog-planche-sapo', 'https://static.exercisedb.dev/media/rQhGcin.gif', 'catalogo/prancha-frog-planche-sapo--rQhGcin.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-frog-planche-sapo--rQhGcin.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','peitorais','tríceps'], '["Step:1 Set a straight-arm plank with the hands below the shoulders and the feet together.","Step:2 Bend your elbows and lower your body toward the ground, with your spine steady.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:40.504102+00', '2026-10-31 19:44:40.373+00'), ('RQNVT10', 'Alongamento assistido de glúteo e piriforme deitado', 'assisted lying gluteus and piriformis stretch', 'alongamento-assistido-de-gluteo-e-piriforme-deitado', 'https://static.exercisedb.dev/media/RQNVT10.gif', 'catalogo/alongamento-assistido-de-gluteo-e-piriforme-deitado--RQNVT10.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-assistido-de-gluteo-e-piriforme-deitado--RQNVT10.gif', ARRAY['coxas'], ARRAY['assistido'], ARRAY['glúteos'], ARRAY['posteriores de coxa'], '["Step:1 Settle onto your back with your legs extended.","Step:2 Before moving, bend your right knee and place your right ankle on your left thigh, just above the knee.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:40.128995+00', '2026-10-31 19:44:39.999+00'), ('RqOtqD7', 'Abdominal infra no cabo', 'cable reverse crunch', 'abdominal-infra-no-cabo', 'https://static.exercisedb.dev/media/RqOtqD7.gif', 'catalogo/abdominal-infra-no-cabo--RqOtqD7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-infra-no-cabo--RqOtqD7.gif', ARRAY['abdômen'], ARRAY['cabo'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Connect a cable to a low pulley and lie down facing up on a mat.","Step:2 Take hold of the cable with both hands and extend your arms straight up toward the ceiling.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:40.46177+00', '2026-10-31 19:44:40.331+00'), ('rQxwMxO', 'Flexão de braço em parada de mão', 'handstand push-up', 'flexao-de-braco-em-parada-de-mao', 'https://static.exercisedb.dev/media/rQxwMxO.gif', 'catalogo/flexao-de-braco-em-parada-de-mao--rQxwMxO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-em-parada-de-mao--rQxwMxO.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['deltoides','peitorais','core'], '["Step:1 Choose a wall and face away from it, standing a few feet away.","Step:2 Set your hands on the ground about shoulder width and kick your feet up against the wall, coming into a handstand position.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:40.245814+00', '2026-10-31 19:44:40.102+00'), ('rR0LJzx', 'Stiff com halteres (levantamento terra romeno)', 'dumbbell romanian deadlift', 'stiff-com-halteres-levantamento-terra-romeno', 'https://static.exercisedb.dev/media/rR0LJzx.gif', 'catalogo/stiff-com-halteres-levantamento-terra-romeno--rR0LJzx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stiff-com-halteres-levantamento-terra-romeno--rR0LJzx.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 With your back straight and your core engaged, hinge at the hips and lower the dumbbells toward the ground, letting your knees to bend slightly.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:40.745197+00', '2026-10-31 19:44:40.601+00'), ('Rr7S3yg', 'Elevação frontal com halteres', 'dumbbell front raise', 'elevacao-frontal-com-halteres', 'https://static.exercisedb.dev/media/Rr7S3yg.gif', 'catalogo/elevacao-frontal-com-halteres--Rr7S3yg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-halteres--Rr7S3yg.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.","Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:40.731732+00', '2026-10-31 19:44:40.59+00'), ('RrLske5', 'Mergulho no banco com joelhos flexionados', 'bench dip (knees bent)', 'mergulho-no-banco-com-joelhos-flexionados', 'https://static.exercisedb.dev/media/RrLske5.gif', 'catalogo/mergulho-no-banco-com-joelhos-flexionados--RrLske5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-no-banco-com-joelhos-flexionados--RrLske5.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge next to your hips.","Step:2 Move your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:41.142075+00', '2026-10-31 19:44:41.003+00'), ('RRWFUcw', 'Avanço com halteres', 'dumbbell lunge', 'avanco-com-halteres', 'https://static.exercisedb.dev/media/RRWFUcw.gif', 'catalogo/avanco-com-halteres--RRWFUcw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-halteres--RRWFUcw.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Step forward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:41.263937+00', '2026-10-31 19:44:41.125+00'), ('rseLfH3', 'Supino unilateral no chão com kettlebell e amplitude estendida', 'Kettlebell Extended Range Single-Arm Press On Floor', 'supino-unilateral-no-chao-com-kettlebell-e-amplitude-estendida', 'https://static.exercisedb.dev/media/rseLfH3.gif', 'catalogo/supino-unilateral-no-chao-com-kettlebell-e-amplitude-estendida--rseLfH3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-no-chao-com-kettlebell-e-amplitude-estendida--rseLfH3.gif', ARRAY['peito'], ARRAY['kettlebell'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin by lying on your back on the floor with your knees bent and feet planted.","Step:2 Take a kettlebell in one hand, with your palm facing toward your feet.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:41.219444+00', '2026-10-31 19:44:41.086+00'), ('RSOsp5d', 'Círculo ao redor do corpo em pé com halteres (around the world)', 'dumbbell standing around world', 'circulo-ao-redor-do-corpo-em-pe-com-halteres-around-the-world', 'https://static.exercisedb.dev/media/RSOsp5d.gif', 'catalogo/circulo-ao-redor-do-corpo-em-pe-com-halteres-around-the-world--RSOsp5d.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/circulo-ao-redor-do-corpo-em-pe-com-halteres-around-the-world--RSOsp5d.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Reach your arms straight out to the sides at shoulder height, palms facing down.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Guide the weights through a broad circular arc without leaning or swinging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:41.656811+00', '2026-10-31 19:44:41.517+00'), ('rTbyBYV', 'Alongamento lateral de dorsal deitado na bola suíça', 'exercise ball lying side lat stretch', 'alongamento-lateral-de-dorsal-deitado-na-bola-suica', 'https://static.exercisedb.dev/media/rTbyBYV.gif', 'catalogo/alongamento-lateral-de-dorsal-deitado-na-bola-suica--rTbyBYV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lateral-de-dorsal-deitado-na-bola-suica--rTbyBYV.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['grande dorsal'], ARRAY['deltoides','tríceps'], '["Step:1 Settle onto your side with your legs extended and your head supported by the stability ball.","Step:2 Set your top arm on the ball for stability.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:41.768436+00', '2026-10-31 19:44:41.627+00'), ('RtyAsy1', 'Toque circular no pé com braços afastados', 'Arms Apart Circular Toe Touch', 'toque-circular-no-pe-com-bracos-afastados', 'https://static.exercisedb.dev/media/RtyAsy1.gif', 'catalogo/toque-circular-no-pe-com-bracos-afastados--RtyAsy1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/toque-circular-no-pe-com-bracos-afastados--RtyAsy1.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and arms extended to the sides.","Step:2 With your legs straight, bend forward at the waist and reach down toward your toes with your right hand.","Step:3 Soften the knees and let the hips start the fold.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Keep the movement controlled throughout the range.","Step:6 Hold briefly at a comfortable depth, then rise by extending the hips."]', '2026-10-31 19:44:41.820237+00', '2026-10-31 19:44:41.687+00'), ('rUXfn3R', 'Extensão lombar na máquina', 'Machine Back Extension', 'extensao-lombar-na-maquina', 'https://static.exercisedb.dev/media/rUXfn3R.gif', 'catalogo/extensao-lombar-na-maquina--rUXfn3R.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar-na-maquina--rUXfn3R.gif', ARRAY['costas'], ARRAY['máquina de alavanca'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the machine to fit your body size and range of motion.","Step:2 Take a seat on the machine with your back against the pad and your feet secured.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Finish in a straight body line, before the lower back overarches.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:44:41.874773+00', '2026-10-31 19:44:41.731+00'), ('RVwzP10', 'Pulldown no cabo (pulldown com braços estendidos)', 'cable pulldown', 'pulldown-no-cabo-pulldown-com-bracos-estendidos', 'https://static.exercisedb.dev/media/RVwzP10.gif', 'catalogo/pulldown-no-cabo-pulldown-com-bracos-estendidos--RVwzP10.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pulldown-no-cabo-pulldown-com-bracos-estendidos--RVwzP10.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['grande dorsal'], ARRAY['bíceps','antebraços'], '["Step:1 Set the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Step:2 Take a seat on the seat with your back straight and your feet planted.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:44:42.160234+00', '2026-10-31 19:44:42.026+00'), ('rWoBmi5', 'Paralela coreana (Korean dips)', 'korean dips', 'paralela-coreana-korean-dips', 'https://static.exercisedb.dev/media/rWoBmi5.gif', 'catalogo/paralela-coreana-korean-dips--rWoBmi5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/paralela-coreana-korean-dips--rWoBmi5.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set yourself between two parallel bars with your arms extended and supporting your body weight.","Step:2 Before moving, lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:43.143233+00', '2026-10-31 19:44:42.994+00'), ('RxayqAZ', 'Supino pegada fechada com halteres', 'dumbbell close-grip press', 'supino-pegada-fechada-com-halteres', 'https://static.exercisedb.dev/media/RxayqAZ.gif', 'catalogo/supino-pegada-fechada-com-halteres--RxayqAZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-pegada-fechada-com-halteres--RxayqAZ.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on a flat bench with a dumbbell in each hand, resting on your thighs.","Step:2 Use your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:42.735241+00', '2026-10-31 19:44:42.603+00'), ('RYcV1kH', 'Agachamento com salto e afundo para trás com barra', 'barbell squat jump step rear lunge', 'agachamento-com-salto-e-afundo-para-tras-com-barra', 'https://static.exercisedb.dev/media/RYcV1kH.gif', 'catalogo/agachamento-com-salto-e-afundo-para-tras-com-barra--RYcV1kH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-salto-e-afundo-para-tras-com-barra--RYcV1kH.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width, holding a barbell across your upper back.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:42.437621+00', '2026-10-31 19:44:42.305+00'), ('rZ80Gbp', 'Rosca concentrada unilateral sentado na polia', 'Cable Seated Single-Arm Concentration Curl', 'rosca-concentrada-unilateral-sentado-na-polia', 'https://static.exercisedb.dev/media/rZ80Gbp.gif', 'catalogo/rosca-concentrada-unilateral-sentado-na-polia--rZ80Gbp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-unilateral-sentado-na-polia--rZ80Gbp.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; your back straight.","Step:2 Take a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:42.501332+00', '2026-10-31 19:44:42.359+00'), ('s0HKO2I', 'Extensão de tríceps ajoelhado com peso corporal', 'bodyweight kneeling triceps extension', 'extensao-de-triceps-ajoelhado-com-peso-corporal', 'https://static.exercisedb.dev/media/s0HKO2I.gif', 'catalogo/extensao-de-triceps-ajoelhado-com-peso-corporal--s0HKO2I.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-ajoelhado-com-peso-corporal--s0HKO2I.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['deltoides','peitorais'], '["Step:1 Get down on the ground with your knees about hip width.","Step:2 Set your hands on the ground in front of you, about shoulder width, fingers pointing forward.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:43.022857+00', '2026-10-31 19:44:42.892+00'), ('S1JXDAG', 'Rotação de tronco sentado com faixa elástica', 'band seated twist', 'rotacao-de-tronco-sentado-com-faixa-elastica', 'https://static.exercisedb.dev/media/S1JXDAG.gif', 'catalogo/rotacao-de-tronco-sentado-com-faixa-elastica--S1JXDAG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-sentado-com-faixa-elastica--S1JXDAG.gif', ARRAY['abdômen'], ARRAY['faixa elástica'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Take a seat on the ground with your legs extended in front of you and your back straight.","Step:2 Loop the band around your waist and hold the ends with both hands.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:43.010514+00', '2026-10-31 19:44:42.874+00'), ('s34Y4LR', 'Rotação de tronco sentado na bola suíça com peso', 'weighted seated twist (on stability ball)', 'rotacao-de-tronco-sentado-na-bola-suica-com-peso', 'https://static.exercisedb.dev/media/s34Y4LR.gif', 'catalogo/rotacao-de-tronco-sentado-na-bola-suica-com-peso--s34Y4LR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-sentado-na-bola-suica-com-peso--s34Y4LR.gif', ARRAY['abdômen'], ARRAY['peso adicional','bola suíça'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a weight plate or dumbbell with both hands close to your chest.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:43.342257+00', '2026-10-31 19:44:43.209+00'), ('S37C94C', 'Jerk unilateral com kettlebell', 'Kettlebell Single-Arm Jerk', 'jerk-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/S37C94C.gif', 'catalogo/jerk-unilateral-com-kettlebell--S37C94C.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/jerk-unilateral-com-kettlebell--S37C94C.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand at shoulder height.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:44:43.229198+00', '2026-10-31 19:44:43.098+00'), ('S4pwGlc', 'Agachamento pliométrico com halter', 'dumbbell plyo squat', 'agachamento-pliometrico-com-halter', 'https://static.exercisedb.dev/media/S4pwGlc.gif', 'catalogo/agachamento-pliometrico-com-halter--S4pwGlc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-pliometrico-com-halter--S4pwGlc.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at your sides.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:43.555065+00', '2026-10-31 19:44:43.421+00'), ('s5PdDyY', 'Tate press com halteres', 'dumbbell tate press', 'tate-press-com-halteres', 'https://static.exercisedb.dev/media/s5PdDyY.gif', 'catalogo/tate-press-com-halteres--s5PdDyY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/tate-press-com-halteres--s5PdDyY.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on a flat bench with a dumbbell in each hand, palms facing each other.","Step:2 Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are turned away from you.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:43.665385+00', '2026-10-31 19:44:43.515+00'), ('s7HX1BY', 'Agachamento com base larga com barra', 'barbell wide squat', 'agachamento-com-base-larga-com-barra', 'https://static.exercisedb.dev/media/s7HX1BY.gif', 'catalogo/agachamento-com-base-larga-com-barra--s7HX1BY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-base-larga-com-barra--s7HX1BY.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointing slightly outward.","Step:2 Rest the bar across the upper back and take a secure grip.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:43.81448+00', '2026-10-31 19:44:43.673+00'), ('S8mo30S', 'Elevação frontal em pé com barra acima da cabeça', 'barbell standing front raise over head', 'elevacao-frontal-em-pe-com-barra-acima-da-cabeca', 'https://static.exercisedb.dev/media/S8mo30S.gif', 'catalogo/elevacao-frontal-em-pe-com-barra-acima-da-cabeca--S8mo30S.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-em-pe-com-barra-acima-da-cabeca--S8mo30S.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width, holding a barbell ahead of your thighs with palms facing down.","Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:43.900194+00', '2026-10-31 19:44:43.76+00'), ('s8nrDXF', 'Abdominal crunch com peso', 'weighted crunch', 'abdominal-crunch-com-peso', 'https://static.exercisedb.dev/media/s8nrDXF.gif', 'catalogo/abdominal-crunch-com-peso--s8nrDXF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-crunch-com-peso--s8nrDXF.gif', ARRAY['abdômen'], ARRAY['peso adicional'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Take a weight plate or dumbbell on your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:43.96271+00', '2026-10-31 19:44:43.813+00'), ('S93zLTG', 'Desenvolvimento sentado com faixa elástica', 'Band Seated Shoulder Press', 'desenvolvimento-sentado-com-faixa-elastica', 'https://static.exercisedb.dev/media/S93zLTG.gif', 'catalogo/desenvolvimento-sentado-com-faixa-elastica--S93zLTG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-com-faixa-elastica--S93zLTG.gif', ARRAY['ombros'], ARRAY['faixa elástica'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Take a seat on a chair or bench with your back straight and feet planted.","Step:2 Take hold of the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:44.677927+00', '2026-10-31 19:44:44.534+00'), ('s999Hdo', 'Rosca direta unilateral sentado na bola suíça com halter', 'Dumbbell Single-Arm Seated Biceps Curl On Exercise Ball', 'rosca-direta-unilateral-sentado-na-bola-suica-com-halter', 'https://static.exercisedb.dev/media/s999Hdo.gif', 'catalogo/rosca-direta-unilateral-sentado-na-bola-suica-com-halter--s999Hdo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-unilateral-sentado-na-bola-suica-com-halter--s999Hdo.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand with your palm facing up and your arm straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:44.660421+00', '2026-10-31 19:44:44.519+00'), ('S9zHIvU', 'Remada para deltoide posterior com barra', 'barbell rear delt row', 'remada-para-deltoide-posterior-com-barra', 'https://static.exercisedb.dev/media/S9zHIvU.gif', 'catalogo/remada-para-deltoide-posterior-com-barra--S9zHIvU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-para-deltoide-posterior-com-barra--S9zHIvU.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','romboides','bíceps'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take a barbell with palms facing down, hands just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:44.682779+00', '2026-10-31 19:44:44.541+00'), ('SaDOwk7', 'Salto para trás', 'backward jump', 'salto-para-tras', 'https://static.exercisedb.dev/media/SaDOwk7.gif', 'catalogo/salto-para-tras--SaDOwk7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/salto-para-tras--SaDOwk7.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, bend your knees slightly and jump backwards, pushing off with both feet.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:44:44.564274+00', '2026-10-31 19:44:44.422+00'), ('Ser9eQp', 'Extensão de tríceps na máquina', 'Machine Triceps Extension', 'extensao-de-triceps-na-maquina', 'https://static.exercisedb.dev/media/Ser9eQp.gif', 'catalogo/extensao-de-triceps-na-maquina--Ser9eQp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-na-maquina--Ser9eQp.gif', ARRAY['braços'], ARRAY['máquina'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and straighten your arms in front of you.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:45.034207+00', '2026-10-31 19:44:44.887+00'), ('SGY8Zui', 'Clean and press com barra', 'barbell clean and press', 'clean-and-press-com-barra', 'https://static.exercisedb.dev/media/SGY8Zui.gif', 'catalogo/clean-and-press-com-barra--SGY8Zui.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/clean-and-press-com-barra--SGY8Zui.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos','deltoides','tríceps'], '["Step:1 Stand and set your feet about shoulder width and the barbell on the floor in front of you.","Step:2 Bend your knees and hinge at the hips to lower down and grip the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:44:45.696626+00', '2026-10-31 19:44:45.566+00'), ('SHUMp5H', 'Supino declinado unilateral com halter pegada martelo', 'Dumbbell Decline Single-Arm Hammer Press', 'supino-declinado-unilateral-com-halter-pegada-martelo', 'https://static.exercisedb.dev/media/SHUMp5H.gif', 'catalogo/supino-declinado-unilateral-com-halter-pegada-martelo--SHUMp5H.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-unilateral-com-halter-pegada-martelo--SHUMp5H.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a decline bench with a dumbbell in one hand, resting on your chest.","Step:2 Extend your arm straight up, keeping your elbow soft.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:45.300651+00', '2026-10-31 19:44:45.16+00'), ('SiWCcTN', 'Power clean', 'power clean', 'power-clean', 'https://static.exercisedb.dev/media/SiWCcTN.gif', 'catalogo/power-clean--SiWCcTN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/power-clean--SiWCcTN.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['posteriores de coxa'], ARRAY['glúteos','quadríceps','panturrilhas'], '["Step:1 Start with the barbell on the ground in front of you, with your feet about shoulder width.","Step:2 Bend down and grip the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:44:45.339758+00', '2026-10-31 19:44:45.207+00'), ('SJAA2IQ', 'Rosca de punho supinada com barra no banco', 'barbell palms up wrist curl over a bench', 'rosca-de-punho-supinada-com-barra-no-banco', 'https://static.exercisedb.dev/media/SJAA2IQ.gif', 'catalogo/rosca-de-punho-supinada-com-barra-no-banco--SJAA2IQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-supinada-com-barra-no-banco--SJAA2IQ.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['bíceps','deltoides'], '["Step:1 Plant both feet while seated on a bench; hold a barbell with palms facing up.","Step:2 Support the forearms on the bench while leaving the wrists free beyond its edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:45.647075+00', '2026-10-31 19:44:45.513+00'), ('sJFIDIp', 'Rosca concentrada com apoio na perna', 'biceps leg concentration curl', 'rosca-concentrada-com-apoio-na-perna', 'https://static.exercisedb.dev/media/sJFIDIp.gif', 'catalogo/rosca-concentrada-com-apoio-na-perna--sJFIDIp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-com-apoio-na-perna--sJFIDIp.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a bench with your legs spread apart and your feet planted.","Step:2 Take a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:45.905721+00', '2026-10-31 19:44:45.774+00'), ('SJqRxOt', 'Remada sentada na polia com corda', 'cable rope seated row', 'remada-sentada-na-polia-com-corda', 'https://static.exercisedb.dev/media/SJqRxOt.gif', 'catalogo/remada-sentada-na-polia-com-corda--SJqRxOt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-na-polia-com-corda--SJqRxOt.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the rowing machine with your feet flat on the footrests and knees soft.","Step:2 Hold the cable ropes with palms facing down, palms facing each other.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:46.155749+00', '2026-10-31 19:44:46.017+00'), ('SKXQAx3', 'Abdominal reverso com rolo', 'roller reverse crunch', 'abdominal-reverso-com-rolo', 'https://static.exercisedb.dev/media/SKXQAx3.gif', 'catalogo/abdominal-reverso-com-rolo--SKXQAx3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-reverso-com-rolo--SKXQAx3.gif', ARRAY['abdômen'], ARRAY['rolo'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your arms extended straight above your head and your legs straight out in front of you.","Step:2 Set the roller between your feet and grip it with your toes.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:45.931973+00', '2026-10-31 19:44:45.795+00'), ('slDvUAU', 'Rosca martelo com halteres', 'dumbbell hammer curl', 'rosca-martelo-com-halteres', 'https://static.exercisedb.dev/media/slDvUAU.gif', 'catalogo/rosca-martelo-com-halteres--slDvUAU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-martelo-com-halteres--slDvUAU.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.","Step:2 Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl with palms facing each other and elbows near your sides; avoid rocking back.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:46.302173+00', '2026-10-31 19:44:46.167+00'), ('SLKj2pX', 'Abdominal casulo', 'cocoons', 'abdominal-casulo', 'https://static.exercisedb.dev/media/SLKj2pX.gif', 'catalogo/abdominal-casulo--SLKj2pX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-casulo--SLKj2pX.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril','eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:46.339115+00', '2026-10-31 19:44:46.196+00'), ('sM84pE4', 'Alongamento de dorsal na bola suíça', 'exercise ball lat stretch', 'alongamento-de-dorsal-na-bola-suica', 'https://static.exercisedb.dev/media/sM84pE4.gif', 'catalogo/alongamento-de-dorsal-na-bola-suica--sM84pE4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-dorsal-na-bola-suica--sM84pE4.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['latíssimo do dorso'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on a stability ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand and extend your arm straight up overhead.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:46.723783+00', '2026-10-31 19:44:46.592+00'), ('Sn8wxAI', 'Abdominal na bola suíça com braços estendidos', 'crunch (on stability ball, arms straight)', 'abdominal-na-bola-suica-com-bracos-estendidos', 'https://static.exercisedb.dev/media/Sn8wxAI.gif', 'catalogo/abdominal-na-bola-suica-com-bracos-estendidos--Sn8wxAI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-na-bola-suica-com-bracos-estendidos--Sn8wxAI.gif', ARRAY['abdômen'], ARRAY['bola suíça'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Recline on the ball until your lower back is supported and your upper body is parallel to the floor.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:46.76456+00', '2026-10-31 19:44:46.631+00'), ('SNFfUff', 'Elevação de quadril deitado com barra', 'barbell lying lifting (on hip)', 'elevacao-de-quadril-deitado-com-barra', 'https://static.exercisedb.dev/media/SNFfUff.gif', 'catalogo/elevacao-de-quadril-deitado-com-barra--SNFfUff.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-deitado-com-barra--SNFfUff.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['isquiotibiais','quadríceps'], '["Step:1 Settle onto your back on a bench with your feet planted and your knees bent.","Step:2 Take hold of the barbell with palms facing down and position it on your hips.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:46.74832+00', '2026-10-31 19:44:46.615+00'), ('Snj1wSv', 'Flexão de braço pliométrica', 'plyo push up', 'flexao-de-braco-pliometrica', 'https://static.exercisedb.dev/media/Snj1wSv.gif', 'catalogo/flexao-de-braco-pliometrica--Snj1wSv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-pliometrica--Snj1wSv.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width.","Step:2 Lower your chest toward the ground by bending your elbows, keeping your body in a straight line.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:47.00452+00', '2026-10-31 19:44:46.864+00'), ('soIB2rj', 'Flexão de braço diamante', 'diamond push-up', 'flexao-de-braco-diamante', 'https://static.exercisedb.dev/media/soIB2rj.gif', 'catalogo/flexao-de-braco-diamante--soIB2rj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-diamante--soIB2rj.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Begin in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Step:2 Hold your body in a straight line from head to toe, engaging your core and glutes.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:47.305871+00', '2026-10-31 19:44:47.177+00'), ('SP3hUez', 'Batida de pernas estilo nado (swimmer kicks)', 'Swimmer Kicks', 'batida-de-pernas-estilo-nado-swimmer-kicks', 'https://static.exercisedb.dev/media/SP3hUez.gif', 'catalogo/batida-de-pernas-estilo-nado-swimmer-kicks--SP3hUez.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/batida-de-pernas-estilo-nado-swimmer-kicks--SP3hUez.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['isquiotibiais','quadríceps','panturrilhas'], '["Step:1 Position yourself face down on a mat with your arms extended overhead.","Step:2 Brace your trunk and lift your chest and legs off the ground simultaneously.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:44:47.325562+00', '2026-10-31 19:44:47.194+00'), ('SpsOSXk', 'Puxada por trás da nuca no cabo', 'cable rear pulldown', 'puxada-por-tras-da-nuca-no-cabo', 'https://static.exercisedb.dev/media/SpsOSXk.gif', 'catalogo/puxada-por-tras-da-nuca-no-cabo--SpsOSXk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-por-tras-da-nuca-no-cabo--SpsOSXk.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Set the cable machine so that the pulley is at the highest position.","Step:2 Sit facing the machine with your feet planted and your knees soft.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:44:47.369866+00', '2026-10-31 19:44:47.23+00'), ('SpYC0Kp', 'Supino reto com halteres', 'dumbbell bench press', 'supino-reto-com-halteres', 'https://static.exercisedb.dev/media/SpYC0Kp.gif', 'catalogo/supino-reto-com-halteres--SpYC0Kp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-reto-com-halteres--SpYC0Kp.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Take a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:47.382199+00', '2026-10-31 19:44:47.218+00'), ('SSsBDwB', 'Avanço para trás com halteres', 'dumbbell rear lunge', 'avanco-para-tras-com-halteres', 'https://static.exercisedb.dev/media/SSsBDwB.gif', 'catalogo/avanco-para-tras-com-halteres--SSsBDwB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-para-tras-com-halteres--SSsBDwB.gif', ARRAY['coxas'], ARRAY['halteres'], ARRAY['glúteos'], ARRAY['quadríceps','isquiotibiais','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Step backward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:47.60621+00', '2026-10-31 19:44:47.463+00'), ('sTfvVsG', 'Crucifixo inverso com elástico', 'band reverse fly', 'crucifixo-inverso-com-elastico', 'https://static.exercisedb.dev/media/sTfvVsG.gif', 'catalogo/crucifixo-inverso-com-elastico--sTfvVsG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-elastico--sTfvVsG.gif', ARRAY['ombros'], ARRAY['elástico'], ARRAY['deltoides'], ARRAY['parte superior das costas','trapézio'], '["Step:1 Connect the band to a stationary object at chest height.","Step:2 Stand and set your feet about shoulder width and hold the band with both hands in front of you.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:47.905879+00', '2026-10-31 19:44:47.755+00'), ('sTg7iys', 'Elevação frontal com elástico', 'band front lateral raise', 'elevacao-frontal-com-elastico', 'https://static.exercisedb.dev/media/sTg7iys.gif', 'catalogo/elevacao-frontal-com-elastico--sTg7iys.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-elastico--sTg7iys.gif', ARRAY['ombros'], ARRAY['elástico'], ARRAY['deltoides'], ARRAY['trapézio','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold the band ahead of your thighs with your palms facing down.","Step:2 Maintain straight arms and lift the band up in front of you until your arms are parallel to the ground.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:47.895659+00', '2026-10-31 19:44:47.762+00'), ('sU5BrfP', 'Alongamento de posterior de coxa com perna elevada', 'leg up hamstring stretch', 'alongamento-de-posterior-de-coxa-com-perna-elevada', 'https://static.exercisedb.dev/media/sU5BrfP.gif', 'catalogo/alongamento-de-posterior-de-coxa-com-perna-elevada--sU5BrfP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-posterior-de-coxa-com-perna-elevada--sU5BrfP.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['isquiotibiais'], ARRAY['glúteos'], '["Step:1 Settle onto your back with your legs extended.","Step:2 Bend one knee and bring it toward your chest, holding onto your thigh or shin.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:48.168872+00', '2026-10-31 19:44:48.026+00'), ('sVQCCeG', 'Cadeirinha com marcha na parede', 'march sit (wall)', 'cadeirinha-com-marcha-na-parede', 'https://static.exercisedb.dev/media/sVQCCeG.gif', 'catalogo/cadeirinha-com-marcha-na-parede--sVQCCeG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cadeirinha-com-marcha-na-parede--sVQCCeG.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','isquiotibiais','panturrilhas'], '["Step:1 Stand and set your back against a wall and your feet about hip width.","Step:2 With control slide your back down the wall until your knees are bent at a 90-degree angle.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Lift one knee at a time while holding the wall-sit depth and keeping your back against the wall.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:44:47.955669+00', '2026-10-31 19:44:47.81+00'), ('sVvXT5J', 'Flexão pike na bola suíça', 'exercise ball pike push up', 'flexao-pike-na-bola-suica', 'https://static.exercisedb.dev/media/sVvXT5J.gif', 'catalogo/flexao-pike-na-bola-suica--sVvXT5J.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-pike-na-bola-suica--sVvXT5J.gif', ARRAY['peito'], ARRAY['bola suíça'], ARRAY['peitorais'], ARRAY['deltoides','tríceps','core'], '["Step:1 Begin in a push-up position with your hands on the floor and your shins resting on the stability ball.","Step:2 Brace your trunk and lift your hips up toward the ceiling, rolling the ball toward your hands.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:48.429324+00', '2026-10-31 19:44:48.287+00'), ('SxHteRW', 'Elevação frontal alternada com halteres em pé', 'dumbbell standing alternate raise', 'elevacao-frontal-alternada-com-halteres-em-pe', 'https://static.exercisedb.dev/media/SxHteRW.gif', 'catalogo/elevacao-frontal-alternada-com-halteres-em-pe--SxHteRW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-alternada-com-halteres-em-pe--SxHteRW.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your body.","Step:2 Keep your spine in a comfortable neutral position and your core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:44:48.4736+00', '2026-10-31 19:44:48.338+00'), ('sxY5Biu', 'Rosca Zottman unilateral no banco Scott com halter', 'Dumbbell Single-Arm Zottman Preacher Curl', 'rosca-zottman-unilateral-no-banco-scott-com-halter', 'https://static.exercisedb.dev/media/sxY5Biu.gif', 'catalogo/rosca-zottman-unilateral-no-banco-scott-com-halter--sxY5Biu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-zottman-unilateral-no-banco-scott-com-halter--sxY5Biu.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher curl bench and hold a dumbbell in one hand with palms facing up.","Step:2 Set your upper arm on the preacher bench pad, letting your arm to fully extend.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl palms-up, turn the palms down at the top, and lower with that overhand grip.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:48.508131+00', '2026-10-31 19:44:48.35+00'), ('sYCcnon', 'Tríceps unilateral em pé no cabo', 'Cable Standing Single-Arm Triceps Extension', 'triceps-unilateral-em-pe-no-cabo', 'https://static.exercisedb.dev/media/sYCcnon.gif', 'catalogo/triceps-unilateral-em-pe-no-cabo--sYCcnon.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-unilateral-em-pe-no-cabo--sYCcnon.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width, facing the cable machine.","Step:2 Take hold of the cable handle with your right hand, palm facing down, and position your arm so that it is straight and parallel to the ground.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:44:48.457956+00', '2026-10-31 19:44:48.321+00'), ('SYJ4Bkt', 'Rosca Scott deitado com barra', 'barbell lying preacher curl', 'rosca-scott-deitado-com-barra', 'https://static.exercisedb.dev/media/SYJ4Bkt.gif', 'catalogo/rosca-scott-deitado-com-barra--SYJ4Bkt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-deitado-com-barra--SYJ4Bkt.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with palms facing up.","Step:2 With your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:48.795222+00', '2026-10-31 19:44:48.653+00'), ('szIn2UK', 'Abdominal com fase negativa', 'negative crunch', 'abdominal-com-fase-negativa', 'https://static.exercisedb.dev/media/szIn2UK.gif', 'catalogo/abdominal-com-fase-negativa--szIn2UK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-fase-negativa--szIn2UK.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:49.095748+00', '2026-10-31 19:44:48.961+00'), ('sZOR9EV', 'Rotação de tronco ajoelhado na máquina', 'Machine Kneeling Twist', 'rotacao-de-tronco-ajoelhado-na-maquina', 'https://static.exercisedb.dev/media/sZOR9EV.gif', 'catalogo/rotacao-de-tronco-ajoelhado-na-maquina--sZOR9EV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-ajoelhado-na-maquina--sZOR9EV.gif', ARRAY['abdômen'], ARRAY['máquina articulada'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles or the sides of the machine for stability.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:49.052924+00', '2026-10-31 19:44:48.921+00'), ('SzX3uzM', 'Remada curvada com barra pegada supinada', 'Barbell Reverse-Grip Bent Over Row', 'remada-curvada-com-barra-pegada-supinada', 'https://static.exercisedb.dev/media/SzX3uzM.gif', 'catalogo/remada-curvada-com-barra-pegada-supinada--SzX3uzM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-com-barra-pegada-supinada--SzX3uzM.gif', ARRAY['costas'], ARRAY['barra'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take a barbell with palms facing down, and hands just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:49.14169+00', '2026-10-31 19:44:48.997+00'), ('T0yTjgW', 'Supino na máquina', 'Machine Chest Press', 'supino-na-maquina', 'https://static.exercisedb.dev/media/T0yTjgW.gif', 'catalogo/supino-na-maquina--T0yTjgW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-na-maquina--T0yTjgW.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and position your elbows at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:49.314282+00', '2026-10-31 19:44:49.178+00'), ('T2fA5Ir', 'Agachamento no bosu', 'squat on bosu ball', 'agachamento-no-bosu', 'https://static.exercisedb.dev/media/T2fA5Ir.gif', 'catalogo/agachamento-no-bosu--T2fA5Ir.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-no-bosu--T2fA5Ir.gif', ARRAY['coxas'], ARRAY['bosu'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Set the bosu ball on the ground with the flat side up.","Step:2 Stand and set your feet about shoulder width and position yourself on top of the bosu ball.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:49.392128+00', '2026-10-31 19:44:49.253+00'), ('T2mxWqc', 'Barra fixa supinada', 'chin-up', 'barra-fixa-supinada', 'https://static.exercisedb.dev/media/T2mxWqc.gif', 'catalogo/barra-fixa-supinada--T2mxWqc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada--T2mxWqc.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.","Step:2 Brace your trunk and pull your body up toward the bar, leading with your chest.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:49.537432+00', '2026-10-31 19:44:49.403+00'), ('t8iSghb', 'Afundo com barra', 'barbell lunge', 'afundo-com-barra', 'https://static.exercisedb.dev/media/t8iSghb.gif', 'catalogo/afundo-com-barra--t8iSghb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-com-barra--t8iSghb.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width and a barbell resting on your upper back.","Step:2 Step forward with your right foot, keeping your torso upright.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:44:49.832794+00', '2026-10-31 19:44:49.685+00'), ('T8UpLkb', 'Barra fixa com pegada mista', 'mixed grip chin-up', 'barra-fixa-com-pegada-mista', 'https://static.exercisedb.dev/media/T8UpLkb.gif', 'catalogo/barra-fixa-com-pegada-mista--T8UpLkb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-pegada-mista--T8UpLkb.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with palms facing up (palms facing toward you) and your hands just beyond shoulder width.","Step:2 Suspend yourself from the bar with your arms straight and your feet off the ground.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:49.880348+00', '2026-10-31 19:44:49.736+00'), ('tBWXbIT', 'Crucifixo inclinado no cabo', 'cable incline fly', 'crucifixo-inclinado-no-cabo', 'https://static.exercisedb.dev/media/tBWXbIT.gif', 'catalogo/crucifixo-inclinado-no-cabo--tBWXbIT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inclinado-no-cabo--tBWXbIT.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the cable machine to a low position and attach the handles.","Step:2 Take a seat on an incline bench with your back against the pad and feet planted.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:50.323407+00', '2026-10-31 19:44:50.185+00'), ('tc5dYrf', 'Remada em pé para deltoide posterior com elástico', 'band standing rear delt row', 'remada-em-pe-para-deltoide-posterior-com-elastico', 'https://static.exercisedb.dev/media/tc5dYrf.gif', 'catalogo/remada-em-pe-para-deltoide-posterior-com-elastico--tc5dYrf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-para-deltoide-posterior-com-elastico--tc5dYrf.gif', ARRAY['ombros'], ARRAY['elástico'], ARRAY['deltoides'], ARRAY['trapézio','romboides','bíceps'], '["Step:1 Stand and set your feet about shoulder width and place the band under your feet.","Step:2 Take hold of the band handles with your palms facing each other and your arms extended in front of you.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:50.028081+00', '2026-10-31 19:44:49.868+00'), ('TDYiji6', 'Agachamento com salto', 'jump squat', 'agachamento-com-salto', 'https://static.exercisedb.dev/media/TDYiji6.gif', 'catalogo/agachamento-com-salto--TDYiji6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-salto--TDYiji6.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:50.264218+00', '2026-10-31 19:44:50.132+00'), ('TFA88iB', 'Elevação frontal com elástico', 'band front raise', 'elevacao-frontal-com-elastico', 'https://static.exercisedb.dev/media/TFA88iB.gif', 'catalogo/elevacao-frontal-com-elastico--TFA88iB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-com-elastico--TFA88iB.gif', ARRAY['ombros'], ARRAY['elástico'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold the band ahead of your thighs with your palms facing down.","Step:2 Maintain straight arms and With control raise them forward until they are parallel to the ground.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:50.690123+00', '2026-10-31 19:44:50.548+00'), ('tFGKm99', 'Alongamento intermediário de flexores do quadril e quadríceps com corda', 'intermediate hip flexor and quad stretch', 'alongamento-intermediario-de-flexores-do-quadril-e-quadriceps-com-corda', 'https://static.exercisedb.dev/media/tFGKm99.gif', 'catalogo/alongamento-intermediario-de-flexores-do-quadril-e-quadriceps-com-corda--tFGKm99.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-intermediario-de-flexores-do-quadril-e-quadriceps-com-corda--tFGKm99.gif', ARRAY['coxas'], ARRAY['corda'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand upright with your feet about shoulder width.","Step:2 Use a stable object for support.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:50.327006+00', '2026-10-31 19:44:50.175+00'), ('TFqbd8t', 'Abdominal no solo', 'crunch floor', 'abdominal-no-solo', 'https://static.exercisedb.dev/media/TFqbd8t.gif', 'catalogo/abdominal-no-solo--TFqbd8t.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-no-solo--TFqbd8t.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:50.871823+00', '2026-10-31 19:44:50.732+00'), ('tFToB7l', 'Prancha invertida com elevação de perna', 'reverse plank with leg lift', 'prancha-invertida-com-elevacao-de-perna', 'https://static.exercisedb.dev/media/tFToB7l.gif', 'catalogo/prancha-invertida-com-elevacao-de-perna--tFToB7l.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-invertida-com-elevacao-de-perna--tFToB7l.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['glúteos','posteriores de coxa','deltoides'], '["Step:1 Take a seat on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing toward your feet.","Step:2 Before moving, press through your hands and lift your hips off the ground, coming into a reverse plank position.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:51.106059+00', '2026-10-31 19:44:50.965+00'), ('tgryw5Y', 'Flexão de braço na bola suíça', 'push-up (on stability ball)', 'flexao-de-braco-na-bola-suica', 'https://static.exercisedb.dev/media/tgryw5Y.gif', 'catalogo/flexao-de-braco-na-bola-suica--tgryw5Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-na-bola-suica--tgryw5Y.gif', ARRAY['peito'], ARRAY['bola suíça'], ARRAY['peitorais'], ARRAY['tríceps','deltoides','core'], '["Step:1 Set the stability ball on the ground and position yourself facing down with your hands on the ball, about shoulder width.","Step:2 Reach your legs straight out behind you, balancing on your toes.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:50.902958+00', '2026-10-31 19:44:50.767+00'), ('ThKP69G', 'Tríceps pulley com pegada invertida na barra W com arm blaster', 'Cable Reverse-Grip Triceps Pushdown (Sz-Bar) (With Arm Blaster)', 'triceps-pulley-com-pegada-invertida-na-barra-w-com-arm-blaster', 'https://static.exercisedb.dev/media/ThKP69G.gif', 'catalogo/triceps-pulley-com-pegada-invertida-na-barra-w-com-arm-blaster--ThKP69G.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-pulley-com-pegada-invertida-na-barra-w-com-arm-blaster--ThKP69G.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Connect a straight bar to the cable machine at the highest setting.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:44:51.169425+00', '2026-10-31 19:44:51.033+00'), ('TiaZTxx', 'Rosca direta sentado com halteres', 'dumbbell seated curl', 'rosca-direta-sentado-com-halteres', 'https://static.exercisedb.dev/media/TiaZTxx.gif', 'catalogo/rosca-direta-sentado-com-halteres--TiaZTxx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-sentado-com-halteres--TiaZTxx.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; a dumbbell in each hand, palms facing forward.","Step:2 Keep your spine in a comfortable neutral position and your elbows close to your torso.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:51.304774+00', '2026-10-31 19:44:51.165+00'), ('tig3PXb', 'Remada em pé com pegada fechada com peso corporal', 'bodyweight standing close-grip row', 'remada-em-pe-com-pegada-fechada-com-peso-corporal', 'https://static.exercisedb.dev/media/tig3PXb.gif', 'catalogo/remada-em-pe-com-pegada-fechada-com-peso-corporal--tig3PXb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-com-pegada-fechada-com-peso-corporal--tig3PXb.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Bend forward at the waist, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:51.42961+00', '2026-10-31 19:44:51.279+00'), ('tj41Nu6', 'Leg press 45° com pés afastados', 'sled 45° leg wide press', 'leg-press-45-com-pes-afastados', 'https://static.exercisedb.dev/media/tj41Nu6.gif', 'catalogo/leg-press-45-com-pes-afastados--tj41Nu6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-45-com-pes-afastados--tj41Nu6.gif', ARRAY['coxas'], ARRAY['leg press'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the sled machine to a 45-degree angle.","Step:2 Take a seat on the sled machine with your back against the pad and your feet on the foot platform.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:51.522726+00', '2026-10-31 19:44:51.371+00'), ('tJ5nYqo', 'Rosca direta com barra W e arm blaster', 'ez-bar biceps curl (with arm blaster)', 'rosca-direta-com-barra-w-e-arm-blaster', 'https://static.exercisedb.dev/media/tJ5nYqo.gif', 'catalogo/rosca-direta-com-barra-w-e-arm-blaster--tJ5nYqo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra-w-e-arm-blaster--tJ5nYqo.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up.","Step:2 Set your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:52.024734+00', '2026-10-31 19:44:51.889+00'), ('tnaj0mT', 'Swing 360', 'swing 360', 'swing-360', 'https://static.exercisedb.dev/media/tnaj0mT.gif', 'catalogo/swing-360--tnaj0mT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/swing-360--tnaj0mT.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['deltoides','core'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Keep your arms straight out in front of you, parallel to the ground.","Step:3 Set the shoulders and let the weight move back between the legs as the hips hinge.","Step:4 Hinge back, then drive the hips forward to send the weight up; let the arms guide it.","Step:5 Let the hips, not the shoulders, provide the power.","Step:6 Let the weight fall naturally and hinge again for the next swing."]', '2026-10-31 19:44:52.062385+00', '2026-10-31 19:44:51.922+00'), ('Tq6gbK6', 'Remada sentada no cabo com coluna reta', 'cable straight back seated row', 'remada-sentada-no-cabo-com-coluna-reta', 'https://static.exercisedb.dev/media/Tq6gbK6.gif', 'catalogo/remada-sentada-no-cabo-com-coluna-reta--Tq6gbK6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-no-cabo-com-coluna-reta--Tq6gbK6.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços','deltoides'], '["Step:1 Take a seat on the cable row machine with your feet flat on the footrests and your knees soft.","Step:2 Hold the cable handles with palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:52.477935+00', '2026-10-31 19:44:52.342+00'), ('trmte8s', 'Encolhimento com elástico', 'band shrug', 'encolhimento-com-elastico', 'https://static.exercisedb.dev/media/trmte8s.gif', 'catalogo/encolhimento-com-elastico--trmte8s.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-com-elastico--trmte8s.gif', ARRAY['costas'], ARRAY['elástico'], ARRAY['trapézio'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and place the band under your feet, holding the ends with your hands.","Step:2 Maintain straight arms and relaxed, and let the band hang ahead of your thighs.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:44:52.276011+00', '2026-10-31 19:44:52.132+00'), ('trqKQv2', 'Supino no Smith', 'smith bench press', 'supino-no-smith', 'https://static.exercisedb.dev/media/trqKQv2.gif', 'catalogo/supino-no-smith--trqKQv2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-no-smith--trqKQv2.gif', ARRAY['peito'], ARRAY['Smith'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the height of the smith machine bar to chest level.","Step:2 Settle onto the bench with your feet firmly planted on the ground.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:52.376595+00', '2026-10-31 19:44:52.231+00'), ('tTuZSDT', 'Puxada unilateral aberta na máquina', 'Machine Single-Arm Lateral Wide Pulldown', 'puxada-unilateral-aberta-na-maquina', 'https://static.exercisedb.dev/media/tTuZSDT.gif', 'catalogo/puxada-unilateral-aberta-na-maquina--tTuZSDT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-unilateral-aberta-na-maquina--tTuZSDT.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handle with palms facing down and fully extend your arm, keeping a slight bend in your elbow.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it."]', '2026-10-31 19:44:54.062279+00', '2026-10-31 19:44:53.92+00'), ('TUZLh71', 'Agachamento com elástico', 'band squat', 'agachamento-com-elastico', 'https://static.exercisedb.dev/media/TUZLh71.gif', 'catalogo/agachamento-com-elastico--TUZLh71.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-elastico--TUZLh71.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, with the band placed just above your knees.","Step:2 With your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:52.848185+00', '2026-10-31 19:44:52.717+00'), ('TV87DNB', 'Inchworm (caminhada com as mãos)', 'inchworm', 'inchworm-caminhada-com-as-maos', 'https://static.exercisedb.dev/media/TV87DNB.gif', 'catalogo/inchworm-caminhada-com-as-maos--TV87DNB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/inchworm-caminhada-com-as-maos--TV87DNB.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','posteriores de coxa'], '["Step:1 Begin in a standing position with your feet about hip width.","Step:2 Before moving, bend forward at the waist and place your hands on the ground in front of you.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:44:53.104088+00', '2026-10-31 19:44:52.964+00'), ('TVdivgY', 'Supino inclinado alternado com halteres', 'dumbbell incline alternate press', 'supino-inclinado-alternado-com-halteres', 'https://static.exercisedb.dev/media/TVdivgY.gif', 'catalogo/supino-inclinado-alternado-com-halteres--TVdivgY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-alternado-com-halteres--TVdivgY.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, resting on your thighs.","Step:2 Recline on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:44:53.521058+00', '2026-10-31 19:44:53.386+00'), ('TXtXc84', 'Abdominal infra grupado na polia', 'cable tuck reverse crunch', 'abdominal-infra-grupado-na-polia', 'https://static.exercisedb.dev/media/TXtXc84.gif', 'catalogo/abdominal-infra-grupado-na-polia--TXtXc84.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-infra-grupado-na-polia--TXtXc84.gif', ARRAY['abdômen'], ARRAY['polia'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Connect a cable to a low pulley and lie down on a mat facing up.","Step:2 Take hold of the cable with both hands and extend your arms straight up above your chest.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:52.997182+00', '2026-10-31 19:44:52.842+00'), ('tZkGYZ9', 'Abdominal bicicleta com elástico', 'band bicycle crunch', 'abdominal-bicicleta-com-elastico', 'https://static.exercisedb.dev/media/tZkGYZ9.gif', 'catalogo/abdominal-bicicleta-com-elastico--tZkGYZ9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-bicicleta-com-elastico--tZkGYZ9.gif', ARRAY['abdômen'], ARRAY['faixa elástica'], ARRAY['abdominais'], ARRAY['flexores do quadril','oblíquos'], '["Step:1 Settle onto your back with your hands behind your head and your knees bent.","Step:2 Lift your feet off the ground and bring your right knee toward your chest while simultaneously twisting your torso to bring your left elbow toward your right knee.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Bring one elbow toward the opposite knee as the other leg extends; switch sides in a steady rhythm.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:53.450596+00', '2026-10-31 19:44:53.314+00'), ('tznL2Ad', 'Arremesso duplo com kettlebell (double jerk)', 'kettlebell double jerk', 'arremesso-duplo-com-kettlebell-double-jerk', 'https://static.exercisedb.dev/media/tznL2Ad.gif', 'catalogo/arremesso-duplo-com-kettlebell-double-jerk--tznL2Ad.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arremesso-duplo-com-kettlebell-double-jerk--tznL2Ad.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Receive the load with the torso braced and feet stable.","Step:6 Stand tall to finish, then lower the weight under control before the next rep."]', '2026-10-31 19:44:53.996379+00', '2026-10-31 19:44:53.858+00'), ('u0cNiij', 'Elevação de quadril baixa no chão', 'low glute bridge on floor', 'elevacao-de-quadril-baixa-no-chao', 'https://static.exercisedb.dev/media/u0cNiij.gif', 'catalogo/elevacao-de-quadril-baixa-no-chao--u0cNiij.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-quadril-baixa-no-chao--u0cNiij.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','core'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your arms by your sides, palms facing down.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:53.772805+00', '2026-10-31 19:44:53.641+00'), ('u0pLNgz', 'Panturrilha unilateral no leg press com sled', 'Sled Single-Leg Calf Press On Leg Press', 'panturrilha-unilateral-no-leg-press-com-sled', 'https://static.exercisedb.dev/media/u0pLNgz.gif', 'catalogo/panturrilha-unilateral-no-leg-press-com-sled--u0pLNgz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-unilateral-no-leg-press-com-sled--u0pLNgz.gif', ARRAY['panturrilhas'], ARRAY['máquina sled'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set the seat of the leg press machine so that your knees are soft when your feet are on the sled.","Step:2 Take a seat on the machine with your back against the backrest and your feet on the sled, about shoulder width.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:44:54.318854+00', '2026-10-31 19:44:54.167+00'), ('u27Kcdz', 'Extensão de quadril no banco', 'bench hip extension', 'extensao-de-quadril-no-banco', 'https://static.exercisedb.dev/media/u27Kcdz.gif', 'catalogo/extensao-de-quadril-no-banco--u27Kcdz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-quadril-no-banco--u27Kcdz.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa'], '["Step:1 Take a seat on a bench with your back against the bench and your feet planted.","Step:2 Set your hands on the bench for support.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:54.438777+00', '2026-10-31 19:44:54.295+00'), ('u2X71Np', 'Elevação frontal na polia', 'cable front raise', 'elevacao-frontal-na-polia', 'https://static.exercisedb.dev/media/u2X71Np.gif', 'catalogo/elevacao-frontal-na-polia--u2X71Np.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-na-polia--u2X71Np.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['tríceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width and Hold the cable handle with palms facing down.","Step:2 Keep your spine in a comfortable neutral position and your core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:44:54.360696+00', '2026-10-31 19:44:54.221+00'), ('U3ffHlY', 'Tríceps testa deitado no chão com corda na polia', 'Cable Rope Lying On Floor Triceps Extension', 'triceps-testa-deitado-no-chao-com-corda-na-polia', 'https://static.exercisedb.dev/media/U3ffHlY.gif', 'catalogo/triceps-testa-deitado-no-chao-com-corda-na-polia--U3ffHlY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-deitado-no-chao-com-corda-na-polia--U3ffHlY.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Fit the rope handle to the cable''s lowest setting.","Step:2 Settle onto the floor facing up, with your head toward the cable machine.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:54.553881+00', '2026-10-31 19:44:54.405+00'), ('u4bAmKp', 'Desenvolvimento com rotação e elástico', 'band twisting overhead press', 'desenvolvimento-com-rotacao-e-elastico', 'https://static.exercisedb.dev/media/u4bAmKp.gif', 'catalogo/desenvolvimento-com-rotacao-e-elastico--u4bAmKp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-com-rotacao-e-elastico--u4bAmKp.gif', ARRAY['ombros'], ARRAY['faixa elástica'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and place the band under your feet.","Step:2 Take hold of the band handles at shoulder height with your palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weights up while turning the palms inward; reverse the turn as you lower.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:54.87951+00', '2026-10-31 19:44:54.733+00'), ('u5ESqzH', 'Panturrilha burro (donkey calf raise)', 'donkey calf raise', 'panturrilha-burro-donkey-calf-raise', 'https://static.exercisedb.dev/media/u5ESqzH.gif', 'catalogo/panturrilha-burro-donkey-calf-raise--u5ESqzH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-burro-donkey-calf-raise--u5ESqzH.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your toes on an elevated surface, such as a step or block.","Step:2 Set your hands on a stable support, such as a wall or railing, for balance.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:44:55.216848+00', '2026-10-31 19:44:55.084+00'), ('U5INZY6', 'Puxada unilateral na polia', 'Cable Single-Arm Pulldown', 'puxada-unilateral-na-polia', 'https://static.exercisedb.dev/media/U5INZY6.gif', 'catalogo/puxada-unilateral-na-polia--U5INZY6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-unilateral-na-polia--U5INZY6.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Connect a single handle to a high pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it."]', '2026-10-31 19:44:55.240883+00', '2026-10-31 19:44:55.098+00'), ('U6G2gk9', 'Body-up (extensão de tríceps com peso corporal)', 'body-up', 'body-up-extensao-de-triceps-com-peso-corporal', 'https://static.exercisedb.dev/media/U6G2gk9.gif', 'catalogo/body-up-extensao-de-triceps-com-peso-corporal--U6G2gk9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/body-up-extensao-de-triceps-com-peso-corporal--U6G2gk9.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Begin by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Step:2 Reach your legs out in front of you, keeping your heels on the ground and your body straight.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:44:55.181806+00', '2026-10-31 19:44:55.045+00'), ('U7D9Fx3', 'Tríceps francês inclinado com halteres (duas mãos)', 'Dumbbell Incline Two-Arm Extension', 'triceps-frances-inclinado-com-halteres-duas-maos', 'https://static.exercisedb.dev/media/U7D9Fx3.gif', 'catalogo/triceps-frances-inclinado-com-halteres-duas-maos--U7D9Fx3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-inclinado-com-halteres-duas-maos--U7D9Fx3.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on an incline bench with a dumbbell in each hand, resting on your thighs.","Step:2 With control lie back on the bench, keeping the dumbbells close to your chest.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:55.171563+00', '2026-10-31 19:44:55.032+00'), ('UDlhcO8', 'Remada alta com barra', 'barbell upright row', 'remada-alta-com-barra', 'https://static.exercisedb.dev/media/UDlhcO8.gif', 'catalogo/remada-alta-com-barra--UDlhcO8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-com-barra--UDlhcO8.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell with palms facing down, hands just beyond shoulder width.","Step:2 Keep the barbell hanging ahead of your thighs, arms straight.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:55.50082+00', '2026-10-31 19:44:55.353+00'), ('UDm6cGl', 'Desenvolvimento alternado com kettlebell (seesaw press)', 'kettlebell seesaw press', 'desenvolvimento-alternado-com-kettlebell-seesaw-press', 'https://static.exercisedb.dev/media/UDm6cGl.gif', 'catalogo/desenvolvimento-alternado-com-kettlebell-seesaw-press--UDm6cGl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-alternado-com-kettlebell-seesaw-press--UDm6cGl.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.","Step:2 Before moving, press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:55.890568+00', '2026-10-31 19:44:55.724+00'), ('UEjSrKI', 'Rotação de tronco sentado na polia', 'cable seated twist', 'rotacao-de-tronco-sentado-na-polia', 'https://static.exercisedb.dev/media/UEjSrKI.gif', 'catalogo/rotacao-de-tronco-sentado-na-polia--UEjSrKI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-sentado-na-polia--UEjSrKI.gif', ARRAY['abdômen'], ARRAY['polia'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Take a seat on a cable machine with your feet planted and your knees soft.","Step:2 Take hold of the cable handle with both hands and extend your arms straight in front of you.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:44:56.330427+00', '2026-10-31 19:44:56.195+00'), ('ufaxB52', 'Flexão de braço fechada com elástico', 'band close-grip push-up', 'flexao-de-braco-fechada-com-elastico', 'https://static.exercisedb.dev/media/ufaxB52.gif', 'catalogo/flexao-de-braco-fechada-com-elastico--ufaxB52.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-fechada-com-elastico--ufaxB52.gif', ARRAY['braços'], ARRAY['faixa elástica'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Set a band around your upper arms, just above the elbows.","Step:2 Get into a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:44:55.808996+00', '2026-10-31 19:44:55.667+00'), ('UfePqpx', 'Levantamento terra no Smith', 'smith deadlift', 'levantamento-terra-no-smith', 'https://static.exercisedb.dev/media/UfePqpx.gif', 'catalogo/levantamento-terra-no-smith--UfePqpx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-no-smith--UfePqpx.gif', ARRAY['coxas'], ARRAY['Smith'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','eretores da espinha'], '["Step:1 Prepare the smith machine with the bar at hip height.","Step:2 Stand and set your feet about shoulder width, toes pointing slightly outward.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:44:56.157135+00', '2026-10-31 19:44:56.023+00'), ('UFGF6gk', 'Remada sentada cruzada com corda na polia', 'cable rope crossover seated row', 'remada-sentada-cruzada-com-corda-na-polia', 'https://static.exercisedb.dev/media/UFGF6gk.gif', 'catalogo/remada-sentada-cruzada-com-corda-na-polia--UFGF6gk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-cruzada-com-corda-na-polia--UFGF6gk.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on the rowing machine with your feet flat on the footrests and your knees soft.","Step:2 Hold the cable ropes with palms facing down, palms facing each other.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:56.380986+00', '2026-10-31 19:44:56.229+00'), ('UgDm3oy', 'Agachamento com salto ajoelhado com barra', 'kneeling jump squat', 'agachamento-com-salto-ajoelhado-com-barra', 'https://static.exercisedb.dev/media/UgDm3oy.gif', 'catalogo/agachamento-com-salto-ajoelhado-com-barra--UgDm3oy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-salto-ajoelhado-com-barra--UgDm3oy.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin by kneeling on the ground with your feet about hip width and your toes pointing forward.","Step:2 Take a barbell across your upper back, resting it on your shoulders.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:44:56.514397+00', '2026-10-31 19:44:56.282+00'), ('UGhRD1A', 'Limpador de para-brisa deitado', 'Lying Windshield Wipers', 'limpador-de-para-brisa-deitado', 'https://static.exercisedb.dev/media/UGhRD1A.gif', 'catalogo/limpador-de-para-brisa-deitado--UGhRD1A.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/limpador-de-para-brisa-deitado--UGhRD1A.gif', ARRAY['abdômen'], ARRAY['assistido'], ARRAY['abdominais'], ARRAY['flexores do quadril','oblíquos'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Set your hands under your glutes for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift both legs, then lower them together toward one side without letting the shoulders roll off the floor.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Bring the legs back through center, then lower them toward the other side with the same control."]', '2026-10-31 19:44:56.796048+00', '2026-10-31 19:44:56.653+00'), ('UHJlbu3', 'Swing com Kettlebell', 'kettlebell swing', 'swing-com-kettlebell', 'https://static.exercisedb.dev/media/UHJlbu3.gif', 'catalogo/swing-com-kettlebell--UHJlbu3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/swing-com-kettlebell--UHJlbu3.gif', ARRAY['Coxas'], ARRAY['Kettlebell'], ARRAY['Glúteos'], ARRAY['Posteriores da coxa','Core'], '["Step:1 Stand and set your feet about shoulder width, toes pointed slightly outward.","Step:2 Take hold of the kettlebell with both hands ahead of your body, arms extended.","Step:3 Set the shoulders and let the weight move back between the legs as the hips hinge.","Step:4 Hinge back, then drive the hips forward to send the weight up; let the arms guide it.","Step:5 Let the hips, not the shoulders, provide the power.","Step:6 Let the weight fall naturally and hinge again for the next swing."]', '2026-10-31 19:44:56.655758+00', '2026-10-31 19:44:56.507+00'), ('UIbGx6H', 'Supino Reverso com Halteres', 'dumbbell reverse bench press', 'supino-reverso-com-halteres', 'https://static.exercisedb.dev/media/UIbGx6H.gif', 'catalogo/supino-reverso-com-halteres--UIbGx6H.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-reverso-com-halteres--UIbGx6H.gif', ARRAY['Peito'], ARRAY['Halteres'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides'], '["Step:1 Settle onto a bench with your feet planted and your knees bent.","Step:2 Take a dumbbell in each hand with palms facing down, palms facing toward your feet.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:57.210874+00', '2026-10-31 19:44:57.056+00'), ('UilDHSs', 'Desenvolvimento em Pé com Halteres Pegada Neutra', 'Dumbbell Standing Neutral-Grip Press', 'desenvolvimento-em-pe-com-halteres-pegada-neutra', 'https://static.exercisedb.dev/media/UilDHSs.gif', 'catalogo/desenvolvimento-em-pe-com-halteres-pegada-neutra--UilDHSs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-em-pe-com-halteres-pegada-neutra--UilDHSs.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Tríceps','Peitorais'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Step:2 With your core engaged and your back straight, press the dumbbells upwards until your arms are straight overhead.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms facing each other and the wrists straight.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:57.092698+00', '2026-10-31 19:44:56.952+00'), ('uJmK7Z1', 'Rosca de Punho Sentado com Halteres Pegada Neutra', 'dumbbell seated neutral wrist curl', 'rosca-de-punho-sentado-com-halteres-pegada-neutra', 'https://static.exercisedb.dev/media/uJmK7Z1.gif', 'catalogo/rosca-de-punho-sentado-com-halteres-pegada-neutra--uJmK7Z1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-sentado-com-halteres-pegada-neutra--uJmK7Z1.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing each other.","Step:2 Set your forearms on your thighs, letting the dumbbells to hang down.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:44:57.18332+00', '2026-10-31 19:44:57.038+00'), ('UKWTJWR', 'Crossover em Pé com Tronco Ereto na Polia', 'cable standing up straight crossovers', 'crossover-em-pe-com-tronco-ereto-na-polia', 'https://static.exercisedb.dev/media/UKWTJWR.gif', 'catalogo/crossover-em-pe-com-tronco-ereto-na-polia--UKWTJWR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crossover-em-pe-com-tronco-ereto-na-polia--UKWTJWR.gif', ARRAY['Peito'], ARRAY['Polia'], ARRAY['Peitorais'], ARRAY['Deltoides','Tríceps'], '["Step:1 Take your place in the middle of a cable machine with your feet about shoulder width.","Step:2 Take hold of the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:44:57.286009+00', '2026-10-31 19:44:57.149+00'), ('uKyN64F', 'Agachamento Unilateral com Barra', 'Barbell Single-Leg Squat', 'agachamento-unilateral-com-barra', 'https://static.exercisedb.dev/media/uKyN64F.gif', 'catalogo/agachamento-unilateral-com-barra--uKyN64F.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-unilateral-com-barra--uKyN64F.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Quadríceps'], ARRAY['Glúteos','Posteriores da coxa','Panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell across your upper back.","Step:2 Before moving, lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent; switch sides when the set calls for it."]', '2026-10-31 19:44:57.401852+00', '2026-10-31 19:44:57.266+00'), ('uL9CsKm', 'Círculos de Tornozelo', 'ankle circles', 'circulos-de-tornozelo', 'https://static.exercisedb.dev/media/uL9CsKm.gif', 'catalogo/circulos-de-tornozelo--uL9CsKm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/circulos-de-tornozelo--uL9CsKm.gif', ARRAY['Panturrilhas'], ARRAY['Peso corporal'], ARRAY['Panturrilhas'], ARRAY['Estabilizadores do tornozelo'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Before moving, lift one leg off the ground and rotate your ankle in a circular motion.","Step:3 Relax the limb above the joint you are circling.","Step:4 Circle the joint slowly in one direction, then reverse the circle without forcing the range.","Step:5 Keep the rest of the limb still while the joint traces each circle.","Step:6 Switch to the other side after completing both directions."]', '2026-10-31 19:44:57.763327+00', '2026-10-31 19:44:57.618+00'), ('UM8mgyG', 'Desenvolvimento Arnold com Kettlebell', 'kettlebell arnold press', 'desenvolvimento-arnold-com-kettlebell', 'https://static.exercisedb.dev/media/UM8mgyG.gif', 'catalogo/desenvolvimento-arnold-com-kettlebell--UM8mgyG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-arnold-com-kettlebell--UM8mgyG.gif', ARRAY['Ombros'], ARRAY['Kettlebell'], ARRAY['Deltoides'], ARRAY['Tríceps','Parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height with your palms facing toward you.","Step:2 Brace your trunk and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:44:58.074198+00', '2026-10-31 19:44:57.944+00'), ('UmpPAAe', 'Tríceps Coice em Pé com Halter', 'dumbbell standing kickback', 'triceps-coice-em-pe-com-halter', 'https://static.exercisedb.dev/media/UmpPAAe.gif', 'catalogo/triceps-coice-em-pe-com-halter--UmpPAAe.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-em-pe-com-halter--UmpPAAe.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:44:58.190471+00', '2026-10-31 19:44:58.046+00'), ('UNAB8ak', 'Rosca Bíceps Unilateral Acima da Cabeça com Elástico', 'Band Single-Arm Overhead Biceps Curl', 'rosca-biceps-unilateral-acima-da-cabeca-com-elastico', 'https://static.exercisedb.dev/media/UNAB8ak.gif', 'catalogo/rosca-biceps-unilateral-acima-da-cabeca-com-elastico--UNAB8ak.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-unilateral-acima-da-cabeca-com-elastico--UNAB8ak.gif', ARRAY['Braços'], ARRAY['Elástico'], ARRAY['Bíceps'], ARRAY['Antebraços','Deltoides'], '["Step:1 Stand and set your feet about shoulder width and place one end of the band under your foot.","Step:2 Take hold of the other end of the band with your arm straight overhead, palm facing forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:44:57.98924+00', '2026-10-31 19:44:57.853+00'), ('uOV3Itw', 'Alongamento de Tríceps', 'triceps stretch', 'alongamento-de-triceps', 'https://static.exercisedb.dev/media/uOV3Itw.gif', 'catalogo/alongamento-de-triceps--uOV3Itw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-triceps--uOV3Itw.gif', ARRAY['Braços'], ARRAY['Peso corporal'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Either stand or sit upright with your back straight.","Step:2 Reach one arm overhead, bending it at the elbow.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:58.401596+00', '2026-10-31 19:44:58.265+00'), ('UpAlold', 'Ponte Reversa Declinada', 'rear decline bridge', 'ponte-reversa-declinada', 'https://static.exercisedb.dev/media/UpAlold.gif', 'catalogo/ponte-reversa-declinada--UpAlold.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/ponte-reversa-declinada--UpAlold.gif', ARRAY['Coxas'], ARRAY['Peso corporal'], ARRAY['Glúteos'], ARRAY['Posteriores da coxa','Eretores da espinha'], '["Step:1 Settle onto your back with your feet planted and your knees bent.","Step:2 Set your arms by your sides with your palms facing down.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:44:58.80375+00', '2026-10-31 19:44:58.667+00'), ('UpWmA5E', 'L-Sit no Chão', 'l-sit on floor', 'l-sit-no-chao', 'https://static.exercisedb.dev/media/UpWmA5E.gif', 'catalogo/l-sit-no-chao--UpWmA5E.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/l-sit-no-chao--UpWmA5E.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Take a seat on the floor with your legs extended in front of you.","Step:2 Set your hands on the floor beside your hips, fingers pointing forward.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:44:58.980927+00', '2026-10-31 19:44:58.84+00'), ('UQr48Oi', 'Pull-in na Bola Suíça', 'pull-in (on stability ball)', 'pull-in-na-bola-suica', 'https://static.exercisedb.dev/media/UQr48Oi.gif', 'catalogo/pull-in-na-bola-suica--UQr48Oi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pull-in-na-bola-suica--UQr48Oi.gif', ARRAY['Abdômen'], ARRAY['Bola suíça'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Begin by sitting on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Set your hands on the sides of the stability ball for support.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:59.096329+00', '2026-10-31 19:44:58.96+00'), ('uSkDMYl', 'Rosca Bíceps com Halteres na Posição da Cegonha', 'Dumbbell Biceps Curl With Stork Stance', 'rosca-biceps-com-halteres-na-posicao-da-cegonha', 'https://static.exercisedb.dev/media/uSkDMYl.gif', 'catalogo/rosca-biceps-com-halteres-na-posicao-da-cegonha--uSkDMYl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-com-halteres-na-posicao-da-cegonha--uSkDMYl.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.","Step:2 Reach one leg behind you, balancing on the toes of that foot.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:44:58.776118+00', '2026-10-31 19:44:58.63+00'), ('uTBt1HV', 'Barra Fixa Escapular', 'scapular pull-up', 'barra-fixa-escapular', 'https://static.exercisedb.dev/media/uTBt1HV.gif', 'catalogo/barra-fixa-escapular--uTBt1HV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-escapular--uTBt1HV.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Trapézio'], ARRAY['Bíceps','Romboides','Deltoides posteriores'], '["Step:1 Begin by hanging from a pull-up bar with your palms turned away from you and your arms straight.","Step:2 Draw back your shoulder blades by pulling them down and back.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:44:59.14955+00', '2026-10-31 19:44:59.012+00'), ('UtmIqcI', 'Alongamento Lateral de Punho', 'side wrist pull stretch', 'alongamento-lateral-de-punho', 'https://static.exercisedb.dev/media/UtmIqcI.gif', 'catalogo/alongamento-lateral-de-punho--UtmIqcI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lateral-de-punho--UtmIqcI.gif', ARRAY['Antebraços'], ARRAY['Peso corporal'], ARRAY['Antebraços'], ARRAY['Punhos','Mãos'], '["Step:1 Stand and set your feet about shoulder width and your arms extended in front of you.","Step:2 Reach your right arm out to the side, parallel to the ground, with your palm facing down.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:59.348118+00', '2026-10-31 19:44:59.213+00'), ('Uto7l43', 'Alongamento de Peitoral e Ombro Anterior', 'chest and front of shoulder stretch', 'alongamento-de-peitoral-e-ombro-anterior', 'https://static.exercisedb.dev/media/Uto7l43.gif', 'catalogo/alongamento-de-peitoral-e-ombro-anterior--Uto7l43.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-peitoral-e-ombro-anterior--Uto7l43.gif', ARRAY['Peito'], ARRAY['Peso corporal'], ARRAY['Peitorais'], ARRAY['Deltoides'], '["Step:1 Stand tall and set your feet about shoulder width.","Step:2 Reach your arms straight out in front of you at shoulder height.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:44:59.602556+00', '2026-10-31 19:44:59.459+00'), ('uTv34oq', 'Remada em Pé com Peso Corporal (com Toalha)', 'bodyweight standing row (with towel)', 'remada-em-pe-com-peso-corporal-com-toalha', 'https://static.exercisedb.dev/media/uTv34oq.gif', 'catalogo/remada-em-pe-com-peso-corporal-com-toalha--uTv34oq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-com-peso-corporal-com-toalha--uTv34oq.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a towel in front of you with both hands.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:44:59.610635+00', '2026-10-31 19:44:59.472+00'), ('UVL20oz', 'Otis Up', 'otis up', 'otis-up', 'https://static.exercisedb.dev/media/UVL20oz.gif', 'catalogo/otis-up--UVL20oz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/otis-up--UVL20oz.gif', ARRAY['Abdômen'], ARRAY['Com peso'], ARRAY['Abdominais'], ARRAY['Flexores do quadril','Eretores da espinha'], '["Step:1 Settle onto your back with your knees bent and feet planted.","Step:2 Set your hands behind your head with your elbows pointing outwards.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:44:59.655209+00', '2026-10-31 19:44:59.523+00'), ('UVo2Qs2', 'Elevação de pernas alternada (flutter kick)', 'flutter kicks', 'elevacao-de-pernas-alternada-flutter-kick', 'https://static.exercisedb.dev/media/UVo2Qs2.gif', 'catalogo/elevacao-de-pernas-alternada-flutter-kick--UVo2Qs2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-alternada-flutter-kick--UVo2Qs2.gif', ARRAY['Coxas'], ARRAY['Peso corporal'], ARRAY['Glúteos'], ARRAY['Flexores do quadril','Abdominais'], '["Step:1 Settle onto your back with your legs extended and your hands by your sides.","Step:2 Brace your trunk and lift your legs off the ground about 6 inches.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:44:59.726919+00', '2026-10-31 19:44:59.597+00'), ('uWpxD4v', 'Elevação de joelhos suspenso com balanço de braços', 'arm slingers hanging bent knee legs', 'elevacao-de-joelhos-suspenso-com-balanco-de-bracos', 'https://static.exercisedb.dev/media/uWpxD4v.gif', 'catalogo/elevacao-de-joelhos-suspenso-com-balanco-de-bracos--uWpxD4v.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-joelhos-suspenso-com-balanco-de-bracos--uWpxD4v.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Deltoides','Costas'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your knees bent at a 90-degree angle.","Step:2 Brace your trunk and lift your knees toward your chest, bringing them as close to your elbows as possible.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:44:59.987987+00', '2026-10-31 19:44:59.849+00'), ('uX3sUBz', 'Remada invertida', 'inverted row', 'remada-invertida', 'https://static.exercisedb.dev/media/uX3sUBz.gif', 'catalogo/remada-invertida--uX3sUBz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-invertida--uX3sUBz.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Prepare a bar at waist height on a Smith machine or use a suspension trainer.","Step:2 Face the bar or suspension trainer and grab it with palms facing down, hands about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:00.063076+00', '2026-10-31 19:44:59.921+00'), ('uxJcFUU', 'Tríceps testa na polia', 'cable lying triceps extension', 'triceps-testa-na-polia', 'https://static.exercisedb.dev/media/uxJcFUU.gif', 'catalogo/triceps-testa-na-polia--uxJcFUU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-na-polia--uxJcFUU.gif', ARRAY['Braços'], ARRAY['Polia'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Connect a rope handle to a low pulley cable machine.","Step:2 Get onto a flat bench facing up, with your head toward the cable machine.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:00.69337+00', '2026-10-31 19:45:00.548+00'), ('UXpKJoq', 'Mesa flexora deitado na máquina (duas pernas e uma perna)', 'Machine Lying Two-Single-Leg Curl', 'mesa-flexora-deitado-na-maquina-duas-pernas-e-uma-perna', 'https://static.exercisedb.dev/media/UXpKJoq.gif', 'catalogo/mesa-flexora-deitado-na-maquina-duas-pernas-e-uma-perna--UXpKJoq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mesa-flexora-deitado-na-maquina-duas-pernas-e-uma-perna--UXpKJoq.gif', ARRAY['Coxas'], ARRAY['Máquina'], ARRAY['Isquiotibiais'], ARRAY['Glúteos'], '["Step:1 Set the machine to fit your body and sit on it with your back against the backrest.","Step:2 Set your legs on the lever pad, just above your ankles.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Ease back to the start before repeating; switch sides when the set calls for it."]', '2026-10-31 19:45:00.936186+00', '2026-10-31 19:45:00.783+00'), ('UzkLrem', 'Crucifixo inverso com halteres (apoiando a cabeça)', 'dumbbell rear lateral raise (support head)', 'crucifixo-inverso-com-halteres-apoiando-a-cabeca', 'https://static.exercisedb.dev/media/UzkLrem.gif', 'catalogo/crucifixo-inverso-com-halteres-apoiando-a-cabeca--UzkLrem.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres-apoiando-a-cabeca--UzkLrem.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Trapézio','Romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:00.808878+00', '2026-10-31 19:45:00.607+00'), ('uZKq7lo', 'Salto para frente', 'forward jump', 'salto-para-frente', 'https://static.exercisedb.dev/media/uZKq7lo.gif', 'catalogo/salto-para-frente--uZKq7lo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/salto-para-frente--uZKq7lo.gif', ARRAY['Coxas'], ARRAY['Peso corporal'], ARRAY['Quadríceps'], ARRAY['Panturrilhas','Isquiotibiais','Glúteos'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, bend your knees and lower your body into a squat position.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:45:01.08073+00', '2026-10-31 19:45:00.704+00'), ('V07qpXy', 'Leg press alternado na máquina', 'Machine Alternate Leg Press', 'leg-press-alternado-na-maquina', 'https://static.exercisedb.dev/media/V07qpXy.gif', 'catalogo/leg-press-alternado-na-maquina--V07qpXy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-alternado-na-maquina--V07qpXy.gif', ARRAY['Coxas'], ARRAY['Máquina'], ARRAY['Quadríceps'], ARRAY['Isquiotibiais','Glúteos'], '["Step:1 Set the seat and foot platform of the leverage machine to your desired position.","Step:2 Take a seat on the machine with your back against the backrest and your feet on the foot platform.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Bring the weight or body back to its starting position without rushing; switch sides when the set calls for it."]', '2026-10-31 19:45:00.777069+00', '2026-10-31 19:45:00.637+00'), ('v1qBec9', 'Crucifixo inverso com halteres', 'dumbbell rear lateral raise', 'crucifixo-inverso-com-halteres', 'https://static.exercisedb.dev/media/v1qBec9.gif', 'catalogo/crucifixo-inverso-com-halteres--v1qBec9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres--v1qBec9.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Trapézio','Romboides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady and core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:01.366317+00', '2026-10-31 19:45:01.23+00'), ('v2DfH14', 'Remada curvada unilateral com halter', 'Single-Arm Dumbbell Bent-Over Row', 'remada-curvada-unilateral-com-halter', 'https://static.exercisedb.dev/media/v2DfH14.gif', 'catalogo/remada-curvada-unilateral-com-halter--v2DfH14.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-unilateral-com-halter--v2DfH14.gif', ARRAY['Costas'], ARRAY['Halteres'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a dumbbell in one hand with a neutral grip.","Step:2 Bend forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:45:01.399063+00', '2026-10-31 19:45:01.21+00'), ('v3vLFW0', 'Flexão de braço fechada (com joelhos apoiados)', 'close-grip push-up (on knees)', 'flexao-de-braco-fechada-com-joelhos-apoiados', 'https://static.exercisedb.dev/media/v3vLFW0.gif', 'catalogo/flexao-de-braco-fechada-com-joelhos-apoiados--v3vLFW0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-fechada-com-joelhos-apoiados--v3vLFW0.gif', ARRAY['Braços'], ARRAY['Peso corporal'], ARRAY['Tríceps'], ARRAY['Peitoral','Deltoides'], '["Step:1 Begin by getting on your hands and knees, with your hands about shoulder width and your knees about hip width.","Step:2 Lower your upper body toward the ground by bending your elbows, keeping them close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:01.382193+00', '2026-10-31 19:45:01.249+00'), ('v3xmPAR', 'Peck deck (voador) sentado na máquina', 'Machine Seated Fly', 'peck-deck-voador-sentado-na-maquina', 'https://static.exercisedb.dev/media/v3xmPAR.gif', 'catalogo/peck-deck-voador-sentado-na-maquina--v3xmPAR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/peck-deck-voador-sentado-na-maquina--v3xmPAR.gif', ARRAY['Peito'], ARRAY['Máquina'], ARRAY['Peitoral'], ARRAY['Deltoides','Trapézio'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with a pronated grip and keep your elbows soft.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:45:01.999623+00', '2026-10-31 19:45:01.861+00'), ('V4ryaZa', 'Rosca direta com barra W pegada fechada', 'EZ-Bar Close-Grip Curl', 'rosca-direta-com-barra-w-pegada-fechada', 'https://static.exercisedb.dev/media/V4ryaZa.gif', 'catalogo/rosca-direta-com-barra-w-pegada-fechada--V4ryaZa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-barra-w-pegada-fechada--V4ryaZa.gif', ARRAY['Braços'], ARRAY['Barra W'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up, hands about shoulder width.","Step:2 Hold your elbows near your torso and your upper arms stationary throughout the movement.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:01.734516+00', '2026-10-31 19:45:01.591+00'), ('v7p5bYl', 'Extensão de pernas sentado no chão (kick out)', 'kick out sit', 'extensao-de-pernas-sentado-no-chao-kick-out', 'https://static.exercisedb.dev/media/v7p5bYl.gif', 'catalogo/extensao-de-pernas-sentado-no-chao-kick-out--v7p5bYl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-pernas-sentado-no-chao-kick-out--v7p5bYl.gif', ARRAY['Coxas'], ARRAY['Peso corporal'], ARRAY['Isquiotibiais'], ARRAY['Quadríceps','Glúteos'], '["Step:1 Take a seat on the edge of a bench or chair with your feet planted and your knees bent at a 90-degree angle.","Step:2 Recline slightly and place your hands on the edge of the bench or chair for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:45:02.021854+00', '2026-10-31 19:45:01.878+00'), ('VaP75jl', 'Avanço para trás com barra', 'barbell rear lunge', 'avanco-para-tras-com-barra', 'https://static.exercisedb.dev/media/VaP75jl.gif', 'catalogo/avanco-para-tras-com-barra--VaP75jl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-para-tras-com-barra--VaP75jl.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Quadríceps','Isquiotibiais','Panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width and a barbell resting on your upper back.","Step:2 Step backward with your right foot, landing on the ball of your foot.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:45:02.467594+00', '2026-10-31 19:45:02.319+00'), ('vAwm6rK', 'Supino na polia na bola suíça', 'cable press on exercise ball', 'supino-na-polia-na-bola-suica', 'https://static.exercisedb.dev/media/vAwm6rK.gif', 'catalogo/supino-na-polia-na-bola-suica--vAwm6rK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-na-polia-na-bola-suica--vAwm6rK.gif', ARRAY['Peito'], ARRAY['Polia','Bola suíça'], ARRAY['Peitoral'], ARRAY['Deltoides','Tríceps'], '["Step:1 Take a seat on an exercise ball with your feet planted and your knees at a 90-degree angle.","Step:2 Take hold of the cable handles at chest height with your palms facing down and your elbows bent.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:02.35804+00', '2026-10-31 19:45:02.222+00'), ('VBAWRPG', 'Prancha frontal com peso', 'weighted front plank', 'prancha-frontal-com-peso', 'https://static.exercisedb.dev/media/VBAWRPG.gif', 'catalogo/prancha-frontal-com-peso--VBAWRPG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-frontal-com-peso--VBAWRPG.gif', ARRAY['Abdômen'], ARRAY['Anilha/peso adicional'], ARRAY['Abdominais'], ARRAY['Deltoides','Eretores da espinha'], '["Step:1 Begin by lying face down on the floor.","Step:2 Set your forearms on the ground, with your elbows directly under your shoulders.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:02.346115+00', '2026-10-31 19:45:02.211+00'), ('vBNyir7', 'Rosca Scott com barra W pegada supinada invertida (pegada pronada)', 'EZ-Bar Reverse-Grip Preacher Curl', 'rosca-scott-com-barra-w-pegada-supinada-invertida-pegada-pronada', 'https://static.exercisedb.dev/media/vBNyir7.gif', 'catalogo/rosca-scott-com-barra-w-pegada-supinada-invertida-pegada-pronada--vBNyir7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-com-barra-w-pegada-supinada-invertida-pegada-pronada--vBNyir7.gif', ARRAY['Braços'], ARRAY['Barra W'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Take a seat on a preacher bench with your chest against the pad and your feet planted.","Step:2 Hold the ez barbell with palms facing up, hands about shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:02.611405+00', '2026-10-31 19:45:02.459+00'), ('VdLZ3nB', 'Rosca aranha inversa unilateral com halter', 'Dumbbell Single-Arm Reverse Spider Curl', 'rosca-aranha-inversa-unilateral-com-halter', 'https://static.exercisedb.dev/media/VdLZ3nB.gif', 'catalogo/rosca-aranha-inversa-unilateral-com-halter--VdLZ3nB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-aranha-inversa-unilateral-com-halter--VdLZ3nB.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Stand tall with a dumbbell in one hand, palm facing down and arm straight.","Step:2 With your upper arm stationary, curl the dumbbell toward your shoulder by flexing your elbow.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:45:02.589768+00', '2026-10-31 19:45:02.455+00'), ('VEcJRo2', 'Elevação pélvica suspenso na barra com pernas estendidas', 'hanging leg hip raise', 'elevacao-pelvica-suspenso-na-barra-com-pernas-estendidas', 'https://static.exercisedb.dev/media/VEcJRo2.gif', 'catalogo/elevacao-pelvica-suspenso-na-barra-com-pernas-estendidas--VEcJRo2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-pelvica-suspenso-na-barra-com-pernas-estendidas--VEcJRo2.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril','Eretores da espinha'], '["Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.","Step:2 Brace your trunk and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Stop when the hips line up with the torso; do not arch higher through the lower back.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:45:03.192446+00', '2026-10-31 19:45:03.057+00'), ('VedGSby', 'Flexão de joelhos assistida de bruços (isquiotibiais)', 'assisted prone hamstring', 'flexao-de-joelhos-assistida-de-brucos-isquiotibiais', 'https://static.exercisedb.dev/media/VedGSby.gif', 'catalogo/flexao-de-joelhos-assistida-de-brucos-isquiotibiais--VedGSby.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-joelhos-assistida-de-brucos-isquiotibiais--VedGSby.gif', ARRAY['Coxas'], ARRAY['Assistido'], ARRAY['Isquiotibiais'], ARRAY['Glúteos','Eretores da espinha'], '["Step:1 Position yourself face down on a mat or bench with your legs straight.","Step:2 Ask a partner to help or use a resistance band to secure your ankles.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:03.220683+00', '2026-10-31 19:45:03.076+00'), ('veXwo0D', 'Remada sentada no chão na polia com pegada aberta', 'cable floor seated wide-grip row', 'remada-sentada-no-chao-na-polia-com-pegada-aberta', 'https://static.exercisedb.dev/media/veXwo0D.gif', 'catalogo/remada-sentada-no-chao-na-polia-com-pegada-aberta--veXwo0D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-no-chao-na-polia-com-pegada-aberta--veXwo0D.gif', ARRAY['Costas'], ARRAY['Polia'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Take a seat on the floor with your legs extended and your back straight.","Step:2 Connect a cable handle to a low pulley and position the cable machine behind you.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:03.632509+00', '2026-10-31 19:45:03.501+00'), ('Vh0GsK4', 'Supino inclinado na polia', 'cable incline bench press', 'supino-inclinado-na-polia', 'https://static.exercisedb.dev/media/Vh0GsK4.gif', 'catalogo/supino-inclinado-na-polia--Vh0GsK4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-na-polia--Vh0GsK4.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Set the bench to a 45-degree incline.","Step:2 Connect the cable handles to the high pulleys.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:03.694303+00', '2026-10-31 19:45:03.561+00'), ('VhX2JdE', 'Rosca de punho por trás em pé na polia', 'cable standing back wrist curl', 'rosca-de-punho-por-tras-em-pe-na-polia', 'https://static.exercisedb.dev/media/VhX2JdE.gif', 'catalogo/rosca-de-punho-por-tras-em-pe-na-polia--VhX2JdE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-por-tras-em-pe-na-polia--VhX2JdE.gif', ARRAY['antebraços'], ARRAY['polia'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable handle with palms facing down.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:45:03.338595+00', '2026-10-31 19:45:03.199+00'), ('vi8EhoE', 'Pullover circular com halter', 'dumbbell around pullover', 'pullover-circular-com-halter', 'https://static.exercisedb.dev/media/vi8EhoE.gif', 'catalogo/pullover-circular-com-halter--vi8EhoE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-circular-com-halter--vi8EhoE.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['tríceps','latíssimo do dorso'], '["Step:1 Settle onto a bench with your head at one end and your feet firmly on the ground.","Step:2 Take a dumbbell with both hands and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:45:03.741848+00', '2026-10-31 19:45:03.605+00'), ('vIICElP', 'Rotação interna de quadril deitado com faixa elástica', 'band lying hip internal rotation', 'rotacao-interna-de-quadril-deitado-com-faixa-elastica', 'https://static.exercisedb.dev/media/vIICElP.gif', 'catalogo/rotacao-interna-de-quadril-deitado-com-faixa-elastica--vIICElP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-interna-de-quadril-deitado-com-faixa-elastica--vIICElP.gif', ARRAY['coxas'], ARRAY['faixa elástica'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Settle onto your back with your legs straight and a resistance band looped around your feet.","Step:2 Bend your knees and bring them toward your chest, keeping your feet together.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:03.808034+00', '2026-10-31 19:45:03.66+00'), ('VjYliFZ', 'Tríceps na polia com pegada invertida', 'cable reverse-grip pushdown', 'triceps-na-polia-com-pegada-invertida', 'https://static.exercisedb.dev/media/VjYliFZ.gif', 'catalogo/triceps-na-polia-com-pegada-invertida--VjYliFZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-na-polia-com-pegada-invertida--VjYliFZ.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Connect a straight bar to a high pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Stand far enough from the stack for the cable to stay taut.","Step:4 Keep your elbows near your ribs and straighten your arms against the cable.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:04.222893+00', '2026-10-31 19:45:04.066+00'), ('vKilzz3', 'Rosca interna em pé com halter', 'dumbbell standing inner biceps curl', 'rosca-interna-em-pe-com-halter', 'https://static.exercisedb.dev/media/vKilzz3.gif', 'catalogo/rosca-interna-em-pe-com-halter--vKilzz3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-interna-em-pe-com-halter--vKilzz3.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with a dumbbell in each hand, palms facing your torso.","Step:2 Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:04.489713+00', '2026-10-31 19:45:04.347+00'), ('VLYXo8S', 'Rotação circular de braços com peso', 'weighted round arm', 'rotacao-circular-de-bracos-com-peso', 'https://static.exercisedb.dev/media/VLYXo8S.gif', 'catalogo/rotacao-circular-de-bracos-com-peso--VLYXo8S.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-circular-de-bracos-com-peso--VLYXo8S.gif', ARRAY['ombros'], ARRAY['peso adicional'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:04.36418+00', '2026-10-31 19:45:04.223+00'), ('vM5YS2g', 'Extensão reversa de quadril na bola suíça', 'reverse hyper extension (on stability ball)', 'extensao-reversa-de-quadril-na-bola-suica', 'https://static.exercisedb.dev/media/vM5YS2g.gif', 'catalogo/extensao-reversa-de-quadril-na-bola-suica--vM5YS2g.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-reversa-de-quadril-na-bola-suica--vM5YS2g.gif', ARRAY['coxas'], ARRAY['bola suíça'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Position yourself face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Step:2 Set your hands on the ground in front of you for stability.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:04.233809+00', '2026-10-31 19:45:04.089+00'), ('vmwLyCg', 'Desenvolvimento em W com halteres', 'dumbbell w-press', 'desenvolvimento-em-w-com-halteres', 'https://static.exercisedb.dev/media/vmwLyCg.gif', 'catalogo/desenvolvimento-em-w-com-halteres--vmwLyCg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-em-w-com-halteres--vmwLyCg.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing forward.","Step:2 Before moving, raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:04.321865+00', '2026-10-31 19:45:04.187+00'), ('VnfUNW7', 'Barra fixa supinada com pegada fechada', 'Close-Grip Chin-Up', 'barra-fixa-supinada-com-pegada-fechada', 'https://static.exercisedb.dev/media/VnfUNW7.gif', 'catalogo/barra-fixa-supinada-com-pegada-fechada--VnfUNW7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada-com-pegada-fechada--VnfUNW7.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with your palms facing toward you and your hands about shoulder width.","Step:2 Suspend yourself from the bar with your arms straight and your feet off the ground.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:04.713927+00', '2026-10-31 19:45:04.578+00'), ('VO2qeJg', 'Abdução de quadril na prancha lateral', 'Side Plank Hip Abduction', 'abducao-de-quadril-na-prancha-lateral', 'https://static.exercisedb.dev/media/VO2qeJg.gif', 'catalogo/abducao-de-quadril-na-prancha-lateral--VO2qeJg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abducao-de-quadril-na-prancha-lateral--VO2qeJg.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['abdutores'], ARRAY['oblíquos','glúteos'], '["Step:1 Begin by lying on your side with your legs extended and stacked on top of each other.","Step:2 Support yourself up on your forearm, keeping your elbow directly below your shoulder.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Hold the side plank line and raise the top leg without letting the hips roll back.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Lower the leg without dropping the hips, then repeat before changing sides."]', '2026-10-31 19:45:04.927739+00', '2026-10-31 19:45:04.773+00'), ('vpp9Ku2', 'Remada sentada unilateral alternada na polia', 'Cable Seated Single-Arm Alternate Row', 'remada-sentada-unilateral-alternada-na-polia', 'https://static.exercisedb.dev/media/vpp9Ku2.gif', 'catalogo/remada-sentada-unilateral-alternada-na-polia--vpp9Ku2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-unilateral-alternada-na-polia--vpp9Ku2.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Take a seat on a bench facing a cable machine with your feet planted and knees soft.","Step:2 Hold the handle with one hand and keep your arm straight in front of you.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:45:05.276296+00', '2026-10-31 19:45:05.144+00'), ('VPPtusI', 'Remada invertida com joelhos flexionados', 'inverted row bent knees', 'remada-invertida-com-joelhos-flexionados', 'https://static.exercisedb.dev/media/VPPtusI.gif', 'catalogo/remada-invertida-com-joelhos-flexionados--VPPtusI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-invertida-com-joelhos-flexionados--VPPtusI.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Prepare a bar at waist height and lie underneath it.","Step:2 Take hold of the bar with palms facing down, just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:06.213215+00', '2026-10-31 19:45:06.074+00'), ('vpQaQkH', 'Ergômetro de esqui', 'ski ergometer', 'ergometro-de-esqui', 'https://static.exercisedb.dev/media/vpQaQkH.gif', 'catalogo/ergometro-de-esqui--vpQaQkH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/ergometro-de-esqui--vpQaQkH.gif', ARRAY['braços'], ARRAY['ergômetro de esqui'], ARRAY['tríceps'], ARRAY['deltoides','antebraços'], '["Step:1 Set the seat height and footrests to a comfortable position.","Step:2 Hold the handles with palms facing down.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:45:05.694886+00', '2026-10-31 19:45:05.558+00'), ('vptOQ4N', 'Flexão profunda com halteres', 'deep push up', 'flexao-profunda-com-halteres', 'https://static.exercisedb.dev/media/vptOQ4N.gif', 'catalogo/flexao-profunda-com-halteres--vptOQ4N.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-profunda-com-halteres--vptOQ4N.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width and your body in a straight line.","Step:2 Lower your chest toward the ground by bending your elbows, keeping them close to your body.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:05.358452+00', '2026-10-31 19:45:05.213+00'), ('VQ3sNCn', 'Tríceps coice unilateral sentado com halter', 'Dumbbell Seated Single-Arm Kickback', 'triceps-coice-unilateral-sentado-com-halter', 'https://static.exercisedb.dev/media/VQ3sNCn.gif', 'catalogo/triceps-coice-unilateral-sentado-com-halter--VQ3sNCn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-unilateral-sentado-com-halter--VQ3sNCn.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in one hand.","Step:2 Bend your torso forward at the waist, with your spine steady and parallel to the ground.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:45:05.495761+00', '2026-10-31 19:45:05.356+00'), ('vqsbmL0', 'Desenvolvimento de ombros na máquina', 'Machine Shoulder Press', 'desenvolvimento-de-ombros-na-maquina', 'https://static.exercisedb.dev/media/vqsbmL0.gif', 'catalogo/desenvolvimento-de-ombros-na-maquina--vqsbmL0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-de-ombros-na-maquina--vqsbmL0.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Set the seat height and backrest of the leverage machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the backrest and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:05.916267+00', '2026-10-31 19:45:05.783+00'), ('vR1vold', 'Agachamento Zercher completo com barra', 'barbell full zercher squat', 'agachamento-zercher-completo-com-barra', 'https://static.exercisedb.dev/media/vR1vold.gif', 'catalogo/agachamento-zercher-completo-com-barra--vR1vold.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-zercher-completo-com-barra--vR1vold.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Stand and set your feet about shoulder width and toes slightly turned out.","Step:2 Take hold of the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:06.27753+00', '2026-10-31 19:45:06.129+00'), ('vrhHa6D', 'Barra fixa assistida com pegada neutra fechada', 'Assisted Parallel Close-Grip Pull-Up', 'barra-fixa-assistida-com-pegada-neutra-fechada', 'https://static.exercisedb.dev/media/vrhHa6D.gif', 'catalogo/barra-fixa-assistida-com-pegada-neutra-fechada--vrhHa6D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-assistida-com-pegada-neutra-fechada--vrhHa6D.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Set the machine to your desired weight and height.","Step:2 Set your hands on the parallel bars with a close grip, palms facing each other.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:06.293427+00', '2026-10-31 19:45:06.146+00'), ('vsMcDi9', 'Rosca concentrada em pé com barra', 'barbell standing concentration curl', 'rosca-concentrada-em-pe-com-barra', 'https://static.exercisedb.dev/media/vsMcDi9.gif', 'catalogo/rosca-concentrada-em-pe-com-barra--vsMcDi9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-concentrada-em-pe-com-barra--vsMcDi9.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell in one hand, palm facing up.","Step:2 Set your opposite hand on your thigh for support.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:06.394714+00', '2026-10-31 19:45:06.25+00'), ('vsVoPHt', 'Supino declinado na máquina', 'Machine Decline Chest Press', 'supino-declinado-na-maquina', 'https://static.exercisedb.dev/media/vsVoPHt.gif', 'catalogo/supino-declinado-na-maquina--vsVoPHt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-na-maquina--vsVoPHt.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitoral'], ARRAY['tríceps','deltoides'], '["Step:1 Set the seat height and backrest of the leverage machine to a comfortable position.","Step:2 Take a seat on the machine with your back against the backrest and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:07.326265+00', '2026-10-31 19:45:07.192+00'), ('VtTbiP3', 'Pull through com elástico', 'band pull through', 'pull-through-com-elastico', 'https://static.exercisedb.dev/media/VtTbiP3.gif', 'catalogo/pull-through-com-elastico--VtTbiP3.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pull-through-com-elastico--VtTbiP3.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Connect a resistance band to a sturdy anchor point at ground level.","Step:2 Face the away from the anchor point from a stable stance with feet about shoulder width.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:45:06.959049+00', '2026-10-31 19:45:06.815+00'), ('vtusOWT', 'Supino no chão unilateral com barra', 'Barbell Single-Arm Floor Press', 'supino-no-chao-unilateral-com-barra', 'https://static.exercisedb.dev/media/vtusOWT.gif', 'catalogo/supino-no-chao-unilateral-com-barra--vtusOWT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-no-chao-unilateral-com-barra--vtusOWT.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Settle onto your back on the floor with your knees bent and feet planted.","Step:2 Take hold of the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:45:06.828824+00', '2026-10-31 19:45:06.692+00'), ('VuoerH0', 'Mergulho de tríceps no banco (pernas no banco)', 'triceps dip (bench leg)', 'mergulho-de-triceps-no-banco-pernas-no-banco', 'https://static.exercisedb.dev/media/VuoerH0.gif', 'catalogo/mergulho-de-triceps-no-banco-pernas-no-banco--VuoerH0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-de-triceps-no-banco-pernas-no-banco--VuoerH0.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Take a seat on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Step your feet forward, sliding your butt off the bench, and straighten your arms.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:45:07.247294+00', '2026-10-31 19:45:07.106+00'), ('vUTfFHw', 'Rosca de punho com elástico', 'band wrist curl', 'rosca-de-punho-com-elastico', 'https://static.exercisedb.dev/media/vUTfFHw.gif', 'catalogo/rosca-de-punho-com-elastico--vUTfFHw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-com-elastico--vUTfFHw.gif', ARRAY['antebraços'], ARRAY['elástico'], ARRAY['antebraços'], ARRAY['bíceps','tríceps'], '["Step:1 Take a seat on a bench or chair with your feet planted.","Step:2 Take hold of the band with both hands, palms facing up, and rest your forearms on your thighs.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:45:07.068108+00', '2026-10-31 19:45:06.919+00'), ('vvNjDJS', 'Tríceps coice na polia com dois braços', 'Cable Two-Arm Triceps Kickback', 'triceps-coice-na-polia-com-dois-bracos', 'https://static.exercisedb.dev/media/vvNjDJS.gif', 'catalogo/triceps-coice-na-polia-com-dois-bracos--vvNjDJS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-na-polia-com-dois-bracos--vvNjDJS.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take hold of the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:07.46244+00', '2026-10-31 19:45:07.317+00'), ('Vvwjz6N', 'Elevação glúteo-isquiotibiais (glute-ham raise)', 'glute-ham raise', 'elevacao-gluteo-isquiotibiais-glute-ham-raise', 'https://static.exercisedb.dev/media/Vvwjz6N.gif', 'catalogo/elevacao-gluteo-isquiotibiais-glute-ham-raise--Vvwjz6N.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-gluteo-isquiotibiais-glute-ham-raise--Vvwjz6N.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['posteriores de coxa'], ARRAY['glúteos','eretores da espinha'], '["Step:1 Set the glute-ham raise machine to fit your body.","Step:2 Set yourself face down on the machine with your ankles secured.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:45:07.84679+00', '2026-10-31 19:45:07.712+00'), ('VW88JNd', 'Panturrilha sentado unilateral com halter - palma para cima', 'Dumbbell Seated Single-Leg Calf Raise - Palm Up', 'panturrilha-sentado-unilateral-com-halter-palma-para-cima', 'https://static.exercisedb.dev/media/VW88JNd.gif', 'catalogo/panturrilha-sentado-unilateral-com-halter-palma-para-cima--VW88JNd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-sentado-unilateral-com-halter-palma-para-cima--VW88JNd.gif', ARRAY['panturrilhas'], ARRAY['halter'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Take a seat on a bench or chair with your back straight and your feet planted.","Step:2 Take a dumbbell in one hand and place it on top of your thigh, palm facing up.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Lower the heels at a measured pace before rising again; switch sides when the set calls for it."]', '2026-10-31 19:45:07.670624+00', '2026-10-31 19:45:07.53+00'), ('VX5YKR5', 'Elevação de pernas deitado assistida com lançamento para baixo', 'assisted lying leg raise with throw down', 'elevacao-de-pernas-deitado-assistida-com-lancamento-para-baixo', 'https://static.exercisedb.dev/media/VX5YKR5.gif', 'catalogo/elevacao-de-pernas-deitado-assistida-com-lancamento-para-baixo--VX5YKR5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-deitado-assistida-com-lancamento-para-baixo--VX5YKR5.gif', ARRAY['abdômen'], ARRAY['assistido'], ARRAY['abdominais'], ARRAY['flexores do quadril','quadríceps'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Set your hands under your glutes for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:45:07.878769+00', '2026-10-31 19:45:07.735+00'), ('vYk8lqw', 'Crucifixo inverso com halteres no banco inclinado', 'dumbbell incline rear lateral raise', 'crucifixo-inverso-com-halteres-no-banco-inclinado', 'https://static.exercisedb.dev/media/vYk8lqw.gif', 'catalogo/crucifixo-inverso-com-halteres-no-banco-inclinado--vYk8lqw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-com-halteres-no-banco-inclinado--vYk8lqw.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your chest against the backrest and hold a dumbbell in each hand.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:08.29976+00', '2026-10-31 19:45:08.145+00'), ('VYmYxK5', 'Supino martelo unilateral com halter na bola suíça', 'Dumbbell Single-Arm Hammer Press On Exercise Ball', 'supino-martelo-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/VYmYxK5.gif', 'catalogo/supino-martelo-unilateral-com-halter-na-bola-suica--VYmYxK5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-martelo-unilateral-com-halter-na-bola-suica--VYmYxK5.gif', ARRAY['braços'], ARRAY['halter','bola suíça'], ARRAY['tríceps'], ARRAY['deltoides','peitoral'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:45:08.01511+00', '2026-10-31 19:45:07.884+00'), ('vzAxBtt', 'Clean and jerk unilateral com kettlebell', 'Kettlebell Single-Arm Clean And Jerk', 'clean-and-jerk-unilateral-com-kettlebell', 'https://static.exercisedb.dev/media/vzAxBtt.gif', 'catalogo/clean-and-jerk-unilateral-com-kettlebell--vzAxBtt.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/clean-and-jerk-unilateral-com-kettlebell--vzAxBtt.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand with palms facing down.","Step:2 Before moving, bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:45:08.551211+00', '2026-10-31 19:45:08.415+00'), ('w1NOByi', 'Agachamento com remada no elástico', 'band squat row', 'agachamento-com-remada-no-elastico', 'https://static.exercisedb.dev/media/w1NOByi.gif', 'catalogo/agachamento-com-remada-no-elastico--w1NOByi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-remada-no-elastico--w1NOByi.gif', ARRAY['coxas'], ARRAY['elástico'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','costas'], '["Step:1 Connect the band to a sturdy anchor point at waist height.","Step:2 Face the anchor point from a stable stance with feet about shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:08.807999+00', '2026-10-31 19:45:08.674+00'), ('w2oRpuH', 'Remada sentada alternada pegada fechada na máquina', 'Machine Alternating Narrow Grip Seated Row', 'remada-sentada-alternada-pegada-fechada-na-maquina', 'https://static.exercisedb.dev/media/w2oRpuH.gif', 'catalogo/remada-sentada-alternada-pegada-fechada-na-maquina--w2oRpuH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-sentada-alternada-pegada-fechada-na-maquina--w2oRpuH.gif', ARRAY['costas'], ARRAY['máquina articulada'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Set the seat height and footplate position to ensure proper alignment.","Step:2 Take a seat on the machine with your back straight and feet flat on the footplate.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:45:09.080252+00', '2026-10-31 19:45:08.945+00'), ('W31mMjd', 'Agachamento lateral com barra', 'barbell side split squat', 'agachamento-lateral-com-barra', 'https://static.exercisedb.dev/media/W31mMjd.gif', 'catalogo/agachamento-lateral-com-barra--W31mMjd.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-lateral-com-barra--W31mMjd.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet wider than about shoulder width, toes pointing slightly outward.","Step:2 Take a barbell across your upper back, resting it on your traps.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:08.716542+00', '2026-10-31 19:45:08.574+00'), ('w4dLzSx', 'Crucifixo declinado unilateral na polia', 'Cable Single-Arm Decline Chest Fly', 'crucifixo-declinado-unilateral-na-polia', 'https://static.exercisedb.dev/media/w4dLzSx.gif', 'catalogo/crucifixo-declinado-unilateral-na-polia--w4dLzSx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-declinado-unilateral-na-polia--w4dLzSx.gif', ARRAY['peito'], ARRAY['polia'], ARRAY['peitoral'], ARRAY['deltoides','tríceps'], '["Step:1 Connect a D-handle to a low pulley cable machine and set the bench to a decline angle.","Step:2 Get onto the bench with your head toward the machine and grab the handle with your right hand.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Open the arms back along the same arc without dropping the load; switch sides when the set calls for it."]', '2026-10-31 19:45:09.441347+00', '2026-10-31 19:45:09.305+00'), ('W6PxUkg', 'Tríceps coice com halter', 'dumbbell kickback', 'triceps-coice-com-halter', 'https://static.exercisedb.dev/media/W6PxUkg.gif', 'catalogo/triceps-coice-com-halter--W6PxUkg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-com-halter--W6PxUkg.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:09.412065+00', '2026-10-31 19:45:09.274+00'), ('W8KAlkI', 'Flexão de braço na medicine ball', 'push-up medicine ball', 'flexao-de-braco-na-medicine-ball', 'https://static.exercisedb.dev/media/W8KAlkI.gif', 'catalogo/flexao-de-braco-na-medicine-ball--W8KAlkI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-na-medicine-ball--W8KAlkI.gif', ARRAY['peito'], ARRAY['medicine ball'], ARRAY['peitoral'], ARRAY['tríceps','deltoides','core'], '["Step:1 Begin in a high plank position with your hands on the medicine ball, about shoulder width.","Step:2 Brace your trunk and lower your body toward the ground by bending your elbows, with your spine steady.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:09.726045+00', '2026-10-31 19:45:09.596+00'), ('W9pFVv1', 'Agachamento no banco com barra', 'barbell bench squat', 'agachamento-no-banco-com-barra', 'https://static.exercisedb.dev/media/W9pFVv1.gif', 'catalogo/agachamento-no-banco-com-barra--W9pFVv1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-no-banco-com-barra--W9pFVv1.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Prepare a barbell on a squat rack at chest height.","Step:2 Face the away from the rack, from a stable stance with feet about shoulder width.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:10.115086+00', '2026-10-31 19:45:09.981+00'), ('WbNq5Xu', 'Supino em Pé na Máquina', 'Machine Standing Chest Press', 'supino-em-pe-na-maquina', 'https://static.exercisedb.dev/media/WbNq5Xu.gif', 'catalogo/supino-em-pe-na-maquina--WbNq5Xu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-em-pe-na-maquina--WbNq5Xu.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and position your hands at chest level.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:10.067862+00', '2026-10-31 19:45:09.926+00'), ('wbUYILZ', 'Remada Invertida com Elevação de Cotovelos', 'elbow lift - reverse push-up', 'remada-invertida-com-elevacao-de-cotovelos', 'https://static.exercisedb.dev/media/wbUYILZ.gif', 'catalogo/remada-invertida-com-elevacao-de-cotovelos--wbUYILZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-invertida-com-elevacao-de-cotovelos--wbUYILZ.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['tríceps','deltoides'], '["Step:1 Begin by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Step:2 Brace your trunk and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:10.003065+00', '2026-10-31 19:45:09.849+00'), ('WCAvOfC', 'Abdominal Tocando a Ponta dos Pés Alternado', 'Side-To-Side Toe Touch', 'abdominal-tocando-a-ponta-dos-pes-alternado', 'https://static.exercisedb.dev/media/WCAvOfC.gif', 'catalogo/abdominal-tocando-a-ponta-dos-pes-alternado--WCAvOfC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-tocando-a-ponta-dos-pes-alternado--WCAvOfC.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Stand and set your feet about shoulder width and your arms extended to the sides.","Step:2 Bend at the waist to the right, reaching your right hand toward your right foot while keeping your left hand extended to the side.","Step:3 Soften the knees and let the hips start the fold.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Keep the movement controlled throughout the range.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:45:10.078167+00', '2026-10-31 19:45:09.927+00'), ('WcHl7ru', 'Supino Fechado no Smith', 'smith close-grip bench press', 'supino-fechado-no-smith', 'https://static.exercisedb.dev/media/WcHl7ru.gif', 'catalogo/supino-fechado-no-smith--WcHl7ru.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-fechado-no-smith--WcHl7ru.gif', ARRAY['braços'], ARRAY['Smith'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the barbell with a close grip, slightly narrower than about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:10.316083+00', '2026-10-31 19:45:10.169+00'), ('wd4ds3s', 'Remada em Pé com Peso Corporal', 'bodyweight standing row', 'remada-em-pe-com-peso-corporal', 'https://static.exercisedb.dev/media/wd4ds3s.gif', 'catalogo/remada-em-pe-com-peso-corporal--wd4ds3s.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-com-peso-corporal--wd4ds3s.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Hold a bar or handles with palms facing down.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:10.804645+00', '2026-10-31 19:45:10.66+00'), ('wDN97Ca', 'Supino Máquina com Pegada Interna', 'machine inner chest press', 'supino-maquina-com-pegada-interna', 'https://static.exercisedb.dev/media/wDN97Ca.gif', 'catalogo/supino-maquina-com-pegada-interna--wDN97Ca.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-maquina-com-pegada-interna--wDN97Ca.gif', ARRAY['peito'], ARRAY['máquina articulada'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and position your elbows at a 90-degree angle.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:10.77364+00', '2026-10-31 19:45:10.629+00'), ('wdRZISl', 'Desenvolvimento Militar em Pé com Pegada Fechada na Barra', 'Barbell Standing Close-Grip Military Press', 'desenvolvimento-militar-em-pe-com-pegada-fechada-na-barra', 'https://static.exercisedb.dev/media/wdRZISl.gif', 'catalogo/desenvolvimento-militar-em-pe-com-pegada-fechada-na-barra--wdRZISl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-em-pe-com-pegada-fechada-na-barra--wdRZISl.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold the barbell with palms facing down, hands slightly closer than about shoulder width.","Step:2 Before moving, lift the barbell to shoulder height, keeping your elbows close to your body.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:11.102194+00', '2026-10-31 19:45:10.961+00'), ('wDUqY2u', 'Rosca na Polia Acima da Cabeça', 'cable overhead curl', 'rosca-na-polia-acima-da-cabeca', 'https://static.exercisedb.dev/media/wDUqY2u.gif', 'catalogo/rosca-na-polia-acima-da-cabeca--wDUqY2u.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-na-polia-acima-da-cabeca--wDUqY2u.gif', ARRAY['braços'], ARRAY['polia'], ARRAY['bíceps'], ARRAY['antebraços','deltoides'], '["Step:1 Connect a straight bar to a high pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:10.797282+00', '2026-10-31 19:45:10.65+00'), ('weoDEpH', 'Elevação de Pernas Estendidas na Cadeira Romana', 'Captains Chair Straight-Leg Raise', 'elevacao-de-pernas-estendidas-na-cadeira-romana', 'https://static.exercisedb.dev/media/weoDEpH.gif', 'catalogo/elevacao-de-pernas-estendidas-na-cadeira-romana--weoDEpH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-estendidas-na-cadeira-romana--weoDEpH.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Take a seat on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.","Step:2 Hold your torso stable and your back straight.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:45:11.100845+00', '2026-10-31 19:45:10.959+00'), ('wEulIzp', 'Elevação Lateral Unilateral na Polia', 'Cable Single-Arm Lateral Raise', 'elevacao-lateral-unilateral-na-polia', 'https://static.exercisedb.dev/media/wEulIzp.gif', 'catalogo/elevacao-lateral-unilateral-na-polia--wEulIzp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-unilateral-na-polia--wEulIzp.gif', ARRAY['ombros'], ARRAY['polia'], ARRAY['deltoides'], ARRAY['trapézio','tríceps'], '["Step:1 Stand and set your feet about shoulder width, facing the cable machine.","Step:2 Take hold of the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:45:11.428388+00', '2026-10-31 19:45:11.291+00'), ('wf24o8S', 'Remada com Kettlebell com Dois Braços', 'Kettlebell Two-Arm Row', 'remada-com-kettlebell-com-dois-bracos', 'https://static.exercisedb.dev/media/wf24o8S.gif', 'catalogo/remada-com-kettlebell-com-dois-bracos--wf24o8S.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-com-kettlebell-com-dois-bracos--wf24o8S.gif', ARRAY['costas'], ARRAY['kettlebell'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a kettlebell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:11.881842+00', '2026-10-31 19:45:11.483+00'), ('wfotm7S', 'Agachamento com Salto após Queda (Drop Jump)', 'bodyweight drop jump squat', 'agachamento-com-salto-apos-queda-drop-jump', 'https://static.exercisedb.dev/media/wfotm7S.gif', 'catalogo/agachamento-com-salto-apos-queda-drop-jump--wfotm7S.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-com-salto-apos-queda-drop-jump--wfotm7S.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:11.410848+00', '2026-10-31 19:45:11.27+00'), ('Wgaz7pm', 'Abdominal na Máquina Sentado', 'Machine Seated Crunch', 'abdominal-na-maquina-sentado', 'https://static.exercisedb.dev/media/Wgaz7pm.gif', 'catalogo/abdominal-na-maquina-sentado--Wgaz7pm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-na-maquina-sentado--Wgaz7pm.gif', ARRAY['abdômen'], ARRAY['máquina articulada'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Take a seat on the leverage machine with your back against the pad and your feet planted.","Step:2 Hold the handles or place your hands on the side pads for support.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:12.096493+00', '2026-10-31 19:45:11.949+00'), ('Wgbn9qo', 'Mergulho de Tríceps entre Bancos', 'triceps dip (between benches)', 'mergulho-de-triceps-entre-bancos', 'https://static.exercisedb.dev/media/Wgbn9qo.gif', 'catalogo/mergulho-de-triceps-entre-bancos--Wgbn9qo.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-de-triceps-entre-bancos--Wgbn9qo.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Step:2 Move your butt off the bench, supporting your weight with your hands.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:45:12.259745+00', '2026-10-31 19:45:12.114+00'), ('WgJnBH5', 'Rosca Direta com Halteres Sentado na Bola Suíça', 'dumbbell seated biceps curl (on stability ball)', 'rosca-direta-com-halteres-sentado-na-bola-suica', 'https://static.exercisedb.dev/media/WgJnBH5.gif', 'catalogo/rosca-direta-com-halteres-sentado-na-bola-suica--WgJnBH5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-sentado-na-bola-suica--WgJnBH5.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a stability ball with your feet planted and your back straight.","Step:2 Take a dumbbell in each hand with your palms facing forward and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:12.058753+00', '2026-10-31 19:45:11.919+00'), ('WhuFnR7', 'Elevação de Pernas Deitado no Banco Reto', 'lying leg raise flat bench', 'elevacao-de-pernas-deitado-no-banco-reto', 'https://static.exercisedb.dev/media/WhuFnR7.gif', 'catalogo/elevacao-de-pernas-deitado-no-banco-reto--WhuFnR7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-deitado-no-banco-reto--WhuFnR7.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['flexores do quadril'], '["Step:1 Settle onto a flat bench with your back pressed against it.","Step:2 Set your hands under your glutes for support.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:45:12.429395+00', '2026-10-31 19:45:12.299+00'), ('wi2H9QX', 'Supino Declinado com Pegada Aberta no Smith', 'Smith Wide-Grip Decline Bench Press', 'supino-declinado-com-pegada-aberta-no-smith', 'https://static.exercisedb.dev/media/wi2H9QX.gif', 'catalogo/supino-declinado-com-pegada-aberta-no-smith--wi2H9QX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-com-pegada-aberta-no-smith--wi2H9QX.gif', ARRAY['peito'], ARRAY['Smith'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the decline bench to the desired angle.","Step:2 Get onto the bench with your feet secured under the foot pads.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:12.673458+00', '2026-10-31 19:45:12.533+00'), ('wigSg76', 'Flexão de Braços com Palmas', 'clap push up', 'flexao-de-bracos-com-palmas', 'https://static.exercisedb.dev/media/wigSg76.gif', 'catalogo/flexao-de-bracos-com-palmas--wigSg76.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-bracos-com-palmas--wigSg76.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Begin in a high plank position with your hands just beyond shoulder width.","Step:2 Lower your body toward the ground by bending your elbows, keeping your core engaged.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:13.173823+00', '2026-10-31 19:45:13.034+00'), ('wkgnGfb', 'Supino Inclinado Pegada Neutra com Halteres na Bola Suíça', 'dumbbell incline hammer press on exercise ball', 'supino-inclinado-pegada-neutra-com-halteres-na-bola-suica', 'https://static.exercisedb.dev/media/wkgnGfb.gif', 'catalogo/supino-inclinado-pegada-neutra-com-halteres-na-bola-suica--wkgnGfb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-inclinado-pegada-neutra-com-halteres-na-bola-suica--wkgnGfb.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on an exercise ball with a dumbbell in each hand, palms facing each other.","Step:2 Step your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:13.418602+00', '2026-10-31 19:45:12.996+00'), ('WKMQzCD', 'Afundo com Passagem de Kettlebell', 'kettlebell lunge pass through', 'afundo-com-passagem-de-kettlebell', 'https://static.exercisedb.dev/media/WKMQzCD.gif', 'catalogo/afundo-com-passagem-de-kettlebell--WKMQzCD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-com-passagem-de-kettlebell--WKMQzCD.gif', ARRAY['coxas'], ARRAY['kettlebell'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell ahead of your chest with both hands.","Step:2 Step forward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:45:12.841296+00', '2026-10-31 19:45:12.689+00'), ('WL4EmxJ', 'Abdução de Quadril em Prancha Lateral', 'side bridge hip abduction', 'abducao-de-quadril-em-prancha-lateral', 'https://static.exercisedb.dev/media/WL4EmxJ.gif', 'catalogo/abducao-de-quadril-em-prancha-lateral--WL4EmxJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abducao-de-quadril-em-prancha-lateral--WL4EmxJ.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['abdutores'], ARRAY['glúteos','oblíquos'], '["Step:1 Settle onto your side with your legs extended and stacked on top of each other.","Step:2 Support yourself up on your forearm, keeping your elbow directly below your shoulder.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Hold the side plank line and raise the top leg without letting the hips roll back.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Lower the leg without dropping the hips, then repeat before changing sides."]', '2026-10-31 19:45:12.99107+00', '2026-10-31 19:45:12.849+00'), ('WLvTAv5', 'Rosca com Barra Deitado de Bruços no Banco Inclinado', 'barbell prone incline curl', 'rosca-com-barra-deitado-de-brucos-no-banco-inclinado', 'https://static.exercisedb.dev/media/WLvTAv5.gif', 'catalogo/rosca-com-barra-deitado-de-brucos-no-banco-inclinado--WLvTAv5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-com-barra-deitado-de-brucos-no-banco-inclinado--WLvTAv5.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Position yourself face down on the bench with your chest and stomach resting against it.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:13.313147+00', '2026-10-31 19:45:13.176+00'), ('WME869U', 'Extensão Lombar na Bola Suíça com Joelhos Fora do Chão', 'exercise ball back extension with knees off ground', 'extensao-lombar-na-bola-suica-com-joelhos-fora-do-chao', 'https://static.exercisedb.dev/media/WME869U.gif', 'catalogo/extensao-lombar-na-bola-suica-com-joelhos-fora-do-chao--WME869U.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar-na-bola-suica-com-joelhos-fora-do-chao--WME869U.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the stability ball on the ground and Position yourself face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Step:2 Set your hands behind your head or crossed over your chest.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:45:13.970701+00', '2026-10-31 19:45:13.83+00'), ('wnEscH8', 'Abdominal com desenvolvimento de barra', 'barbell press sit-up', 'abdominal-com-desenvolvimento-de-barra', 'https://static.exercisedb.dev/media/wnEscH8.gif', 'catalogo/abdominal-com-desenvolvimento-de-barra--wnEscH8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-desenvolvimento-de-barra--wnEscH8.gif', ARRAY['Abdômen'], ARRAY['Barra'], ARRAY['Abdômen'], ARRAY['Deltoides','Peitorais'], '["Step:1 Settle onto your back on a mat with your knees bent and feet planted.","Step:2 Take hold of the barbell with palms facing down, resting it on your chest.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:13.961007+00', '2026-10-31 19:45:13.818+00'), ('wOLmCXc', 'Tríceps coice com halter em postura de cegonha', 'Dumbbell Triceps Kickback With Stork Stance', 'triceps-coice-com-halter-em-postura-de-cegonha', 'https://static.exercisedb.dev/media/wOLmCXc.gif', 'catalogo/triceps-coice-com-halter-em-postura-de-cegonha--wOLmCXc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-com-halter-em-postura-de-cegonha--wOLmCXc.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in your right hand.","Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:14.037827+00', '2026-10-31 19:45:13.886+00'), ('wpbD28t', 'Flexão lateral', 'side push-up', 'flexao-lateral', 'https://static.exercisedb.dev/media/wpbD28t.gif', 'catalogo/flexao-lateral--wpbD28t.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-lateral--wpbD28t.gif', ARRAY['Braços'], ARRAY['Peso corporal'], ARRAY['Tríceps'], ARRAY['Deltoides','Peitorais','Core'], '["Step:1 Begin by lying on your side with your legs extended and stacked on top of each other.","Step:2 Set your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:14.063773+00', '2026-10-31 19:45:13.933+00'), ('wPypxFY', 'Flexão lateral de tronco na polia', 'cable side bend', 'flexao-lateral-de-tronco-na-polia', 'https://static.exercisedb.dev/media/wPypxFY.gif', 'catalogo/flexao-lateral-de-tronco-na-polia--wPypxFY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-lateral-de-tronco-na-polia--wPypxFY.gif', ARRAY['Abdômen'], ARRAY['Polia'], ARRAY['Abdômen'], ARRAY['Oblíquos'], '["Step:1 Stand and set your feet about shoulder width and Hold the cable handle with one hand.","Step:2 Keep your spine in a comfortable neutral position and your core engaged.","Step:3 Stand or sit tall with the pelvis facing forward.","Step:4 Bend sideways through the waist without twisting or letting the hips shift.","Step:5 Let the side of the trunk work; do not twist or shift the hips.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:45:14.438898+00', '2026-10-31 19:45:14.295+00'), ('wQ2c4XD', 'Levantamento terra romeno com barra', 'barbell romanian deadlift', 'levantamento-terra-romeno-com-barra', 'https://static.exercisedb.dev/media/wQ2c4XD.gif', 'catalogo/levantamento-terra-romeno-com-barra--wQ2c4XD.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/levantamento-terra-romeno-com-barra--wQ2c4XD.gif', ARRAY['Coxas'], ARRAY['Barra'], ARRAY['Glúteos'], ARRAY['Posteriores de coxa','Eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and your toes pointing forward.","Step:2 Take hold of the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:45:14.750379+00', '2026-10-31 19:45:14.384+00'), ('wqNPGCg', 'Remada para deltoide posterior na polia (com corda)', 'cable rear delt row (with rope)', 'remada-para-deltoide-posterior-na-polia-com-corda', 'https://static.exercisedb.dev/media/wqNPGCg.gif', 'catalogo/remada-para-deltoide-posterior-na-polia-com-corda--wqNPGCg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-para-deltoide-posterior-na-polia-com-corda--wqNPGCg.gif', ARRAY['Ombros'], ARRAY['Polia'], ARRAY['Deltoides'], ARRAY['Trapézio','Romboides','Bíceps'], '["Step:1 Connect a rope handle to a low pulley cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:14.583656+00', '2026-10-31 19:45:14.444+00'), ('WrYPP2g', 'Remada alta unilateral na polia com costas retas (ajoelhado)', 'Cable Single-Arm Straight Back High Row (Kneeling)', 'remada-alta-unilateral-na-polia-com-costas-retas-ajoelhado', 'https://static.exercisedb.dev/media/WrYPP2g.gif', 'catalogo/remada-alta-unilateral-na-polia-com-costas-retas-ajoelhado--WrYPP2g.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-unilateral-na-polia-com-costas-retas-ajoelhado--WrYPP2g.gif', ARRAY['Costas'], ARRAY['Polia'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Deltoides'], '["Step:1 Connect a handle to a cable machine at waist height.","Step:2 Kneel facing the cable machine and grab the handle with one hand.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:45:14.829516+00', '2026-10-31 19:45:14.694+00'), ('wSScovH', 'Extensão de quadril inclinado com faixa elástica', 'band bent-over hip extension', 'extensao-de-quadril-inclinado-com-faixa-elastica', 'https://static.exercisedb.dev/media/wSScovH.gif', 'catalogo/extensao-de-quadril-inclinado-com-faixa-elastica--wSScovH.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-quadril-inclinado-com-faixa-elastica--wSScovH.gif', ARRAY['Coxas'], ARRAY['Faixa elástica'], ARRAY['Glúteos'], ARRAY['Posteriores de coxa','Eretores da espinha'], '["Step:1 Secure the band low on a solid anchor.","Step:2 Face the away from the anchor point from a stable stance with feet about shoulder width.","Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.","Step:4 Press through the feet and lift your hips until your torso and thighs line up.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the hips steadily and keep the feet planted for the next lift."]', '2026-10-31 19:45:15.044748+00', '2026-10-31 19:45:14.883+00'), ('wt6rwjk', 'Remada curvada com halter e rotação da palma', 'dumbbell palm rotational bent over row', 'remada-curvada-com-halter-e-rotacao-da-palma', 'https://static.exercisedb.dev/media/wt6rwjk.gif', 'catalogo/remada-curvada-com-halter-e-rotacao-da-palma--wt6rwjk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-com-halter-e-rotacao-da-palma--wt6rwjk.gif', ARRAY['Costas'], ARRAY['Halter'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.","Step:2 Bend forward at the hips, with your spine steady and your knees soft.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:15.022156+00', '2026-10-31 19:45:14.876+00'), ('wu5LXwz', 'Extensão de tríceps com barra olímpica', 'olympic barbell triceps extension', 'extensao-de-triceps-com-barra-olimpica', 'https://static.exercisedb.dev/media/wu5LXwz.gif', 'catalogo/extensao-de-triceps-com-barra-olimpica--wu5LXwz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-de-triceps-com-barra-olimpica--wu5LXwz.gif', ARRAY['Braços'], ARRAY['Barra olímpica'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Begin by standing with your feet about shoulder width and holding the barbell with palms facing down.","Step:2 Raise the barbell above your head, straighten your arms.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:15.531777+00', '2026-10-31 19:45:15.393+00'), ('WU9BLIs', 'Torção russa com peso (pernas elevadas)', 'weighted russian twist (legs up)', 'torcao-russa-com-peso-pernas-elevadas', 'https://static.exercisedb.dev/media/WU9BLIs.gif', 'catalogo/torcao-russa-com-peso-pernas-elevadas--WU9BLIs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/torcao-russa-com-peso-pernas-elevadas--WU9BLIs.gif', ARRAY['Abdômen'], ARRAY['Com peso'], ARRAY['Abdômen'], ARRAY['Oblíquos','Flexores do quadril'], '["Step:1 Take a seat on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Step:2 Take hold of the weight with both hands ahead of your chest, keeping your elbows soft.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:15.657114+00', '2026-10-31 19:45:15.525+00'), ('WVD66ff', 'Extensão lombar na bola suíça com rotação', 'exercise ball back extension with rotation', 'extensao-lombar-na-bola-suica-com-rotacao', 'https://static.exercisedb.dev/media/WVD66ff.gif', 'catalogo/extensao-lombar-na-bola-suica-com-rotacao--WVD66ff.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar-na-bola-suica-com-rotacao--WVD66ff.gif', ARRAY['Costas'], ARRAY['Bola suíça'], ARRAY['Eretores da espinha'], ARRAY['Glúteos','Posteriores de coxa'], '["Step:1 Begin by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Step:2 Set your hands behind your head or cross them over your chest.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:15.763776+00', '2026-10-31 19:45:15.623+00'), ('wVompEp', 'Flexão de braço no bosu', 'push up on bosu ball', 'flexao-de-braco-no-bosu', 'https://static.exercisedb.dev/media/wVompEp.gif', 'catalogo/flexao-de-braco-no-bosu--wVompEp.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-no-bosu--wVompEp.gif', ARRAY['Peitoral'], ARRAY['Bosu'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides','Core'], '["Step:1 Set the bosu ball on the ground with the flat side facing up.","Step:2 Set yourself in a push-up position with your hands on the outer edges of the bosu ball.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:15.937665+00', '2026-10-31 19:45:15.801+00'), ('WW95auq', 'Abdominal ajoelhado na polia', 'cable kneeling crunch', 'abdominal-ajoelhado-na-polia', 'https://static.exercisedb.dev/media/WW95auq.gif', 'catalogo/abdominal-ajoelhado-na-polia--WW95auq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-ajoelhado-na-polia--WW95auq.gif', ARRAY['Abdômen'], ARRAY['Polia'], ARRAY['Abdômen'], ARRAY['Oblíquos'], '["Step:1 Connect a rope handle to a high pulley and kneel down turned away from the machine.","Step:2 Take hold of the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:15.661592+00', '2026-10-31 19:45:15.519+00'), ('WWD6FzI', 'Leg press 45° unilateral', 'Sled 45 Degrees Single-Leg Press', 'leg-press-45-unilateral', 'https://static.exercisedb.dev/media/WWD6FzI.gif', 'catalogo/leg-press-45-unilateral--WWD6FzI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-45-unilateral--WWD6FzI.gif', ARRAY['Coxas'], ARRAY['Máquina de leg press'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de coxa','Panturrilhas'], '["Step:1 Set the sled machine to a 45-degree angle.","Step:2 Take a seat on the sled machine with your back against the pad and your feet on the footplate.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Keep the pelvis level as the supporting leg does the work.","Step:6 Ease back to the start before repeating; switch sides when the set calls for it."]', '2026-10-31 19:45:16.501411+00', '2026-10-31 19:45:16.349+00'), ('wWFspEi', 'Afundo estático unilateral no Smith', 'smith single leg split squat', 'afundo-estatico-unilateral-no-smith', 'https://static.exercisedb.dev/media/wWFspEi.gif', 'catalogo/afundo-estatico-unilateral-no-smith--wWFspEi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/afundo-estatico-unilateral-no-smith--wWFspEi.gif', ARRAY['Coxas'], ARRAY['Smith'], ARRAY['Quadríceps'], ARRAY['Glúteos','Posteriores de coxa'], '["Step:1 Take your place in front of the smith machine with your feet about shoulder width.","Step:2 Set one foot behind you on a bench or step, with your toes pointing forward.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:16.319036+00', '2026-10-31 19:45:16.188+00'), ('wXvUZC8', 'Empurrar e puxar com peso corporal', 'push and pull bodyweight', 'empurrar-e-puxar-com-peso-corporal', 'https://static.exercisedb.dev/media/wXvUZC8.gif', 'catalogo/empurrar-e-puxar-com-peso-corporal--wXvUZC8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/empurrar-e-puxar-com-peso-corporal--wXvUZC8.gif', ARRAY['Peitoral'], ARRAY['Peso corporal'], ARRAY['Peitorais'], ARRAY['Tríceps','Deltoides'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your body in a straight line.","Step:2 Lower your chest toward the ground by bending your elbows, keeping your body straight.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:16.679695+00', '2026-10-31 19:45:16.547+00'), ('wyaqzOS', 'Tríceps testa unilateral com halter deitado, pegada pronada', 'Dumbbell Lying Single-Arm Pronated Triceps Extension', 'triceps-testa-unilateral-com-halter-deitado-pegada-pronada', 'https://static.exercisedb.dev/media/wyaqzOS.gif', 'catalogo/triceps-testa-unilateral-com-halter-deitado-pegada-pronada--wyaqzOS.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-unilateral-com-halter-deitado-pegada-pronada--wyaqzOS.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Settle onto a bench with your back and head supported, and your feet planted.","Step:2 Take a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:45:16.759293+00', '2026-10-31 19:45:16.621+00'), ('x0lwvfq', 'Tríceps coice alternado com halter sentado e inclinado', 'dumbbell seated bent over alternate kickback', 'triceps-coice-alternado-com-halter-sentado-e-inclinado', 'https://static.exercisedb.dev/media/x0lwvfq.gif', 'catalogo/triceps-coice-alternado-com-halter-sentado-e-inclinado--x0lwvfq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-coice-alternado-com-halter-sentado-e-inclinado--x0lwvfq.gif', ARRAY['Braços'], ARRAY['Halter'], ARRAY['Tríceps'], ARRAY['Deltoides','Costas'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, palms facing inwards.","Step:2 Bend forward at the waist, with your spine steady and parallel to the ground.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Hold the upper arm beside your torso and straighten the elbow behind you.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:45:16.773952+00', '2026-10-31 19:45:16.637+00'), ('x2chWLO', 'Alongamento lateral do pescoço', 'neck side stretch', 'alongamento-lateral-do-pescoco', 'https://static.exercisedb.dev/media/x2chWLO.gif', 'catalogo/alongamento-lateral-do-pescoco--x2chWLO.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lateral-do-pescoco--x2chWLO.gif', ARRAY['Pescoço'], ARRAY['Peso corporal'], ARRAY['Levantador da escápula'], ARRAY['Trapézio','Esternocleidomastoideo'], '["Step:1 Either stand or sit up straight with your shoulders relaxed.","Step:2 Tilt your head to one side, bringing your ear toward your shoulder.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:17.186356+00', '2026-10-31 19:45:16.767+00'), ('x306lCW', 'Rotação externa de ombro em pé com halter', 'dumbbell upright shoulder external rotation', 'rotacao-externa-de-ombro-em-pe-com-halter', 'https://static.exercisedb.dev/media/x306lCW.gif', 'catalogo/rotacao-externa-de-ombro-em-pe-com-halter--x306lCW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-externa-de-ombro-em-pe-com-halter--x306lCW.gif', ARRAY['Ombros'], ARRAY['Halter'], ARRAY['Deltoides'], ARRAY['Manguito rotador','Trapézio'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand with your palms facing your body.","Step:2 Raise your arms out to the sides until they are parallel to the ground, keeping your elbows soft.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:17.374708+00', '2026-10-31 19:45:17.228+00'), ('X3cqyXz', 'Remada curvada na máquina', 'Machine Bent Over Row', 'remada-curvada-na-maquina', 'https://static.exercisedb.dev/media/X3cqyXz.gif', 'catalogo/remada-curvada-na-maquina--X3cqyXz.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-na-maquina--X3cqyXz.gif', ARRAY['Costas'], ARRAY['Barra'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Stand and set your feet about shoulder width and knees soft.","Step:2 Take hold of the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:17.274373+00', '2026-10-31 19:45:17.121+00'), ('X3TCNEU', 'Fallout abdominal na suspensão', 'suspended abdominal fallout', 'fallout-abdominal-na-suspensao', 'https://static.exercisedb.dev/media/X3TCNEU.gif', 'catalogo/fallout-abdominal-na-suspensao--X3TCNEU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/fallout-abdominal-na-suspensao--X3TCNEU.gif', ARRAY['Abdômen'], ARRAY['Peso corporal','Fitas de suspensão'], ARRAY['Abdômen'], ARRAY['Oblíquos','Flexores do quadril'], '["Step:1 Connect a suspension trainer to a high anchor point and adjust the straps to waist height.","Step:2 Face away from the anchor point and hold the handles with your arms extended in front of you.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:45:17.593526+00', '2026-10-31 19:45:17.449+00'), ('x69MAlq', 'Pulldown com braços estendidos na polia', 'cable straight arm pulldown', 'pulldown-com-bracos-estendidos-na-polia', 'https://static.exercisedb.dev/media/x69MAlq.gif', 'catalogo/pulldown-com-bracos-estendidos-na-polia--x69MAlq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pulldown-com-bracos-estendidos-na-polia--x69MAlq.gif', ARRAY['Costas'], ARRAY['Polia'], ARRAY['Grande dorsal'], ARRAY['Deltoides','Bíceps'], '["Step:1 Connect a straight bar to the high pulley of a cable machine.","Step:2 Face the machine from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:45:17.605849+00', '2026-10-31 19:45:17.46+00'), ('X6C6i5Y', 'Mergulho para tríceps', 'triceps dip', 'mergulho-para-triceps', 'https://static.exercisedb.dev/media/X6C6i5Y.gif', 'catalogo/mergulho-para-triceps--X6C6i5Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-para-triceps--X6C6i5Y.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Step:2 Move your butt off the bench, supporting your weight with your hands.","Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.","Step:4 Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.","Step:5 Choose a depth that lets the shoulders stay comfortable.","Step:6 Press through the hands to rise, then reset the shoulders before another rep."]', '2026-10-31 19:45:17.758168+00', '2026-10-31 19:45:17.622+00'), ('x6KpKpq', 'Flexão de braço pegada fechada', 'close-grip push-up', 'flexao-de-braco-pegada-fechada', 'https://static.exercisedb.dev/media/x6KpKpq.gif', 'catalogo/flexao-de-braco-pegada-fechada--x6KpKpq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-pegada-fechada--x6KpKpq.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Begin in a high plank position with your hands placed close together, directly under your shoulders.","Step:2 Brace your trunk and lower your body toward the ground, keeping your elbows close to your sides.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:17.873645+00', '2026-10-31 19:45:17.743+00'), ('X6ytgYZ', 'Prancha lateral com crucifixo inverso com halter', 'dumbbell side plank with rear fly', 'prancha-lateral-com-crucifixo-inverso-com-halter', 'https://static.exercisedb.dev/media/X6ytgYZ.gif', 'catalogo/prancha-lateral-com-crucifixo-inverso-com-halter--X6ytgYZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-lateral-com-crucifixo-inverso-com-halter--X6ytgYZ.gif', ARRAY['costas'], ARRAY['halter'], ARRAY['parte superior das costas'], ARRAY['deltoides','core'], '["Step:1 Begin by lying on your side with your legs extended and stacked on top of each other.","Step:2 Set your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:18.243006+00', '2026-10-31 19:45:18.095+00'), ('X7jbxra', 'Alongamento de joelho com círculos', 'circles knee stretch', 'alongamento-de-joelho-com-circulos', 'https://static.exercisedb.dev/media/X7jbxra.gif', 'catalogo/alongamento-de-joelho-com-circulos--X7jbxra.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-joelho-com-circulos--X7jbxra.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Stand and set your feet about shoulder width and your hands on your hips.","Step:2 Before moving, bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:18.140351+00', '2026-10-31 19:45:17.999+00'), ('x825CZm', 'Elevação lateral inversa sentado no cabo', 'cable seated rear lateral raise', 'elevacao-lateral-inversa-sentado-no-cabo', 'https://static.exercisedb.dev/media/x825CZm.gif', 'catalogo/elevacao-lateral-inversa-sentado-no-cabo--x825CZm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-inversa-sentado-no-cabo--x825CZm.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Take a seat on a bench facing the cable machine with your feet planted.","Step:2 Hold the cable handles with palms facing down and extend your arms straight in front of you.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:18.232047+00', '2026-10-31 19:45:18.093+00'), ('XaaRnRn', 'Flexão de braço inclinada com pegada invertida', 'Incline Reverse-Grip Push-Up', 'flexao-de-braco-inclinada-com-pegada-invertida', 'https://static.exercisedb.dev/media/XaaRnRn.gif', 'catalogo/flexao-de-braco-inclinada-com-pegada-invertida--XaaRnRn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-inclinada-com-pegada-invertida--XaaRnRn.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set your hands on the edge of a bench or elevated surface, just beyond shoulder width.","Step:2 Reach your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:18.841086+00', '2026-10-31 19:45:18.71+00'), ('XalXcvM', 'Avanço com extensão de tríceps com halter', 'dumbbell forward lunge triceps extension', 'avanco-com-extensao-de-triceps-com-halter', 'https://static.exercisedb.dev/media/XalXcvM.gif', 'catalogo/avanco-com-extensao-de-triceps-com-halter--XalXcvM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/avanco-com-extensao-de-triceps-com-halter--XalXcvM.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['tríceps'], ARRAY['deltoides','core'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand.","Step:2 Step forward with your right foot, lowering your body into a lunge position.","Step:3 Set your stance wide enough to balance before bending either knee.","Step:4 Step into the movement and bend both knees, keeping your front foot planted.","Step:5 Keep the front foot planted and avoid collapsing inward at the knee.","Step:6 Push through the lead foot to return to the start, then change legs as planned."]', '2026-10-31 19:45:18.67907+00', '2026-10-31 19:45:18.536+00'), ('xAySMB0', 'Prancha de equilíbrio', 'balance board', 'prancha-de-equilibrio', 'https://static.exercisedb.dev/media/xAySMB0.gif', 'catalogo/prancha-de-equilibrio--xAySMB0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/prancha-de-equilibrio--xAySMB0.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['panturrilhas','posteriores de coxa','glúteos'], '["Step:1 Set the balance board on a flat surface.","Step:2 Get onto the balance board with one foot, ensuring it is centered.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:18.728188+00', '2026-10-31 19:45:18.59+00'), ('xbkPfaw', 'Remada unilateral em pé com peso corporal', 'Bodyweight Standing Single-Arm Row', 'remada-unilateral-em-pe-com-peso-corporal', 'https://static.exercisedb.dev/media/xbkPfaw.gif', 'catalogo/remada-unilateral-em-pe-com-peso-corporal--xbkPfaw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-unilateral-em-pe-com-peso-corporal--xbkPfaw.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['parte superior das costas'], ARRAY['bíceps','antebraços'], '["Step:1 Stand and set your feet about shoulder width, knees soft, and hold a dumbbell in one hand.","Step:2 Bend forward at the hips, with your spine steady and your core engaged.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:45:19.092447+00', '2026-10-31 19:45:18.954+00'), ('xBYcQHj', 'Puxada no cabo com pegada supinada', 'cable underhand pulldown', 'puxada-no-cabo-com-pegada-supinada', 'https://static.exercisedb.dev/media/xBYcQHj.gif', 'catalogo/puxada-no-cabo-com-pegada-supinada--xBYcQHj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-no-cabo-com-pegada-supinada--xBYcQHj.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Set the cable machine so that the pulldown bar is at a height above your head.","Step:2 Sit down on the seat and grab the pulldown bar with palms facing up, hands just beyond shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Pull with the elbows rather than leaning far back to move the handle.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:45:18.887981+00', '2026-10-31 19:45:18.749+00'), ('xDh0lJr', 'Desenvolvimento atrás da nuca em pé com barra', 'standing behind neck press', 'desenvolvimento-atras-da-nuca-em-pe-com-barra', 'https://static.exercisedb.dev/media/xDh0lJr.gif', 'catalogo/desenvolvimento-atras-da-nuca-em-pe-com-barra--xDh0lJr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-atras-da-nuca-em-pe-com-barra--xDh0lJr.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Stand and set your feet about shoulder width and hold the barbell behind your neck with palms facing down.","Step:2 Keep your spine in a comfortable neutral position and core engaged.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:19.510573+00', '2026-10-31 19:45:19.365+00'), ('XDOiFns', 'Panturrilha no sled com inclinação para frente', 'sled forward angled calf raise', 'panturrilha-no-sled-com-inclinacao-para-frente', 'https://static.exercisedb.dev/media/XDOiFns.gif', 'catalogo/panturrilha-no-sled-com-inclinacao-para-frente--XDOiFns.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-no-sled-com-inclinacao-para-frente--XDOiFns.gif', ARRAY['panturrilhas'], ARRAY['máquina sled'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Set the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Step:2 Set your hands on the handles or the sides of the machine for support.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:19.610744+00', '2026-10-31 19:45:19.48+00'), ('xdYPUtE', 'Agachamento sissy', 'sissy squat', 'agachamento-sissy', 'https://static.exercisedb.dev/media/xdYPUtE.gif', 'catalogo/agachamento-sissy--xdYPUtE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-sissy--xdYPUtE.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['panturrilhas','glúteos'], '["Step:1 Stand and set your feet about shoulder width and your toes pointing slightly outward.","Step:2 Use a stable object for balance if needed.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:19.463558+00', '2026-10-31 19:45:19.317+00'), ('XeMvLgE', 'Serra com rolo abdominal', 'roller body saw', 'serra-com-rolo-abdominal', 'https://static.exercisedb.dev/media/XeMvLgE.gif', 'catalogo/serra-com-rolo-abdominal--XeMvLgE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/serra-com-rolo-abdominal--XeMvLgE.gif', ARRAY['abdômen'], ARRAY['rolo abdominal'], ARRAY['abdominais'], ARRAY['deltoides','tríceps','core'], '["Step:1 Begin in a plank position with your forearms on the roller and your body in a straight line.","Step:2 Brace your trunk and With control roll the roller forward, extending your body as far as you can while maintaining control.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:45:19.572548+00', '2026-10-31 19:45:19.435+00'), ('XFc3vpY', 'Rosca bíceps sentado com elástico', 'Band Seated Biceps Curl', 'rosca-biceps-sentado-com-elastico', 'https://static.exercisedb.dev/media/XFc3vpY.gif', 'catalogo/rosca-biceps-sentado-com-elastico--XFc3vpY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-biceps-sentado-com-elastico--XFc3vpY.gif', ARRAY['braços'], ARRAY['elástico'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a chair or bench with your back straight and feet planted.","Step:2 Take hold of the resistance band with palms facing up, and arms extended down by your sides.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:19.805213+00', '2026-10-31 19:45:19.667+00'), ('xGgAGPm', 'Alongamento de perna estendida na cadeira', 'chair leg extended stretch', 'alongamento-de-perna-estendida-na-cadeira', 'https://static.exercisedb.dev/media/xGgAGPm.gif', 'catalogo/alongamento-de-perna-estendida-na-cadeira--xGgAGPm.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-perna-estendida-na-cadeira--xGgAGPm.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','panturrilhas'], '["Step:1 Take a seat on the edge of a chair with your back straight and feet planted.","Step:2 Reach one leg straight out in front of you, keeping your heel on the ground.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:20.297135+00', '2026-10-31 19:45:20.153+00'), ('xgsGFVM', 'Abdominal caranguejo com rotação e toque no pé', 'crab twist toe touch', 'abdominal-caranguejo-com-rotacao-e-toque-no-pe', 'https://static.exercisedb.dev/media/xgsGFVM.gif', 'catalogo/abdominal-caranguejo-com-rotacao-e-toque-no-pe--xgsGFVM.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-caranguejo-com-rotacao-e-toque-no-pe--xgsGFVM.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Begin by sitting on the ground with your knees bent and feet planted.","Step:2 Set your hands behind you, fingers pointing toward your feet, and lift your hips off the ground.","Step:3 Soften the knees and let the hips start the fold.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Keep the movement controlled throughout the range.","Step:6 Hold briefly at a comfortable depth, then rise by extending the hips."]', '2026-10-31 19:45:20.124859+00', '2026-10-31 19:45:19.983+00'), ('XgWyAiA', 'Mergulho para peitoral (na estação de barras paralelas e barra fixa)', 'chest dip (on dip-pull-up cage)', 'mergulho-para-peitoral-na-estacao-de-barras-paralelas-e-barra-fixa', 'https://static.exercisedb.dev/media/XgWyAiA.gif', 'catalogo/mergulho-para-peitoral-na-estacao-de-barras-paralelas-e-barra-fixa--XgWyAiA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mergulho-para-peitoral-na-estacao-de-barras-paralelas-e-barra-fixa--XgWyAiA.gif', ARRAY['peito'], ARRAY['peso corporal'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Set the dip bars to a height that allows you to comfortably grip them.","Step:2 Stand between the bars and place your hands on each bar, just beyond shoulder width.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:20.141871+00', '2026-10-31 19:45:20.005+00'), ('XhfS1DZ', 'Alongamento dos fibulares', 'peroneals stretch', 'alongamento-dos-fibulares', 'https://static.exercisedb.dev/media/XhfS1DZ.gif', 'catalogo/alongamento-dos-fibulares--XhfS1DZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-dos-fibulares--XhfS1DZ.gif', ARRAY['panturrilhas'], ARRAY['corda'], ARRAY['panturrilhas'], ARRAY['tornozelos','pés'], '["Step:1 Take a seat on the ground with your legs extended in front of you.","Step:2 Thread the rope around the ball of your foot and hold the ends of the rope with your hands.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:20.683015+00', '2026-10-31 19:45:20.544+00'), ('xHKN2s8', 'Arranco unilateral com barra', 'Barbell Single-Arm Snatch', 'arranco-unilateral-com-barra', 'https://static.exercisedb.dev/media/xHKN2s8.gif', 'catalogo/arranco-unilateral-com-barra--xHKN2s8.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/arranco-unilateral-com-barra--xHKN2s8.gif', ARRAY['ombros'], ARRAY['barra'], ARRAY['deltoides'], ARRAY['trapézio','antebraços','core'], '["Step:1 Stand and set your feet about shoulder width, toes pointing slightly outwards.","Step:2 Take hold of the barbell with palms facing down, hands just beyond shoulder width.","Step:3 Brace before the pull and keep the load close to the body.","Step:4 Drive through the legs and hips, then guide the weight to its receiving position.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it."]', '2026-10-31 19:45:20.455875+00', '2026-10-31 19:45:20.298+00'), ('xi0yckC', 'Elevação de ombros inclinada com barra', 'barbell incline shoulder raise', 'elevacao-de-ombros-inclinada-com-barra', 'https://static.exercisedb.dev/media/xi0yckC.gif', 'catalogo/elevacao-de-ombros-inclinada-com-barra--xi0yckC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-ombros-inclinada-com-barra--xi0yckC.gif', ARRAY['peito'], ARRAY['barra'], ARRAY['serrátil anterior'], ARRAY['deltoides','trapézio'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Take a seat on the bench with your back against the pad and feet planted.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:21.270237+00', '2026-10-31 19:45:21.13+00'), ('xiA6lRr', 'Rosca direta sentado com halteres', 'Dumbbell Seated Biceps Curl', 'rosca-direta-sentado-com-halteres', 'https://static.exercisedb.dev/media/xiA6lRr.gif', 'catalogo/rosca-direta-sentado-com-halteres--xiA6lRr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-sentado-com-halteres--xiA6lRr.gif', ARRAY['braços'], ARRAY['halter'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.","Step:2 Keep your spine in a comfortable neutral position and your elbows close to your torso.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:21.098174+00', '2026-10-31 19:45:20.957+00'), ('xifhB5W', 'Alongamento de deltoide posterior', 'rear deltoid stretch', 'alongamento-de-deltoide-posterior', 'https://static.exercisedb.dev/media/xifhB5W.gif', 'catalogo/alongamento-de-deltoide-posterior--xifhB5W.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-deltoide-posterior--xifhB5W.gif', ARRAY['ombros'], ARRAY['peso corporal'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Stand tall and set your feet about shoulder width.","Step:2 Reach your right arm across your chest, placing your left hand on your right elbow.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:20.853254+00', '2026-10-31 19:45:20.707+00'), ('XIHEoCG', 'Panturrilha em pé', 'standing calves', 'panturrilha-em-pe', 'https://static.exercisedb.dev/media/XIHEoCG.gif', 'catalogo/panturrilha-em-pe--XIHEoCG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe--XIHEoCG.gif', ARRAY['panturrilhas'], ARRAY['peso corporal'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Stand and set your feet about shoulder width, toes pointing forward.","Step:2 Before moving, raise your heels off the ground as high as possible, standing on your toes.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:21.477827+00', '2026-10-31 19:45:21.332+00'), ('xiHiJcA', 'Crucifixo inverso na máquina sentado (pegada neutra)', 'Machine Seated Reverse Fly (Parallel Grip)', 'crucifixo-inverso-na-maquina-sentado-pegada-neutra', 'https://static.exercisedb.dev/media/xiHiJcA.gif', 'catalogo/crucifixo-inverso-na-maquina-sentado-pegada-neutra--xiHiJcA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-inverso-na-maquina-sentado-pegada-neutra--xiHiJcA.gif', ARRAY['ombros'], ARRAY['máquina articulada'], ARRAY['deltoides'], ARRAY['trapézio','romboides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with a parallel grip, palms facing each other, and keep your arms soft.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:45:21.629259+00', '2026-10-31 19:45:21.485+00'), ('xLYSdtg', 'Crucifixo no cabo (altura média)', 'cable middle fly', 'crucifixo-no-cabo-altura-media', 'https://static.exercisedb.dev/media/xLYSdtg.gif', 'catalogo/crucifixo-no-cabo-altura-media--xLYSdtg.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-no-cabo-altura-media--xLYSdtg.gif', ARRAY['peito'], ARRAY['cabo'], ARRAY['peitorais'], ARRAY['deltoides','tríceps'], '["Step:1 Connect cables to both sides of a cable machine at chest height.","Step:2 Take your place in the center of the machine with one foot slightly in front of the other.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:45:21.612018+00', '2026-10-31 19:45:21.476+00'), ('XlZ4lAC', 'Good morning com barra', 'barbell good morning', 'good-morning-com-barra', 'https://static.exercisedb.dev/media/XlZ4lAC.gif', 'catalogo/good-morning-com-barra--XlZ4lAC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/good-morning-com-barra--XlZ4lAC.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['posteriores de coxa'], ARRAY['eretores da espinha'], '["Step:1 Begin by standing with your feet about shoulder width and the barbell resting on your upper back.","Step:2 With your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:45:21.7739+00', '2026-10-31 19:45:21.643+00'), ('xMjBKwn', 'Elevação lateral para frontal com halteres', 'dumbbell lateral to front raise', 'elevacao-lateral-para-frontal-com-halteres', 'https://static.exercisedb.dev/media/xMjBKwn.gif', 'catalogo/elevacao-lateral-para-frontal-com-halteres--xMjBKwn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-para-frontal-com-halteres--xMjBKwn.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your body.","Step:2 Keep your spine in a comfortable neutral position and Brace your trunk.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:21.849104+00', '2026-10-31 19:45:21.711+00'), ('xmM75XG', 'Abdominal com peso acima da cabeça na bola suíça', 'weighted overhead crunch (on stability ball)', 'abdominal-com-peso-acima-da-cabeca-na-bola-suica', 'https://static.exercisedb.dev/media/xmM75XG.gif', 'catalogo/abdominal-com-peso-acima-da-cabeca-na-bola-suica--xmM75XG.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-peso-acima-da-cabeca-na-bola-suica--xmM75XG.gif', ARRAY['abdômen'], ARRAY['peso adicional','bola suíça'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 Take a weight plate or dumbbell with both hands and extend your arms overhead.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:22.391618+00', '2026-10-31 19:45:22.248+00'), ('xnInPfE', 'Roda abdominal em pé com barra', 'Barbell Standing Ab Rollout', 'roda-abdominal-em-pe-com-barra', 'https://static.exercisedb.dev/media/xnInPfE.gif', 'catalogo/roda-abdominal-em-pe-com-barra--xnInPfE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/roda-abdominal-em-pe-com-barra--xnInPfE.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['deltoides','eretores da espinha'], '["Step:1 Stand upright with your feet about shoulder width and hold the barbell with both hands ahead of your thighs.","Step:2 Brace your trunk and With control roll the barbell down toward the ground, with your spine steady and your arms extended.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:45:22.553173+00', '2026-10-31 19:45:22.416+00'), ('xNrS20v', 'Rosca inversa com barra', 'barbell reverse curl', 'rosca-inversa-com-barra', 'https://static.exercisedb.dev/media/xNrS20v.gif', 'catalogo/rosca-inversa-com-barra--xNrS20v.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-com-barra--xNrS20v.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell with palms facing down.","Step:2 Let the elbows do the moving while the upper arms stay put and Breathe out and curl the barbell upward, contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:22.407745+00', '2026-10-31 19:45:22.276+00'), ('xo6sENf', 'Elevação de panturrilha com bola suíça na parede', 'exercise ball on the wall calf raise', 'elevacao-de-panturrilha-com-bola-suica-na-parede', 'https://static.exercisedb.dev/media/xo6sENf.gif', 'catalogo/elevacao-de-panturrilha-com-bola-suica-na-parede--xo6sENf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-panturrilha-com-bola-suica-na-parede--xo6sENf.gif', ARRAY['panturrilhas'], ARRAY['halteres','bola suíça'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Stand and set your back against a wall and place an exercise ball between your lower back and the wall.","Step:2 Set your feet about shoulder width, with your toes pointing forward.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:22.505935+00', '2026-10-31 19:45:22.367+00'), ('XooAdhl', 'Parada de mão', 'handstand', 'parada-de-mao', 'https://static.exercisedb.dev/media/XooAdhl.gif', 'catalogo/parada-de-mao--XooAdhl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/parada-de-mao--XooAdhl.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['deltoides','core'], '["Step:1 Choose an open space with enough room to perform a handstand.","Step:2 Set your hands on the ground about shoulder width, fingers pointing forward.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:22.479313+00', '2026-10-31 19:45:22.344+00'), ('XPUDTt7', 'Flexão de braço do pike para cobra', 'pike-to-cobra push-up', 'flexao-de-braco-do-pike-para-cobra', 'https://static.exercisedb.dev/media/XPUDTt7.gif', 'catalogo/flexao-de-braco-do-pike-para-cobra--XPUDTt7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-do-pike-para-cobra--XPUDTt7.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['core','deltoides','tríceps'], '["Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.","Step:2 Brace your trunk and lift your hips up toward the ceiling, forming an inverted V shape with your body.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:23.023104+00', '2026-10-31 19:45:22.882+00'), ('XsCcxCC', 'Good morning sentado na máquina', 'Machine Seated Good Morning', 'good-morning-sentado-na-maquina', 'https://static.exercisedb.dev/media/XsCcxCC.gif', 'catalogo/good-morning-sentado-na-maquina--XsCcxCC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/good-morning-sentado-na-maquina--XsCcxCC.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Set the seat height so that your hips are slightly higher than your knees.","Step:2 Take a seat on the machine with your back against the pad and your feet flat on the footrests.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:45:23.590037+00', '2026-10-31 19:45:23.447+00'), ('XSCHmiI', 'Elíptico', 'cycle cross trainer', 'eliptico', 'https://static.exercisedb.dev/media/XSCHmiI.gif', 'catalogo/eliptico--XSCHmiI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/eliptico--XSCHmiI.gif', ARRAY['cardio'], ARRAY['máquina articulada'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Set your feet on the pedals and grip the handlebars.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:45:23.173977+00', '2026-10-31 19:45:23.03+00'), ('xTjr103', 'Alongamento de posterior de coxa e panturrilha em pé com faixa', 'standing hamstring and calf stretch with strap', 'alongamento-de-posterior-de-coxa-e-panturrilha-em-pe-com-faixa', 'https://static.exercisedb.dev/media/xTjr103.gif', 'catalogo/alongamento-de-posterior-de-coxa-e-panturrilha-em-pe-com-faixa--xTjr103.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-posterior-de-coxa-e-panturrilha-em-pe-com-faixa--xTjr103.gif', ARRAY['coxas'], ARRAY['corda'], ARRAY['posteriores de coxa'], ARRAY['panturrilhas'], '["Step:1 Stand upright with your feet about shoulder width.","Step:2 Take hold of the strap with both hands and place it around the ball of your foot.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:23.598015+00', '2026-10-31 19:45:23.447+00'), ('XU3ePuv', 'Abdominal no cabo em pé com corda', 'cable standing crunch (with rope attachment)', 'abdominal-no-cabo-em-pe-com-corda', 'https://static.exercisedb.dev/media/XU3ePuv.gif', 'catalogo/abdominal-no-cabo-em-pe-com-corda--XU3ePuv.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-no-cabo-em-pe-com-corda--XU3ePuv.gif', ARRAY['abdômen'], ARRAY['cabo'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Connect a rope to a cable machine at chest height.","Step:2 Face the away from the machine from a stable stance with feet about shoulder width.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:23.62276+00', '2026-10-31 19:45:23.474+00'), ('XUUD0Fs', 'Remada para deltoide posterior com halteres deitado', 'dumbbell lying rear delt row', 'remada-para-deltoide-posterior-com-halteres-deitado', 'https://static.exercisedb.dev/media/XUUD0Fs.gif', 'catalogo/remada-para-deltoide-posterior-com-halteres-deitado--XUUD0Fs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-para-deltoide-posterior-com-halteres-deitado--XUUD0Fs.gif', ARRAY['costas'], ARRAY['halteres'], ARRAY['parte superior das costas'], ARRAY['deltoides','bíceps'], '["Step:1 Position yourself face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Step:2 Extend your arms straight down toward the floor, keeping a slight bend in your elbows.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:23.595357+00', '2026-10-31 19:45:23.461+00'), ('xUwnBMT', 'Desenvolvimento sentado no Smith', 'smith seated shoulder press', 'desenvolvimento-sentado-no-smith', 'https://static.exercisedb.dev/media/xUwnBMT.gif', 'catalogo/desenvolvimento-sentado-no-smith--xUwnBMT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-no-smith--xUwnBMT.gif', ARRAY['ombros'], ARRAY['Smith'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Set the seat height so that the handles are at shoulder level.","Step:2 Take a seat on the machine with your back against the pad and your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:24.018356+00', '2026-10-31 19:45:23.875+00'), ('XVDdcoj', 'Rotação russa', 'russian twist', 'rotacao-russa', 'https://static.exercisedb.dev/media/XVDdcoj.gif', 'catalogo/rotacao-russa--XVDdcoj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-russa--XVDdcoj.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Take a seat on the ground with your knees bent and feet planted.","Step:2 Lean back slightly while with your spine steady and your core engaged.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:24.154418+00', '2026-10-31 19:45:24.012+00'), ('XVzF3iZ', 'Rosca direta com halteres deitado em decúbito dorsal', 'dumbbell lying supine biceps curl', 'rosca-direta-com-halteres-deitado-em-decubito-dorsal', 'https://static.exercisedb.dev/media/XVzF3iZ.gif', 'catalogo/rosca-direta-com-halteres-deitado-em-decubito-dorsal--XVzF3iZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-com-halteres-deitado-em-decubito-dorsal--XVzF3iZ.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Settle onto a bench with your back and head supported, and your feet planted.","Step:2 Take a dumbbell in each hand with your palms facing up and your arms straight.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:24.623137+00', '2026-10-31 19:45:24.49+00'), ('xXm4nYq', 'Crucifixo declinado com halteres', 'dumbbell decline fly', 'crucifixo-declinado-com-halteres', 'https://static.exercisedb.dev/media/xXm4nYq.gif', 'catalogo/crucifixo-declinado-com-halteres--xXm4nYq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-declinado-com-halteres--xXm4nYq.gif', ARRAY['peito'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Secure the feet on a decline bench, keeping the head below the hips.","Step:2 Take a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:45:24.500534+00', '2026-10-31 19:45:24.361+00'), ('Xy4jlWA', 'Desenvolvimento Arnold com halteres', 'dumbbell arnold press', 'desenvolvimento-arnold-com-halteres', 'https://static.exercisedb.dev/media/Xy4jlWA.gif', 'catalogo/desenvolvimento-arnold-com-halteres--Xy4jlWA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-arnold-com-halteres--Xy4jlWA.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['tríceps','peitorais'], '["Step:1 Take a seat on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Step:2 Press the dumbbells upward until your arms are straight and your palms are facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:24.525224+00', '2026-10-31 19:45:24.384+00'), ('Y1MsI1l', 'Cadeira extensora com elástico', 'Band Leg Extension', 'cadeira-extensora-com-elastico', 'https://static.exercisedb.dev/media/Y1MsI1l.gif', 'catalogo/cadeira-extensora-com-elastico--Y1MsI1l.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cadeira-extensora-com-elastico--Y1MsI1l.gif', ARRAY['coxas'], ARRAY['faixa elástica'], ARRAY['quadríceps'], ARRAY['posteriores de coxa'], '["Step:1 Connect the resistance band to a sturdy anchor point and secure it around your ankle.","Step:2 Face the anchor point from a stable stance with feet about shoulder width.","Step:3 Set the pad just above the ankles and keep the thighs against the seat.","Step:4 Straighten your knees to lift the pad, keeping your hips against the seat.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:45:24.944894+00', '2026-10-31 19:45:24.781+00'), ('Y4BRNQF', 'Flexão de braço na bola suíça', 'push-up (on stability ball)', 'flexao-de-braco-na-bola-suica', 'https://static.exercisedb.dev/media/Y4BRNQF.gif', 'catalogo/flexao-de-braco-na-bola-suica--Y4BRNQF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-braco-na-bola-suica--Y4BRNQF.gif', ARRAY['peito'], ARRAY['bola suíça'], ARRAY['peitoral'], ARRAY['tríceps','deltoides','core'], '["Step:1 Set the stability ball on the ground and position yourself facing down with your hands on the ball, about shoulder width.","Step:2 Reach your legs straight out behind you, balancing on your toes.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:24.932661+00', '2026-10-31 19:45:24.8+00'), ('Y4QlY8z', 'Panturrilha em pé no Smith', 'smith toe raise', 'panturrilha-em-pe-no-smith', 'https://static.exercisedb.dev/media/Y4QlY8z.gif', 'catalogo/panturrilha-em-pe-no-smith--Y4QlY8z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-no-smith--Y4QlY8z.gif', ARRAY['panturrilhas'], ARRAY['Smith machine'], ARRAY['panturrilhas'], ARRAY['tornozelos','tibial anterior'], '["Step:1 Set the smith machine bar to a height that allows you to comfortably stand with your feet planted.","Step:2 Set yourself under the bar with your shoulders directly below it and your feet about shoulder width.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:25.099348+00', '2026-10-31 19:45:24.963+00'), ('y5p0H8a', 'Corrida na esteira', 'run (equipment)', 'corrida-na-esteira', 'https://static.exercisedb.dev/media/y5p0H8a.gif', 'catalogo/corrida-na-esteira--y5p0H8a.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/corrida-na-esteira--y5p0H8a.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Begin by standing upright with your feet about hip width.","Step:2 Brace your trunk and keep your upper body relaxed.","Step:3 Start at a pace that lets the feet and arms move in sync.","Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.","Step:5 Keep the pattern repeatable as speed increases.","Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip."]', '2026-10-31 19:45:25.146483+00', '2026-10-31 19:45:24.993+00'), ('y5U5B9Y', 'Rosca Zottman no banco Scott com halteres', 'dumbbell zottman preacher curl', 'rosca-zottman-no-banco-scott-com-halteres', 'https://static.exercisedb.dev/media/y5U5B9Y.gif', 'catalogo/rosca-zottman-no-banco-scott-com-halteres--y5U5B9Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-zottman-no-banco-scott-com-halteres--y5U5B9Y.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Take a seat on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Step:2 Curl the dumbbells up toward your shoulders, With the upper arms still and your palms facing up.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl palms-up, turn the palms down at the top, and lower with that overhand grip.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:25.506594+00', '2026-10-31 19:45:25.359+00'), ('Y5X65IB', 'Rosca inversa com barra W', 'EZ-Bar Reverse-Grip Curl', 'rosca-inversa-com-barra-w', 'https://static.exercisedb.dev/media/Y5X65IB.gif', 'catalogo/rosca-inversa-com-barra-w--Y5X65IB.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-inversa-com-barra-w--Y5X65IB.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up.","Step:2 Hold your elbows near your torso and your upper arms stationary throughout the exercise.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Curl the weight with your palms facing down, keeping the elbows close and torso still.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:25.477798+00', '2026-10-31 19:45:25.337+00'), ('Y7YcmIJ', 'Agachamento frontal com barra no banco', 'barbell bench front squat', 'agachamento-frontal-com-barra-no-banco', 'https://static.exercisedb.dev/media/Y7YcmIJ.gif', 'catalogo/agachamento-frontal-com-barra-no-banco--Y7YcmIJ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frontal-com-barra-no-banco--Y7YcmIJ.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Begin by standing with your feet about shoulder width and the barbell resting on your upper chest, just below your collarbone.","Step:2 Take hold of the barbell with palms facing down, keeping your elbows up and your upper arms parallel to the ground.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:25.829361+00', '2026-10-31 19:45:25.682+00'), ('y8bYM8w', 'Agachamento búlgaro unilateral com elástico', 'band single leg split squat', 'agachamento-bulgaro-unilateral-com-elastico', 'https://static.exercisedb.dev/media/y8bYM8w.gif', 'catalogo/agachamento-bulgaro-unilateral-com-elastico--y8bYM8w.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-bulgaro-unilateral-com-elastico--y8bYM8w.gif', ARRAY['coxas'], ARRAY['faixa elástica'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Stand and set your feet about hip width and place a resistance band around your ankles.","Step:2 Step wide forward with your right foot and a smaller step back with your left foot.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:26.013531+00', '2026-10-31 19:45:25.873+00'), ('Y9hNPcN', 'Abdominal lateral sentado na parede', 'seated side crunch (wall)', 'abdominal-lateral-sentado-na-parede', 'https://static.exercisedb.dev/media/Y9hNPcN.gif', 'catalogo/abdominal-lateral-sentado-na-parede--Y9hNPcN.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-lateral-sentado-na-parede--Y9hNPcN.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos'], '["Step:1 Take a seat on the floor with your back against a wall and your legs extended in front of you.","Step:2 Bend your knees and place your feet planted, about hip width.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:26.492822+00', '2026-10-31 19:45:26.35+00'), ('yaAxcQr', 'Subida na corda', 'rope climb', 'subida-na-corda', 'https://static.exercisedb.dev/media/yaAxcQr.gif', 'catalogo/subida-na-corda--yaAxcQr.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/subida-na-corda--yaAxcQr.gif', ARRAY['costas'], ARRAY['corda'], ARRAY['parte superior das costas'], ARRAY['antebraços','bíceps','deltoides'], '["Step:1 Face the rope from a stable stance with feet about shoulder width.","Step:2 Take hold of the rope with both hands, palms facing toward you.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:25.939174+00', '2026-10-31 19:45:25.799+00'), ('YAk5dIw', 'Barra fixa supinada', 'Reverse-Grip Pull-Up', 'barra-fixa-supinada', 'https://static.exercisedb.dev/media/YAk5dIw.gif', 'catalogo/barra-fixa-supinada--YAk5dIw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-supinada--YAk5dIw.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with palms facing up, hands about shoulder width.","Step:2 Suspend yourself from the bar with your arms straight and your body straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:26.575646+00', '2026-10-31 19:45:26.431+00'), ('yaMIo4D', 'Remada na polia no banco inclinado', 'cable incline bench row', 'remada-na-polia-no-banco-inclinado', 'https://static.exercisedb.dev/media/yaMIo4D.gif', 'catalogo/remada-na-polia-no-banco-inclinado--yaMIo4D.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-na-polia-no-banco-inclinado--yaMIo4D.gif', ARRAY['costas'], ARRAY['polia'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoide posterior'], '["Step:1 Prepare an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Step:2 Take a seat on the bench facing the cable machine with your feet planted and your knees soft.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:26.837553+00', '2026-10-31 19:45:26.7+00'), ('yB9SvIF', 'Supino declinado pegada fechada no Smith', 'Smith Machine Decline Close-Grip Bench Press', 'supino-declinado-pegada-fechada-no-smith', 'https://static.exercisedb.dev/media/yB9SvIF.gif', 'catalogo/supino-declinado-pegada-fechada-no-smith--yB9SvIF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-declinado-pegada-fechada-no-smith--yB9SvIF.gif', ARRAY['braços'], ARRAY['Smith machine'], ARRAY['tríceps'], ARRAY['peitoral','deltoides'], '["Step:1 Set the bench on the smith machine to a decline position.","Step:2 Get onto the bench with your feet firmly planted on the ground.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:26.728233+00', '2026-10-31 19:45:26.579+00'), ('yCvYdi7', 'Desenvolvimento unilateral com kettlebell com inclinação lateral', 'Kettlebell Single-Arm Military Press To The Side', 'desenvolvimento-unilateral-com-kettlebell-com-inclinacao-lateral', 'https://static.exercisedb.dev/media/yCvYdi7.gif', 'catalogo/desenvolvimento-unilateral-com-kettlebell-com-inclinacao-lateral--yCvYdi7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-unilateral-com-kettlebell-com-inclinacao-lateral--yCvYdi7.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','core'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand at shoulder height.","Step:2 Brace your trunk and Keep your spine in a comfortable neutral position.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:45:26.735202+00', '2026-10-31 19:45:26.596+00'), ('Ye5Qxb0', 'Rosca aranha com barra W', 'EZ-Bar Spider Curl', 'rosca-aranha-com-barra-w', 'https://static.exercisedb.dev/media/Ye5Qxb0.gif', 'catalogo/rosca-aranha-com-barra-w--Ye5Qxb0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-aranha-com-barra-w--Ye5Qxb0.gif', ARRAY['braços'], ARRAY['barra W'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand and set your feet about shoulder width and hold the ez barbell with palms facing up.","Step:2 Set your upper arms on a preacher bench or stability ball, letting your elbows to hang down.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:27.08996+00', '2026-10-31 19:45:26.946+00'), ('ye84CTU', 'Rosca Scott na máquina', 'Machine Preacher Curl', 'rosca-scott-na-maquina', 'https://static.exercisedb.dev/media/ye84CTU.gif', 'catalogo/rosca-scott-na-maquina--ye84CTU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-na-maquina--ye84CTU.gif', ARRAY['braços'], ARRAY['máquina articulada'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing up, just beyond shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:27.55028+00', '2026-10-31 19:45:27.406+00'), ('Yg7MJAT', 'Elevação lateral unilateral com halter e apoio', 'Dumbbell Single-Arm Lateral Raise With Support', 'elevacao-lateral-unilateral-com-halter-e-apoio', 'https://static.exercisedb.dev/media/Yg7MJAT.gif', 'catalogo/elevacao-lateral-unilateral-com-halter-e-apoio--Yg7MJAT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-lateral-unilateral-com-halter-e-apoio--Yg7MJAT.gif', ARRAY['ombros'], ARRAY['halteres'], ARRAY['deltoides'], ARRAY['trapézio','manguito rotador'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand, with your palm facing your body.","Step:2 Set your other hand on a stable surface, such as a bench or wall, for support.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it."]', '2026-10-31 19:45:27.346615+00', '2026-10-31 19:45:27.21+00'), ('yg8Totb', 'Tríceps testa com barra atrás da cabeça deitado', 'Barbell Lying Back Of The Head Triceps Extension', 'triceps-testa-com-barra-atras-da-cabeca-deitado', 'https://static.exercisedb.dev/media/yg8Totb.gif', 'catalogo/triceps-testa-com-barra-atras-da-cabeca-deitado--yg8Totb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra-atras-da-cabeca-deitado--yg8Totb.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take a barbell with palms facing down, hands about shoulder width, and extend your arms straight up over your chest.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:27.305408+00', '2026-10-31 19:45:27.165+00'), ('YIUAtYf', 'Rotação russa com peso', 'weighted russian twist', 'rotacao-russa-com-peso', 'https://static.exercisedb.dev/media/YIUAtYf.gif', 'catalogo/rotacao-russa-com-peso--YIUAtYf.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-russa-com-peso--YIUAtYf.gif', ARRAY['abdômen'], ARRAY['peso adicional'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Take a seat on the ground with your knees bent and feet planted.","Step:2 Take hold of the weight with both hands ahead of your chest.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:27.458462+00', '2026-10-31 19:45:27.312+00'), ('yJUHKTn', 'Muscle up', 'muscle up', 'muscle-up', 'https://static.exercisedb.dev/media/yJUHKTn.gif', 'catalogo/muscle-up--yJUHKTn.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/muscle-up--yJUHKTn.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','tríceps','deltoides','peitoral'], '["Step:1 Begin by hanging from a pull-up bar with your palms turned away from you and your arms straight.","Step:2 Brace your trunk and pull your body up toward the bar, leading with your chest.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:27.611864+00', '2026-10-31 19:45:27.477+00'), ('ykA5tU7', 'Alongamento de peitoral na bola suíça', 'chest stretch with exercise ball', 'alongamento-de-peitoral-na-bola-suica', 'https://static.exercisedb.dev/media/ykA5tU7.gif', 'catalogo/alongamento-de-peitoral-na-bola-suica--ykA5tU7.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-peitoral-na-bola-suica--ykA5tU7.gif', ARRAY['peito'], ARRAY['bola suíça'], ARRAY['peitoral'], ARRAY['deltoides','tríceps'], '["Step:1 Take a seat on the stability ball with your feet planted and your back straight.","Step:2 Take hold of the exercise ball with both hands and extend your arms straight out in front of you.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:27.865051+00', '2026-10-31 19:45:27.731+00'), ('ykHcWme', 'Panturrilha no leg press', 'sled calf press on leg press', 'panturrilha-no-leg-press', 'https://static.exercisedb.dev/media/ykHcWme.gif', 'catalogo/panturrilha-no-leg-press--ykHcWme.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-no-leg-press--ykHcWme.gif', ARRAY['panturrilhas'], ARRAY['máquina de leg press'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','quadríceps'], '["Step:1 Set the seat of the leg press machine so that your knees are soft when your feet are on the sled.","Step:2 Set your feet about shoulder width on the sled, with your toes pointing forward.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:28.260868+00', '2026-10-31 19:45:28.115+00'), ('ykUOVze', 'Panturrilha em pé na máquina', 'Machine Standing Calf Raise', 'panturrilha-em-pe-na-maquina', 'https://static.exercisedb.dev/media/ykUOVze.gif', 'catalogo/panturrilha-em-pe-na-maquina--ykUOVze.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-na-maquina--ykUOVze.gif', ARRAY['panturrilhas'], ARRAY['máquina articulada'], ARRAY['panturrilhas'], ARRAY['sóleo','estabilizadores do tornozelo'], '["Step:1 Set the machine to your height and stand with your feet about shoulder width.","Step:2 Set your shoulders under the pads and hold onto the handles for stability.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:28.290692+00', '2026-10-31 19:45:28.153+00'), ('yl2IYyy', 'Panturrilha em pé no cabo', 'cable standing calf raise', 'panturrilha-em-pe-no-cabo', 'https://static.exercisedb.dev/media/yl2IYyy.gif', 'catalogo/panturrilha-em-pe-no-cabo--yl2IYyy.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-em-pe-no-cabo--yl2IYyy.gif', ARRAY['panturrilhas'], ARRAY['cabo'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Use the cable machine handles or attach a cable ankle strap to your ankles.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:28.34112+00', '2026-10-31 19:45:28.206+00'), ('yn0LjwL', 'Alongamento de glúteos deitado assistido', 'assisted lying glutes stretch', 'alongamento-de-gluteos-deitado-assistido', 'https://static.exercisedb.dev/media/yn0LjwL.gif', 'catalogo/alongamento-de-gluteos-deitado-assistido--yn0LjwL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-gluteos-deitado-assistido--yn0LjwL.gif', ARRAY['coxas'], ARRAY['assistido'], ARRAY['glúteos'], ARRAY['posteriores de coxa'], '["Step:1 Settle onto your back with your legs extended.","Step:2 Before moving, bend your right knee and place your right ankle on your left thigh, just above the knee.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:28.499601+00', '2026-10-31 19:45:28.116+00'), ('yn2lLSI', 'Leg press 45° (vista de trás)', 'sled 45° leg press (back pov)', 'leg-press-45-vista-de-tras', 'https://static.exercisedb.dev/media/yn2lLSI.gif', 'catalogo/leg-press-45-vista-de-tras--yn2lLSI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/leg-press-45-vista-de-tras--yn2lLSI.gif', ARRAY['coxas'], ARRAY['máquina de leg press'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Set the seat of the sled machine so that your knees are at a 45-degree angle.","Step:2 Take a seat on the sled machine with your back against the backrest and your feet about shoulder width on the footplate.","Step:3 Set your feet firmly on the plate and keep the hips against the seat.","Step:4 Bend the knees to bring the platform toward you, then press it away through the feet.","Step:5 Stop the descent before the hips lift from the seat.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:28.414711+00', '2026-10-31 19:45:28.274+00'), ('yn8yg1r', 'Agachamento goblet com halter', 'dumbbell goblet squat', 'agachamento-goblet-com-halter', 'https://static.exercisedb.dev/media/yn8yg1r.gif', 'catalogo/agachamento-goblet-com-halter--yn8yg1r.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-goblet-com-halter--yn8yg1r.gif', ARRAY['coxas'], ARRAY['halter'], ARRAY['quadríceps'], ARRAY['glúteos','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a dumbbell vertically against your chest with both hands.","Step:2 With your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:28.881248+00', '2026-10-31 19:45:28.717+00'), ('YPoVrBi', 'Rotação interna de ombro sentado no cabo', 'cable seated shoulder internal rotation', 'rotacao-interna-de-ombro-sentado-no-cabo', 'https://static.exercisedb.dev/media/YPoVrBi.gif', 'catalogo/rotacao-interna-de-ombro-sentado-no-cabo--YPoVrBi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-interna-de-ombro-sentado-no-cabo--YPoVrBi.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['manguito rotador','tríceps'], '["Step:1 Take a seat on a bench or chair facing the cable machine with your feet planted.","Step:2 Take hold of the cable handle with your arm extended straight out in front of you, parallel to the ground.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:28.840754+00', '2026-10-31 19:45:28.698+00'), ('yq3GAJX', 'Toque circular nos pés com mãos entrelaçadas atrás', 'Hands Reversed Clasped Circular Toe Touch', 'toque-circular-nos-pes-com-maos-entrelacadas-atras', 'https://static.exercisedb.dev/media/yq3GAJX.gif', 'catalogo/toque-circular-nos-pes-com-maos-entrelacadas-atras--yq3GAJX.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/toque-circular-nos-pes-com-maos-entrelacadas-atras--yq3GAJX.gif', ARRAY['coxas'], ARRAY['peso corporal'], ARRAY['glúteos'], ARRAY['posteriores de coxa','quadríceps','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width and your arms extended to the sides.","Step:2 Bend forward at the waist, with your spine steady and your knees soft.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold briefly at a comfortable depth, then rise by extending the hips."]', '2026-10-31 19:45:29.128027+00', '2026-10-31 19:45:28.985+00'), ('yQe5HpE', 'Rotação de tronco em pé com barra', 'barbell standing twist', 'rotacao-de-tronco-em-pe-com-barra', 'https://static.exercisedb.dev/media/yQe5HpE.gif', 'catalogo/rotacao-de-tronco-em-pe-com-barra--yQe5HpE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rotacao-de-tronco-em-pe-com-barra--yQe5HpE.gif', ARRAY['abdômen'], ARRAY['barra'], ARRAY['abdominais'], ARRAY['oblíquos','eretores da espinha'], '["Step:1 Stand and set your feet about shoulder width and hold a barbell ahead of your chest with both hands, palms facing down.","Step:2 Brace your trunk and Keep your spine in a comfortable neutral position throughout the exercise.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:29.224985+00', '2026-10-31 19:45:29.088+00'), ('YqJw82s', 'Supino fechado com pegada supinada na barra', 'barbell reverse close-grip bench press', 'supino-fechado-com-pegada-supinada-na-barra', 'https://static.exercisedb.dev/media/YqJw82s.gif', 'catalogo/supino-fechado-com-pegada-supinada-na-barra--YqJw82s.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-fechado-com-pegada-supinada-na-barra--YqJw82s.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with a reverse grip, hands about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:29.337418+00', '2026-10-31 19:45:29.197+00'), ('YRaCa5Y', 'Maltese completo', 'full maltese', 'maltese-completo', 'https://static.exercisedb.dev/media/YRaCa5Y.gif', 'catalogo/maltese-completo--YRaCa5Y.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/maltese-completo--YRaCa5Y.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','peitorais'], '["Step:1 Begin by standing with your feet about shoulder width and your arms extended straight out to the sides.","Step:2 With control lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:29.874388+00', '2026-10-31 19:45:29.729+00'), ('yRLPCLu', 'Tríceps testa com barra e pegada supinada', 'Barbell Reverse-Grip Skullcrusher', 'triceps-testa-com-barra-e-pegada-supinada', 'https://static.exercisedb.dev/media/yRLPCLu.gif', 'catalogo/triceps-testa-com-barra-e-pegada-supinada--yRLPCLu.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-com-barra-e-pegada-supinada--yRLPCLu.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['tríceps'], ARRAY['antebraços'], '["Step:1 Settle onto a bench with your feet planted and your head at the end of the bench.","Step:2 Take hold of the barbell with a reverse grip, palms facing toward your face, and your hands about shoulder width.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:29.488007+00', '2026-10-31 19:45:29.341+00'), ('yRpV5TC', 'Toque no ombro na prancha', 'shoulder tap', 'toque-no-ombro-na-prancha', 'https://static.exercisedb.dev/media/yRpV5TC.gif', 'catalogo/toque-no-ombro-na-prancha--yRpV5TC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/toque-no-ombro-na-prancha--yRpV5TC.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','tríceps'], '["Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Brace your trunk and lift your right hand off the ground, reaching across to tap your left shoulder.","Step:3 Brace the trunk lightly before moving a limb.","Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.","Step:5 Keep the pelvis from rocking as the arm or leg moves.","Step:6 Reset your posture before changing sides or beginning the next rep."]', '2026-10-31 19:45:29.748766+00', '2026-10-31 19:45:29.604+00'), ('yRYyfdA', 'Alongamento de posteriores de coxa sentado na bola suíça', 'exercise ball seated hamstring stretch', 'alongamento-de-posteriores-de-coxa-sentado-na-bola-suica', 'https://static.exercisedb.dev/media/yRYyfdA.gif', 'catalogo/alongamento-de-posteriores-de-coxa-sentado-na-bola-suica--yRYyfdA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-posteriores-de-coxa-sentado-na-bola-suica--yRYyfdA.gif', ARRAY['coxas'], ARRAY['bola suíça'], ARRAY['posteriores de coxa'], ARRAY['glúteos','eretores da espinha'], '["Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 With control roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:29.884572+00', '2026-10-31 19:45:29.731+00'), ('Ys97II0', 'Elevação frontal sentado com halteres', 'dumbbell seated front raise', 'elevacao-frontal-sentado-com-halteres', 'https://static.exercisedb.dev/media/Ys97II0.gif', 'catalogo/elevacao-frontal-sentado-com-halteres--Ys97II0.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-frontal-sentado-com-halteres--Ys97II0.gif', ARRAY['ombros'], ARRAY['halter'], ARRAY['deltoides'], ARRAY['trapézio','bíceps'], '["Step:1 Plant both feet while seated on a bench; a dumbbell in each hand, resting on your thighs.","Step:2 Keep your spine in a comfortable neutral position and core engaged.","Step:3 Start with a manageable load and a small bend in the elbows.","Step:4 Lift the arms forward to about shoulder height, keeping the ribs down and torso still.","Step:5 Stop near shoulder height rather than shrugging to lift higher.","Step:6 Lower the arms slowly to your sides without swinging the weight."]', '2026-10-31 19:45:29.891782+00', '2026-10-31 19:45:29.753+00'), ('yT9tk17', 'Elevação de pernas com rotação', 'Twisted Leg Raise', 'elevacao-de-pernas-com-rotacao', 'https://static.exercisedb.dev/media/yT9tk17.gif', 'catalogo/elevacao-de-pernas-com-rotacao--yT9tk17.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-de-pernas-com-rotacao--yT9tk17.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['oblíquos','flexores do quadril'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and lift your legs off the ground, bringing them toward your chest.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:45:30.08651+00', '2026-10-31 19:45:29.953+00'), ('YtaCTYl', 'Rosca de punho unilateral sentado com pegada neutra e halter', 'Dumbbell Single-Arm Seated Neutral Wrist Curl', 'rosca-de-punho-unilateral-sentado-com-pegada-neutra-e-halter', 'https://static.exercisedb.dev/media/YtaCTYl.gif', 'catalogo/rosca-de-punho-unilateral-sentado-com-pegada-neutra-e-halter--YtaCTYl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-unilateral-sentado-com-pegada-neutra-e-halter--YtaCTYl.gif', ARRAY['antebraços'], ARRAY['halter'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing up.","Step:2 Set your forearm on your thigh, letting your wrist to hang off the edge.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it."]', '2026-10-31 19:45:30.784447+00', '2026-10-31 19:45:30.635+00'), ('YtgD7Xq', 'Barra fixa com pegada na largura dos ombros', 'shoulder grip pull-up', 'barra-fixa-com-pegada-na-largura-dos-ombros', 'https://static.exercisedb.dev/media/YtgD7Xq.gif', 'catalogo/barra-fixa-com-pegada-na-largura-dos-ombros--YtgD7Xq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/barra-fixa-com-pegada-na-largura-dos-ombros--YtgD7Xq.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','antebraços'], '["Step:1 Take hold of the pull-up bar with a shoulder-width grip, palms turned away from you.","Step:2 Hang freely with your arms straight.","Step:3 Begin from a controlled hang with the shoulders active rather than slack.","Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.","Step:5 Avoid swinging the legs to clear the bar.","Step:6 Lower to long arms without dropping suddenly from the top."]', '2026-10-31 19:45:30.370012+00', '2026-10-31 19:45:30.228+00'), ('YTur5nR', 'Rosca unilateral no cabo', 'Cable Single-Arm Curl', 'rosca-unilateral-no-cabo', 'https://static.exercisedb.dev/media/YTur5nR.gif', 'catalogo/rosca-unilateral-no-cabo--YTur5nR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-unilateral-no-cabo--YTur5nR.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the cable handle with palms facing up, palm facing up.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:45:30.445141+00', '2026-10-31 19:45:30.307+00'), ('yU7w7CA', 'Alongamento lombar na bola suíça (pirâmide)', 'exercise ball lower back stretch (pyramid)', 'alongamento-lombar-na-bola-suica-piramide', 'https://static.exercisedb.dev/media/yU7w7CA.gif', 'catalogo/alongamento-lombar-na-bola-suica-piramide--yU7w7CA.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-lombar-na-bola-suica-piramide--yU7w7CA.gif', ARRAY['costas'], ARRAY['bola suíça'], ARRAY['latíssimo do dorso'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.","Step:2 With control walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Keep the ball steady and use the feet to manage your balance.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:30.493473+00', '2026-10-31 19:45:30.361+00'), ('yUdIGNs', 'Remada para deltoide posterior no cabo (com estribos)', 'cable rear delt row (stirrups)', 'remada-para-deltoide-posterior-no-cabo-com-estribos', 'https://static.exercisedb.dev/media/yUdIGNs.gif', 'catalogo/remada-para-deltoide-posterior-no-cabo-com-estribos--yUdIGNs.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-para-deltoide-posterior-no-cabo-com-estribos--yUdIGNs.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['trapézio','romboides','bíceps'], '["Step:1 Connect a stirrup handle to a low cable pulley and stand facing the machine.","Step:2 Hold the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:31.048677+00', '2026-10-31 19:45:30.884+00'), ('YUYAMEj', 'Alongamento de quadríceps em decúbito ventral assistido', 'assisted prone lying quads stretch', 'alongamento-de-quadriceps-em-decubito-ventral-assistido', 'https://static.exercisedb.dev/media/YUYAMEj.gif', 'catalogo/alongamento-de-quadriceps-em-decubito-ventral-assistido--YUYAMEj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-quadriceps-em-decubito-ventral-assistido--YUYAMEj.gif', ARRAY['coxas'], ARRAY['assistido'], ARRAY['quadríceps'], ARRAY['posteriores de coxa','glúteos'], '["Step:1 Position yourself face down on the ground with your legs extended.","Step:2 Before moving, bend your left knee and reach back with your left hand to grab your left foot or ankle.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:30.91076+00', '2026-10-31 19:45:30.778+00'), ('ywaNfuh', 'Panturrilha invertida no Smith', 'smith reverse calf raises', 'panturrilha-invertida-no-smith', 'https://static.exercisedb.dev/media/ywaNfuh.gif', 'catalogo/panturrilha-invertida-no-smith--ywaNfuh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/panturrilha-invertida-no-smith--ywaNfuh.gif', ARRAY['panturrilhas'], ARRAY['Smith'], ARRAY['panturrilhas'], ARRAY['posteriores de coxa'], '["Step:1 Set the smith machine bar to a height just below your shoulders.","Step:2 Face the bar with your feet about hip width and toes pointing forward.","Step:3 Let the ankles move freely while the rest of the body stays quiet.","Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.","Step:5 Pause at the top without rolling the ankles outward.","Step:6 Lower the heels at a measured pace before rising again."]', '2026-10-31 19:45:31.278726+00', '2026-10-31 19:45:31.147+00'), ('YwnI4ja', 'Rosca interna em pé no cabo', 'cable standing inner curl', 'rosca-interna-em-pe-no-cabo', 'https://static.exercisedb.dev/media/YwnI4ja.gif', 'catalogo/rosca-interna-em-pe-no-cabo--YwnI4ja.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-interna-em-pe-no-cabo--YwnI4ja.gif', ARRAY['braços'], ARRAY['cabo'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Hold the cable handle with palms facing up.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:31.316114+00', '2026-10-31 19:45:31.168+00'), ('yWxMvB5', 'Thruster com kettlebell', 'kettlebell thruster', 'thruster-com-kettlebell', 'https://static.exercisedb.dev/media/yWxMvB5.gif', 'catalogo/thruster-com-kettlebell--yWxMvB5.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/thruster-com-kettlebell--yWxMvB5.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['quadríceps','glúteos','core'], '["Step:1 Begin by standing with your feet about shoulder width, holding a kettlebell ahead of your chest with both hands, palms facing each other.","Step:2 Before moving, lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","Step:3 Rack the weight securely and brace before dropping into the squat.","Step:4 Stand from the squat and use that leg drive to press the weight overhead.","Step:5 Let the leg drive start the press while keeping the ribs from flaring.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:31.333613+00', '2026-10-31 19:45:31.193+00'), ('YZ4961r', 'Planche completo', 'full planche', 'planche-completo', 'https://static.exercisedb.dev/media/YZ4961r.gif', 'catalogo/planche-completo--YZ4961r.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/planche-completo--YZ4961r.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','peitorais','tríceps'], '["Step:1 Begin in a push-up position with your hands about shoulder width and your fingers pointing forward.","Step:2 Brace your trunk and With control shift your weight forward, lifting your feet off the ground.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:31.592594+00', '2026-10-31 19:45:31.454+00'), ('yz9nUhF', 'Crucifixo com halteres', 'dumbbell fly', 'crucifixo-com-halteres', 'https://static.exercisedb.dev/media/yz9nUhF.gif', 'catalogo/crucifixo-com-halteres--yz9nUhF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/crucifixo-com-halteres--yz9nUhF.gif', ARRAY['peito'], ARRAY['halter'], ARRAY['peitorais'], ARRAY['deltoides'], '["Step:1 Settle onto a bench with a dumbbell in each hand, palms facing each other.","Step:2 Reach your arms straight up over your chest, with a slight bend in your elbows.","Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.","Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.","Step:5 Keep the elbow angle nearly unchanged through the arc.","Step:6 Open the arms back along the same arc without dropping the load."]', '2026-10-31 19:45:31.643959+00', '2026-10-31 19:45:31.497+00'), ('Yza7XrQ', 'Rosca alternada com barra', 'barbell alternate biceps curl', 'rosca-alternada-com-barra', 'https://static.exercisedb.dev/media/Yza7XrQ.gif', 'catalogo/rosca-alternada-com-barra--Yza7XrQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-alternada-com-barra--Yza7XrQ.gif', ARRAY['braços'], ARRAY['barra'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Stand tall with your feet about shoulder width and hold a barbell in each hand, palms facing forward.","Step:2 Let the elbows do the moving while the upper arms stay put and Breathe out and curl the weights while contracting your biceps.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:45:31.966124+00', '2026-10-31 19:45:31.827+00'), ('yzYH9pI', 'Rosca de punho invertida com barra sobre o banco', 'barbell palms down wrist curl over a bench', 'rosca-de-punho-invertida-com-barra-sobre-o-banco', 'https://static.exercisedb.dev/media/yzYH9pI.gif', 'catalogo/rosca-de-punho-invertida-com-barra-sobre-o-banco--yzYH9pI.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-de-punho-invertida-com-barra-sobre-o-banco--yzYH9pI.gif', ARRAY['antebraços'], ARRAY['barra'], ARRAY['antebraços'], ARRAY['bíceps','braquial'], '["Step:1 Plant both feet while seated on a bench; your forearms resting on your thighs, palms facing down.","Step:2 Take a barbell with palms facing down, hands about shoulder width.","Step:3 Keep the elbows relaxed so the small muscles of the hand or forearm take the load.","Step:4 Move through the wrists or fingers while the forearms stay supported and still.","Step:5 Use a small, smooth range without swinging the elbows.","Step:6 Ease back to the start without letting the load fall from your hands."]', '2026-10-31 19:45:32.445331+00', '2026-10-31 19:45:32.289+00'), ('Z5YStHW', 'Alongamento de tríceps acima da cabeça', 'overhead triceps stretch', 'alongamento-de-triceps-acima-da-cabeca', 'https://static.exercisedb.dev/media/Z5YStHW.gif', 'catalogo/alongamento-de-triceps-acima-da-cabeca--Z5YStHW.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-de-triceps-acima-da-cabeca--Z5YStHW.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Either stand or sit upright with your feet about shoulder width.","Step:2 Extend one arm overhead, bending at the elbow so that your hand reaches toward the opposite shoulder blade.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:32.056723+00', '2026-10-31 19:45:31.909+00'), ('z6TAHoT', 'Supino com halteres com rotação', 'dumbbell twisting bench press', 'supino-com-halteres-com-rotacao', 'https://static.exercisedb.dev/media/z6TAHoT.gif', 'catalogo/supino-com-halteres-com-rotacao--z6TAHoT.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-com-halteres-com-rotacao--z6TAHoT.gif', ARRAY['braços'], ARRAY['halteres'], ARRAY['tríceps'], ARRAY['peitorais','deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold a dumbbell in each hand at chest level with the palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weights up while turning the palms inward; reverse the turn as you lower.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:32.698753+00', '2026-10-31 19:45:32.557+00'), ('ZA8b5hc', 'Agachamento goblet com kettlebell', 'kettlebell goblet squat', 'agachamento-goblet-com-kettlebell', 'https://static.exercisedb.dev/media/ZA8b5hc.gif', 'catalogo/agachamento-goblet-com-kettlebell--ZA8b5hc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-goblet-com-kettlebell--ZA8b5hc.gif', ARRAY['coxas'], ARRAY['kettlebell'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width, holding a kettlebell close to your chest with both hands.","Step:2 With your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:32.206418+00', '2026-10-31 19:45:32.051+00'), ('za9Ni4z', 'Rack pull com barra', 'barbell rack pull', 'rack-pull-com-barra', 'https://static.exercisedb.dev/media/za9Ni4z.gif', 'catalogo/rack-pull-com-barra--za9Ni4z.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rack-pull-com-barra--za9Ni4z.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['posteriores de coxa','eretores da espinha'], '["Step:1 Prepare a barbell on a rack at knee height.","Step:2 Stand and set your feet about shoulder width, toes pointing slightly outwards.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:45:32.595237+00', '2026-10-31 19:45:32.452+00'), ('zCgxPbV', 'Puxada com rotação no cabo', 'cable twisting pull', 'puxada-com-rotacao-no-cabo', 'https://static.exercisedb.dev/media/zCgxPbV.gif', 'catalogo/puxada-com-rotacao-no-cabo--zCgxPbV.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-com-rotacao-no-cabo--zCgxPbV.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['latíssimo do dorso'], ARRAY['deltoides','bíceps'], '["Step:1 Connect a cable handle to a low pulley and stand facing the machine.","Step:2 Hold the handle with your left hand and step away from the machine, extending your arm fully.","Step:3 Set the pelvis and make the turn through the rib cage.","Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.","Step:5 Keep the turn smooth instead of throwing the arms across the body.","Step:6 Return through center before turning to the other side."]', '2026-10-31 19:45:32.621887+00', '2026-10-31 19:45:32.49+00'), ('zd4P4B2', 'Stalder press', 'stalder press', 'stalder-press', 'https://static.exercisedb.dev/media/zd4P4B2.gif', 'catalogo/stalder-press--zd4P4B2.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/stalder-press--zd4P4B2.gif', ARRAY['braços'], ARRAY['peso corporal'], ARRAY['tríceps'], ARRAY['deltoides','core'], '["Step:1 Begin by standing with your feet about shoulder width and your arms extended overhead.","Step:2 Bend your knees slightly and Brace your trunk.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:33.117632+00', '2026-10-31 19:45:32.983+00'), ('Ze7MoIb', 'Supino unilateral com halteres com pegada invertida', 'Dumbbell Single-Arm Reverse-Grip Press', 'supino-unilateral-com-halteres-com-pegada-invertida', 'https://static.exercisedb.dev/media/Ze7MoIb.gif', 'catalogo/supino-unilateral-com-halteres-com-pegada-invertida--Ze7MoIb.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-com-halteres-com-pegada-invertida--Ze7MoIb.gif', ARRAY['peitoral'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Take a seat on a flat bench with a dumbbell in one hand, palm facing toward your body.","Step:2 Set your feet planted and Keep your spine in a comfortable neutral position.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:45:33.399014+00', '2026-10-31 19:45:33.252+00'), ('ZEkjZDi', 'Desenvolvimento militar sentado com dois kettlebells', 'Kettlebell Seated Two-Arm Military Press', 'desenvolvimento-militar-sentado-com-dois-kettlebells', 'https://static.exercisedb.dev/media/ZEkjZDi.gif', 'catalogo/desenvolvimento-militar-sentado-com-dois-kettlebells--ZEkjZDi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-militar-sentado-com-dois-kettlebells--ZEkjZDi.gif', ARRAY['ombros'], ARRAY['kettlebell'], ARRAY['deltoides'], ARRAY['tríceps','parte superior das costas'], '["Step:1 Take a seat on a bench with your back straight and feet planted.","Step:2 Take a kettlebell in each hand at shoulder level with your palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:33.170793+00', '2026-10-31 19:45:33.03+00'), ('zfNHMN9', 'Saltos laterais de patinador', 'skater hops', 'saltos-laterais-de-patinador', 'https://static.exercisedb.dev/media/zfNHMN9.gif', 'catalogo/saltos-laterais-de-patinador--zfNHMN9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/saltos-laterais-de-patinador--zfNHMN9.gif', ARRAY['cardio'], ARRAY['peso corporal'], ARRAY['sistema cardiovascular'], ARRAY['quadríceps','posteriores de coxa','glúteos','panturrilhas'], '["Step:1 Stand and set your feet about shoulder width.","Step:2 Before moving, bend your knees slightly and jump to the right, landing on your right foot.","Step:3 Bend the hips and knees slightly to load the jump.","Step:4 Load the legs with a small bend, then drive through the floor and land softly.","Step:5 Land with bent hips and knees and let the feet absorb the impact.","Step:6 Absorb the landing through the hips and knees before repeating."]', '2026-10-31 19:45:33.30808+00', '2026-10-31 19:45:33.169+00'), ('ZfyAGhK', 'Remada em pé para deltoide posterior no cabo (com corda)', 'cable standing rear delt row (with rope)', 'remada-em-pe-para-deltoide-posterior-no-cabo-com-corda', 'https://static.exercisedb.dev/media/ZfyAGhK.gif', 'catalogo/remada-em-pe-para-deltoide-posterior-no-cabo-com-corda--ZfyAGhK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-em-pe-para-deltoide-posterior-no-cabo-com-corda--ZfyAGhK.gif', ARRAY['ombros'], ARRAY['cabo'], ARRAY['deltoides'], ARRAY['trapézio','romboides','bíceps'], '["Step:1 Face the cable machine from a stable stance with feet about shoulder width.","Step:2 Take hold of the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:33.637536+00', '2026-10-31 19:45:33.494+00'), ('zFzbBfL', 'Abdominal com empurrada na faixa elástica', 'band push sit-up', 'abdominal-com-empurrada-na-faixa-elastica', 'https://static.exercisedb.dev/media/zFzbBfL.gif', 'catalogo/abdominal-com-empurrada-na-faixa-elastica--zFzbBfL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-com-empurrada-na-faixa-elastica--zFzbBfL.gif', ARRAY['abdômen'], ARRAY['faixa elástica'], ARRAY['abdominais'], ARRAY['deltoides','peitorais'], '["Step:1 Connect the band securely to a stable anchor point.","Step:2 Settle onto your back with your knees bent and feet planted.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:33.698928+00', '2026-10-31 19:45:33.551+00'), ('zG0zs85', 'Agachamento frontal com barra', 'barbell front squat', 'agachamento-frontal-com-barra', 'https://static.exercisedb.dev/media/zG0zs85.gif', 'catalogo/agachamento-frontal-com-barra--zG0zs85.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-frontal-com-barra--zG0zs85.gif', ARRAY['coxas'], ARRAY['barra'], ARRAY['glúteos'], ARRAY['quadríceps','posteriores de coxa','panturrilhas','core'], '["Step:1 Begin by standing with your feet about shoulder width, toes slightly turned out.","Step:2 Take hold of the barbell ahead of your shoulders, resting it on your collarbone and shoulders.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:33.698404+00', '2026-10-31 19:45:33.566+00'), ('Zg3XY7P', 'Cadeira flexora', 'Machine Seated Leg Curl', 'cadeira-flexora', 'https://static.exercisedb.dev/media/Zg3XY7P.gif', 'catalogo/cadeira-flexora--Zg3XY7P.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/cadeira-flexora--Zg3XY7P.gif', ARRAY['coxas'], ARRAY['máquina articulada'], ARRAY['posteriores de coxa'], ARRAY['panturrilhas'], '["Step:1 Set the machine to fit your body and sit on it with your back against the backrest.","Step:2 Set your lower legs under the padded lever, just above your ankles.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:45:33.959148+00', '2026-10-31 19:45:33.814+00'), ('zGSIWQi', 'Supino unilateral deitado com halter', 'Dumbbell Lying Single-Arm Press', 'supino-unilateral-deitado-com-halter', 'https://static.exercisedb.dev/media/zGSIWQi.gif', 'catalogo/supino-unilateral-deitado-com-halter--zGSIWQi.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-unilateral-deitado-com-halter--zGSIWQi.gif', ARRAY['peitoral'], ARRAY['halteres'], ARRAY['peitorais'], ARRAY['tríceps','deltoides'], '["Step:1 Settle onto a bench with a dumbbell in one hand and your feet planted.","Step:2 Take hold of the dumbbell at shoulder level with your palm facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it."]', '2026-10-31 19:45:34.212207+00', '2026-10-31 19:45:34.072+00'), ('ZgsNQ6d', 'Inchworm (caminhada com as mãos)', 'inchworm', 'inchworm-caminhada-com-as-maos', 'https://static.exercisedb.dev/media/ZgsNQ6d.gif', 'catalogo/inchworm-caminhada-com-as-maos--ZgsNQ6d.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/inchworm-caminhada-com-as-maos--ZgsNQ6d.gif', ARRAY['abdômen'], ARRAY['peso corporal'], ARRAY['abdominais'], ARRAY['deltoides','posteriores de coxa'], '["Step:1 Begin in a standing position with your feet about hip width.","Step:2 Before moving, bend forward at the waist and place your hands on the ground in front of you.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Stop reaching when the lower back starts to sag.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:45:34.609031+00', '2026-10-31 19:45:34.465+00'), ('ZgwWBoC', 'Remada caiaque Thibaudeau no cabo', 'cable thibaudeau kayak row', 'remada-caiaque-thibaudeau-no-cabo', 'https://static.exercisedb.dev/media/ZgwWBoC.gif', 'catalogo/remada-caiaque-thibaudeau-no-cabo--ZgwWBoC.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-caiaque-thibaudeau-no-cabo--ZgwWBoC.gif', ARRAY['costas'], ARRAY['cabo'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Connect a cable handle to a low pulley and sit facing the machine with your feet planted.","Step:2 Hold the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:34.780224+00', '2026-10-31 19:45:34.646+00'), ('ZH68exZ', 'Puxada com pegada supinada na faixa elástica fixa atrás', 'band fixed back underhand pulldown', 'puxada-com-pegada-supinada-na-faixa-elastica-fixa-atras', 'https://static.exercisedb.dev/media/ZH68exZ.gif', 'catalogo/puxada-com-pegada-supinada-na-faixa-elastica-fixa-atras--ZH68exZ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/puxada-com-pegada-supinada-na-faixa-elastica-fixa-atras--ZH68exZ.gif', ARRAY['costas'], ARRAY['faixa elástica'], ARRAY['latíssimo do dorso'], ARRAY['bíceps','romboides','deltoides posteriores'], '["Step:1 Connect the band to a sturdy anchor point above your head.","Step:2 Face the anchor point from a stable stance with feet about shoulder width.","Step:3 Sit tall and set the shoulders before drawing the handle down.","Step:4 Pull the handle down by driving your elbows toward your ribs; keep your torso steady.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders."]', '2026-10-31 19:45:34.453908+00', '2026-10-31 19:45:34.051+00'), ('zHEpuuc', 'Flexão de pernas inversa assistida no cabo', 'cable assisted inverse leg curl', 'flexao-de-pernas-inversa-assistida-no-cabo', 'https://static.exercisedb.dev/media/zHEpuuc.gif', 'catalogo/flexao-de-pernas-inversa-assistida-no-cabo--zHEpuuc.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-pernas-inversa-assistida-no-cabo--zHEpuuc.gif', ARRAY['coxas'], ARRAY['cabo'], ARRAY['posteriores de coxa'], ARRAY['glúteos','panturrilhas'], '["Step:1 Set the cable machine so that the ankle attachment is at the lowest setting.","Step:2 Position yourself face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Return along the same path at a controlled pace."]', '2026-10-31 19:45:34.987506+00', '2026-10-31 19:45:34.849+00'), ('zhF9lW4', 'Rollout com roda abdominal assistido por faixa elástica', 'Band Assisted Wheel Rollout', 'rollout-com-roda-abdominal-assistido-por-faixa-elastica', 'https://static.exercisedb.dev/media/zhF9lW4.gif', 'catalogo/rollout-com-roda-abdominal-assistido-por-faixa-elastica--zhF9lW4.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rollout-com-roda-abdominal-assistido-por-faixa-elastica--zhF9lW4.gif', ARRAY['abdômen'], ARRAY['faixa elástica'], ARRAY['abdominais'], ARRAY['eretores da espinha'], '["Step:1 Get down on the floor and hold the handles of the band with both hands, palms facing down.","Step:2 Set the band on the ground in front of you and position your hands about shoulder width.","Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.","Step:4 Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.","Step:5 Control the band on the way back instead of letting it snap you into position.","Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line."]', '2026-10-31 19:45:34.957311+00', '2026-10-31 19:45:34.826+00'), ('zhMwOwE', 'Extensão lombar', 'hyperextension', 'extensao-lombar', 'https://static.exercisedb.dev/media/zhMwOwE.gif', 'catalogo/extensao-lombar--zhMwOwE.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/extensao-lombar--zhMwOwE.gif', ARRAY['costas'], ARRAY['peso corporal'], ARRAY['eretores da espinha'], ARRAY['glúteos','posteriores de coxa'], '["Step:1 Set the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Step:2 Fold your arms over your chest or place your hands behind your head.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Finish in a straight body line, before the lower back overarches.","Step:6 Bring the weight or body back to its starting position without rushing."]', '2026-10-31 19:45:35.366803+00', '2026-10-31 19:45:35.216+00'), ('ziFKQXP', 'Tríceps francês unilateral com halter na bola suíça', 'Dumbbell Single-Arm French Press On Exercise Ball', 'triceps-frances-unilateral-com-halter-na-bola-suica', 'https://static.exercisedb.dev/media/ziFKQXP.gif', 'catalogo/triceps-frances-unilateral-com-halter-na-bola-suica--ziFKQXP.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-frances-unilateral-com-halter-na-bola-suica--ziFKQXP.gif', ARRAY['braços'], ARRAY['halteres','bola suíça'], ARRAY['tríceps'], ARRAY['deltoides'], '["Step:1 Take a seat on an exercise ball with your feet planted and your back straight.","Step:2 Take a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Straighten the elbows to bring the bar overhead, then begin the next controlled rep; switch sides when the set calls for it."]', '2026-10-31 19:45:35.238292+00', '2026-10-31 19:45:35.102+00'), ('zILLZ98', 'Rosca direta no Smith', 'Smith Machine Biceps Curl', 'rosca-direta-no-smith', 'https://static.exercisedb.dev/media/zILLZ98.gif', 'catalogo/rosca-direta-no-smith--zILLZ98.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-direta-no-smith--zILLZ98.gif', ARRAY['braços'], ARRAY['Smith machine'], ARRAY['bíceps'], ARRAY['antebraços'], '["Step:1 Set the height of the smith machine bar to be at waist level.","Step:2 Face the smith machine from a stable stance with feet about shoulder width.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Keep the torso quiet and let the elbow bend lift the weight.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still."]', '2026-10-31 19:45:35.350573+00', '2026-10-31 19:45:35.207+00'), ('ZIViNh1', 'Remada unilateral com halter no banco inclinado com pegada invertida', 'Dumbbell Reverse-Grip Incline Bench Single-Arm Row', 'remada-unilateral-com-halter-no-banco-inclinado-com-pegada-invertida', 'https://static.exercisedb.dev/media/ZIViNh1.gif', 'catalogo/remada-unilateral-com-halter-no-banco-inclinado-com-pegada-invertida--ZIViNh1.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-unilateral-com-halter-no-banco-inclinado-com-pegada-invertida--ZIViNh1.gif', ARRAY['costas'], ARRAY['halteres'], ARRAY['parte superior das costas'], ARRAY['bíceps','deltoides'], '["Step:1 Angle the bench to roughly 45 degrees.","Step:2 Set a dumbbell on the floor next to the bench.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it."]', '2026-10-31 19:45:35.482547+00', '2026-10-31 19:45:35.352+00'), ('zK8Fu1W', 'Supino Pegada Invertida no Smith', 'smith reverse-grip press', 'supino-pegada-invertida-no-smith', 'https://static.exercisedb.dev/media/zK8Fu1W.gif', 'catalogo/supino-pegada-invertida-no-smith--zK8Fu1W.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-pegada-invertida-no-smith--zK8Fu1W.gif', ARRAY['Peitoral'], ARRAY['Smith'], ARRAY['Peitoral'], ARRAY['Tríceps','Deltoides'], '["Step:1 Set the height of the smith machine bar to chest level.","Step:2 Face the bar from a stable stance with feet about shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:35.966701+00', '2026-10-31 19:45:35.808+00'), ('zkgRrbK', 'Hiperextensão no Banco', 'hyperextension (on bench)', 'hiperextensao-no-banco', 'https://static.exercisedb.dev/media/zkgRrbK.gif', 'catalogo/hiperextensao-no-banco--zkgRrbK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/hiperextensao-no-banco--zkgRrbK.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Eretores da espinha'], ARRAY['Glúteos','Posteriores de coxa'], '["Step:1 Set the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Step:2 Fold your arms over your chest or place your hands behind your head.","Step:3 Secure the hips and feet on the support before lifting.","Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.","Step:5 Finish in a straight body line, before the lower back overarches.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:35.870211+00', '2026-10-31 19:45:35.72+00'), ('ZNgOYQU', 'Elevação Vertical de Pernas nas Paralelas', 'vertical leg raise (on parallel bars)', 'elevacao-vertical-de-pernas-nas-paralelas', 'https://static.exercisedb.dev/media/ZNgOYQU.gif', 'catalogo/elevacao-vertical-de-pernas-nas-paralelas--ZNgOYQU.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevacao-vertical-de-pernas-nas-paralelas--ZNgOYQU.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Suspend yourself from the parallel bars with your arms straight and your body straight.","Step:2 Brace your trunk and lift your legs up in front of you, keeping them straight.","Step:3 Brace the abdomen and keep the shoulders anchored to the support.","Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.","Step:5 Slow the legs before they pull the lower back out of position.","Step:6 Lower the legs slowly without swinging or losing your trunk position."]', '2026-10-31 19:45:35.969586+00', '2026-10-31 19:45:35.818+00'), ('ZnJHhMk', 'Abdominal Sentado na Máquina (Apoio no Peito)', 'Machine Seated Crunch (Chest Pad)', 'abdominal-sentado-na-maquina-apoio-no-peito', 'https://static.exercisedb.dev/media/ZnJHhMk.gif', 'catalogo/abdominal-sentado-na-maquina-apoio-no-peito--ZnJHhMk.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-sentado-na-maquina-apoio-no-peito--ZnJHhMk.gif', ARRAY['Abdômen'], ARRAY['Máquina de alavanca'], ARRAY['Abdominais'], ARRAY['Oblíquos'], '["Step:1 Set the seat height and chest pad position according to your comfort.","Step:2 Take a seat on the machine with your back against the chest pad and your feet planted.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.","Step:5 Leave a little space between the chin and chest; keep the movement in the torso.","Step:6 Lower the shoulders or torso with control before the next curl."]', '2026-10-31 19:45:36.379599+00', '2026-10-31 19:45:36.246+00'), ('znLogoF', 'Pullover com Barra para Desenvolvimento', 'barbell pullover to press', 'pullover-com-barra-para-desenvolvimento', 'https://static.exercisedb.dev/media/znLogoF.gif', 'catalogo/pullover-com-barra-para-desenvolvimento--znLogoF.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/pullover-com-barra-para-desenvolvimento--znLogoF.gif', ARRAY['Costas'], ARRAY['Barra'], ARRAY['Latíssimo do dorso'], ARRAY['Tríceps','Peitoral','Deltoides'], '["Step:1 Settle onto a bench with your head at one end and your feet on the ground.","Step:2 Take hold of the barbell with a pronated grip (palms turned away from you) and extend your arms straight above your chest.","Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.","Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.","Step:5 Keep the ribs down as the arms travel overhead.","Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs."]', '2026-10-31 19:45:36.407993+00', '2026-10-31 19:45:36.267+00'), ('znP9SIh', 'Abraço de Joelhos ao Peito', 'hug knees to chest', 'abraco-de-joelhos-ao-peito', 'https://static.exercisedb.dev/media/znP9SIh.gif', 'catalogo/abraco-de-joelhos-ao-peito--znP9SIh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abraco-de-joelhos-ao-peito--znP9SIh.gif', ARRAY['Coxas'], ARRAY['Peso corporal'], ARRAY['Glúteos'], ARRAY['Posteriores de coxa','Quadríceps'], '["Step:1 Begin by standing with your feet about shoulder width.","Step:2 Before moving, bend your knees and lower your body down into a squat position.","Step:3 Settle into the starting position and take an easy breath before moving deeper.","Step:4 Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.","Step:5 Stay in a mild stretch rather than pulling farther with momentum.","Step:6 Hold the position with steady breathing, then release gently; repeat on the other side if needed."]', '2026-10-31 19:45:36.537764+00', '2026-10-31 19:45:36.391+00'), ('znQUdHY', 'Desenvolvimento Sentado com Halteres', 'dumbbell seated shoulder press', 'desenvolvimento-sentado-com-halteres', 'https://static.exercisedb.dev/media/znQUdHY.gif', 'catalogo/desenvolvimento-sentado-com-halteres--znQUdHY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/desenvolvimento-sentado-com-halteres--znQUdHY.gif', ARRAY['Ombros'], ARRAY['Halteres'], ARRAY['Deltoides'], ARRAY['Tríceps','Parte superior das costas'], '["Step:1 Take a seat on a bench with a dumbbell in each hand, resting on your thighs.","Step:2 Before moving, raise the dumbbells to shoulder height, palms facing forward.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:36.919501+00', '2026-10-31 19:45:36.789+00'), ('zoOvPcx', 'Supino Pegada Aberta no Smith', 'Smith Wide-Grip Bench Press', 'supino-pegada-aberta-no-smith', 'https://static.exercisedb.dev/media/zoOvPcx.gif', 'catalogo/supino-pegada-aberta-no-smith--zoOvPcx.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/supino-pegada-aberta-no-smith--zoOvPcx.gif', ARRAY['Peitoral'], ARRAY['Smith'], ARRAY['Peitoral'], ARRAY['Tríceps','Deltoides'], '["Step:1 Set the bench to a comfortable position on the smith machine.","Step:2 Get onto the bench with your feet planted.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:36.864016+00', '2026-10-31 19:45:36.722+00'), ('ZOuKWir', 'Flexão de Braços com Joelhos Apoiados', 'Kneeling Push-Up', 'flexao-de-bracos-com-joelhos-apoiados', 'https://static.exercisedb.dev/media/ZOuKWir.gif', 'catalogo/flexao-de-bracos-com-joelhos-apoiados--ZOuKWir.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/flexao-de-bracos-com-joelhos-apoiados--ZOuKWir.gif', ARRAY['Peitoral'], ARRAY['Peso corporal'], ARRAY['Peitoral'], ARRAY['Tríceps','Deltoides'], '["Step:1 Begin by kneeling on the ground with your hands about shoulder width, fingers pointing forward.","Step:2 Reach your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.","Step:4 Bend your elbows to lower your chest while keeping your body in one line.","Step:5 Keep the head in line with the spine as the elbows bend.","Step:6 Press back to straight arms, keeping the body line intact."]', '2026-10-31 19:45:37.006395+00', '2026-10-31 19:45:36.874+00'), ('ZqNOWQ6', 'Remada Vertical Pegada Supinada na Máquina', 'Machine Reverse-Grip Vertical Row', 'remada-vertical-pegada-supinada-na-maquina', 'https://static.exercisedb.dev/media/ZqNOWQ6.gif', 'catalogo/remada-vertical-pegada-supinada-na-maquina--ZqNOWQ6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-vertical-pegada-supinada-na-maquina--ZqNOWQ6.gif', ARRAY['Costas'], ARRAY['Máquina de alavanca'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Set the seat height and footplate position to ensure proper alignment.","Step:2 Take a seat on the machine with your chest against the pad and your feet flat on the footplate.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Keep the palms in the chosen grip without bending the wrists back.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:37.103525+00', '2026-10-31 19:45:36.95+00'), ('ZsiqXYa', 'JM Press com Barra', 'barbell jm bench press', 'jm-press-com-barra', 'https://static.exercisedb.dev/media/ZsiqXYa.gif', 'catalogo/jm-press-com-barra--ZsiqXYa.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/jm-press-com-barra--ZsiqXYa.gif', ARRAY['Braços'], ARRAY['Barra'], ARRAY['Tríceps'], ARRAY['Peitoral','Deltoides'], '["Step:1 Settle onto a bench with your feet planted and your back pressed against the bench.","Step:2 Hold the barbell with palms facing down, just beyond shoulder width.","Step:3 Brace the torso and align the wrists with the forearms.","Step:4 Press the weight or handles away while keeping your trunk braced.","Step:5 Keep the wrists stacked and use a shoulder path that feels natural.","Step:6 Lower the weight to its starting height under control before pressing again."]', '2026-10-31 19:45:37.929765+00', '2026-10-31 19:45:37.515+00'), ('ZSJNetl', 'Remada Alta no Cabo Ajoelhado', 'cable high row (kneeling)', 'remada-alta-no-cabo-ajoelhado', 'https://static.exercisedb.dev/media/ZSJNetl.gif', 'catalogo/remada-alta-no-cabo-ajoelhado--ZSJNetl.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-alta-no-cabo-ajoelhado--ZSJNetl.gif', ARRAY['Costas'], ARRAY['Cabo'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Deltoides'], '["Step:1 Fit a straight bar to the pulley at chest level.","Step:2 Kneel in front of the cable machine and grab the bar with palms facing down, hands about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:37.43177+00', '2026-10-31 19:45:37.278+00'), ('ZSY3MsL', 'Mesa Flexora Invertida Autoassistida no Solo', 'self assisted inverse leg curl (on floor)', 'mesa-flexora-invertida-autoassistida-no-solo', 'https://static.exercisedb.dev/media/ZSY3MsL.gif', 'catalogo/mesa-flexora-invertida-autoassistida-no-solo--ZSY3MsL.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/mesa-flexora-invertida-autoassistida-no-solo--ZSY3MsL.gif', ARRAY['Coxas'], ARRAY['Peso corporal'], ARRAY['Posteriores de coxa'], ARRAY['Glúteos','Panturrilhas'], '["Step:1 Settle onto your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and place your feet planted, about hip width.","Step:3 Line the knees up with the machine or bench edge before starting the curl.","Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.","Step:5 Keep the hips still while the knees bend.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:37.910364+00', '2026-10-31 19:45:37.761+00'), ('ztAa1RK', 'Abdominal V-Up Alternado com Elástico', 'band alternating v-up', 'abdominal-v-up-alternado-com-elastico', 'https://static.exercisedb.dev/media/ztAa1RK.gif', 'catalogo/abdominal-v-up-alternado-com-elastico--ztAa1RK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-v-up-alternado-com-elastico--ztAa1RK.gif', ARRAY['Abdômen'], ARRAY['Elástico'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Settle onto your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Tighten your midsection and lift your legs and upper body off the ground simultaneously, reaching your hands toward your toes.","Step:3 Set the pelvis and keep the neck relaxed before curling upward.","Step:4 Raise your straight legs and torso together, reaching toward the feet before lowering under control.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower the shoulders or torso with control before the next curl; switch sides when the set calls for it."]', '2026-10-31 19:45:37.962516+00', '2026-10-31 19:45:37.82+00'), ('ZujAdR9', 'Tríceps Corda Inclinado no Cabo', 'Cable Rope Incline Triceps Extension', 'triceps-corda-inclinado-no-cabo', 'https://static.exercisedb.dev/media/ZujAdR9.gif', 'catalogo/triceps-corda-inclinado-no-cabo--ZujAdR9.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-corda-inclinado-no-cabo--ZujAdR9.gif', ARRAY['Braços'], ARRAY['Cabo'], ARRAY['Tríceps'], ARRAY['Deltoides'], '["Step:1 Connect a rope to a high pulley and adjust the incline bench to a comfortable angle.","Step:2 Face the away from the pulley from a stable stance with feet about shoulder width.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep the upper arms steady while the forearms travel.","Step:6 Bend the elbows slowly to return to the start of the next rep."]', '2026-10-31 19:45:37.953853+00', '2026-10-31 19:45:37.805+00'), ('ZuPXtCK', 'Agachamento Hack no Smith', 'smith hack squat', 'agachamento-hack-no-smith', 'https://static.exercisedb.dev/media/ZuPXtCK.gif', 'catalogo/agachamento-hack-no-smith--ZuPXtCK.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/agachamento-hack-no-smith--ZuPXtCK.gif', ARRAY['Coxas'], ARRAY['Smith'], ARRAY['Glúteos'], ARRAY['Quadríceps','Posteriores de coxa','Panturrilhas'], '["Step:1 Set the barbell on the smith machine to an appropriate height for your body.","Step:2 Stand and set your feet about shoulder width, toes slightly pointed outwards.","Step:3 Brace the abdomen and spread pressure across the whole foot.","Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.","Step:5 Drive upward with the chest and hips rising together; keep the knees from collapsing inward.","Step:6 Stand fully, reset your footing and breathing, then begin the next descent."]', '2026-10-31 19:45:37.991782+00', '2026-10-31 19:45:37.85+00'), ('ZuXu4Eq', 'Abdominal V-Sit no Solo', 'v-sit on floor', 'abdominal-v-sit-no-solo', 'https://static.exercisedb.dev/media/ZuXu4Eq.gif', 'catalogo/abdominal-v-sit-no-solo--ZuXu4Eq.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/abdominal-v-sit-no-solo--ZuXu4Eq.gif', ARRAY['Abdômen'], ARRAY['Peso corporal'], ARRAY['Abdominais'], ARRAY['Flexores do quadril'], '["Step:1 Take a seat on the floor with your legs extended in front of you.","Step:2 Recline slightly and lift your legs off the ground, keeping them straight.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep breathing steadily as you maintain the same body line.","Step:6 Keep the shape for the planned time, then come out of it with control."]', '2026-10-31 19:45:39.109168+00', '2026-10-31 19:45:38.944+00'), ('Zwiw7XR', 'Rosca Alternada com Halteres e Perna Elevada na Bola Suíça', 'Dumbbell Alternating Biceps Curl With Leg Raised On Exercise Ball', 'rosca-alternada-com-halteres-e-perna-elevada-na-bola-suica', 'https://static.exercisedb.dev/media/Zwiw7XR.gif', 'catalogo/rosca-alternada-com-halteres-e-perna-elevada-na-bola-suica--Zwiw7XR.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-alternada-com-halteres-e-perna-elevada-na-bola-suica--Zwiw7XR.gif', ARRAY['Braços'], ARRAY['Halteres','Bola suíça'], ARRAY['Bíceps'], ARRAY['Antebraços','Deltoides'], '["Step:1 Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.","Step:2 Set an exercise ball behind you and position one foot on top of it, keeping your balance.","Step:3 Set the shoulders and upper arms before bending the elbows.","Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.","Step:5 Finish one side''s motion before the other side takes over.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:45:38.56267+00', '2026-10-31 19:45:38.417+00'), ('ZX9UZmj', 'Remada Curvada no Smith', 'smith bent over row', 'remada-curvada-no-smith', 'https://static.exercisedb.dev/media/ZX9UZmj.gif', 'catalogo/remada-curvada-no-smith--ZX9UZmj.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/remada-curvada-no-smith--ZX9UZmj.gif', ARRAY['Costas'], ARRAY['Smith'], ARRAY['Parte superior das costas'], ARRAY['Bíceps','Antebraços'], '["Step:1 Prepare the smith machine with the bar at hip height.","Step:2 Face the bar from a stable stance with feet about shoulder width.","Step:3 Set the torso and allow the arms to reach forward without rounding excessively.","Step:4 Draw your elbows back and bring the handle or weight toward your torso.","Step:5 Bring the elbows back without jerking the torso.","Step:6 Reach the arms forward again without letting the torso lurch."]', '2026-10-31 19:45:39.092498+00', '2026-10-31 19:45:38.945+00'), ('ZXnjcOQ', 'Rosca Scott Inversa Unilateral no Cabo', 'Cable Single-Arm Reverse Preacher Curl', 'rosca-scott-inversa-unilateral-no-cabo', 'https://static.exercisedb.dev/media/ZXnjcOQ.gif', 'catalogo/rosca-scott-inversa-unilateral-no-cabo--ZXnjcOQ.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/rosca-scott-inversa-unilateral-no-cabo--ZXnjcOQ.gif', ARRAY['Braços'], ARRAY['Cabo'], ARRAY['Bíceps'], ARRAY['Antebraços'], '["Step:1 Move the cable pulley to its lowest setting.","Step:2 Face the cable machine from a stable stance with feet about shoulder width.","Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.","Step:4 Curl the weight while your upper arms stay in contact with the pad.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it."]', '2026-10-31 19:45:38.593898+00', '2026-10-31 19:45:38.453+00'), ('zYmNaoY', 'Elevador', 'elevator', 'elevador', 'https://static.exercisedb.dev/media/zYmNaoY.gif', 'catalogo/elevador--zYmNaoY.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/elevador--zYmNaoY.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Parte superior das costas'], ARRAY['Deltoides','Trapézio'], '["Step:1 Stand and set your feet about shoulder width and your knees soft.","Step:2 Set your hands on your hips or cross them ahead of your chest.","Step:3 Unlock the knees and brace the abdomen before moving the hips back.","Step:4 Push the hips back while keeping the load close and the spine steady.","Step:5 Keep the weight close to the legs and stop when the back would begin to round.","Step:6 Drive the hips forward to stand tall without leaning back at the top."]', '2026-10-31 19:45:38.926688+00', '2026-10-31 19:45:38.784+00'), ('ZZKbeMw', 'Encolhimento na Máquina', 'Machine Shrug', 'encolhimento-na-maquina', 'https://static.exercisedb.dev/media/ZZKbeMw.gif', 'catalogo/encolhimento-na-maquina--ZZKbeMw.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/encolhimento-na-maquina--ZZKbeMw.gif', ARRAY['Costas'], ARRAY['Máquina de alavanca'], ARRAY['Trapézio'], ARRAY['Deltoides'], '["Step:1 Fit the seat to your body, then settle into the machine.","Step:2 Hold the handles with palms facing down and keep your arms straight.","Step:3 Let the arms hang long and keep the head neutral.","Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.","Step:5 Lift and lower vertically without circling the shoulders.","Step:6 Ease back to the start before repeating."]', '2026-10-31 19:45:39.294798+00', '2026-10-31 19:45:39.136+00'), ('zZlORz6', 'Tríceps Testa Unilateral Supinado com Halter', 'Dumbbell Lying Single-Arm Supinated Triceps Extension', 'triceps-testa-unilateral-supinado-com-halter', 'https://static.exercisedb.dev/media/zZlORz6.gif', 'catalogo/triceps-testa-unilateral-supinado-com-halter--zZlORz6.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/triceps-testa-unilateral-supinado-com-halter--zZlORz6.gif', ARRAY['Braços'], ARRAY['Halteres'], ARRAY['Tríceps'], ARRAY['Antebraços'], '["Step:1 Settle onto a bench with your back and head supported, and your feet planted.","Step:2 Take a dumbbell in one hand with palms facing up, and extend your arm straight up above your shoulder.","Step:3 Set the upper arms in place before extending the elbows.","Step:4 Keep the upper arms steady and extend through the elbows to move the weight.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it."]', '2026-10-31 19:45:39.17971+00', '2026-10-31 19:45:39.04+00'), ('ZZTGMKh', 'Alongamento Unilateral na Parede', 'Single-Arm Against Wall', 'alongamento-unilateral-na-parede', 'https://static.exercisedb.dev/media/ZZTGMKh.gif', 'catalogo/alongamento-unilateral-na-parede--ZZTGMKh.gif', 'https://nltoaiiquuryjlnikyxy.supabase.co/storage/v1/object/public/exercise-gifs/catalogo/alongamento-unilateral-na-parede--ZZTGMKh.gif', ARRAY['Costas'], ARRAY['Peso corporal'], ARRAY['Latíssimo do dorso'], ARRAY['Deltoides','Tríceps'], '["Step:1 Face the wall from a stable stance with feet about shoulder width.","Step:2 Reach one arm straight out in front of you and place your palm against the wall.","Step:3 Brace the abdomen and find a position you can maintain without holding your breath.","Step:4 Brace your midsection and hold the position while breathing normally.","Step:5 Keep both shoulders level and resist turning toward the working arm.","Step:6 Keep the shape for the planned time, then come out of it with control; switch sides when the set calls for it."]', '2026-10-31 19:45:39.74196+00', '2026-10-31 19:45:39.611+00');